insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mutarazi-falls','ZWE','Mutarazi Falls',null,'waterfall',-18.53,32.8,'A thin ribbon of water that drops off the Eastern Highlands escarpment into the Honde Valley in two tiers.','Zimbabwe''s highest waterfall at about 762 m, often cited as the second-highest in Africa. A skywalk and zipline now hang over the drop.','Total drop','~762 m',false,true,7,'{"color":"#A8DADC","intensity":0.75,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/d/de/Mutarazi_Falls00.jpg","credit":"Bart Wursten","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Mutarazi_Falls00.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Mtarazi_falls.jpg/1280px-Mtarazi_falls.jpg","credit":"Seabifar","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mtarazi_falls.jpg"}]}'::jsonb,null,'[]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mount-nyangani','ZWE','Mount Nyangani',null,'mountain',-18.3,32.85,'A misty moorland plateau in Nyanga National Park and the source of rivers that flow toward both the Zambezi and the Indian Ocean.','The highest point in Zimbabwe. Local lore holds that the mountain ''swallows'' hikers, and its fast-changing mist has made that legend very easy to believe.','Elevation','2,592 m',false,true,8,'{"color":"#B8B8FF","intensity":0.7,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/18/Mt._Nyangani.jpg/1280px-Mt._Nyangani.jpg","credit":"Seabifar","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mt._Nyangani.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/7/71/Nyangani_south_end.jpg","credit":"Babakathy","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Nyangani_south_end.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/f/f2/Nyama_falls.jpg","credit":"Babakathy","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Nyama_falls.jpg"}]}'::jsonb,null,'[]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('chimanimani','ZWE','Chimanimani Mountains',null,'mountain',-19.8,33.05,'Jagged white quartzite peaks, crystal streams and hidden caves straddling the Mozambique border.','A botanical hotspot with many plant species found nowhere else on Earth. The quartzite gives the range a pale, almost lunar glow at sunrise.','Rock','Quartzite',false,true,9,'{"color":"#E9F5DB","intensity":0.7,"motion":"orbit"}'::jsonb,'{"note":"No openly licensed footage or photos of the Zimbabwe side yet"}'::jsonb,null,'[]'::jsonb)
