insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('great-zimbabwe','ZWE','Great Zimbabwe','Dzimba dza mabwe — “houses of stone”','heritage',-20.2712,30.9333,'The stone capital of a southern African kingdom that flourished from the 11th to the 15th century: dry-stone granite walls curving across a hilltop, a valley and the vast Great Enclosure.','A UNESCO World Heritage Site since 1986 and often described as the largest ancient stone structure south of the Sahara. The nation takes its name from it, and the soapstone Zimbabwe Bird found here flies on the national flag.','Built','c. 1100–1450',true,true,12,'{"color":"#C9A66B","intensity":0.95,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/ASC_Leiden_-_Rietveld_Collection_-_East_Africa_1975_-_05_-_033_-_A_wall_of_the_ruins_of_Great_Zimbabwe_-_Masvingo%2C_Zimbabwe.jpg/1280px-ASC_Leiden_-_Rietveld_Collection_-_East_Africa_1975_-_05_-_033_-_A_wall_of_the_ruins_of_Great_Zimbabwe_-_Masvingo%2C_Zimbabwe.jpg","credit":"Aart Rietveld / ASC Leiden","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:ASC_Leiden_-_Rietveld_Collection_-_East_Africa_1975_-_05_-_033_-_A_wall_of_the_ruins_of_Great_Zimbabwe_-_Masvingo,_Zimbabwe.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/ASC_Leiden_-_Rietveld_Collection_-_East_Africa_1975_-_05_-_036_-_A_tower_of_Great_Zimbabwe_-_Masvingo%2C_Zimbabwe.jpg/1280px-ASC_Leiden_-_Rietveld_Collection_-_East_Africa_1975_-_05_-_036_-_A_tower_of_Great_Zimbabwe_-_Masvingo%2C_Zimbabwe.jpg","credit":"Aart Rietveld / ASC Leiden","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:ASC_Leiden_-_Rietveld_Collection_-_East_Africa_1975_-_05_-_036_-_A_tower_of_Great_Zimbabwe_-_Masvingo,_Zimbabwe.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Eastern-enclosure-great-zimbabwe.jpg/1280px-Eastern-enclosure-great-zimbabwe.jpg","credit":"ctsnow (Flickr)","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Eastern-enclosure-great-zimbabwe.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/364/","https://en.wikipedia.org/wiki/Great_Zimbabwe","https://www.wikidata.org/wiki/Q209217"]'::jsonb)
