insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('cave-squeaker','ZWE','Cave Squeaker','Datya — Shona for frog','fauna',-19.778,33.003,'A tiny frog, about 25 mm long, known only from caves, sinkholes and montane grassland around 1,500 m on the western slopes of the Chimanimani Mountains.','Critically Endangered and lost to science for 54 years: first collected in 1962, it was rediscovered in December 2016 by a Natural History Museum of Zimbabwe team who followed a call they had never heard before.','Known range','~20 km²',false,true,14,'{"color":"#9BE15D","intensity":0.8,"motion":"ripple"}'::jsonb,'{"note":"No openly licensed footage or photos yet — a living swarm stands in"}'::jsonb,'Arthroleptis troglodytes','["https://serpentresearch.com/2017/02/06/2017-02-arthroleptis-troglodytes-rediscovered-in-zimbabwe/","https://www.edgeofexistence.org/species/cave-squeaker/","https://www.gbif.org/species/2429725"]'::jsonb)
