insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tsodilo-hills','BWA','Tsodilo Hills',null,'heritage',-18.77,21.75,'Four quartzite hills rising out of the Kalahari, holding more than 4,500 rock paintings within about 10 km².','Sometimes called the “Louvre of the Desert”, the hills are still revered by the San and Hambukushu as a place of ancestral spirits. World Heritage Site since 2001.','Rock paintings','4,500+',true,true,2,'{"color":"#C8553D","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Tsodilo_Hills,_Botswana1.jpg/1280px-Tsodilo_Hills,_Botswana1.jpg","credit":"Joachim Huber","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Tsodilo_Hills,_Botswana1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/Tsodilo_Hills_rock_paintings1.jpg/1280px-Tsodilo_Hills_rock_paintings1.jpg","credit":"Joachim Huber","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Tsodilo_Hills_rock_paintings1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/Tsodilo_Hills,_Botswana2.jpg/1280px-Tsodilo_Hills,_Botswana2.jpg","credit":"Joachim Huber","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Tsodilo_Hills,_Botswana2.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1021/","https://en.wikipedia.org/wiki/Tsodilo","https://www.wikidata.org/wiki/Q214007"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('chobe-national-park','BWA','Chobe National Park',null,'savanna',-18.65,24.4,'Botswana’s first national park, where the Chobe River pulls enormous herds down to drink in the dry season.','Known for one of the largest elephant concentrations in Africa; tens of thousands gather along the riverfront and the Linyanti in the dry months.','Established','1967',false,true,3,'{"color":"#8FB339","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/1/1f/African_buffalo_(Syncerus_caffer)_in_Botswana.webm/African_buffalo_(Syncerus_caffer)_in_Botswana.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/1/1f/African_buffalo_(Syncerus_caffer)_in_Botswana.webm/African_buffalo_(Syncerus_caffer)_in_Botswana.webm.360p.mpeg4.mov","credit":"Stefan Krasowski","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:African_buffalo_(Syncerus_caffer)_in_Botswana.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Beautiful_savanna_on_our_way_to_the_Chobe_National_Park_(4613620058).jpg/1280px-Beautiful_savanna_on_our_way_to_the_Chobe_National_Park_(4613620058).jpg","credit":"Jorge Láscar from Australia","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Beautiful_savanna_on_our_way_to_the_Chobe_National_Park_(4613620058).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Chobe_N.P._01.jpg/1280px-Chobe_N.P._01.jpg","credit":"LBM1948","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Chobe_N.P._01.jpg"}],"note":"Buffalo herd filmed along the Chobe and Victoria Falls corridor."}'::jsonb,null,'["https://en.wikipedia.org/wiki/Chobe_National_Park","https://www.wikidata.org/wiki/Q859389"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('makgadikgadi-pans','BWA','Makgadikgadi Pans',null,'desert',-20.61,24.78,'The dry bed of an ancient super-lake: salt flats so wide and white they read as sky from the air.','One of the largest salt-pan systems on Earth. After good rains it floods shallowly, flamingos breed, and zebra and wildebeest migrate across its grasslands.','Pan system','~16,000 km²',false,true,4,'{"color":"#F4EFE3","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/Baobab_(Adansonia_digitata),_parque_nacional_Makgadikgadi_Pans,_Botsuana,_2018-07-30,_DD_03-08_PAN.jpg/1280px-Baobab_(Adansonia_digitata),_parque_nacional_Makgadikgadi_Pans,_Botsuana,_2018-07-30,_DD_03-08_PAN.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Baobab_(Adansonia_digitata),_parque_nacional_Makgadikgadi_Pans,_Botsuana,_2018-07-30,_DD_03-08_PAN.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Avestruces_(Struthio_camelus),_salar_del_parque_nacional_Makgadikgadi_Pans,_Botsuana,_2018-07-30,_DD_51.jpg/1280px-Avestruces_(Struthio_camelus),_salar_del_parque_nacional_Makgadikgadi_Pans,_Botsuana,_2018-07-30,_DD_51.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Avestruces_(Struthio_camelus),_salar_del_parque_nacional_Makgadikgadi_Pans,_Botsuana,_2018-07-30,_DD_51.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Baobab_(Adansonia_digitata),_parque_nacional_Makgadikgadi_Pans,_Botsuana,_2018-07-30,_DD_01.jpg/1280px-Baobab_(Adansonia_digitata),_parque_nacional_Makgadikgadi_Pans,_Botsuana,_2018-07-30,_DD_01.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Baobab_(Adansonia_digitata),_parque_nacional_Makgadikgadi_Pans,_Botsuana,_2018-07-30,_DD_01.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Makgadikgadi_Pan","https://www.wikidata.org/wiki/Q1747195"]'::jsonb)
