insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('central-kalahari','BWA','Central Kalahari Game Reserve',null,'desert',-21.89,23.76,'One of Africa’s largest reserves: fossil river valleys, pans and grass under a huge Kalahari sky.','Created in 1961 for both wildlife and the San who live there. After rain, Deception Valley’s ancient riverbed draws springbok, gemsbok and black-maned Kalahari lions.','Area','52,800 km²',false,true,7,'{"color":"#C9A227","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/4/44/Central_Kalahari_Game_Reserve_-_panoramio.jpg","credit":"Parakh Hoon","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Central_Kalahari_Game_Reserve_-_panoramio.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Naro_Bushmen_hunting_in_the_Central_Kalahari_Game_Reserve,_Botswana_2008.jpg/1280px-Naro_Bushmen_hunting_in_the_Central_Kalahari_Game_Reserve,_Botswana_2008.jpg","credit":"DVL2","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Naro_Bushmen_hunting_in_the_Central_Kalahari_Game_Reserve,_Botswana_2008.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Central_Kalahari_Game_Reserve"]'::jsonb)
