insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('devils-claw','BWA','Devil’s Claw',null,'flora',-22.33,23.51,'A Kalahari creeper with magenta trumpet flowers and hooked fruit that hitch rides on passing hooves.','Its storage roots are a traditional medicine now traded worldwide as an anti-inflammatory, so wild harvesting is regulated. The pin is a representative point from GBIF records.','Family','Sesame (Pedaliaceae)',false,true,9,'{"color":"#C2185B","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Teufelskralle_(Harpagophytum_procumbens).jpg/1280px-Teufelskralle_(Harpagophytum_procumbens).jpg","credit":"Olga Ernst & Hp.Baumeler","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Teufelskralle_(Harpagophytum_procumbens).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Harpagophytum_procumbens_MHNT.BOT.2005.0.1243.jpg/1280px-Harpagophytum_procumbens_MHNT.BOT.2005.0.1243.jpg","credit":"Roger Culos","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Harpagophytum_procumbens_MHNT.BOT.2005.0.1243.jpg"}],"note":"Photos from Namibia and a herbarium specimen — no open Botswana photo yet."}'::jsonb,'Harpagophytum procumbens','["https://www.gbif.org/species/3585335","https://en.wikipedia.org/wiki/Harpagophytum"]'::jsonb)
