insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('maloti-drakensberg','ZAF','Maloti-Drakensberg Park','uKhahlamba: “barrier of spears” (isiZulu)','mountain',-29.37,29.53,'A basalt wall rising above 3,000 m along the Lesotho border: the highest part of Southern Africa’s Great Escarpment.','A mixed natural and cultural World Heritage Site (2000, extended into Lesotho in 2013). Its caves and shelters hold the largest concentration of rock paintings in Africa south of the Sahara.','Rock-art images','~35,000+',true,true,1,'{"color":"#3E8E41","intensity":0.85,"motion":"mist"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/1/1e/UKhahlamba-Drakensberg_Park.webm/UKhahlamba-Drakensberg_Park.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/1/1e/UKhahlamba-Drakensberg_Park.webm/UKhahlamba-Drakensberg_Park.webm.360p.mpeg4.mov","credit":"avinjamaier","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:UKhahlamba-Drakensberg_Park.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Drakensberg_(15543813103).jpg/1280px-Drakensberg_(15543813103).jpg","credit":"Darren Glanville from Acle, Norfolk, UK","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Drakensberg_(15543813103).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Drakensberg_(15541237114).jpg/1280px-Drakensberg_(15541237114).jpg","credit":"Darren Glanville from Acle, Norfolk, UK","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Drakensberg_(15541237114).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/985/","https://en.wikipedia.org/wiki/Drakensberg","https://www.wikidata.org/wiki/Q183295"]'::jsonb)
