insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('vredefort-dome','ZAF','Vredefort Dome',null,'landform',-27,27.5,'The eroded core of the oldest and largest known impact structure on Earth, struck about two billion years ago.','The original crater is estimated at 170–300 km across. What remains is a ring of hills around the town of Vredefort, World Heritage Site since 2005.','Age','~2.02 billion years',true,true,4,'{"color":"#D9A441","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Vredefort_Dome_Vredefort-001.jpg/1280px-Vredefort_Dome_Vredefort-001.jpg","credit":"Leo za1","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Vredefort_Dome_Vredefort-001.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/58/Vredefort_Dome_Vredefort-002.jpg/1280px-Vredefort_Dome_Vredefort-002.jpg","credit":"Leo za1","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Vredefort_Dome_Vredefort-002.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1162/","https://en.wikipedia.org/wiki/Vredefort_impact_structure","https://www.wikidata.org/wiki/Q330095"]'::jsonb)
