insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tugela-falls','ZAF','Tugela Falls',null,'waterfall',-28.75,28.89,'A ribbon of water leaping off the Drakensberg Amphitheatre in a chain of free-falling drops.','With a total drop of about 948 m, it vies with Venezuela’s Angel Falls as the world’s tallest waterfall; some measurements rank it first.','Total drop','~948 m',false,true,8,'{"color":"#7FC8F8","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Tugela_falls.jpg/1280px-Tugela_falls.jpg","credit":"Juniper339","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Tugela_falls.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Tugela_Falls.jpg/1280px-Tugela_Falls.jpg","credit":"PhilippN","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Tugela_Falls.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Tugela_Falls_drop-off.jpg/1280px-Tugela_Falls_drop-off.jpg","credit":"Andynct","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Tugela_Falls_drop-off.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Tugela_Falls","https://www.wikidata.org/wiki/Q223649"]'::jsonb)
