insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mandela-legacy-sites','ZAF','Nelson Mandela Legacy Sites',null,'heritage',-25.74,28.212,'Fourteen places that tell South Africa’s 20th-century struggle for freedom. This pin marks the Union Buildings in Pretoria.','Inscribed in 2024 as “Human Rights, Liberation and Reconciliation”; components include Sharpeville, Walter Sisulu Square and Mqhekezweni, where Mandela grew up.','Components','14',true,true,15,'{"color":"#F2E2C4","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/East_Wing_of_the_Union_Buildings.JPG/1280px-East_Wing_of_the_Union_Buildings.JPG","credit":"Portiatn","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:East_Wing_of_the_Union_Buildings.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Pretoria_Union_Buildings-001.jpg/1280px-Pretoria_Union_Buildings-001.jpg","credit":"Leo za1","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Pretoria_Union_Buildings-001.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/1_Aspect_of_Union_Buildings_-_Pretoria_-_South_Africa.jpg/1280px-1_Aspect_of_Union_Buildings_-_Pretoria_-_South_Africa.jpg","credit":"Hein waschefort","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:1_Aspect_of_Union_Buildings_-_Pretoria_-_South_Africa.jpg"}],"note":"Union Buildings, Pretoria — one of 14 components."}'::jsonb,null,'["https://whc.unesco.org/en/list/1676/","https://www.wikidata.org/wiki/Q65936861"]'::jsonb)
