insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('pleistocene-occupation-sites','ZAF','Pleistocene Occupation Sites',null,'heritage',-34.208,22.089,'Coastal and inland caves preserving a record of modern human behaviour that reaches back about 162,000 years.','Pinnacle Point (this pin), Diepkloof and Sibhudu hold early evidence of ochre processing, engraved patterns, shell beads and advanced weapons. World Heritage Site since 2024.','Record','162,000–38,000 yrs ago',true,true,16,'{"color":"#B5835A","intensity":0.85,"motion":"sink"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/3/3a/Pinnacle_Point_Archaeological_Site,_Mossel_Bay_South_Africa.jpg","credit":"Andrew Hall","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Pinnacle_Point_Archaeological_Site,_Mossel_Bay_South_Africa.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/A_view_from_Pinnacle_Point,_Mossel_Bay,_South_Africa.jpg/1280px-A_view_from_Pinnacle_Point,_Mossel_Bay,_South_Africa.jpg","credit":"Satdeep Gill","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:A_view_from_Pinnacle_Point,_Mossel_Bay,_South_Africa.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1723/","https://en.wikipedia.org/wiki/Pinnacle_Point","https://www.wikidata.org/wiki/Q65936860"]'::jsonb)
