insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('namib-sand-sea','NAM','Namib Sand Sea','Sossusvlei','desert',-24.885,15.408,'The only coastal desert in the world with vast dune fields shaped by fog: a sea of sand covering more than 3 million hectares.','Some dunes around Sossusvlei rise over 300 m, and beetles and plants harvest Atlantic fog to drink. World Heritage Site since 2013.','Area','~30,800 km²',true,true,1,'{"color":"#D9480F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/2010-09-25_14-24-19_Namibia_Hardap_Hammerstein.jpg/1280px-2010-09-25_14-24-19_Namibia_Hardap_Hammerstein.jpg","credit":"Hansueli Krapf","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:2010-09-25_14-24-19_Namibia_Hardap_Hammerstein.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/2010-09-25_14-36-05_Namibia_Hardap_Hammerstein.jpg/1280px-2010-09-25_14-36-05_Namibia_Hardap_Hammerstein.jpg","credit":"Hansueli Krapf","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:2010-09-25_14-36-05_Namibia_Hardap_Hammerstein.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/2010-09-25_14-49-37_Namibia_Hardap_Hammerstein.jpg/1280px-2010-09-25_14-49-37_Namibia_Hardap_Hammerstein.jpg","credit":"Hansueli Krapf","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:2010-09-25_14-49-37_Namibia_Hardap_Hammerstein.jpg"}],"note":"Sossusvlei, inside the Namib Sand Sea."}'::jsonb,null,'["https://whc.unesco.org/en/list/1430/","https://en.wikipedia.org/wiki/Namib","https://www.wikidata.org/wiki/Q1773441"]'::jsonb)
