insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('twyfelfontein','NAM','Twyfelfontein','ǀUi-ǁAis','heritage',-20.59,14.37,'One of the largest concentrations of rock engravings in Africa: more than 2,000 figures cut into sandstone around a desert spring.','Rhinos, giraffes, lions and human footprints, carved by hunter-gatherers over thousands of years. Namibia’s first World Heritage Site (2007).','Engravings','2,000+',true,true,2,'{"color":"#C97B3C","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Twyfelfontein_7_(SqueakyMarmot).jpg/1280px-Twyfelfontein_7_(SqueakyMarmot).jpg","credit":"SqueakyMarmot / Mike, Vancouver, Canada","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Twyfelfontein_7_(SqueakyMarmot).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Namibie_Twyfelfontein_05.JPG/1280px-Namibie_Twyfelfontein_05.JPG","credit":"GIRAUD Patrick","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Namibie_Twyfelfontein_05.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Twyfelfontein_20.jpg/1280px-Twyfelfontein_20.jpg","credit":"Mike from Vancouver, Canada","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Twyfelfontein_20.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1255/","https://en.wikipedia.org/wiki/Twyfelfontein","https://www.wikidata.org/wiki/Q754791"]'::jsonb)
