insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('fish-river-canyon','NAM','Fish River Canyon',null,'gorge',-27.59,17.6,'Africa’s largest canyon: about 160 km long and up to roughly 550 m deep, cut by the Fish River through Namibia’s southern plateau.','A five-day hiking trail follows the canyon floor, and hot springs at Ai-Ais sit at its southern end.','Depth','up to ~550 m',false,true,4,'{"color":"#A44A3F","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Fish_River_Canyon_Namibia.jpg/1280px-Fish_River_Canyon_Namibia.jpg","credit":"Thomas Schoch","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Fish_River_Canyon_Namibia.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Namibia_Fischfluss-Canyon_08.jpg/1280px-Namibia_Fischfluss-Canyon_08.jpg","credit":"Zairon","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Namibia_Fischfluss-Canyon_08.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Namibia_Fischfluss-Canyon_18.jpg/1280px-Namibia_Fischfluss-Canyon_18.jpg","credit":"Zairon","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Namibia_Fischfluss-Canyon_18.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Fish_River_Canyon"]'::jsonb)
