insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('skeleton-coast','NAM','Skeleton Coast',null,'coast',-19.19,12.72,'Fog, surf and shipwrecks: a coast where dunes run straight into the cold Atlantic.','The Benguela Current breeds dense fog, and desert-adapted lions and brown hyenas forage along the shore. National park since 1971.','Area','16,845 km²',false,true,8,'{"color":"#1B3A5C","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Namib_Skeleton_Coast_Park,_Namibia_(3045328373).jpg/1280px-Namib_Skeleton_Coast_Park,_Namibia_(3045328373).jpg","credit":"Joachim Huber from Switzerland","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Namib_Skeleton_Coast_Park,_Namibia_(3045328373).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Namib_Skeleton_Coast_Park,_Namibia_(3045342479).jpg/1280px-Namib_Skeleton_Coast_Park,_Namibia_(3045342479).jpg","credit":"Joachim Huber from Switzerland","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Namib_Skeleton_Coast_Park,_Namibia_(3045342479).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Laika_ac_Skeleton_Coast_(8419506040).jpg/1280px-Laika_ac_Skeleton_Coast_(8419506040).jpg","credit":"Laika ac from USA","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Laika_ac_Skeleton_Coast_(8419506040).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Skeleton_Coast_National_Park","https://www.wikidata.org/wiki/Q3695317"]'::jsonb)
