insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('welwitschia','NAM','Welwitschia',null,'flora',-22.62,15.03,'A desert plant with only two leaves, which keep growing for its whole life and are shredded by wind into a tangle.','Individuals are estimated to live well over 1,000 years, drinking Atlantic fog. It appears on Namibia’s coat of arms. This pin marks the Welwitschia Plains near Swakopmund.','Lifespan','1,000+ years',false,true,10,'{"color":"#6A8D3A","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Welwitschia_mirabilis(1).jpg/1280px-Welwitschia_mirabilis(1).jpg","credit":"Thomas Schoch","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Welwitschia_mirabilis(1).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Welwitschia_mirabilis_(female).jpg/1280px-Welwitschia_mirabilis_(female).jpg","credit":"Hans Hillewaert","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Welwitschia_mirabilis_(female).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Welwitschia_mirabilis_S&J5.jpg/1280px-Welwitschia_mirabilis_S&J5.jpg","credit":"Sara & Joachim on Flickr","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Welwitschia_mirabilis_S&J5.jpg"}]}'::jsonb,'Welwitschia mirabilis','["https://en.wikipedia.org/wiki/Welwitschia","https://www.gbif.org/species/search?q=Welwitschia%20mirabilis"]'::jsonb)
