insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('chongoni-rock-art','MWI','Chongoni Rock-Art Area',null,'heritage',-14.29,34.28,'Forested granite hills in central Malawi with 127 painted rock sites, the densest cluster of rock art in Central Africa.','The paintings run from Late Stone Age hunter-gatherers to Chewa farmers, whose rituals still connect to the shelters. World Heritage Site since 2006.','Rock-art sites','127',true,true,3,'{"color":"#E8692C","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/2/2a/Chongoni_rock_art.jpg","credit":"「Malawi」","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Chongoni_rock_art.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Chongoni_Rock-Art_Area-110124.jpg/1280px-Chongoni_Rock-Art_Area-110124.jpg","credit":"Lazare Eloundou Assomo","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Chongoni_Rock-Art_Area-110124.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Chongoni_Rock-Art_Area-110128.jpg/1280px-Chongoni_Rock-Art_Area-110128.jpg","credit":"Lazare Eloundou Assomo","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Chongoni_Rock-Art_Area-110128.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/476/","https://en.wikipedia.org/wiki/Chongoni_Rock_Art_Area","https://www.wikidata.org/wiki/Q832262"]'::jsonb)
