insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('majete','MWI','Majete Wildlife Reserve',null,'savanna',-15.97,34.76,'Emptied by poaching in the 1980s, Majete is again home to the Big Five.','Since African Parks took over management in 2003, thousands of animals have been reintroduced, including elephant, black rhino, lion and leopard.','Restored since','2003',false,true,8,'{"color":"#F2B134","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Majete_wildlife_reserve.jpg/1280px-Majete_wildlife_reserve.jpg","credit":"David Davies","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Majete_wildlife_reserve.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Elephant_at_Majete_wildlife_reserve.jpg/1280px-Elephant_at_Majete_wildlife_reserve.jpg","credit":"David Davies","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Elephant_at_Majete_wildlife_reserve.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/5_Water_buffalo_Wasserb%C3%BCffel_(36884594806).jpg/1280px-5_Water_buffalo_Wasserb%C3%BCffel_(36884594806).jpg","credit":"Cornelius Kibelka from Berlin, Germany","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:5_Water_buffalo_Wasserb%C3%BCffel_(36884594806).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Majete_Wildlife_Reserve"]'::jsonb)
