insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('zebra-mbuna','MWI','Zebra Mbuna','mbuna: “rock-dweller”','fauna',-13.55,34.76,'A rock-dwelling cichlid of Lake Malawi, one of hundreds of mbuna species that evolved within a single lake.','Mbuna graze algae from the rocks. Their colours and fast-forming species make Lake Malawi a living laboratory of evolution. The pin is a representative point from GBIF records.','Length','~11 cm',false,true,10,'{"color":"#2B6CB0","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Maylandia_zebra_61728832.jpg/1280px-Maylandia_zebra_61728832.jpg","credit":"Kai Squires","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Maylandia_zebra_61728832.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Maylandia_zebra.jpg/1280px-Maylandia_zebra.jpg","credit":"Klaus Rudloff","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Maylandia_zebra.jpg"}],"note":"Aquarium specimens — no open underwater footage from the lake yet."}'::jsonb,'Maylandia zebra','["https://en.wikipedia.org/wiki/Zebra_mbuna","https://www.gbif.org/species/search?q=Maylandia%20zebra"]'::jsonb)
