insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('south-luangwa','ZMB','South Luangwa National Park',null,'river',-13.1,31.6,'An oxbow-laced river valley famous as the birthplace of the walking safari.','The Luangwa’s lagoons hold some of Africa’s densest hippo populations, and the valley is renowned for leopards and Thornicroft’s giraffe.','Area','9,050 km²',false,true,1,'{"color":"#E9C46A","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Loxodonta_africana_South_Luangwa_National_Park_(1).jpg/1280px-Loxodonta_africana_South_Luangwa_National_Park_(1).jpg","credit":"Geoff Gallice","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Loxodonta_africana_South_Luangwa_National_Park_(1).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Luangwa_river02.jpg/1280px-Luangwa_river02.jpg","credit":"Paul Maritz","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Luangwa_river02.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Flickr_-_ggallice_-_Bush_sunset.jpg/1280px-Flickr_-_ggallice_-_Bush_sunset.jpg","credit":"Geoff Gallice from Gainesville, FL, USA","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Flickr_-_ggallice_-_Bush_sunset.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/South_Luangwa_National_Park","https://www.wikidata.org/wiki/Q1973215"]'::jsonb)
