insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lower-zambezi','ZMB','Lower Zambezi National Park',null,'river',-15.6,29.57,'Elephants wade between islands on the Zambezi’s north bank, facing Zimbabwe’s Mana Pools.','A private presidential reserve until 1983, which spared it from heavy hunting. With Mana Pools it forms one of Africa’s great river wildernesses.','Proclaimed','1983',false,true,3,'{"color":"#2A6F97","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Lower_Zambezi,_Zambia_(2518067857).jpg/1280px-Lower_Zambezi,_Zambia_(2518067857).jpg","credit":"Joachim Huber from Switzerland","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Lower_Zambezi,_Zambia_(2518067857).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/3/3c/Elephants_Lower_Zambezi.jpg","credit":"Paul Kane","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Elephants_Lower_Zambezi.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/5/50/Hippos_Lower_Zambezi.jpg","credit":"Paul Kane","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Hippos_Lower_Zambezi.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lower_Zambezi_National_Park","https://www.wikidata.org/wiki/Q503518"]'::jsonb)
