insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kalambo-falls','ZMB','Kalambo Falls',null,'waterfall',-8.597,31.24,'A single drop of about 235 m on the Tanzania border, among the tallest uninterrupted waterfalls in Africa.','The site is also a key archaeological record: in 2023 researchers reported the oldest known wooden structure here, at least 476,000 years old.','Single drop','~235 m',false,true,4,'{"color":"#7BDFF2","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/a/ad/Kalambo_Falls.jpg","credit":"Worldtraveller at English Wikipedia","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Kalambo_Falls.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/f/f7/Kalambo_falls.jpg","credit":"Kelvin Chidoti","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kalambo_falls.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/235_meters_of_single_drop_waterfall,_the_second_largest_waterfall_in_Africa.jpg/1280px-235_meters_of_single_drop_waterfall,_the_second_largest_waterfall_in_Africa.jpg","credit":"Humphrey Kaburu","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:235_meters_of_single_drop_waterfall,_the_second_largest_waterfall_in_Africa.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Kalambo_Falls","https://www.wikidata.org/wiki/Q798283","https://www.nature.com/articles/s41586-023-06557-9"]'::jsonb)
