insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bangweulu-wetlands','ZMB','Bangweulu Wetlands','Bangweulu: “where the water meets the sky”','wetland',-11.4,30,'A shallow lake and huge swamp on northern Zambia’s plateau, flat to the horizon.','One of the best places on Earth to see the shoebill, and home to tens of thousands of endemic black lechwe.','Signature bird','Shoebill',false,true,6,'{"color":"#2A6F97","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Bangweulu_Swamps.jpg/1280px-Bangweulu_Swamps.jpg","credit":"Mehmet Karatay","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Bangweulu_Swamps.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Lake_bangweulu.jpg/1280px-Lake_bangweulu.jpg","credit":"Baba''s Door","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Lake_bangweulu.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Dugouts.jpg/1280px-Dugouts.jpg","credit":"Mehmet Karatay","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Dugouts.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Bangweulu","https://en.wikipedia.org/wiki/Bangweulu_Swamps","https://www.wikidata.org/wiki/Q673169"]'::jsonb)
