insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('nsumbu-lake-tanganyika','ZMB','Nsumbu & Lake Tanganyika',null,'lake',-8.74,30.38,'Zambia’s stretch of Lake Tanganyika: sandy bays, cliffs and clear water at the south end of one of the world’s deepest lakes.','Lake Tanganyika is the second-deepest and second-oldest lake on Earth, and its cichlids evolved in parallel with Lake Malawi’s.','Lake depth','~1,470 m',false,true,8,'{"color":"#0B4F6C","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/3/37/Nsumbu_-_panoramio.jpg","credit":"Peter Syfert","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Nsumbu_-_panoramio.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Nsumbu_National_Park","https://en.wikipedia.org/wiki/Lake_Tanganyika"]'::jsonb)
