insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kasanka-bat-migration','ZMB','Kasanka Bat Migration',null,'fauna',-12.56,30.18,'Every November, an estimated 8–10 million straw-coloured fruit bats descend on a small patch of swamp forest in Kasanka National Park.','Often called the largest mammal migration on Earth by numbers. The bats stay for about two months, feasting on wild fruit.','Bats','~8–10 million',false,true,11,'{"color":"#D62828","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://inaturalist-open-data.s3.amazonaws.com/photos/346173458/large.jpeg","credit":"Michael Bakker Paiva","license":"CC BY 4.0","source":"https://www.inaturalist.org/observations/196661247"},{"url":"https://inaturalist-open-data.s3.amazonaws.com/photos/578333493/large.jpg","credit":"Ryan van Huyssteen","license":"CC BY 4.0","source":"https://www.inaturalist.org/observations/319907719"},{"url":"https://inaturalist-open-data.s3.amazonaws.com/photos/24597834/large.jpeg","credit":"TOUROULT Julien","license":"CC BY 4.0","source":"https://www.inaturalist.org/observations/16361804"}]}'::jsonb,'Eidolon helvum','["https://en.wikipedia.org/wiki/Kasanka_National_Park","https://en.wikipedia.org/wiki/Straw-coloured_fruit_bat"]'::jsonb)
