insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('island-of-mozambique','MOZ','Island of Mozambique','Ilha de Moçambique','heritage',-15.035,40.735,'A coral island off the northern coast that gave the country its name and was the capital of Portuguese East Africa until 1898.','World Heritage Site since 1991. Its stone town and macuti (palm-thatch) town show centuries of Swahili, Arab, Indian and Portuguese exchange; the Chapel of Nossa Senhora do Baluarte (1522) is often cited as the oldest European building in the southern hemisphere.','Capital until','1898',true,true,1,'{"color":"#F4D58D","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Mozambique_(3912235854).jpg/1280px-Mozambique_(3912235854).jpg","credit":"F Mira from Lisbon, Portugal","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Mozambique_(3912235854).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Musiro_Ilha_de_Mozambique_(3923789736).jpg/1280px-Musiro_Ilha_de_Mozambique_(3923789736).jpg","credit":"Rosino","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Musiro_Ilha_de_Mozambique_(3923789736).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Boats_outside_Island_of_Mozambique.jpg/1280px-Boats_outside_Island_of_Mozambique.jpg","credit":"Stig Nygaard","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Boats_outside_Island_of_Mozambique.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/599/","https://en.wikipedia.org/wiki/Island_of_Mozambique","https://www.wikidata.org/wiki/Q331099"]'::jsonb)
