insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('gorongosa','MOZ','Gorongosa National Park',null,'savanna',-18.77,34.5,'A rift-valley park of floodplains, lakes and woodland, reborn after civil war nearly wiped out its wildlife.','A long-term restoration partnership has helped large-mammal numbers climb from a few thousand to many tens of thousands. Rain-forested Mount Gorongosa feeds its rivers.','Area','~4,000 km²',false,true,2,'{"color":"#2D6A4F","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/a/a9/Gorongosa_-_terrain.JPG","credit":"Brian Dell","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Gorongosa_-_terrain.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/6/6a/Serra_de_Gorongosa_(4403936386).jpg","credit":"Ton Rulkens from Mozambique","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Serra_de_Gorongosa_(4403936386).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Mayfly,_Gorongosa_National_Park,_Mozambique_(29110144998).jpg/1280px-Mayfly,_Gorongosa_National_Park,_Mozambique_(29110144998).jpg","credit":"Judy Gallagher","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Mayfly,_Gorongosa_National_Park,_Mozambique_(29110144998).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Gorongosa_National_Park","https://www.wikidata.org/wiki/Q113952"]'::jsonb)
