insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bazaruto-archipelago','MOZ','Bazaruto Archipelago',null,'coast',-21.67,35.47,'Islands of towering dunes and turquoise shallows off Vilankulo.','A national park since 1971. Its seagrass meadows shelter Mozambique’s largest remaining dugong population, along with sea turtles and coral reefs.','Islands','6',false,true,3,'{"color":"#00A6A6","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Bazaruto-Island-East-Coast-From-South.jpg/1280px-Bazaruto-Island-East-Coast-From-South.jpg","credit":"Bjørn Christian Tørrissen","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Bazaruto-Island-East-Coast-From-South.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/Bazaruto_Island_Mozambique_from_air.jpg/1280px-Bazaruto_Island_Mozambique_from_air.jpg","credit":"Tom Corser","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Bazaruto_Island_Mozambique_from_air.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/26/Bazaruto-Island-2009.jpg/1280px-Bazaruto-Island-2009.jpg","credit":"Bjørn Christian Tørrissen","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Bazaruto-Island-2009.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Bazaruto_Archipelago","https://www.wikidata.org/wiki/Q1102054"]'::jsonb)
