insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('maputo-national-park','MOZ','Maputo National Park',null,'coast',-26.5,32.8,'Coastal lakes, swamps and forested dunes on Maputo Bay, where turtles nest on the beaches.','Since 2025 it has been part of the transboundary World Heritage Site “iSimangaliso Wetland Park and Maputo National Park”, shared with South Africa.','Area','1,718 km²',true,true,7,'{"color":"#00A6A6","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Maputo_National_Park,_Mozambique.jpg/1280px-Maputo_National_Park,_Mozambique.jpg","credit":"Charles J. Sharp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Maputo_National_Park,_Mozambique.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Plains_zebras_(Equus_quagga)_Maputo.jpg/1280px-Plains_zebras_(Equus_quagga)_Maputo.jpg","credit":"Charles J. Sharp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Plains_zebras_(Equus_quagga)_Maputo.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/South_African_giraffes_(Giraffa_camelopardalis_giraffa)_Maputo.jpg/1280px-South_African_giraffes_(Giraffa_camelopardalis_giraffa)_Maputo.jpg","credit":"Charles J. Sharp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:South_African_giraffes_(Giraffa_camelopardalis_giraffa)_Maputo.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/914/","https://en.wikipedia.org/wiki/Maputo_National_Park","https://www.wikidata.org/wiki/Q130019294"]'::jsonb)
