insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('beni-hammad','DZA','Al Qal''a of Beni Hammad',null,'heritage',35.81,4.79,'The ruined first capital of the Hammadid dynasty, founded in 1007 in the Hodna mountains.','Its great mosque, with a 25 m minaret, is among the oldest in Algeria. The city was abandoned in 1090 under threat from the Banu Hilal. World Heritage Site since 1980.','Founded','1007',true,true,1,'{"color":"#C8955A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Beni_Hammad_Fort.jpg/1280px-Beni_Hammad_Fort.jpg","credit":"Si20u","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Beni_Hammad_Fort.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Beni_Hammad.jpg/1280px-Beni_Hammad.jpg","credit":"Si20u","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Beni_Hammad.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/28-2_Kal%C3%A2a_de_Beni_Hammad_(3).jpg/1280px-28-2_Kal%C3%A2a_de_Beni_Hammad_(3).jpg","credit":"R hakka","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:28-2_Kal%C3%A2a_de_Beni_Hammad_(3).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/102/","https://en.wikipedia.org/wiki/Beni_Hammad_Fort"]'::jsonb)
