insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tassili-n-ajjer','DZA','Tassili n''Ajjer',null,'rock',25.67,9,'A sandstone plateau of rock forests and canyons holding more than 15,000 prehistoric paintings and engravings.','The art records a green Sahara of hippos, cattle herders and dancing figures. The plateau also shelters the last wild Saharan cypresses. A mixed (cultural and natural) World Heritage Site since 1982.','Rock artworks','15,000+',true,true,2,'{"color":"#B5502E","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Camel_In_Tassili.jpg/1280px-Camel_In_Tassili.jpg","credit":"Abdallahdjabi","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Camel_In_Tassili.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Cupressus_dupreziana1.jpg/1280px-Cupressus_dupreziana1.jpg","credit":"Gruban at Flickr","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Cupressus_dupreziana1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Cute_Lezard_Showing_Off_At_Tassili_N_Ajjer_(168099137).jpeg/1280px-Cute_Lezard_Showing_Off_At_Tassili_N_Ajjer_(168099137).jpeg","credit":"2 F Ī K Æ Ł T Ë R","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Cute_Lezard_Showing_Off_At_Tassili_N_Ajjer_(168099137).jpeg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/179/","https://en.wikipedia.org/wiki/Tassili_n''Ajjer"]'::jsonb)
