insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('djemila','DZA','Djémila','Cuicul','heritage',36.32,5.74,'A Roman mountain town at about 900 m, with forum, temples, basilicas and arches laid out on a narrow ridge.','Its plan shows how Roman builders adapted their grid to steep terrain. Its museum walls are covered with mosaics found on site. World Heritage Site since 1982.','Altitude','~900 m',true,true,3,'{"color":"#D9A066","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Dj%C3%A9mila,_panoramica.jpg/1280px-Dj%C3%A9mila,_panoramica.jpg","credit":"Dan Sloan","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Dj%C3%A9mila,_panoramica.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Alg%C3%A9rie,_Djemila,_Les_murs_du_Mus%C3%A9e_rev%C3%AAtus_des_mosa%C3%AFques_trouv%C3%A9es_%C3%A0_Dj%C3%A9mila_-_A61578.jpg/1280px-Alg%C3%A9rie,_Djemila,_Les_murs_du_Mus%C3%A9e_rev%C3%AAtus_des_mosa%C3%AFques_trouv%C3%A9es_%C3%A0_Dj%C3%A9mila_-_A61578.jpg","credit":"Gadmer Frédéric","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Alg%C3%A9rie,_Djemila,_Les_murs_du_Mus%C3%A9e_rev%C3%AAtus_des_mosa%C3%AFques_trouv%C3%A9es_%C3%A0_Dj%C3%A9mila_-_A61578.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/191/","https://en.wikipedia.org/wiki/Djémila"]'::jsonb)
