insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tipasa','DZA','Tipasa',null,'heritage',36.59,2.44,'Punic, Roman, early Christian and Byzantine ruins on the shore west of Algiers.','A trading post turned Roman colony, with basilicas and a royal Numidian-Mauretanian mausoleum nearby. World Heritage Site since 1982.','Inscribed','1982',true,true,4,'{"color":"#5BA4CF","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/View_of_Tipasa_01.jpg/1280px-View_of_Tipasa_01.jpg","credit":"Bernard Gagnon","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:View_of_Tipasa_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/A_roman_column_opposite_the_lighthouse.jpg/1280px-A_roman_column_opposite_the_lighthouse.jpg","credit":"RACHID BENABDELLAH","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:A_roman_column_opposite_the_lighthouse.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Corridor_in_the_form_of_a_gate_to_the_wall_of_a_Roman_temple.jpg/1280px-Corridor_in_the_form_of_a_gate_to_the_wall_of_a_Roman_temple.jpg","credit":"RACHID BENABDELLAH","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Corridor_in_the_form_of_a_gate_to_the_wall_of_a_Roman_temple.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/193/","https://en.wikipedia.org/wiki/Tipasa"]'::jsonb)
