insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('timgad','DZA','Timgad','Thamugadi','heritage',35.48,6.47,'A Roman garrison town founded by Trajan around 100 CE, with an almost perfect grid of streets.','Often called the “Pompeii of North Africa”. Its Arch of Trajan, theatre and library survived because sand buried the city. World Heritage Site since 1982.','Founded','~100 CE',true,true,5,'{"color":"#D98E48","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Timgad,_Algeria_-_panoramio_(30).jpg/1280px-Timgad,_Algeria_-_panoramio_(30).jpg","credit":"Xiaotong Gao","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Timgad,_Algeria_-_panoramio_(30).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/Timgad_3.jpg/1280px-Timgad_3.jpg","credit":"Yassamine98","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Timgad_3.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Timgad_2.jpg/1280px-Timgad_2.jpg","credit":"Yassamine98","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Timgad_2.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/194/","https://en.wikipedia.org/wiki/Timgad"]'::jsonb)
