insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kasbah-of-algiers','DZA','Kasbah of Algiers',null,'heritage',36.78,3.06,'The old hillside medina of Algiers, a maze of whitewashed houses, mosques and Ottoman palaces dropping to the sea.','Built over ancient Icosium and shaped by the Zirids and Ottomans. Its alleys were a stronghold of the independence struggle. World Heritage Site since 1992.','Inscribed','1992',true,true,6,'{"color":"#F2E3C9","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Casbah_alger.jpg/1280px-Casbah_alger.jpg","credit":"jam-L","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Casbah_alger.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Kasbah_Of_Algiers_Algeria.jpg/1280px-Kasbah_Of_Algiers_Algeria.jpg","credit":"Fayeq M.Alnatour","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kasbah_Of_Algiers_Algeria.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/AlgerCasbah.jpg/1280px-AlgerCasbah.jpg","credit":"toufik Lerari","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:AlgerCasbah.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/565/","https://en.wikipedia.org/wiki/Casbah_of_Algiers"]'::jsonb)
