insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mzab-valley','DZA','M''Zab Valley',null,'heritage',32.49,3.68,'Five fortified ksour built from the 10th–11th century by the Ibadi Mozabites in a Saharan valley.','Its simple, functional earthen architecture, with each town climbing to a mosque minaret, has influenced modern architects. World Heritage Site since 1982.','Towns (ksour)','5',true,true,7,'{"color":"#E4B363","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Beni_Isguen,_M''zab_Valley_(15267446323).jpg/1280px-Beni_Isguen,_M''zab_Valley_(15267446323).jpg","credit":"Dan Sloan","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Beni_Isguen,_M''zab_Valley_(15267446323).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/M''zab_Valley_(15886411032).jpg/1280px-M''zab_Valley_(15886411032).jpg","credit":"Dan Sloan","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:M''zab_Valley_(15886411032).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/M''zab_Valley_(15886423002).jpg/1280px-M''zab_Valley_(15886423002).jpg","credit":"Dan Sloan","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:M''zab_Valley_(15886423002).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/188/","https://en.wikipedia.org/wiki/M''zab"]'::jsonb)
