insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('hoggar-mountains','DZA','Hoggar Mountains','Ahaggar','mountain',23.29,5.53,'A volcanic highland in the central Sahara, with basalt organ-pipe peaks rising to Mount Tahat at about 2,900 m.','Homeland of the Kel Ahaggar Tuareg. Sunrise at Assekrem, where Charles de Foucauld built his hermitage, is one of the Sahara’s great views.','Highest peak','Tahat ~2,908 m',false,true,8,'{"color":"#3D3A4B","intensity":0.85,"motion":"mist"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/8/8b/Hoggar_Mountains_-_4th_position_-_Winners_of_Wiki_Loves_Earth_2018.webm/Hoggar_Mountains_-_4th_position_-_Winners_of_Wiki_Loves_Earth_2018.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/8/8b/Hoggar_Mountains_-_4th_position_-_Winners_of_Wiki_Loves_Earth_2018.webm/Hoggar_Mountains_-_4th_position_-_Winners_of_Wiki_Loves_Earth_2018.webm.360p.mpeg4.mov","credit":"Sofiane Mohammed Amri (photo), Nabin K. Sapkota (video)","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Hoggar_Mountains_-_4th_position_-_Winners_of_Wiki_Loves_Earth_2018.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/Ahaggar_Mountains_1981_01.jpg/1280px-Ahaggar_Mountains_1981_01.jpg","credit":"Smiley.toerist","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ahaggar_Mountains_1981_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Ahaggar_Mountains_1981_03.jpg/1280px-Ahaggar_Mountains_1981_03.jpg","credit":"Smiley.toerist","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ahaggar_Mountains_1981_03.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Hoggar_Mountains","https://www.wikidata.org/wiki/Q26399"]'::jsonb)
