insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('djurdjura','DZA','Djurdjura National Park',null,'mountain',36.47,4.13,'Limestone peaks of the Tell Atlas in Kabylie, with cedar forests and deep karst caves.','Home to Barbary macaques, and to Anou Boussouil, one of the deepest known caves in Africa. Also a UNESCO biosphere reserve.','Highest peak','Lalla Khedidja 2,308 m',false,true,9,'{"color":"#2F5D50","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Djurdjura_national_park_algeria.jpg/1280px-Djurdjura_national_park_algeria.jpg","credit":"Hichem Marley","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Djurdjura_national_park_algeria.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Tikjda_015.jpg/1280px-Tikjda_015.jpg","credit":"Yelles","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Tikjda_015.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Grass_field.JPG/1280px-Grass_field.JPG","credit":"Hamza CHEGGOUR","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Grass_field.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Djurdjura_National_Park","https://en.wikipedia.org/wiki/Djurdjura_Mountains"]'::jsonb)
