insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('el-kala','DZA','El Kala National Park',null,'wetland',36.82,8.42,'Lakes, cork-oak forest and dunes on the Mediterranean at the Tunisian border.','Its lakes Tonga and Oubeïra are Ramsar wetlands for wintering waterbirds; the park is also a UNESCO biosphere reserve.','Created','1983',false,true,10,'{"color":"#4C8C4A","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/All%C3%A9e_des_embrumes_(El_Kala_national_park).jpg/1280px-All%C3%A9e_des_embrumes_(El_Kala_national_park).jpg","credit":"Rabah2204","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:All%C3%A9e_des_embrumes_(El_Kala_national_park).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/National_parc_of_El-kala_Taref.jpg/1280px-National_parc_of_El-kala_Taref.jpg","credit":"HAKOUMAhaki","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:National_parc_of_El-kala_Taref.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Plegadis_falcinellus._Mahieddine_Boumendjel.JPG/1280px-Plegadis_falcinellus._Mahieddine_Boumendjel.JPG","credit":"Mahieddine Boumendjel","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Plegadis_falcinellus._Mahieddine_Boumendjel.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/El_Kala_National_Park"]'::jsonb)
