insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('grand-erg-oriental','DZA','Grand Erg Oriental',null,'desert',30,6,'A great sea of dunes in the Algerian Sahara, spilling into Tunisia.','Its star dunes and linear ridges cover roughly 600 km by 200 km, with dunes over 100 m high in places.','Extent','~600 × 200 km',false,true,11,'{"color":"#E0A458","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Grand_Erg_Oriental(js)2.jpg/1280px-Grand_Erg_Oriental(js)2.jpg","credit":"Jerzystrzelecki","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Grand_Erg_Oriental(js)2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Grand_Erg_Oriental(js)3.jpg/1280px-Grand_Erg_Oriental(js)3.jpg","credit":"Jerzystrzelecki","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Grand_Erg_Oriental(js)3.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Grand_Erg_Oriental(js)1.jpg/1280px-Grand_Erg_Oriental(js)1.jpg","credit":"Jerzystrzelecki","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Grand_Erg_Oriental(js)1.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Grand_Erg_Oriental"]'::jsonb)
