insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('fennec-fox','DZA','Fennec Fox',null,'fauna',27,2.5,'The smallest fox, with the largest ears for its size: a nocturnal hunter of the Sahara’s sands. Algeria’s national animal.','Its ears shed desert heat and hear insects underground; furry soles let it run on hot sand. It can go long periods without free water. The pin is a representative point.','Ear length','~10–15 cm',false,true,12,'{"color":"#F2C57C","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/2b/Fennec_fox.webm/Fennec_fox.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/2b/Fennec_fox.webm/Fennec_fox.webm.360p.mpeg4.mov","credit":"Altes","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Fennec_fox.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Fennec_Fox_Vulpes_zerda.jpg/1280px-Fennec_Fox_Vulpes_zerda.jpg","credit":"Drew Avery","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Fennec_Fox_Vulpes_zerda.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fennec_Fox_Peek.jpg/1280px-Fennec_Fox_Peek.jpg","credit":"Anass ERRIHANI","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Fennec_Fox_Peek.jpg"}]}'::jsonb,'Vulpes zerda','["https://en.wikipedia.org/wiki/Fennec_fox","https://www.gbif.org/species/search?q=Vulpes%20zerda"]'::jsonb)
