insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('atlas-cedar','DZA','Atlas Cedar',null,'flora',35.6,6.2,'A tall cedar of the Atlas and Aurès mountains, with blue-green needles and layered branches.','Found only in Morocco and Algeria, where forests are shrinking with drought and grazing. It is listed as Endangered. The pin is a representative point in the Aurès.','IUCN status','Endangered',false,true,13,'{"color":"#2F5D50","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Des_arbres_du_C%C3%A8dre_d''Atlas_Cedrus_atlantica_sur_la_montagne_de_Tichoukte_(SIBE).jpg/1280px-Des_arbres_du_C%C3%A8dre_d''Atlas_Cedrus_atlantica_sur_la_montagne_de_Tichoukte_(SIBE).jpg","credit":"Aziz aitakka","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Des_arbres_du_C%C3%A8dre_d''Atlas_Cedrus_atlantica_sur_la_montagne_de_Tichoukte_(SIBE).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Cedrus_atlantica_in_Jbel_Lekraa.jpg/1280px-Cedrus_atlantica_in_Jbel_Lekraa.jpg","credit":"Mustapha Bassouh","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cedrus_atlantica_in_Jbel_Lekraa.jpg"}]}'::jsonb,'Cedrus atlantica','["https://en.wikipedia.org/wiki/Cedrus_atlantica","https://www.gbif.org/species/search?q=Cedrus%20atlantica"]'::jsonb)
