insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('abu-mena','EGY','Abu Mena',null,'heritage',30.84,29.66,'The ruins of a Late Antique Christian pilgrimage town built over the tomb of Saint Menas, south-west of Alexandria.','Pilgrims carried home small flasks of its holy water, found across the Mediterranean world. Rising groundwater from irrigation has put the site on the List in Danger since 2001.','In Danger since','2001',true,true,1,'{"color":"#E8D5A9","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d8/Ruins_at_Abu_Mena_(VI).jpg/1280px-Ruins_at_Abu_Mena_(VI).jpg","credit":"isawnyu","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Ruins_at_Abu_Mena_(VI).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/Landscape_at_Abu_Mena_(I).jpg/1280px-Landscape_at_Abu_Mena_(I).jpg","credit":"isawnyu","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Landscape_at_Abu_Mena_(I).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Landscape_at_Abu_Mena_(II).jpg/1280px-Landscape_at_Abu_Mena_(II).jpg","credit":"isawnyu","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Landscape_at_Abu_Mena_(II).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/90/","https://en.wikipedia.org/wiki/Abu_Mena"]'::jsonb)
