insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ancient-thebes','EGY','Ancient Thebes and its Necropolis','Waset','heritage',25.72,32.61,'The New Kingdom capital at Luxor: the temples of Karnak and Luxor on the east bank, the Valley of the Kings on the west.','Karnak is one of the largest religious complexes ever built. Across the river lie royal tombs such as Tutankhamun’s and the mortuary temple of Hatshepsut. World Heritage Site since 1979.','Inscribed','1979',true,true,2,'{"color":"#D4A017","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Luxor_Temple_R15.jpg/1280px-Luxor_Temple_R15.jpg","credit":"Marc Ryckaert","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Luxor_Temple_R15.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Luxor_Temple_Courtyard_&_Colonnade_of_Amon-Ophis_III_(9794840664).jpg/1280px-Luxor_Temple_Courtyard_&_Colonnade_of_Amon-Ophis_III_(9794840664).jpg","credit":"Gary Todd","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Luxor_Temple_Courtyard_&_Colonnade_of_Amon-Ophis_III_(9794840664).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Flickr_-_archer10_(Dennis)_-_Egypt-3A-028.jpg/1280px-Flickr_-_archer10_(Dennis)_-_Egypt-3A-028.jpg","credit":"Dennis G. Jarvis","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Flickr_-_archer10_(Dennis)_-_Egypt-3A-028.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/87/","https://en.wikipedia.org/wiki/Thebes,_Egypt"]'::jsonb)
