insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('historic-cairo','EGY','Historic Cairo',null,'heritage',30.05,31.26,'The medieval city of mosques, madrasas, hammams and fountains, founded in the 10th century.','Al-Azhar, one of the world’s oldest universities, and the Citadel of Saladin are part of it. Often called the “city of a thousand minarets”. World Heritage Site since 1979.','Founded','969 CE',true,true,3,'{"color":"#B5651D","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Al-Ghouryia.jpg/1280px-Al-Ghouryia.jpg","credit":"Ashashyou","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Al-Ghouryia.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/%D9%85%D8%B5%D8%B1_%D8%A7%D9%84%D8%B9%D8%B8%D9%8A%D9%85%D8%A9.jpg/1280px-%D9%85%D8%B5%D8%B1_%D8%A7%D9%84%D8%B9%D8%B8%D9%8A%D9%85%D8%A9.jpg","credit":"Kareem Tarek Hussein","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:%D9%85%D8%B5%D8%B1_%D8%A7%D9%84%D8%B9%D8%B8%D9%8A%D9%85%D8%A9.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Al-Imam_al-Shafi''i_Cemetery,_Cairo.jpg/1280px-Al-Imam_al-Shafi''i_Cemetery,_Cairo.jpg","credit":"Hassan Hamdy wahidy","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Al-Imam_al-Shafi''i_Cemetery,_Cairo.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/89/","https://en.wikipedia.org/wiki/Islamic_Cairo"]'::jsonb)
