insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('abu-simbel-philae','EGY','Nubian Monuments from Abu Simbel to Philae',null,'heritage',22.34,31.63,'The temples of Ramesses II at Abu Simbel and of Isis at Philae, among others, on the Nile in Nubia.','In the 1960s an international UNESCO campaign cut Abu Simbel into blocks and moved it uphill, away from the rising waters of Lake Nasser. That campaign inspired the World Heritage Convention.','Abu Simbel moved','1964–1968',true,true,4,'{"color":"#E3A857","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Nubian_Monuments_from_Abu_Simbel_to_Philae-108552.jpg/1280px-Nubian_Monuments_from_Abu_Simbel_to_Philae-108552.jpg","credit":"Christian Manhart","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Nubian_Monuments_from_Abu_Simbel_to_Philae-108552.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Nubian_Monuments_from_Abu_Simbel_to_Philae-108556.jpg/1280px-Nubian_Monuments_from_Abu_Simbel_to_Philae-108556.jpg","credit":"Christian Manhart","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Nubian_Monuments_from_Abu_Simbel_to_Philae-108556.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Nubian_Monuments_from_Abu_Simbel_to_Philae-108554.jpg/1280px-Nubian_Monuments_from_Abu_Simbel_to_Philae-108554.jpg","credit":"Christian Manhart","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Nubian_Monuments_from_Abu_Simbel_to_Philae-108554.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/88/","https://en.wikipedia.org/wiki/International_Campaign_to_Save_the_Monuments_of_Nubia"]'::jsonb)
