insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('giza-memphis','EGY','Memphis and its Necropolis: Giza to Dahshur',null,'heritage',29.98,31.13,'The Old Kingdom capital and its pyramid fields: Giza, Saqqara, Abusir and Dahshur.','The Great Pyramid of Khufu is the only one of the Seven Wonders of the Ancient World still standing. Djoser’s step pyramid at Saqqara is among the oldest large stone buildings. World Heritage Site since 1979.','Great Pyramid','~4,500 years old',true,true,5,'{"color":"#E8D5A9","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/af/All_Gizah_Pyramids.jpg/1280px-All_Gizah_Pyramids.jpg","credit":"Ricardo Liberato","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:All_Gizah_Pyramids.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Pyramids_of_Giza_and_boat_pit.jpg/1280px-Pyramids_of_Giza_and_boat_pit.jpg","credit":"kallerna","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Pyramids_of_Giza_and_boat_pit.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/All_pyramids_of_Giza_panorama_2.jpg/1280px-All_pyramids_of_Giza_panorama_2.jpg","credit":"kallerna","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:All_pyramids_of_Giza_panorama_2.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/86/","https://en.wikipedia.org/wiki/Memphis,_Egypt","https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza"]'::jsonb)
