insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('saint-catherine-sinai','EGY','Saint Catherine Area',null,'mountain',28.56,33.98,'The 6th-century Orthodox monastery of Saint Catherine at the foot of Mount Sinai.','One of the oldest working Christian monasteries, built under Justinian. The mountain is sacred to Christianity, Islam and Judaism. World Heritage Site since 2002.','Monastery built','~548–565 CE',true,true,6,'{"color":"#C1693C","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Mount_Moses.jpg/1280px-Mount_Moses.jpg","credit":"Mohammed Moussa","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Moses.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Saint_Catherine_Monastery_church_and_mosque_towers.jpg/1280px-Saint_Catherine_Monastery_church_and_mosque_towers.jpg","credit":"Florian Prischl","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Saint_Catherine_Monastery_church_and_mosque_towers.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Panorama_Mount_Sinai_south.jpg/1280px-Panorama_Mount_Sinai_south.jpg","credit":"Florian Prischl","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Panorama_Mount_Sinai_south.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/954/","https://en.wikipedia.org/wiki/Saint_Catherine''s_Monastery"]'::jsonb)
