insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('wadi-al-hitan','EGY','Wadi Al-Hitan','Whale Valley','desert',29.27,30.04,'Hundreds of fossil whale skeletons lying in the desert of the Fayoum, from a sea that covered it 40 million years ago.','The fossils of Basilosaurus and Dorudon still have small hind legs, showing how whales evolved from land mammals. Egypt’s first natural World Heritage Site (2005).','Fossil age','~40 million years',true,true,7,'{"color":"#F0E1C0","intensity":0.85,"motion":"sink"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Wadi_Al-Hitan_(Whale_Valley).jpg/1280px-Wadi_Al-Hitan_(Whale_Valley).jpg","credit":"Mohammed Moussa","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Wadi_Al-Hitan_(Whale_Valley).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Wadi_Al-Hitan_(Whale_Valley)-113614.jpg/1280px-Wadi_Al-Hitan_(Whale_Valley)-113614.jpg","credit":"Guy Debonnet","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Wadi_Al-Hitan_(Whale_Valley)-113614.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Wadi_Al-Hitan_(Whale_Valley)-113616.jpg/1280px-Wadi_Al-Hitan_(Whale_Valley)-113616.jpg","credit":"Guy Debonnet","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Wadi_Al-Hitan_(Whale_Valley)-113616.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1186/","https://en.wikipedia.org/wiki/Wadi_Al-Hitan"]'::jsonb)
