insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('white-desert','EGY','White Desert','Sahara el Beyda','desert',27.28,28.2,'Chalk towers and “mushroom” rocks sculpted by wind in the Farafra Depression.','The chalk is made of tiny marine fossils. In moonlight the formations glow like snow; the area has been protected since 2002.','Protected since','2002',false,true,8,'{"color":"#F5F1E6","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Egypt_White_Desert_The_Mushroom.jpg/1280px-Egypt_White_Desert_The_Mushroom.jpg","credit":"Nearodney","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Egypt_White_Desert_The_Mushroom.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Desert_blanc.jpg/1280px-Desert_blanc.jpg","credit":"Daniel Fafard","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Desert_blanc.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Champinnones_blancos.jpg/1280px-Champinnones_blancos.jpg","credit":"Silviapef","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Champinnones_blancos.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/White_Desert_National_Park"]'::jsonb)
