insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ras-muhammad','EGY','Ras Muhammad National Park',null,'coast',27.77,34.21,'The southern tip of Sinai, where the Gulfs of Suez and Aqaba meet over coral reefs.','Egypt’s first national park (1983). Its reef walls drop hundreds of metres, and its mangroves are among the most northerly in the world.','Established','1983',false,true,9,'{"color":"#1F9BBF","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Egypt,_Ras_Muhammad_national_park.jpg/1280px-Egypt,_Ras_Muhammad_national_park.jpg","credit":"Paul Grach","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Egypt,_Ras_Muhammad_national_park.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Alfombra_de_algas_amarillas,_parque_nacional_Ras_Muhammad,_Egipto,_2022-03-27,_DD_42.jpg/1280px-Alfombra_de_algas_amarillas,_parque_nacional_Ras_Muhammad,_Egipto,_2022-03-27,_DD_42.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Alfombra_de_algas_amarillas,_parque_nacional_Ras_Muhammad,_Egipto,_2022-03-27,_DD_42.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Underground_water_groove_in_Ras_Muhammad_National_Park.jpg/1280px-Underground_water_groove_in_Ras_Muhammad_National_Park.jpg","credit":"Hesham Kassem","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Underground_water_groove_in_Ras_Muhammad_National_Park.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Ras_Muhammad_National_Park"]'::jsonb)
