insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('gilf-kebir','EGY','Gilf Kebir',null,'landform',23.44,25.84,'A vast sandstone plateau in Egypt’s far south-west, one of the most remote places in the Sahara.','Its caves hold the “Cave of Swimmers” and the Cave of the Beasts, with painted figures from a wetter Sahara.','Plateau area','~7,770 km²',false,true,10,'{"color":"#B5502E","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/GilfKebirSouth.jpg/1280px-GilfKebirSouth.jpg","credit":"Roland Unger","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:GilfKebirSouth.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/f/fa/Gilf_Kebir_jan_2007_tourists_valley.jpg","credit":"Ilan Molcho","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Gilf_Kebir_jan_2007_tourists_valley.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Gilf_Kebir","https://en.wikipedia.org/wiki/Cave_of_Swimmers"]'::jsonb)
