insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('siwa-oasis','EGY','Siwa Oasis',null,'lake',29.21,25.52,'A palm and olive oasis near the Libyan border, with salt lakes and a town of mud-and-salt kershef.','Its Oracle of Amun was consulted by Alexander the Great. The Siwi people speak a Berber language, unlike the rest of Egypt.','Below sea level','~18 m',false,true,11,'{"color":"#6B8E23","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Siwa_Oasis_homes_(May_2007).jpg/1280px-Siwa_Oasis_homes_(May_2007).jpg","credit":"VascoPlanet Egypt","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Siwa_Oasis_homes_(May_2007).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Siwa_Oasis,_Qesm_Siwah,_Matrouh_Governorate,_Egypt_-_panoramio_(7).jpg/1280px-Siwa_Oasis,_Qesm_Siwah,_Matrouh_Governorate,_Egypt_-_panoramio_(7).jpg","credit":"mykola.rykov","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Siwa_Oasis,_Qesm_Siwah,_Matrouh_Governorate,_Egypt_-_panoramio_(7).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/The_way_to_siwa_oasis.jpg/1280px-The_way_to_siwa_oasis.jpg","credit":"Ahmed Emad H","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:The_way_to_siwa_oasis.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Siwa_Oasis"]'::jsonb)
