insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('steppe-eagle-suez','EGY','Steppe Eagle',null,'fauna',29.97,32.55,'A large migrating eagle that funnels through Suez and Sinai each spring and autumn, between Eurasia and East Africa.','The Red Sea flyway carries hundreds of thousands of raptors over Egypt. The steppe eagle has declined sharply and is listed as Endangered. The pin is at Suez.','IUCN status','Endangered',false,true,12,'{"color":"#8B5E34","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Aquila_nipalensis_orientalis_qtl1.jpg/1280px-Aquila_nipalensis_orientalis_qtl1.jpg","credit":"Quartl","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Aquila_nipalensis_orientalis_qtl1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Aquila_nipalensis_-_20100905.jpg/1280px-Aquila_nipalensis_-_20100905.jpg","credit":"H005","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Aquila_nipalensis_-_20100905.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Aquila_nipalensis_orientalis_qtl2.jpg/1280px-Aquila_nipalensis_orientalis_qtl2.jpg","credit":"Quartl","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Aquila_nipalensis_orientalis_qtl2.jpg"}]}'::jsonb,'Aquila nipalensis','["https://en.wikipedia.org/wiki/Steppe_eagle","https://www.gbif.org/species/search?q=Aquila%20nipalensis"]'::jsonb)
