insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('blue-lotus','EGY','Blue Lotus','sšn (ancient Egyptian)','flora',30.6,31.2,'A water lily of the Nile that opens at morning and closes at dusk, painted on tomb walls for thousands of years.','Ancient Egyptians linked it with the sun and rebirth; it appears in temple art and on Tutankhamun’s funerary objects. The pin is in the Nile Delta.','Opens','At sunrise',false,true,13,'{"color":"#4F6FD6","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Nymphaea_Caerulea_Aug_2009.jpg/1280px-Nymphaea_Caerulea_Aug_2009.jpg","credit":"Kemmi.1 (Stefan Kemmerling)","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Nymphaea_Caerulea_Aug_2009.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Nymphaea_caerulea-20091014-RM-115245.jpg/1280px-Nymphaea_caerulea-20091014-RM-115245.jpg","credit":"Ermell","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Nymphaea_caerulea-20091014-RM-115245.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Nymphaea_caerulea-20091014-RM-115358.jpg/1280px-Nymphaea_caerulea-20091014-RM-115358.jpg","credit":"Ermell","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Nymphaea_caerulea-20091014-RM-115358.jpg"}]}'::jsonb,'Nymphaea caerulea','["https://en.wikipedia.org/wiki/Nymphaea_caerulea","https://www.gbif.org/species/search?q=Nymphaea%20caerulea"]'::jsonb)
