insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tadrart-acacus','LBY','Rock-Art Sites of Tadrart Acacus',null,'rock',24.83,10.33,'A mountain range of dark sandstone arches near Ghat, with thousands of paintings and engravings.','The art spans from about 12,000 BCE to the 1st century CE, showing giraffes, elephants and later cattle and horses as the Sahara dried. World Heritage Site since 1985; on the List in Danger since 2016.','Art spans','~12,000 BCE–100 CE',true,true,1,'{"color":"#B5502E","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Libya_5076_Tadrart_Acacus_Luca_Galuzzi_2007.jpg/1280px-Libya_5076_Tadrart_Acacus_Luca_Galuzzi_2007.jpg","credit":"Luca Galuzzi (Lucag)","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Libya_5076_Tadrart_Acacus_Luca_Galuzzi_2007.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Rock-Art_Sites_of_Tadrart_Acacus-109792.jpg/1280px-Rock-Art_Sites_of_Tadrart_Acacus-109792.jpg","credit":"Yvon Fruneau","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Rock-Art_Sites_of_Tadrart_Acacus-109792.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Tadrart01.JPG/1280px-Tadrart01.JPG","credit":"Pir6mon","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Tadrart01.JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/287/","https://en.wikipedia.org/wiki/Acacus_Mountains"]'::jsonb)
