insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('cyrene','LBY','Cyrene',null,'heritage',32.82,21.86,'A Greek colony founded about 631 BCE in the Green Mountain, later one of the great Roman cities of Africa.','Its sanctuary of Apollo and Temple of Zeus rival those of Greece. Cyrene was famed for silphium, a medicinal plant traded until it vanished. On the List in Danger since 2016.','Founded','~631 BCE',true,true,2,'{"color":"#E8D5A9","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Archaeological_Site_of_Cyrene-109030.jpg/1280px-Archaeological_Site_of_Cyrene-109030.jpg","credit":"Francesco Bandarin","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Archaeological_Site_of_Cyrene-109030.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Archaeological_Site_of_Cyrene-109031.jpg/1280px-Archaeological_Site_of_Cyrene-109031.jpg","credit":"Francesco Bandarin","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Archaeological_Site_of_Cyrene-109031.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/6/61/Archaeological_Site_of_Cyrene-109025.jpg","credit":"Giovanni Boccardi","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Archaeological_Site_of_Cyrene-109025.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/190/","https://en.wikipedia.org/wiki/Cyrene,_Libya"]'::jsonb)
