insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ghadames','LBY','Old Town of Ghadamès','“the pearl of the desert”','heritage',30.13,9.5,'An oasis town of linked mud-brick houses and covered alleys on the old caravan routes.','Houses have separate levels for families and rooftop walkways for women. The town stays cool in desert heat. World Heritage Site since 1986.','Inscribed','1986',true,true,3,'{"color":"#F2E3C9","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Ghadames,_2006.jpg/1280px-Ghadames,_2006.jpg","credit":"Teogomez","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Ghadames,_2006.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Ghadames_2.jpg/1280px-Ghadames_2.jpg","credit":"Teogomez","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Ghadames_2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Ghadames_3.jpg/1280px-Ghadames_3.jpg","credit":"Teogomez","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Ghadames_3.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/362/","https://en.wikipedia.org/wiki/Ghadames"]'::jsonb)
