insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('leptis-magna','LBY','Leptis Magna',null,'heritage',32.64,14.29,'One of the best-preserved Roman cities, enlarged by the emperor Septimius Severus, who was born here.','Its theatre, basilica, harbour and the Arch of Septimius Severus survived largely because sand covered them. On the List in Danger since 2016.','Hometown of','Septimius Severus',true,true,4,'{"color":"#D9A066","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Archaeological_Site_of_Leptis_Magna-108965.jpg/1280px-Archaeological_Site_of_Leptis_Magna-108965.jpg","credit":"Francesco Bandarin","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Archaeological_Site_of_Leptis_Magna-108965.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/98/Archaeological_Site_of_Leptis_Magna-108967.jpg/1280px-Archaeological_Site_of_Leptis_Magna-108967.jpg","credit":"Francesco Bandarin","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Archaeological_Site_of_Leptis_Magna-108967.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Archaeological_site_of_leptis_magna.jpg/1280px-Archaeological_site_of_leptis_magna.jpg","credit":"Retaj Alsheikh","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Archaeological_site_of_leptis_magna.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/183/","https://en.wikipedia.org/wiki/Leptis_Magna"]'::jsonb)
