insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sabratha','LBY','Sabratha',null,'heritage',32.81,12.48,'A Phoenician trading post that became a Roman city on the Tripolitanian coast.','Its three-storey theatre, built around 190 CE, looks out to the Mediterranean. On the List in Danger since 2016.','Theatre built','~190 CE',true,true,5,'{"color":"#C8784A","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Archaeological_Site_of_Sabratha_Roman_Theater.jpg/1280px-Archaeological_Site_of_Sabratha_Roman_Theater.jpg","credit":"Amanyalbadry","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Archaeological_Site_of_Sabratha_Roman_Theater.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Archaeological_site_of_Sabratha,_Libya.jpg/1280px-Archaeological_site_of_Sabratha,_Libya.jpg","credit":"Soma dntst Mohammed","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Archaeological_site_of_Sabratha,_Libya.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Theatre_of_Sabratha,_Libya.jpg/1280px-Theatre_of_Sabratha,_Libya.jpg","credit":"Wikimedia Commons contributor","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Theatre_of_Sabratha,_Libya.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/184/","https://en.wikipedia.org/wiki/Sabratha"]'::jsonb)
