insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('waw-an-namus','LBY','Waw an Namus',null,'volcano',24.9,17.75,'A black volcanic crater in the middle of the Sahara, holding small salty lakes ringed with reeds.','Its dark ash field stands out from space against the sand. The crater is about 4 km across, one of the most isolated volcanoes on Earth.','Crater width','~4 km',false,true,6,'{"color":"#2F3E46","intensity":0.85,"motion":"sink"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Waw_an-Namus-zentraler_Krater.jpg/1280px-Waw_an-Namus-zentraler_Krater.jpg","credit":"StFr","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Waw_an-Namus-zentraler_Krater.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/d/d8/Waw_an_namus_from_top.jpg","credit":"ruba_ch / Rudolf Baumann","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Waw_an_namus_from_top.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Waw_An_Namus_-_STS052.JPG/1280px-Waw_An_Namus_-_STS052.JPG","credit":"NASA","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Waw_An_Namus_-_STS052.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Waw_an_Namus"]'::jsonb)
