insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('jebel-akhdar-libya','LBY','Jebel Akhdar','the Green Mountain','forest',32.6,21.47,'A wooded limestone upland in Cyrenaica, the wettest part of Libya.','Juniper and cypress woods and fertile valleys made it the heartland of ancient Cyrene, in a country that is mostly desert.','Rainfall','Up to ~600 mm/yr',false,true,7,'{"color":"#6A994E","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Al_Bakour4.JPG/1280px-Al_Bakour4.JPG","credit":"Maher A. A. Abdussalam","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Al_Bakour4.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Cows_graze_near_Wadi_Jarjarama.JPG/1280px-Cows_graze_near_Wadi_Jarjarama.JPG","credit":"Maher27777","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Cows_graze_near_Wadi_Jarjarama.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Al_Marj_Tacnis_road.JPG/1280px-Al_Marj_Tacnis_road.JPG","credit":"Maher A. A. Abdussalam","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Al_Marj_Tacnis_road.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Jebel_Akhdar_(Libya)"]'::jsonb)
