insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ubari-lakes','LBY','Ubari Lakes',null,'lake',26.79,12.78,'Palm-fringed salt lakes among the dunes of the Ubari Sand Sea in the Fezzan.','Fed by ancient groundwater, the lakes are saltier than the sea. Lakes such as Gaberoun and Umm al-Maa are falling as the water table drops.','Region','Fezzan',false,true,8,'{"color":"#2E86AB","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Libya_5391_Ubari_Lakes_Luca_Galuzzi_2007.jpg/1280px-Libya_5391_Ubari_Lakes_Luca_Galuzzi_2007.jpg","credit":"Luca Galuzzi (Lucag)","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Libya_5391_Ubari_Lakes_Luca_Galuzzi_2007.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Simon_Reeve_IMG_2583.JPG/1280px-Simon_Reeve_IMG_2583.JPG","credit":"Amy Chapman","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Simon_Reeve_IMG_2583.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Ubari_Sand_Sea"]'::jsonb)
