insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('barbary-sheep','LBY','Barbary Sheep','aoudad','fauna',25.2,10.6,'A sure-footed wild goat-sheep of the Sahara’s rocky massifs, with a long fringe of hair on its throat and forelegs.','It can live without drinking for long periods, getting water from plants. It appears in Saharan rock art. The pin is in the Acacus.','IUCN status','Vulnerable',false,true,9,'{"color":"#B07D4B","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/3/3d/Barbary_sheep.webm/Barbary_sheep.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/3/3d/Barbary_sheep.webm/Barbary_sheep.webm.360p.mpeg4.mov","credit":"Altes","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Barbary_sheep.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Barbary_Sheep_(Ammotragus_lervia).JPG/1280px-Barbary_Sheep_(Ammotragus_lervia).JPG","credit":"The High Fin Sperm Whale","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Barbary_Sheep_(Ammotragus_lervia).JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/BarbarySheep4.jpg/1280px-BarbarySheep4.jpg","credit":"Rei","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:BarbarySheep4.jpg"}]}'::jsonb,'Ammotragus lervia','["https://en.wikipedia.org/wiki/Barbary_sheep","https://www.gbif.org/species/search?q=Ammotragus%20lervia"]'::jsonb)
