insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('pomegranate','LBY','Pomegranate',null,'flora',32.5,13.2,'A fruit tree grown in Mediterranean gardens and oases since antiquity, with ruby seeds inside a leathery skin.','Cultivated across North Africa since Phoenician and Roman times; the Romans called it the “Punic apple”. The pin is a representative point near Tripoli.','Roman name','malum punicum',false,true,10,'{"color":"#C1121F","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Punica_granatum_004.JPG/1280px-Punica_granatum_004.JPG","credit":"H. Zell","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Punica_granatum_004.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Punica_granatum_L._Nana.jpg/1280px-Punica_granatum_L._Nana.jpg","credit":"Jebulon","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Punica_granatum_L._Nana.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Punica_granatum_(pomegranate)_flower_-_relative_size.jpeg/1280px-Punica_granatum_(pomegranate)_flower_-_relative_size.jpeg","credit":"Sankarshansen","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Punica_granatum_(pomegranate)_flower_-_relative_size.jpeg"}]}'::jsonb,'Punica granatum','["https://en.wikipedia.org/wiki/Pomegranate","https://www.gbif.org/species/search?q=Punica%20granatum"]'::jsonb)
