insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('medina-of-fez','MAR','Medina of Fez','Fès el Bali','heritage',34.06,-4.97,'One of the largest car-free urban areas in the world, founded in the 9th century.','Al-Qarawiyyin, founded in 859, is often cited as the oldest continually operating university. The Chouara tannery still dyes leather in stone vats. World Heritage Site since 1981.','Al-Qarawiyyin','859 CE',true,true,1,'{"color":"#2D4BA0","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Delivery_by_mule_in_Medina_of_Fez.jpg/1280px-Delivery_by_mule_in_Medina_of_Fez.jpg","credit":"Subotai85","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Delivery_by_mule_in_Medina_of_Fez.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Medina_of_Fez_082023_005.jpg/1280px-Medina_of_Fez_082023_005.jpg","credit":"Yamen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Fez_082023_005.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Medina_of_Fez_082023_034.jpg/1280px-Medina_of_Fez_082023_034.jpg","credit":"Yamen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Fez_082023_034.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/170/","https://en.wikipedia.org/wiki/Fes_el_Bali"]'::jsonb)
