insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('medina-of-marrakesh','MAR','Medina of Marrakesh',null,'heritage',31.63,-7.99,'The red city founded by the Almoravids in 1070, with the Koutoubia minaret and the square of Jemaa el-Fnaa.','Jemaa el-Fnaa, with its storytellers, musicians and food stalls, helped inspire UNESCO’s list of Intangible Cultural Heritage. World Heritage Site since 1985.','Founded','1070',true,true,2,'{"color":"#C65D3B","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Medina_of_Marrakesh_Sept2022_004.jpg/1280px-Medina_of_Marrakesh_Sept2022_004.jpg","credit":"Yamen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Marrakesh_Sept2022_004.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Medina_of_Marrakesh_Sept2022_048.jpg/1280px-Medina_of_Marrakesh_Sept2022_048.jpg","credit":"Yamen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Marrakesh_Sept2022_048.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Medina_of_Marrakesh_Sept2022_089.jpg/1280px-Medina_of_Marrakesh_Sept2022_089.jpg","credit":"Yamen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Marrakesh_Sept2022_089.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/331/","https://en.wikipedia.org/wiki/Marrakesh"]'::jsonb)
