insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ait-ben-haddou','MAR','Ksar of Aït-Ben-Haddou',null,'heritage',31.05,-7.13,'A fortified village of earthen kasbahs stacked up a hillside on the old caravan road from the Sahara to Marrakesh.','A classic example of southern Moroccan earthen architecture, and a backdrop for many films. World Heritage Site since 1987.','Inscribed','1987',true,true,3,'{"color":"#B5502E","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/A%C3%AFt_Benhaddou_view_from_above.jpg/1280px-A%C3%AFt_Benhaddou_view_from_above.jpg","credit":"Elena Tatiana Chis","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:A%C3%AFt_Benhaddou_view_from_above.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/A%C3%AFt_Benhaddou_view_from_a_restaurant.jpg/1280px-A%C3%AFt_Benhaddou_view_from_a_restaurant.jpg","credit":"Elena Tatiana Chis","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:A%C3%AFt_Benhaddou_view_from_a_restaurant.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/A%C3%AFt_Benhaddou_walk_on_the_streets_souvenir_shop.jpg/1280px-A%C3%AFt_Benhaddou_walk_on_the_streets_souvenir_shop.jpg","credit":"Elena Tatiana Chis","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:A%C3%AFt_Benhaddou_walk_on_the_streets_souvenir_shop.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/444/","https://en.wikipedia.org/wiki/Aït_Benhaddou"]'::jsonb)
