insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('meknes','MAR','Historic City of Meknes',null,'heritage',33.89,-5.56,'The imperial capital of Sultan Moulay Ismail, ringed by some 40 km of walls.','The monumental Bab Mansour gate and vast royal granaries and stables show the scale of his 17th-century projects. World Heritage Site since 1996.','City walls','~40 km',true,true,4,'{"color":"#3E8E7E","intensity":0.85,"motion":"orbit"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/c/cf/Bab_Mensour-_The_Poem.webm/Bab_Mensour-_The_Poem.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/c/cf/Bab_Mensour-_The_Poem.webm/Bab_Mensour-_The_Poem.webm.360p.mpeg4.mov","credit":"Karmouch","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Bab_Mensour-_The_Poem.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Classical_Architecture_and_Street_Vendor_-_Medina_(Old_City)_-_Meknes_-_Morocco.jpg/1280px-Classical_Architecture_and_Street_Vendor_-_Medina_(Old_City)_-_Meknes_-_Morocco.jpg","credit":"Adam Jones, Ph.D.","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Classical_Architecture_and_Street_Vendor_-_Medina_(Old_City)_-_Meknes_-_Morocco.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Medina,_Meknes,_Morocco_-_panoramio_(14).jpg/1280px-Medina,_Meknes,_Morocco_-_panoramio_(14).jpg","credit":"Ben Bender","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Medina,_Meknes,_Morocco_-_panoramio_(14).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/793/","https://en.wikipedia.org/wiki/Meknes"]'::jsonb)
