insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('volubilis','MAR','Volubilis',null,'heritage',34.07,-5.55,'A Berber and Roman city on fertile plains below the Zerhoun hills, with fine floor mosaics still in place.','A capital of Mauretania and a Roman frontier town; later Idris I came here to found the first Moroccan dynasty. World Heritage Site since 1997.','Inscribed','1997',true,true,5,'{"color":"#D9A066","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Panoramic_view_of_Volubilis_-_Morocco.jpg/1280px-Panoramic_view_of_Volubilis_-_Morocco.jpg","credit":"Paul Barker Hemings","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Panoramic_view_of_Volubilis_-_Morocco.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Volubilis,Morocco.jpg/1280px-Volubilis,Morocco.jpg","credit":"Marcin Sochacki (Wanted)","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Volubilis,Morocco.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Morocco_-_ancient_Roman_remains_in_Volubilis.JPG/1280px-Morocco_-_ancient_Roman_remains_in_Volubilis.JPG","credit":"High Contrast","license":"CC BY 3.0 DE","source":"https://commons.wikimedia.org/wiki/File:Morocco_-_ancient_Roman_remains_in_Volubilis.JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/836/","https://en.wikipedia.org/wiki/Volubilis"]'::jsonb)
