insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tetouan-medina','MAR','Medina of Tétouan','Titawin','heritage',35.57,-5.37,'A whitewashed medina below the Rif, rebuilt by Andalusian refugees after 1492.','It is one of the most complete medinas in Morocco and shows strong Andalusian influence. World Heritage Site since 1997.','Rebuilt from','late 15th c.',true,true,6,'{"color":"#F2E3C9","intensity":0.85,"motion":"orbit"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/59/Medina_of_Tetouan_traditional_tannery_2.webm/Medina_of_Tetouan_traditional_tannery_2.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/59/Medina_of_Tetouan_traditional_tannery_2.webm/Medina_of_Tetouan_traditional_tannery_2.webm.360p.mpeg4.mov","credit":"Ideophagous","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Tetouan_traditional_tannery_2.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Medina_of_T%C3%A9touan.jpg/1280px-Medina_of_T%C3%A9touan.jpg","credit":"Alamrani.a","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Medina_of_T%C3%A9touan.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Rue_Chahboun_Medina_T%C3%A9touan_MedinaStories_Mlnzwyibz_09112020.jpg/1280px-Rue_Chahboun_Medina_T%C3%A9touan_MedinaStories_Mlnzwyibz_09112020.jpg","credit":"Yamen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Rue_Chahboun_Medina_T%C3%A9touan_MedinaStories_Mlnzwyibz_09112020.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/837/","https://en.wikipedia.org/wiki/Tétouan"]'::jsonb)
