insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('essaouira','MAR','Medina of Essaouira','Mogador','coast',31.51,-9.77,'An 18th-century fortified port on the Atlantic, laid out by a French engineer for the sultan.','It blends European military design with a North African medina, and it is known for its wind, gnawa music and thuya-wood crafts. World Heritage Site since 2001.','Built from','1760s',true,true,7,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Medina_of_Essaouira_(formerly_Mogador)-113160.jpg/1280px-Medina_of_Essaouira_(formerly_Mogador)-113160.jpg","credit":"Leila Maziz","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Essaouira_(formerly_Mogador)-113160.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Medina_of_Essaouira_(formerly_Mogador)-113167.jpg/1280px-Medina_of_Essaouira_(formerly_Mogador)-113167.jpg","credit":"Leila Maziz","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Essaouira_(formerly_Mogador)-113167.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Medina_of_Essaouira_(formerly_Mogador)-113171.jpg/1280px-Medina_of_Essaouira_(formerly_Mogador)-113171.jpg","credit":"Leila Maziz","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Essaouira_(formerly_Mogador)-113171.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/753/","https://en.wikipedia.org/wiki/Medina_of_Essaouira"]'::jsonb)
