insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mazagan','MAR','Portuguese City of Mazagan','El Jadida','heritage',33.26,-8.5,'A Portuguese Renaissance fortress on the Atlantic, built from 1514.','Its vaulted underground cistern, where light falls through a single opening onto shallow water, is the town’s best-known sight. World Heritage Site since 2004.','Fortified from','1514',true,true,8,'{"color":"#1E5AA8","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/El_Jadida_cistern.jpg/1280px-El_Jadida_cistern.jpg","credit":"Axel Rouvin","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:El_Jadida_cistern.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/La_Citerne_portugaise.jpg/1280px-La_Citerne_portugaise.jpg","credit":"Guilandre","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:La_Citerne_portugaise.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Water_reflection_Portuguese_Cistern.jpg/1280px-Water_reflection_Portuguese_Cistern.jpg","credit":"Alamrani.a","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Water_reflection_Portuguese_Cistern.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1058/","https://en.wikipedia.org/wiki/El_Jadida"]'::jsonb)
