insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('rabat-heritage','MAR','Rabat, Modern Capital and Historic City',null,'heritage',34.02,-6.84,'The capital on the Bou Regreg, joining the Kasbah of the Udayas and Hassan Tower with a 20th-century city plan.','Inscribed in 2012 for its dialogue between Arab-Muslim heritage and modern European urbanism; Hassan Tower is the unfinished minaret of a 12th-century mosque.','Inscribed','2012',true,true,9,'{"color":"#E8A33D","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Kasbah_Oudayas_exterior.jpg/1280px-Kasbah_Oudayas_exterior.jpg","credit":"Davide Cesare Veniani","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Kasbah_Oudayas_exterior.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/The_streets_inside_the_Kasbah_of_the_Udayas,_Rabat,_Morocco.jpg/1280px-The_streets_inside_the_Kasbah_of_the_Udayas,_Rabat,_Morocco.jpg","credit":"Alllexxxis","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:The_streets_inside_the_Kasbah_of_the_Udayas,_Rabat,_Morocco.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Kasbah_of_the_Udayas_2.jpg/1280px-Kasbah_of_the_Udayas_2.jpg","credit":"Dieglop","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kasbah_of_the_Udayas_2.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1401/","https://en.wikipedia.org/wiki/Kasbah_of_the_Udayas"]'::jsonb)
