insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('jbel-toubkal','MAR','Jbel Toubkal',null,'mountain',31.06,-7.92,'The highest peak in North Africa, in the High Atlas south of Marrakesh.','At 4,167 m it is often snow-capped in winter. Berber villages in the Imlil valley are the starting point of the climb.','Height','4,167 m',false,true,10,'{"color":"#5B6C8F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/View_from_Toubkal_west_flank.jpg/1280px-View_from_Toubkal_west_flank.jpg","credit":"ThartmannWiki","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:View_from_Toubkal_west_flank.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Veronica-Jbel_Toubkal_II.jpg/1280px-Veronica-Jbel_Toubkal_II.jpg","credit":"David","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Veronica-Jbel_Toubkal_II.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Spring_blossom_Toubkal_National_Park.jpg/1280px-Spring_blossom_Toubkal_National_Park.jpg","credit":"Toni Wöhrl","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Spring_blossom_Toubkal_National_Park.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Toubkal"]'::jsonb)
