insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ouzoud-falls','MAR','Ouzoud Falls',null,'waterfall',32.02,-6.72,'A tiered waterfall of about 110 m dropping into the gorge of the El Abid River in the Middle Atlas.','Barbary macaques live in the olive groves around the falls. The name comes from the Berber word for olive.','Drop','~110 m',false,true,11,'{"color":"#7BDFF2","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Cascade_Ouzoud.jpg/1280px-Cascade_Ouzoud.jpg","credit":"leila Kh","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cascade_Ouzoud.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Cascade_d''Ouzoud.jpg/1280px-Cascade_d''Ouzoud.jpg","credit":"Houssain tork","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cascade_d''Ouzoud.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Azoud_falls_Morocco.jpg/1280px-Azoud_falls_Morocco.jpg","credit":"Zagoravive","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Azoud_falls_Morocco.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Ouzoud_Falls"]'::jsonb)
