insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('erg-chebbi','MAR','Erg Chebbi',null,'desert',31.15,-3.98,'A field of orange dunes near Merzouga, on the western edge of the Sahara.','Its dunes rise up to about 150 m. After rare rains a lake forms nearby and flamingos sometimes visit.','Dune height','Up to ~150 m',false,true,12,'{"color":"#E07A3F","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Erg_chebbi_sunrise.jpg/1280px-Erg_chebbi_sunrise.jpg","credit":"JanSuchy","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Erg_chebbi_sunrise.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Morocco_Africa_Flickr_Rosino_December_2005_84514010.jpg/1280px-Morocco_Africa_Flickr_Rosino_December_2005_84514010.jpg","credit":"Rosino","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Morocco_Africa_Flickr_Rosino_December_2005_84514010.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Erg_Chebbi"]'::jsonb)
