insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('todgha-gorge','MAR','Todgha Gorge',null,'gorge',31.59,-5.59,'A limestone canyon in the High Atlas, with walls up to about 400 m and a gap as narrow as about 10 m.','The Todgha River cut through the eastern High Atlas here; the gorge is a major rock-climbing area.','Wall height','Up to ~400 m',false,true,13,'{"color":"#C65D3B","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Todgha_Gorge_from_above.jpg/1280px-Todgha_Gorge_from_above.jpg","credit":"ThartmannWiki","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Todgha_Gorge_from_above.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Todgha_Gorge_walking_through_02.jpg/1280px-Todgha_Gorge_walking_through_02.jpg","credit":"Elena Tatiana Chis","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Todgha_Gorge_walking_through_02.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Todgha_Gorge_walking_through_01.jpg/1280px-Todgha_Gorge_walking_through_01.jpg","credit":"Elena Tatiana Chis","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Todgha_Gorge_walking_through_01.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Todgha_Gorges"]'::jsonb)
