insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('barbary-macaque','MAR','Barbary Macaque','magot','fauna',33.4,-5.2,'The only wild primate north of the Sahara, living in the cedar forests of the Atlas and Rif.','Males help carry and care for infants, unusual among macaques. It is Endangered; Morocco’s Middle Atlas cedar forests near Azrou hold the largest population. A small introduced group lives on Gibraltar.','IUCN status','Endangered',false,true,14,'{"color":"#A47148","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Gibraltar_Barbary_Macaque.jpg/1280px-Gibraltar_Barbary_Macaque.jpg","credit":"RedCoat","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Gibraltar_Barbary_Macaque.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Macaca_sylvanus_head_2011_Gibraltar.jpg/1280px-Macaca_sylvanus_head_2011_Gibraltar.jpg","credit":"Sprok","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Macaca_sylvanus_head_2011_Gibraltar.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Macaca_sylvanus_feet_and_hands.JPG/1280px-Macaca_sylvanus_feet_and_hands.JPG","credit":"Grez","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Macaca_sylvanus_feet_and_hands.JPG"}]}'::jsonb,'Macaca sylvanus','["https://en.wikipedia.org/wiki/Barbary_macaque","https://www.gbif.org/species/search?q=Macaca%20sylvanus"]'::jsonb)
