insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('argan-tree','MAR','Argan Tree',null,'flora',30.5,-9.2,'A thorny, drought-hardy tree of south-west Morocco whose kernels give argan oil.','Goats climb its branches to eat the fruit. Women’s cooperatives press the oil by hand; the argan area is a UNESCO biosphere reserve and the know-how is intangible heritage.','Native range','South-west Morocco',false,true,15,'{"color":"#7A9A3A","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Argan_Tree_near_Tafraoute.jpg/1280px-Argan_Tree_near_Tafraoute.jpg","credit":"Bjørn Christian Tørrissen","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Argan_Tree_near_Tafraoute.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/An_Argan_tree_standing_alone_in_nowhere.JPG/1280px-An_Argan_tree_standing_alone_in_nowhere.JPG","credit":"F.Benotman","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:An_Argan_tree_standing_alone_in_nowhere.JPG"}]}'::jsonb,'Sideroxylon spinosum','["https://en.wikipedia.org/wiki/Argania","https://www.gbif.org/species/search?q=Sideroxylon%20spinosum"]'::jsonb)
