insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('meroe','SDN','Archaeological Sites of the Island of Meroe',null,'heritage',16.93,33.72,'The steep pyramids and royal city of the Kingdom of Kush, between the Nile and the Atbara River.','Meroë was a capital from the 8th century BCE to the 4th century CE, and a centre of iron-working. Its more than 200 pyramids are smaller and steeper than Egypt’s. World Heritage Site since 2011.','Pyramids','200+',true,true,1,'{"color":"#C8784A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/Archaeological_Sites_of_the_Island_of_Meroe-114970.jpg/1280px-Archaeological_Sites_of_the_Island_of_Meroe-114970.jpg","credit":"Ron Van Oers","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Archaeological_Sites_of_the_Island_of_Meroe-114970.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Archaeological_Sites_of_the_Island_of_Meroe-114973.jpg/1280px-Archaeological_Sites_of_the_Island_of_Meroe-114973.jpg","credit":"Ron Van Oers","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Archaeological_Sites_of_the_Island_of_Meroe-114973.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Archaeological_Sites_of_the_Island_of_Meroe-114975.jpg/1280px-Archaeological_Sites_of_the_Island_of_Meroe-114975.jpg","credit":"Ron Van Oers","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Archaeological_Sites_of_the_Island_of_Meroe-114975.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1336/","https://en.wikipedia.org/wiki/Meroë"]'::jsonb)
