insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('gebel-barkal','SDN','Gebel Barkal and the Sites of the Napatan Region',null,'heritage',18.53,31.82,'A flat-topped sandstone mountain by the Nile, held sacred by Egyptians and Kushites as the home of Amun.','Its temples, palaces and the royal tombs at El-Kurru and Nuri belong to the Napatan kings who ruled Egypt as its 25th Dynasty. World Heritage Site since 2003.','Mountain height','~98 m',true,true,2,'{"color":"#D9A54C","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Gebel_Barkal_and_the_Sites_of_the_Napatan_Region-114660.jpg/1280px-Gebel_Barkal_and_the_Sites_of_the_Napatan_Region-114660.jpg","credit":"Maria Gropa","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Gebel_Barkal_and_the_Sites_of_the_Napatan_Region-114660.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Gebel_Barkal_and_the_Sites_of_the_Napatan_Region-114662.jpg/1280px-Gebel_Barkal_and_the_Sites_of_the_Napatan_Region-114662.jpg","credit":"Maria Gropa","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Gebel_Barkal_and_the_Sites_of_the_Napatan_Region-114662.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Gebel_Barkal_and_the_Sites_of_the_Napatan_Region-114664.jpg/1280px-Gebel_Barkal_and_the_Sites_of_the_Napatan_Region-114664.jpg","credit":"Maria Gropa","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Gebel_Barkal_and_the_Sites_of_the_Napatan_Region-114664.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1073/","https://en.wikipedia.org/wiki/Jebel_Barkal"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sanganeb-dungonab','SDN','Sanganeb and Dungonab Bay',null,'coast',21,37.18,'An isolated coral atoll and a coastal bay on Sudan’s Red Sea coast, north of Port Sudan.','Dungonab Bay and Mukkawar Island host dugongs, manta rays and nesting turtles. The site was inscribed as natural World Heritage in 2016.','Inscribed','2016',true,true,3,'{"color":"#1A9E8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Coral_Reef_in_the_Red_Sea.JPG/1280px-Coral_Reef_in_the_Red_Sea.JPG","credit":"Mahmoud Habeeb","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Coral_Reef_in_the_Red_Sea.JPG"}],"note":"Red Sea reef stand-in — no open footage of Sanganeb or Dungonab yet."}'::jsonb,null,'["https://whc.unesco.org/en/list/262/","https://en.wikipedia.org/wiki/Sanganeb","https://en.wikipedia.org/wiki/Dungonab_Bay"]'::jsonb)
