insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('jebel-marra','SDN','Jebel Marra','Marrah Mountains','volcano',12.94,24.24,'A volcanic massif in Darfur rising to about 3,042 m, with crater lakes in its summit caldera.','The Deriba caldera holds two lakes. The mountains catch rain and stay green, with waterfalls and orchards, in an otherwise arid region.','Height','~3,042 m',false,true,4,'{"color":"#557A46","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Sudan_Jebel_Marra_Deriba_Lakes.jpg/1280px-Sudan_Jebel_Marra_Deriba_Lakes.jpg","credit":"J Williams (Hammy07)","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Sudan_Jebel_Marra_Deriba_Lakes.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Marrah_Mountains_waterfall_-_Sudan.jpg/1280px-Marrah_Mountains_waterfall_-_Sudan.jpg","credit":"Mohamed Siddig Abdelaziz","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Marrah_Mountains_waterfall_-_Sudan.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/ISS-64_Deriba_caldera_in_the_Marrah_Mountains_in_Darfur,_Sudan.jpg/1280px-ISS-64_Deriba_caldera_in_the_Marrah_Mountains_in_Darfur,_Sudan.jpg","credit":"NASA","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:ISS-64_Deriba_caldera_in_the_Marrah_Mountains_in_Darfur,_Sudan.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Marrah_Mountains"]'::jsonb)
