insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dinder','SDN','Dinder National Park',null,'savanna',12,35.23,'A savanna and floodplain park on the Ethiopian border, with oxbow lakes called mayas.','It is a UNESCO biosphere reserve and an important wetland for waterbirds; it connects with Ethiopia’s Alatish National Park.','Area','~10,000 km²',false,true,5,'{"color":"#8FB339","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/%D8%A7%D9%84%D8%AF%D9%86%D8%AF%D8%B1.jpg/1280px-%D8%A7%D9%84%D8%AF%D9%86%D8%AF%D8%B1.jpg","credit":"محسن الفكي","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:%D8%A7%D9%84%D8%AF%D9%86%D8%AF%D8%B1.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Dinder_National_Park"]'::jsonb)
