insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bayuda-desert','SDN','Bayuda Desert',null,'volcano',18.33,32.75,'A desert of black volcanic cones and craters inside the great bend of the Nile.','The Bayuda volcanic field has dozens of cinder cones and maar craters, some of them very young in geological terms.','Area','~100,000 km²',false,true,6,'{"color":"#3D3A4B","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/2/29/BayudaDesertWell.jpg","credit":"Clemens Schmillen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:BayudaDesertWell.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Bayuda_Vulkanfeld.jpg/1280px-Bayuda_Vulkanfeld.jpg","credit":"NASA","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Bayuda_Vulkanfeld.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Bayuda_Desert"]'::jsonb)
