insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('secretarybird','SDN','Secretarybird',null,'fauna',12.2,34.9,'A long-legged eagle that hunts on foot, stamping snakes and lizards to death in the grass.','Its kick lasts a fraction of a second and is aimed with great precision. It is on Sudan’s coat of arms, and is listed as Endangered. The pin is a representative point near Dinder.','IUCN status','Endangered',false,true,7,'{"color":"#3A6EA5","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/3/36/Secretarybird_(Sagittarius_serpentarius)_hunting_in_the_grass_....webm/Secretarybird_(Sagittarius_serpentarius)_hunting_in_the_grass_....webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/3/36/Secretarybird_(Sagittarius_serpentarius)_hunting_in_the_grass_....webm/Secretarybird_(Sagittarius_serpentarius)_hunting_in_the_grass_....webm.360p.mpeg4.mov","credit":"Bernard DUPONT","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Secretarybird_(Sagittarius_serpentarius)_hunting_in_the_grass_....webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Sagittarius_serpentarius_Sekret%C3%A4r.JPG/1280px-Sagittarius_serpentarius_Sekret%C3%A4r.JPG","credit":"Yoky","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Sagittarius_serpentarius_Sekret%C3%A4r.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Sagittarius_serpentarius_qtl1.jpg/1280px-Sagittarius_serpentarius_qtl1.jpg","credit":"Quartl","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Sagittarius_serpentarius_qtl1.jpg"}]}'::jsonb,'Sagittarius serpentarius','["https://en.wikipedia.org/wiki/Secretarybird","https://www.gbif.org/species/search?q=Sagittarius%20serpentarius"]'::jsonb)
