insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('gum-arabic-tree','SDN','Gum Arabic Tree','hashab','flora',13.2,30.2,'A small thorny tree of the Sahel whose resin is gum arabic, used in food, drinks and paints.','Sudan’s “gum belt” in Kordofan and Darfur supplies much of the world’s gum arabic. The trees also fix nitrogen and hold back the desert. The pin is in Kordofan.','Gum belt','Kordofan · Darfur',false,true,8,'{"color":"#D9A54C","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Senegalia_senegal_Saifoulaye_Kanon.jpg/1280px-Senegalia_senegal_Saifoulaye_Kanon.jpg","credit":"Saifoulaye KANON","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Senegalia_senegal_Saifoulaye_Kanon.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Senegalia_senegal_(kummat).jpg/1280px-Senegalia_senegal_(kummat).jpg","credit":"WikiPanti","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Senegalia_senegal_(kummat).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Senegalia_senegal_var._leiorachis_20D_3939.jpg/1280px-Senegalia_senegal_var._leiorachis_20D_3939.jpg","credit":"SAplants","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Senegalia_senegal_var._leiorachis_20D_3939.jpg"}]}'::jsonb,'Senegalia senegal','["https://en.wikipedia.org/wiki/Senegalia_senegal","https://en.wikipedia.org/wiki/Gum_arabic"]'::jsonb)
