insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('el-jem','TUN','Amphitheatre of El Jem','Thysdrus','heritage',35.3,10.71,'A 3rd-century Roman amphitheatre that could seat about 35,000 people, standing in a small town on the plain.','One of the largest amphitheatres of the Roman world and among the best preserved. World Heritage Site since 1979.','Seats','~35,000',true,true,1,'{"color":"#E2B04A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/2e/El_Jem_amphitheatre_video_no_text_27102020.webm/El_Jem_amphitheatre_video_no_text_27102020.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/2e/El_Jem_amphitheatre_video_no_text_27102020.webm/El_Jem_amphitheatre_video_no_text_27102020.webm.360p.mpeg4.mov","credit":"Yamen and contributors","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:El_Jem_amphitheatre_video_no_text_27102020.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Anfiteatro,_El_Jem,_T%C3%BAnez,_2016-09-04,_DD_08.jpg/1280px-Anfiteatro,_El_Jem,_T%C3%BAnez,_2016-09-04,_DD_08.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Anfiteatro,_El_Jem,_T%C3%BAnez,_2016-09-04,_DD_08.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Amphi_El_Jem.jpg/1280px-Amphi_El_Jem.jpg","credit":"Cimoi","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Amphi_El_Jem.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/38/","https://en.wikipedia.org/wiki/Amphitheatre_of_El_Jem"]'::jsonb)
