insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('carthage','TUN','Archaeological Site of Carthage',null,'heritage',36.86,10.33,'The Phoenician city that rivalled Rome, destroyed in 146 BCE and rebuilt as a Roman capital of Africa.','Its round Punic military harbour, the Antonine Baths and the tophet survive among the villas of modern suburbs. World Heritage Site since 1979.','Destroyed','146 BCE',true,true,2,'{"color":"#1E5AA8","intensity":0.85,"motion":"orbit"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/1/18/Karthago,_Ph%C3%B6nizische_Gro%C3%9Fstadt_(CC_BY-SA_4.0).webm/Karthago,_Ph%C3%B6nizische_Gro%C3%9Fstadt_(CC_BY-SA_4.0).webm.480p.vp9.webm","credit":"ZDF/Terra X/Faber Courtial, Jörg Courtial","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Karthago,_Ph%C3%B6nizische_Gro%C3%9Fstadt_(CC_BY-SA_4.0).webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Archaeological_Site_of_Carthage-130237.jpg/1280px-Archaeological_Site_of_Carthage-130237.jpg","credit":"Christian Manhart","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Archaeological_Site_of_Carthage-130237.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Tunisie_Carthage_Ruines_08.JPG/1280px-Tunisie_Carthage_Ruines_08.JPG","credit":"Calips","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Tunisie_Carthage_Ruines_08.JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/37/","https://en.wikipedia.org/wiki/Carthage"]'::jsonb)
