insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dougga','TUN','Dougga','Thugga','heritage',36.42,9.22,'A Numidian, Punic and Roman hill town with a capitol, theatre and houses still standing over olive groves.','Often called the best-preserved small Roman town in North Africa. Its Libyco-Punic mausoleum is a rare monument of Numidian architecture. World Heritage Site since 1997.','Site area','~75 ha',true,true,3,'{"color":"#C1440E","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/26/Dougga_06.jpg/1280px-Dougga_06.jpg","credit":"Bernard Gagnon","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Dougga_06.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Dougga,_Beja.jpg/1280px-Dougga,_Beja.jpg","credit":"Emna Trabelsi","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Dougga,_Beja.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Byzantine_Fortifications_at_Dougga_-_isawnyu.jpg/1280px-Byzantine_Fortifications_at_Dougga_-_isawnyu.jpg","credit":"Institute for the Study of the Ancient World","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Byzantine_Fortifications_at_Dougga_-_isawnyu.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/794/","https://en.wikipedia.org/wiki/Dougga"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('djerba','TUN','Djerba: Testimony to a Settlement Pattern',null,'coast',33.8,10.88,'The largest island in North Africa, with scattered homesteads, mosques and synagogues among olive groves.','Ibadi, Sunni and Jewish communities have shared the island for centuries; the El Ghriba synagogue is one of Africa’s oldest. World Heritage Site since 2023.','Island area','514 km²',true,true,4,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Djerba_Island.jpeg/1280px-Djerba_Island.jpeg","credit":"NASA Earth Observatory (Lauren Dauphin, Landsat)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Djerba_Island.jpeg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Djerba_hood.jpg/1280px-Djerba_hood.jpg","credit":"Noomen9","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Djerba_hood.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/Reflet_ros%C3%A9.jpg/1280px-Reflet_ros%C3%A9.jpg","credit":"Nourane75","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Reflet_ros%C3%A9.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1640/","https://en.wikipedia.org/wiki/Djerba"]'::jsonb)
