insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ichkeul','TUN','Ichkeul National Park',null,'wetland',37.12,9.66,'A lake and marshes near Bizerte that switch between fresh and salty water with the seasons.','Hundreds of thousands of ducks, geese and coots winter here. Dams once pushed it onto the List in Danger; it was removed in 2006 after recovery. World Heritage Site since 1980.','Wintering birds','Hundreds of thousands',true,true,5,'{"color":"#4C8C4A","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Ichkeul_National_Park_16.JPG/1280px-Ichkeul_National_Park_16.JPG","credit":"Anisbgs","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Ichkeul_National_Park_16.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Ichkeul_4.JPG/1280px-Ichkeul_4.JPG","credit":"Hamed gamaoun","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Ichkeul_4.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Ichkeul_5.JPG/1280px-Ichkeul_5.JPG","credit":"Hamed gamaoun","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Ichkeul_5.JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/8/","https://en.wikipedia.org/wiki/Lake_Ichkeul"]'::jsonb)
