insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kairouan','TUN','Kairouan',null,'heritage',35.68,10.1,'The first Arab-Muslim city of the Maghreb, founded in 670.','Its Great Mosque, with a forest of reused Roman columns, became a model for mosques across the region. World Heritage Site since 1988.','Founded','670',true,true,6,'{"color":"#E8D5A9","intensity":0.85,"motion":"orbit"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/5e/Bir_Barrouta_Kairouan.webm/Bir_Barrouta_Kairouan.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/5e/Bir_Barrouta_Kairouan.webm/Bir_Barrouta_Kairouan.webm.360p.mpeg4.mov","credit":"Habib M''henni","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Bir_Barrouta_Kairouan.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Kairouan,_4_f%C3%A9vrier_2024,_ZVE04341.jpg/1280px-Kairouan,_4_f%C3%A9vrier_2024,_ZVE04341.jpg","credit":"Habib M''henni","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kairouan,_4_f%C3%A9vrier_2024,_ZVE04341.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Kairouan,_4_f%C3%A9vrier_2024,_ZVE04319.jpg/1280px-Kairouan,_4_f%C3%A9vrier_2024,_ZVE04319.jpg","credit":"Habib M''henni","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kairouan,_4_f%C3%A9vrier_2024,_ZVE04319.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/499/","https://en.wikipedia.org/wiki/Kairouan"]'::jsonb)
