insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('medina-of-sousse','TUN','Medina of Sousse',null,'heritage',35.83,10.64,'A walled port town of the early Islamic period, with a ribat (fortified monastery) and Great Mosque.','The ribat, built in the 8th–9th century, guarded the coast. World Heritage Site since 1988.','Inscribed','1988',true,true,7,'{"color":"#F5F3EE","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Medina_of_Sousse-130320.jpg/1280px-Medina_of_Sousse-130320.jpg","credit":"Christian Manhart","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Sousse-130320.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/be/Medina_of_Sousse,_Sousse_Governorate,_Tunisia,_January_2024_-_Thru_window_in_rain.jpg/1280px-Medina_of_Sousse,_Sousse_Governorate,_Tunisia,_January_2024_-_Thru_window_in_rain.jpg","credit":"Sharon Hahn Darlin","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Sousse,_Sousse_Governorate,_Tunisia,_January_2024_-_Thru_window_in_rain.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/498/","https://en.wikipedia.org/wiki/Medina_of_Sousse"]'::jsonb)
