insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('medina-of-tunis','TUN','Medina of Tunis',null,'heritage',36.8,10.17,'The old city of Tunis, with some 700 monuments including palaces, mosques and madrasas.','From the 12th to the 16th century Tunis was among the greatest cities of the Islamic world. World Heritage Site since 1979.','Monuments','~700',true,true,8,'{"color":"#C1440E","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Medina_of_Tunis_-_world_heritage_-_UNESCO.jpg/1280px-Medina_of_Tunis_-_world_heritage_-_UNESCO.jpg","credit":"Sami Mlouhi","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Tunis_-_world_heritage_-_UNESCO.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Medina_of_Tunis_002.jpg/1280px-Medina_of_Tunis_002.jpg","credit":"Touzrimounir","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Tunis_002.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/Medina_of_Tunis_001.jpg/1280px-Medina_of_Tunis_001.jpg","credit":"Touzrimounir","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Medina_of_Tunis_001.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/36/","https://en.wikipedia.org/wiki/Medina_of_Tunis"]'::jsonb)
