insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kerkuane','TUN','Punic Town of Kerkuane',null,'heritage',36.95,11.1,'The only Phoenician-Punic city to survive without being rebuilt by the Romans, on Cap Bon.','Abandoned around 250 BCE, it preserves house plans, streets and bathtubs from Punic daily life. World Heritage Site since 1985.','Abandoned','~250 BCE',true,true,9,'{"color":"#E2B04A","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Punic_Town_of_Kerkuane_and_its_Necropolis-130314.jpg/1280px-Punic_Town_of_Kerkuane_and_its_Necropolis-130314.jpg","credit":"Christian Manhart","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Punic_Town_of_Kerkuane_and_its_Necropolis-130314.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Punic_Town_of_Kerkuane_and_its_Necropolis-130309.jpg/1280px-Punic_Town_of_Kerkuane_and_its_Necropolis-130309.jpg","credit":"Christian Manhart","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Punic_Town_of_Kerkuane_and_its_Necropolis-130309.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Punic_Town_of_Kerkuane_and_its_Necropolis-130310.jpg/1280px-Punic_Town_of_Kerkuane_and_its_Necropolis-130310.jpg","credit":"Christian Manhart","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Punic_Town_of_Kerkuane_and_its_Necropolis-130310.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/332/","https://en.wikipedia.org/wiki/Kerkouane"]'::jsonb)
