insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sidi-bou-said','TUN','Village of Sidi Bou Saïd',null,'heritage',36.87,10.34,'A white village with blue doors and shutters on a cliff above the Gulf of Tunis.','Protected by decree since 1915, the village drew painters such as Paul Klee and August Macke. Inscribed as a World Heritage Site in 2026.','Inscribed','2026',true,true,10,'{"color":"#1E5AA8","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Sidi_Bou_Said,_Tunisia,_19_March_2018_DSC_8004.jpg/1280px-Sidi_Bou_Said,_Tunisia,_19_March_2018_DSC_8004.jpg","credit":"Habib M''henni","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Sidi_Bou_Said,_Tunisia,_19_March_2018_DSC_8004.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/L%E2%80%99arc_de_Sidi_bou_said.jpg/1280px-L%E2%80%99arc_de_Sidi_bou_said.jpg","credit":"Elh Katcha","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:L%E2%80%99arc_de_Sidi_bou_said.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/%D9%85%D9%86%D8%B7%D9%82%D8%A9_%D8%B3%D9%8A%D8%AF%D9%8A_%D8%A8%D9%88%D8%B3%D8%B9%D9%8A%D8%AF.jpg/1280px-%D9%85%D9%86%D8%B7%D9%82%D8%A9_%D8%B3%D9%8A%D8%AF%D9%8A_%D8%A8%D9%88%D8%B3%D8%B9%D9%8A%D8%AF.jpg","credit":"روتانا مبارك","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:%D9%85%D9%86%D8%B7%D9%82%D8%A9_%D8%B3%D9%8A%D8%AF%D9%8A_%D8%A8%D9%88%D8%B3%D8%B9%D9%8A%D8%AF.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1769/","https://en.wikipedia.org/wiki/Sidi_Bou_Said"]'::jsonb)
