insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('chott-el-djerid','TUN','Chott el Djerid',null,'lake',33.7,8.43,'The largest salt pan in the Sahara, a crust of salt crossed by a causeway.','It covers about 7,000 km². In summer heat its surface makes mirages; after rain, algae can tint pools pink.','Area','~7,000 km²',false,true,11,'{"color":"#E8B4BC","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Chott_el_Djerid(js)2.jpg/1280px-Chott_el_Djerid(js)2.jpg","credit":"Jerzystrzelecki","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Chott_el_Djerid(js)2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Chott_el_Djerid(js)4.jpg/1280px-Chott_el_Djerid(js)4.jpg","credit":"Jerzystrzelecki","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Chott_el_Djerid(js)4.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/Chott_el_Djerid(js)5.jpg/1280px-Chott_el_Djerid(js)5.jpg","credit":"Jerzystrzelecki","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Chott_el_Djerid(js)5.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Chott_el_Djerid"]'::jsonb)
