insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('jebel-chambi','TUN','Jebel ech Chambi',null,'mountain',35.21,8.68,'Tunisia’s highest mountain, near Kasserine, with Aleppo pine forest on its slopes.','It is a national park and biosphere reserve, home to Cuvier’s gazelle and Barbary sheep.','Height','1,544 m',false,true,12,'{"color":"#5B6C8F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/Parc_national_chaambi_02.jpg/1280px-Parc_national_chaambi_02.jpg","credit":"TOUMOU","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Parc_national_chaambi_02.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Chambi1.JPG/1280px-Chambi1.JPG","credit":"Nabucodonosor","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Chambi1.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Alg%C3%A9rie_vue_Djebel_Chambi.jpg/1280px-Alg%C3%A9rie_vue_Djebel_Chambi.jpg","credit":"Ggeorgery","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Alg%C3%A9rie_vue_Djebel_Chambi.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Jebel_ech_Chambi"]'::jsonb)
