insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bou-hedma','TUN','Bou-Hedma National Park',null,'savanna',34.42,9.5,'The last stand of pseudo-savanna with Acacia raddiana in Tunisia.','Scimitar-horned oryx and addax, both long gone from the wild in Tunisia, have been reintroduced here.','Created','1980',false,true,13,'{"color":"#C2B280","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Parc_national_de_Bouhedma.jpg/1280px-Parc_national_de_Bouhedma.jpg","credit":"El Golli Mohamed","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Parc_national_de_Bouhedma.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Acacia_raddiana_in_Bouhedma.jpg/1280px-Acacia_raddiana_in_Bouhedma.jpg","credit":"IssamBarhoumi","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Acacia_raddiana_in_Bouhedma.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Acacia_raddiana_in_Bouhedma_-_Fruits.jpg/1280px-Acacia_raddiana_in_Bouhedma_-_Fruits.jpg","credit":"IssamBarhoumi","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Acacia_raddiana_in_Bouhedma_-_Fruits.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Bou-Hedma_National_Park"]'::jsonb)
