insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('barbary-stag','TUN','Barbary Stag','Atlas deer','fauna',36.65,8.6,'Africa’s only native deer, living in the cork-oak forests along the Tunisian–Algerian border.','Hunted almost to extinction by the 1960s; protection in Tunisia and Algeria has helped it recover. The pin is in the Kroumirie forests.','Only native','deer of Africa',false,true,14,'{"color":"#8B5E34","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Cervus_elaphus_barbarus,_Friguia_Park,_Tunisie_2015.jpg/1280px-Cervus_elaphus_barbarus,_Friguia_Park,_Tunisie_2015.jpg","credit":"Habib M''henni","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cervus_elaphus_barbarus,_Friguia_Park,_Tunisie_2015.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Cervus_elaphus_barbarus,_Tierpark_Berlin,_523-629.jpg/1280px-Cervus_elaphus_barbarus,_Tierpark_Berlin,_523-629.jpg","credit":"Lotse","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Cervus_elaphus_barbarus,_Tierpark_Berlin,_523-629.jpg"}]}'::jsonb,'Cervus elaphus barbarus','["https://en.wikipedia.org/wiki/Barbary_stag","https://www.gbif.org/species/search?q=Cervus%20elaphus%20barbarus"]'::jsonb)
