insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('olive-sfax','TUN','Olive Tree',null,'flora',34.74,10.5,'The tree of Tunisia: tens of millions of olive trees cover the Sahel and the plains around Sfax.','Olives have been grown here since Phoenician times, and Tunisia is one of the world’s largest olive-oil exporters. The pin is near Sfax.','Grown since','Phoenician times',false,true,15,'{"color":"#7A9A3A","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Olea_europaea_2810.jpg/1280px-Olea_europaea_2810.jpg","credit":"Anna Anichkova","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Olea_europaea_2810.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Olea_europaea_1782.jpg/1280px-Olea_europaea_1782.jpg","credit":"Anna Anichkova","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Olea_europaea_1782.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Olea_europaea_6086.jpg/1280px-Olea_europaea_6086.jpg","credit":"Anna Anichkova","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Olea_europaea_6086.jpg"}]}'::jsonb,'Olea europaea','["https://en.wikipedia.org/wiki/Olive","https://en.wikipedia.org/wiki/Olive_oil"]'::jsonb)
