insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dakhla-lagoon','ESH','Dakhla Bay',null,'coast',23.71,-15.95,'A long Atlantic lagoon behind a sandy peninsula, where the desert meets cold, nutrient-rich ocean.','Steady trade winds make it a kitesurfing destination; its shallows support oysters, seagrass and wintering shorebirds. The city of Dakhla is in the Moroccan-administered part of the disputed territory.','Lagoon length','~40 km',false,true,1,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Dakhla,_Western_Sahara_(2).jpg/1280px-Dakhla,_Western_Sahara_(2).jpg","credit":"YoTuT","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Dakhla,_Western_Sahara_(2).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Dakhla,_Western_Sahara.jpg/1280px-Dakhla,_Western_Sahara.jpg","credit":"YoTuT","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Dakhla,_Western_Sahara.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Dakhla,_Western_Sahara_(3).jpg/1280px-Dakhla,_Western_Sahara_(3).jpg","credit":"YoTuT","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Dakhla,_Western_Sahara_(3).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Dakhla,_Western_Sahara","https://en.wikipedia.org/wiki/Western_Sahara"]'::jsonb)
