insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('saguia-el-hamra','ESH','Saguia el-Hamra','“the red watercourse”','river',27.15,-13.2,'A long dry riverbed (wadi) running across the north of Western Sahara to the Atlantic near Laayoune.','It flows only after rare storms. The name, “red watercourse”, also served for the northern region of the former Spanish Sahara.','Flows','After rare storms',false,true,2,'{"color":"#B5651D","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Saguia_el-Hamra.jpg/1280px-Saguia_el-Hamra.jpg","credit":"ZAINEB HACHAMI","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Saguia_el-Hamra.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Saguia_el-Hamra"]'::jsonb)
