insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('guelta-zemmur','ESH','Guelta Zemmur',null,'rock',25.15,-12.37,'A rocky desert of granite inselbergs and seasonal pools (gueltas) in the interior of Western Sahara.','Gueltas are rock basins that hold rainwater for months and were vital to herders and wildlife. Rock art is found across the region.','Guelta','seasonal rock pool',false,true,3,'{"color":"#D4A373","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Western_Sahara_desert_1.jpg/1280px-Western_Sahara_desert_1.jpg","credit":"Radosław Botev","license":"Attribution","source":"https://commons.wikimedia.org/wiki/File:Western_Sahara_desert_1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Western_Sahara_desert_2.jpg/1280px-Western_Sahara_desert_2.jpg","credit":"Radosław Botev","license":"Attribution","source":"https://commons.wikimedia.org/wiki/File:Western_Sahara_desert_2.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Guelta_Zemmur","https://en.wikipedia.org/wiki/Guelta"]'::jsonb)
