insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dorcas-gazelle','ESH','Dorcas Gazelle',null,'fauna',26,-12,'A small, pale gazelle of the Sahara that may never need to drink, getting water from plants and dew.','Once common across North Africa, it has declined from hunting and is listed as Vulnerable. The pin is a representative point.','Shoulder height','~55–65 cm',false,true,4,'{"color":"#E0B07A","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Gazella_dorcas.JPG/1280px-Gazella_dorcas.JPG","credit":"Altaipanther","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Gazella_dorcas.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Gazella_dorcas,_Israel.jpg/1280px-Gazella_dorcas,_Israel.jpg","credit":"MinoZig","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Gazella_dorcas,_Israel.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/Dorcasgazellemarwell.jpg/1280px-Dorcasgazellemarwell.jpg","credit":"Khendon","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Dorcasgazellemarwell.jpg"}]}'::jsonb,'Gazella dorcas','["https://en.wikipedia.org/wiki/Dorcas_gazelle","https://www.gbif.org/species/search?q=Gazella%20dorcas"]'::jsonb)
