insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('umbrella-thorn-sahara','ESH','Umbrella Thorn Acacia',null,'flora',24.5,-13.5,'A flat-topped thorn tree, often the only shade in the Saharan plains.','Its deep roots reach groundwater, and its pods feed camels and goats. The same species grows from the Sahara to East Africa. The pin is a representative point.','Roots reach','Deep groundwater',false,true,5,'{"color":"#6A994E","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Acacia_(Vachellia_tortilis),_parque_nacional_de_Amboseli,_Kenia,_2024-05-22,_DD_99.jpg/1280px-Acacia_(Vachellia_tortilis),_parque_nacional_de_Amboseli,_Kenia,_2024-05-22,_DD_99.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Acacia_(Vachellia_tortilis),_parque_nacional_de_Amboseli,_Kenia,_2024-05-22,_DD_99.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d8/Acacia_(Vachellia_tortilis),_parque_nacional_Serengueti,_Tanzania,_2024-05-26,_DD_26.jpg/1280px-Acacia_(Vachellia_tortilis),_parque_nacional_Serengueti,_Tanzania,_2024-05-26,_DD_26.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Acacia_(Vachellia_tortilis),_parque_nacional_Serengueti,_Tanzania,_2024-05-26,_DD_26.jpg"}],"note":"Photographed in East Africa — the same species grows across the Sahara’s edges."}'::jsonb,'Vachellia tortilis','["https://en.wikipedia.org/wiki/Vachellia_tortilis","https://www.gbif.org/species/search?q=Vachellia%20tortilis"]'::jsonb)
