insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('royal-palaces-of-abomey','BEN','Royal Palaces of Abomey',null,'heritage',7.19,1.99,'The earthen palaces of the twelve kings of Dahomey, spread over 47 ha at the heart of Abomey.','Their walls carry painted bas-reliefs that record the kingdom’s history and wars. Dahomey (1600–1894) was one of the most powerful West African states. World Heritage Site since 1985.','Kingdom','~1600–1894',true,true,1,'{"color":"#C8553D","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Abomey_royal_palace_wall.jpg/1280px-Abomey_royal_palace_wall.jpg","credit":"Willem Heerbaart","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Abomey_royal_palace_wall.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Royal_Palaces,_Abomey_(Benin)_banner.jpg/1280px-Royal_Palaces,_Abomey_(Benin)_banner.jpg","credit":"Willem Heerbaart","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Royal_Palaces,_Abomey_(Benin)_banner.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Royal_Palaces_of_Abomey-133492.jpg/1280px-Royal_Palaces_of_Abomey-133492.jpg","credit":"Karalyn Monteil","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Royal_Palaces_of_Abomey-133492.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/323/","https://en.wikipedia.org/wiki/Royal_Palaces_of_Abomey"]'::jsonb)
