insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('w-arly-pendjari','BEN','W-Arly-Pendjari Complex','Pendjari National Park','savanna',11.05,1.52,'The largest intact savanna ecosystem in West Africa, shared by Benin, Burkina Faso and Niger.','It holds most of the region’s remaining lions and elephants, plus cheetah, buffalo and roan antelope. The transboundary site was completed in 2017.','Countries','3',true,true,2,'{"color":"#E9C46A","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Pendjari.JPG/1280px-Pendjari.JPG","credit":"Martin Wegmann","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Pendjari.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Parc_national_de_la_Pendjari.JPG/1280px-Parc_national_de_la_Pendjari.JPG","credit":"Fawaz.tairou","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Parc_national_de_la_Pendjari.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Pendjari_kuhantilopen.JPG/1280px-Pendjari_kuhantilopen.JPG","credit":"Gregor Rom","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pendjari_kuhantilopen.JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/749/","https://en.wikipedia.org/wiki/Pendjari_National_Park","https://en.wikipedia.org/wiki/W-Arly-Pendjari_Complex"]'::jsonb)
