insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ganvie','BEN','Ganvié',null,'lake',6.47,2.42,'A town of about 20,000 people built on stilts in Lake Nokoué, reached only by boat.','The Tofinu built it on the water around the 17th–18th century, out of reach of Dahomey’s slave-raiding warriors, whose beliefs forbade them to fight on water. Markets are held from canoes.','People','~20,000',false,true,3,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/59/Ganvi%C3%A9_au_fil_de_l''eau_(3).webm/Ganvi%C3%A9_au_fil_de_l''eau_(3).webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/59/Ganvi%C3%A9_au_fil_de_l''eau_(3).webm/Ganvi%C3%A9_au_fil_de_l''eau_(3).webm.360p.mpeg4.mov","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ganvi%C3%A9_au_fil_de_l''eau_(3).webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Lake_of_Ganvi%C3%A9-Benin,_2013.jpg/1280px-Lake_of_Ganvi%C3%A9-Benin,_2013.jpg","credit":"jbdodane","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Lake_of_Ganvi%C3%A9-Benin,_2013.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Young_Fisher_on_the_Ganvi%C3%A9_lake.jpg/1280px-Young_Fisher_on_the_Ganvi%C3%A9_lake.jpg","credit":"jbdodane","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Young_Fisher_on_the_Ganvi%C3%A9_lake.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Fisher_on_the_Ganvi%C3%A9_lakes.jpg/1280px-Fisher_on_the_Ganvi%C3%A9_lakes.jpg","credit":"jbdodane","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Fisher_on_the_Ganvi%C3%A9_lakes.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Ganvie"]'::jsonb)
