insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kota-falls','BEN','Kota Falls','Chutes de Kota','waterfall',10.36,1.43,'A waterfall and swimming pool in the Atakora hills near Natitingou.','The stream drops over a sandstone ledge into a deep pool, shaded by gallery forest in a dry landscape.','Region','Atakora',false,true,4,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Chutes_de_Kota-Passerelle.jpg/1280px-Chutes_de_Kota-Passerelle.jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Chutes_de_Kota-Passerelle.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Baignade_aux_chutes_de_Kota.jpg/1280px-Baignade_aux_chutes_de_Kota.jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Baignade_aux_chutes_de_Kota.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Baignade_aux_chutes_de_Kota_(2).jpg/1280px-Baignade_aux_chutes_de_Kota_(2).jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Baignade_aux_chutes_de_Kota_(2).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Natitingou"]'::jsonb)
