insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bouche-du-roy','BEN','Bouche du Roy',null,'coast',6.27,1.98,'The estuary where the Mono River and the Grand-Popo lagoon meet the Gulf of Guinea.','Mangroves, sea-turtle beaches and fishing villages lie within a community conservation area and a transboundary UNESCO biosphere reserve with Togo.','Biosphere reserve','Mono Delta (2017)',false,true,5,'{"color":"#2A6F97","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/Ciel_nuageux_et_cocotiers.jpg/1280px-Ciel_nuageux_et_cocotiers.jpg","credit":"Padonou Dotou","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ciel_nuageux_et_cocotiers.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Cabane_de_p%C3%AAcheurs.jpg/1280px-Cabane_de_p%C3%AAcheurs.jpg","credit":"Padonou Dotou","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cabane_de_p%C3%AAcheurs.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Bottes_de_jonc.jpg/1280px-Bottes_de_jonc.jpg","credit":"Padonou Dotou","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Bottes_de_jonc.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Bouche_du_Roy"]'::jsonb)
