insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ball-python-ouidah','BEN','Royal Python','dangbé (Fon)','fauna',6.36,2.09,'A gentle python that curls into a ball when threatened, sacred in the Vodun religion of southern Benin.','At Ouidah’s Temple of Pythons, dozens of royal pythons are kept as embodiments of the deity Dangbé and may roam the town at night. The pin is at Ouidah.','Length','~1–1.5 m',false,true,6,'{"color":"#8B5E34","intensity":0.85,"motion":"orbit"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b4/Ball_python_(Python_regius)_in_a_zoo.webm/Ball_python_(Python_regius)_in_a_zoo.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b4/Ball_python_(Python_regius)_in_a_zoo.webm/Ball_python_(Python_regius)_in_a_zoo.webm.360p.mpeg4.mov","credit":"Trevor Zoo at Millbrook School","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Ball_python_(Python_regius)_in_a_zoo.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Python_regius_070731_a.jpg/1280px-Python_regius_070731_a.jpg","credit":"Rainer Altenkamp","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Python_regius_070731_a.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/Python-regius-kopf-k%C3%B6nigspython.jpg/1280px-Python-regius-kopf-k%C3%B6nigspython.jpg","credit":"Holger Krisp","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Python-regius-kopf-k%C3%B6nigspython.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Python_regius_-_ball_python.jpg/1280px-Python_regius_-_ball_python.jpg","credit":"Brian Gratwicke","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Python_regius_-_ball_python.jpg"}]}'::jsonb,'Python regius','["https://en.wikipedia.org/wiki/Ball_python","https://en.wikipedia.org/wiki/Temple_of_Pythons"]'::jsonb)
