insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('african-fan-palm','BEN','African Fan Palm','rônier','flora',10.8,1.6,'A tall fan palm of West African savannas, with a bulge part-way up its trunk.','Its trunks resist termites and are used for building, its fruit and shoots are eaten, and its sap is tapped for palm wine. The pin is in northern Benin.','Height','Up to ~25 m',false,true,7,'{"color":"#6A994E","intensity":0.85,"motion":"bloom"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/58/Harvesting_ronier_fruit_(Borassus_aethiopum)_on_the_Ferme_Burok_Dhiediou_near_Silinkine,_Casamance,_Senegal_02.webm/Harvesting_ronier_fruit_(Borassus_aethiopum)_on_the_Ferme_Burok_Dhiediou_near_Silinkine,_Casamance,_Senegal_02.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/58/Harvesting_ronier_fruit_(Borassus_aethiopum)_on_the_Ferme_Burok_Dhiediou_near_Silinkine,_Casamance,_Senegal_02.webm/Harvesting_ronier_fruit_(Borassus_aethiopum)_on_the_Ferme_Burok_Dhiediou_near_Silinkine,_Casamance,_Senegal_02.webm.360p.mpeg4.mov","credit":"Kai Kemmann","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Harvesting_ronier_fruit_(Borassus_aethiopum)_on_the_Ferme_Burok_Dhiediou_near_Silinkine,_Casamance,_Senegal_02.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Borassus_aethiopum_0070.jpg/1280px-Borassus_aethiopum_0070.jpg","credit":"Atamari","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Borassus_aethiopum_0070.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Borassus_aethiopum_MS_4049.jpg/1280px-Borassus_aethiopum_MS_4049.jpg","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Borassus_aethiopum_MS_4049.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Borassus_aethiopum_seeds.jpg/1280px-Borassus_aethiopum_seeds.jpg","credit":"Karelj","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Borassus_aethiopum_seeds.jpg"}]}'::jsonb,'Borassus aethiopum','["https://en.wikipedia.org/wiki/Borassus_aethiopum","https://www.gbif.org/species/search?q=Borassus%20aethiopum"]'::jsonb)
