insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('loropeni','BFA','Ruins of Loropéni',null,'heritage',10.31,-3.56,'Stone walls up to 6 m high enclosing a settlement linked to the trans-Saharan gold trade.','The best preserved of about ten fortresses in the Lobi area; parts date to at least the 11th century. Burkina Faso’s first World Heritage Site (2009).','Walls','Up to 6 m',true,true,1,'{"color":"#B5502E","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/2016.05-441-131ap_wall_Lorop%C3%A9ni_Ruins_nr.Lorop%C3%A9ni(Poni_Prv.),BF_sun15may2016-1106h.jpg/1280px-2016.05-441-131ap_wall_Lorop%C3%A9ni_Ruins_nr.Lorop%C3%A9ni(Poni_Prv.),BF_sun15may2016-1106h.jpg","credit":"Rik Schuiling / TropCrop-TCS","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:2016.05-441-131ap_wall_Lorop%C3%A9ni_Ruins_nr.Lorop%C3%A9ni(Poni_Prv.),BF_sun15may2016-1106h.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/2016.05-441-134ap_archeology,excavation_Lorop%C3%A9ni_Ruins_nr.Lorop%C3%A9ni(Poni_Prv.),BF_sun15may2016-1119h.jpg/1280px-2016.05-441-134ap_archeology,excavation_Lorop%C3%A9ni_Ruins_nr.Lorop%C3%A9ni(Poni_Prv.),BF_sun15may2016-1119h.jpg","credit":"Rik Schuiling / TropCrop-TCS","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:2016.05-441-134ap_archeology,excavation_Lorop%C3%A9ni_Ruins_nr.Lorop%C3%A9ni(Poni_Prv.),BF_sun15may2016-1119h.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1225/","https://en.wikipedia.org/wiki/Ruins_of_Loropéni"]'::jsonb)
