insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ferrous-metallurgy-burkina','BFA','Ancient Ferrous Metallurgy Sites',null,'heritage',12.6,-2.3,'Five sites with furnaces, mines and slag heaps from about 2,700 years of iron-smelting.','The oldest, at Douroula, dates to the 8th century BCE. Smiths still hold a special place in local society. World Heritage Site since 2019.','Oldest','8th c. BCE',true,true,2,'{"color":"#8B3A2B","intensity":0.85,"motion":"orbit"}'::jsonb,'{"note":"No openly licensed photos of the furnace sites yet."}'::jsonb,null,'["https://whc.unesco.org/en/list/1602/","https://en.wikipedia.org/wiki/Ancient_ferrous_metallurgy_sites_of_Burkina_Faso"]'::jsonb)
