insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tiebele','BFA','Royal Court of Tiébélé',null,'heritage',11.1,-0.97,'A Kassena royal compound of earthen houses painted by women with black, white and red geometric designs.','The paintings are renewed before the rainy season using earth, chalk and plant varnish. World Heritage Site since 2024.','Inscribed','2024',true,true,3,'{"color":"#E3A857","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Tiebele_traditional_house_decoration_Burkina_Faso.jpg/1280px-Tiebele_traditional_house_decoration_Burkina_Faso.jpg","credit":"c.hug","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Tiebele_traditional_house_decoration_Burkina_Faso.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Tiebele_village_in_Burkina_Faso_06.jpg/1280px-Tiebele_village_in_Burkina_Faso_06.jpg","credit":"Alexander Leisser","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Tiebele_village_in_Burkina_Faso_06.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Ti%C3%A9b%C3%A9l%C3%A9_vue_de_la_colline.jpg/1280px-Ti%C3%A9b%C3%A9l%C3%A9_vue_de_la_colline.jpg","credit":"Hugues","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Ti%C3%A9b%C3%A9l%C3%A9_vue_de_la_colline.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1713/","https://en.wikipedia.org/wiki/Tiébélé"]'::jsonb)
