insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sindou-peaks','BFA','Sindou Peaks','Pics de Sindou','rock',10.67,-5.17,'A ridge of sandstone needles and towers carved by wind and rain near the Mali border.','The peaks are sacred to the Senoufo and a protected natural site.','Region','Cascades',false,true,4,'{"color":"#C65D3B","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Pics_de_Sindou_WP32_SDr9756.JPG/1280px-Pics_de_Sindou_WP32_SDr9756.JPG","credit":"Stefan Dressler","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Pics_de_Sindou_WP32_SDr9756.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/PicsdeSindou.jpg/1280px-PicsdeSindou.jpg","credit":"Sylvain Crouzillat (croucrou)","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:PicsdeSindou.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Burkina_20110120_164655.jpg/1280px-Burkina_20110120_164655.jpg","credit":"Sylvain Crouzillat (croucrou)","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Burkina_20110120_164655.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Sindou_Peaks"]'::jsonb)
