insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('karfiguela-falls','BFA','Karfiguéla Falls','Cascades de Banfora','waterfall',10.71,-4.82,'A series of cascades over sandstone steps near Banfora, among mango groves.','One of the few permanent waterfalls in Burkina Faso, fed by the Comoé basin.','Near','Banfora',false,true,5,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Cascades_de_Karfiguela_(12568284134).jpg/1280px-Cascades_de_Karfiguela_(12568284134).jpg","credit":"Maarten van der Bent","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Cascades_de_Karfiguela_(12568284134).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Waterfalls_at_Karfiguela,_Burkina_Faso.jpg/1280px-Waterfalls_at_Karfiguela,_Burkina_Faso.jpg","credit":"c.hug","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Waterfalls_at_Karfiguela,_Burkina_Faso.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Cascades_de_Karfiguela_(12567794645).jpg/1280px-Cascades_de_Karfiguela_(12567794645).jpg","credit":"Maarten van der Bent","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Cascades_de_Karfiguela_(12567794645).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Karfiguéla_Falls"]'::jsonb)
