insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('nazinga','BFA','Nazinga Game Ranch',null,'savanna',11.19,-1.48,'A savanna reserve in the south known for elephants gathering at its waterholes.','Founded in 1979 to restore wildlife numbers, it now holds one of the densest elephant populations in West Africa.','Founded','1979',false,true,6,'{"color":"#6B8E23","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Elephants_Nazinga_MS5175.JPG/1280px-Elephants_Nazinga_MS5175.JPG","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Elephants_Nazinga_MS5175.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Detarium_microcarpum_MS5220.JPG/1280px-Detarium_microcarpum_MS5220.JPG","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Detarium_microcarpum_MS5220.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Leptadenia_hastata_MS4996.JPG/1280px-Leptadenia_hastata_MS4996.JPG","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Leptadenia_hastata_MS4996.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Nazinga_Game_Ranch"]'::jsonb)
