insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sacred-crocodiles-sabou','BFA','Sacred Crocodiles of Sabou',null,'fauna',12.06,-2.24,'A crocodile of the Sahel’s pools, long confused with the Nile crocodile, held sacred in villages such as Sabou and Bazoulé.','It was recognised as a separate species in 2011. Villagers feed and protect the pond crocodiles, believed to carry ancestral spirits. The pin is at Sabou.','Recognised','2011',false,true,7,'{"color":"#4C6B3C","intensity":0.85,"motion":"ripple"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/e/ea/Threatened.webm/Threatened.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/e/ea/Threatened.webm/Threatened.webm.360p.mpeg4.mov","credit":"Thierry Dugnolle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Threatened.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/Crocodylus_suchus_78409213.jpg/1280px-Crocodylus_suchus_78409213.jpg","credit":"eyrezer","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Crocodylus_suchus_78409213.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Crocodylus_suchus_Copenhagen.jpg/1280px-Crocodylus_suchus_Copenhagen.jpg","credit":"Long Zheng","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Crocodylus_suchus_Copenhagen.jpg"}]}'::jsonb,'Crocodylus suchus','["https://en.wikipedia.org/wiki/West_African_crocodile","https://www.gbif.org/species/search?q=Crocodylus%20suchus"]'::jsonb)
