insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('nere','BFA','Néré','African locust bean','flora',11.2,-4.3,'A savanna tree with red pom-pom flowers whose fermented seeds make soumbala, a seasoning across West Africa.','Its flowers are pollinated by fruit bats. Farmers keep néré trees standing in their fields. The pin is a representative point.','Seasoning','soumbala',false,true,8,'{"color":"#C1121F","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Parkia_biglobosa_Burkina.jpg/1280px-Parkia_biglobosa_Burkina.jpg","credit":"Vitellaria","license":"CC BY-SA 2.0 DE","source":"https://commons.wikimedia.org/wiki/File:Parkia_biglobosa_Burkina.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Parkia_biglobosa_MS_4398.jpg/1280px-Parkia_biglobosa_MS_4398.jpg","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Parkia_biglobosa_MS_4398.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/B%C3%A9nin-Parkia_biglobosa_(1).jpg/1280px-B%C3%A9nin-Parkia_biglobosa_(1).jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:B%C3%A9nin-Parkia_biglobosa_(1).jpg"}]}'::jsonb,'Parkia biglobosa','["https://en.wikipedia.org/wiki/Parkia_biglobosa","https://www.gbif.org/species/search?q=Parkia%20biglobosa"]'::jsonb)
