insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('cidade-velha','CPV','Cidade Velha','Ribeira Grande','heritage',14.92,-23.61,'The first European colonial town in the tropics, founded in 1462 on Santiago island.','It was a hub of the Atlantic slave trade; its pillory, fortress and cathedral ruins remain. World Heritage Site since 2009.','Founded','1462',true,true,1,'{"color":"#E9C46A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e0/Vista_forte_cidade_velha_cabo_verde.webm/Vista_forte_cidade_velha_cabo_verde.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e0/Vista_forte_cidade_velha_cabo_verde.webm/Vista_forte_cidade_velha_cabo_verde.webm.360p.mpeg4.mov","credit":"Vasco Marques","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Vista_forte_cidade_velha_cabo_verde.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/S%C3%A9_Catedral,_Cidade_Velha,_Cape_Verde.jpg/1280px-S%C3%A9_Catedral,_Cidade_Velha,_Cape_Verde.jpg","credit":"Xandu","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:S%C3%A9_Catedral,_Cidade_Velha,_Cape_Verde.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Pelourinho_Cidade_Velha_IW.jpg/1280px-Pelourinho_Cidade_Velha_IW.jpg","credit":"Ingo Wölbern","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Pelourinho_Cidade_Velha_IW.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1310/","https://en.wikipedia.org/wiki/Cidade_Velha"]'::jsonb)
