insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('pico-do-fogo','CPV','Pico do Fogo',null,'volcano',14.95,-24.34,'An active stratovolcano rising to 2,829 m, the highest point of Cabo Verde.','Its last eruption, in 2014–15, buried villages in the Chã das Caldeiras crater, where people grow grapes and coffee in volcanic soil.','Height','2,829 m',false,true,2,'{"color":"#2B2D42","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Road_to_caldera_in_Fogo_&_Pico_de_Fogo_2,_2010_12.jpg/1280px-Road_to_caldera_in_Fogo_&_Pico_de_Fogo_2,_2010_12.jpg","credit":"Ximonic, Simo Räsänen","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Road_to_caldera_in_Fogo_&_Pico_de_Fogo_2,_2010_12.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/Vignes_et_Pico_do_Fogo_%C3%A0_Ch%C3%A3_das_Caldeiras.jpg/1280px-Vignes_et_Pico_do_Fogo_%C3%A0_Ch%C3%A3_das_Caldeiras.jpg","credit":"F H Mira","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Vignes_et_Pico_do_Fogo_%C3%A0_Ch%C3%A3_das_Caldeiras.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Pico_do_Fogo.jpg/1280px-Pico_do_Fogo.jpg","credit":"Rolfcosar","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Pico_do_Fogo.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Pico_do_Fogo"]'::jsonb)
