insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('paul-valley','CPV','Paul Valley','Vale do Paúl','gorge',17.1,-25,'A deep green valley on Santo Antão, terraced with sugar cane, bananas and yams below the Cova crater.','Trade-wind clouds water the north-east of the island, making it far greener than the rest of the archipelago.','Island','Santo Antão',false,true,3,'{"color":"#2D6A4F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/The_Valley_at_Paul_on_Santo_Ant%C3%A3o,_Cape_Verde.jpg/1280px-The_Valley_at_Paul_on_Santo_Ant%C3%A3o,_Cape_Verde.jpg","credit":"As3.1415rin","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:The_Valley_at_Paul_on_Santo_Ant%C3%A3o,_Cape_Verde.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Vale_do_Pa%C3%BAl,_Santo_Ant%C3%A3o,_Cape_Verde.jpg/1280px-Vale_do_Pa%C3%BAl,_Santo_Ant%C3%A3o,_Cape_Verde.jpg","credit":"CaptainDarwin","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Vale_do_Pa%C3%BAl,_Santo_Ant%C3%A3o,_Cape_Verde.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Santo_Ant%C3%A3o_294A8976_Cova.jpg/1280px-Santo_Ant%C3%A3o_294A8976_Cova.jpg","credit":"Christian Pirkl","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Santo_Ant%C3%A3o_294A8976_Cova.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Santo_Antão,_Cape_Verde"]'::jsonb)
