insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('pedra-de-lume','CPV','Pedra de Lume',null,'lake',16.76,-22.89,'Salt pans inside an extinct volcanic crater on the island of Sal.','Seawater seeps into the crater and evaporates; the salt was exported from the 19th century. The brine is so dense that bathers float.','Island','Sal',false,true,4,'{"color":"#F4ACB7","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Pedradelume.jpg/1280px-Pedradelume.jpg","credit":"Montek","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pedradelume.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f5/Pedradelumesalina.jpg/1280px-Pedradelumesalina.jpg","credit":"Montek","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pedradelumesalina.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/Pedra_de_Lume.JPG/1280px-Pedra_de_Lume.JPG","credit":"Juan Caparrós","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pedra_de_Lume.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Pedra_de_Lume"]'::jsonb)
