insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('viana-desert','CPV','Viana Desert','Deserto de Viana','desert',16.13,-22.86,'White dunes on the island of Boa Vista, built from sand blown across the ocean from the Sahara.','Boa Vista is one of the world’s most important nesting areas for loggerhead turtles.','Island','Boa Vista',false,true,5,'{"color":"#F2CC8F","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Deserto_Viana,_Boa_Vista.jpg/1280px-Deserto_Viana,_Boa_Vista.jpg","credit":"Ingo Wölbern","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Deserto_Viana,_Boa_Vista.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Deserto_de_Viana.jpg/1280px-Deserto_de_Viana.jpg","credit":"Kojote","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Deserto_de_Viana.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Deserto_de_Viana_Wegweiser.jpg/1280px-Deserto_de_Viana_Wegweiser.jpg","credit":"Kojote","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Deserto_de_Viana_Wegweiser.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Boa_Vista,_Cape_Verde"]'::jsonb)
