insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('loggerhead-boa-vista','CPV','Loggerhead Sea Turtle',null,'fauna',16.05,-22.8,'Thousands of loggerheads nest on Boa Vista’s beaches each summer.','Cabo Verde holds one of the largest loggerhead nesting populations in the world, mostly on Boa Vista. The pin is on Boa Vista’s east coast.','Nesting season','~June–October',false,true,6,'{"color":"#457B9D","intensity":0.85,"motion":"ripple"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e1/Hatchling_of_loggerhead_sea_turtle_(Caretta_caretta)_running_to_sea.webm/Hatchling_of_loggerhead_sea_turtle_(Caretta_caretta)_running_to_sea.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e1/Hatchling_of_loggerhead_sea_turtle_(Caretta_caretta)_running_to_sea.webm/Hatchling_of_loggerhead_sea_turtle_(Caretta_caretta)_running_to_sea.webm.360p.mpeg4.mov","credit":"Jean-Lou Justine","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Hatchling_of_loggerhead_sea_turtle_(Caretta_caretta)_running_to_sea.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Loggerhead_Sea_Turtle_(Caretta_caretta)_2.jpg/1280px-Loggerhead_Sea_Turtle_(Caretta_caretta)_2.jpg","credit":"Brian Gratwicke","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Loggerhead_Sea_Turtle_(Caretta_caretta)_2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Caretta_caretta_060417w2.jpg/1280px-Caretta_caretta_060417w2.jpg","credit":"Strobilomyces","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Caretta_caretta_060417w2.jpg"}]}'::jsonb,'Caretta caretta','["https://en.wikipedia.org/wiki/Loggerhead_sea_turtle","https://www.gbif.org/species/search?q=Caretta%20caretta"]'::jsonb)
