insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dragon-tree','CPV','Dragon Tree','dragoeiro','flora',16.6,-24.27,'An umbrella-shaped tree of the Atlantic islands that bleeds red resin, “dragon’s blood”.','The Cabo Verde form survives wild only on a few islands such as São Nicolau. The pin is on São Nicolau.','Resin','“dragon’s blood”',false,true,7,'{"color":"#A8DADC","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/0/05/Dracaena_draco_PA.jpg","credit":"tato grasso","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Dracaena_draco_PA.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Dracaena_draco_qtl1.jpg/1280px-Dracaena_draco_qtl1.jpg","credit":"Quartl","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Dracaena_draco_qtl1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Dracaena_draco_6.jpg/1280px-Dracaena_draco_6.jpg","credit":"Megan Hansen","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Dracaena_draco_6.jpg"}]}'::jsonb,'Dracaena draco','["https://en.wikipedia.org/wiki/Dracaena_draco","https://www.gbif.org/species/search?q=Dracaena%20draco"]'::jsonb)
