insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('comoe-national-park','CIV','Comoé National Park',null,'savanna',9.16,-3.77,'One of the largest protected areas in West Africa, crossed by the Comoé River.','Its mosaic of savanna, gallery forest and riverine habitats once held elephants, hippos and lions. Removed from the List in Danger in 2017 after wildlife recovered.','Area','~11,500 km²',true,true,1,'{"color":"#E9D8A6","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/98/Fleuve_Como%C3%A9_dans_le_Parc_National_de_la_Como%C3%A9.jpg/1280px-Fleuve_Como%C3%A9_dans_le_Parc_National_de_la_Como%C3%A9.jpg","credit":"Abdoul-Azize BOUKARY","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Fleuve_Como%C3%A9_dans_le_Parc_National_de_la_Como%C3%A9.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/NationalparkComoe4.jpg/1280px-NationalparkComoe4.jpg","credit":"Albert Backer","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:NationalparkComoe4.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/Como%C3%A9_Researchstation_Lab_and_solar_panels.jpg/1280px-Como%C3%A9_Researchstation_Lab_and_solar_panels.jpg","credit":"ETF89","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Como%C3%A9_Researchstation_Lab_and_solar_panels.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/227/","https://en.wikipedia.org/wiki/Comoé_National_Park"]'::jsonb)
