insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tai-national-park','CIV','Taï National Park',null,'forest',5.75,-7.12,'One of the last large areas of primary Upper Guinean rainforest.','Its chimpanzees crack nuts with stone and wooden hammers, a tradition archaeologists have traced back over 4,000 years. Pygmy hippos live here too. World Heritage Site since 1982.','Area','~3,300 km²',true,true,2,'{"color":"#2D6A4F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Ta%C3%AF_National_Park_(24148248710).jpg/1280px-Ta%C3%AF_National_Park_(24148248710).jpg","credit":"yakovlev.alexey","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Ta%C3%AF_National_Park_(24148248710).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Schimpansen_im_Nationalpark_Tai.jpg/1280px-Schimpansen_im_Nationalpark_Tai.jpg","credit":"Gregor Rom","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Schimpansen_im_Nationalpark_Tai.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/195/","https://en.wikipedia.org/wiki/Taï_National_Park"]'::jsonb)
