insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('grand-bassam','CIV','Historic Town of Grand-Bassam',null,'heritage',5.2,-3.73,'The first colonial capital of Côte d’Ivoire, with arcaded colonial houses between lagoon and sea.','The town shows the meeting of European and African ways of life; the N’zima village sits beside the old quarter. World Heritage Site since 2012.','Capital','1893–1896',true,true,3,'{"color":"#F77F00","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Historic_town_of_Grand-Bassam_24092023_002.jpg/1280px-Historic_town_of_Grand-Bassam_24092023_002.jpg","credit":"Yamen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Historic_town_of_Grand-Bassam_24092023_002.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/Historic_town_of_Grand-Bassam_24092023_009.jpg/1280px-Historic_town_of_Grand-Bassam_24092023_009.jpg","credit":"Yamen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Historic_town_of_Grand-Bassam_24092023_009.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Historic_town_of_Grand-Bassam_24092023_012.jpg/1280px-Historic_town_of_Grand-Bassam_24092023_012.jpg","credit":"Yamen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Historic_town_of_Grand-Bassam_24092023_012.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1322/","https://en.wikipedia.org/wiki/Grand-Bassam"]'::jsonb)
