insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sudanese-mosques-civ','CIV','Sudanese-style Mosques',null,'heritage',9.09,-4.15,'Eight small earthen mosques with timber struts and buttress towers, in towns such as Kong and Kaouara.','They follow a style that spread with traders from Djenné around the 14th century, and are replastered by their communities. World Heritage Site since 2021.','Mosques','8',true,true,4,'{"color":"#C8784A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Mosqu%C3%A9e_traditionnelle_du_type_Soudanaise_01.jpg/1280px-Mosqu%C3%A9e_traditionnelle_du_type_Soudanaise_01.jpg","credit":"KONE IF","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Mosqu%C3%A9e_traditionnelle_du_type_Soudanaise_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Mosqu%C3%A9e_traditionnelle_du_type_Soudanaise_02.jpg/1280px-Mosqu%C3%A9e_traditionnelle_du_type_Soudanaise_02.jpg","credit":"KONE IF","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Mosqu%C3%A9e_traditionnelle_du_type_Soudanaise_02.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/Mosqu%C3%A9e_traditionnelle_du_type_Soudanaise_03.jpg/1280px-Mosqu%C3%A9e_traditionnelle_du_type_Soudanaise_03.jpg","credit":"KONE IF","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Mosqu%C3%A9e_traditionnelle_du_type_Soudanaise_03.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1648/","https://en.wikipedia.org/wiki/Sudanese-style_mosques_in_northern_Côte_d''Ivoire"]'::jsonb)
