insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('banco-national-park','CIV','Banco National Park',null,'forest',5.38,-4.05,'A primary rainforest inside the city of Abidjan.','Protected since 1926, it is one of the few urban rainforests in the world, with mahogany trees and a historic forestry school.','Protected since','1926',false,true,5,'{"color":"#1B4332","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/INCURSION_AU_PARC_NATIONAL_DU_BANCO_180.jpg/1280px-INCURSION_AU_PARC_NATIONAL_DU_BANCO_180.jpg","credit":"Mouna k","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:INCURSION_AU_PARC_NATIONAL_DU_BANCO_180.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/INCURSION_AU_PARC_NATIONAL_DU_BANCO_196.jpg/1280px-INCURSION_AU_PARC_NATIONAL_DU_BANCO_196.jpg","credit":"Mouna k","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:INCURSION_AU_PARC_NATIONAL_DU_BANCO_196.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/INCURSION_AU_PARC_NATIONAL_DU_BANCO_200.jpg/1280px-INCURSION_AU_PARC_NATIONAL_DU_BANCO_200.jpg","credit":"Mouna k","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:INCURSION_AU_PARC_NATIONAL_DU_BANCO_200.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Banco_National_Park"]'::jsonb)
