insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('cascade-de-man','CIV','La Cascade, Man',null,'waterfall',7.4,-7.58,'A forest waterfall in the mountains around Man, the “city of 18 mountains”.','The Dent de Man peak and liana bridges of the Dan people are nearby.','Region','Tonkpi',false,true,6,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/La_Cascade_de_Man_1990.jpg/1280px-La_Cascade_de_Man_1990.jpg","credit":"Albert Backer","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:La_Cascade_de_Man_1990.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Les_chutes_d''eau_de_la_Cascade_de_Man_dans_la_r%C3%A9gion_du_Tonkpi_02.jpg/1280px-Les_chutes_d''eau_de_la_Cascade_de_Man_dans_la_r%C3%A9gion_du_Tonkpi_02.jpg","credit":"Yasield","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Les_chutes_d''eau_de_la_Cascade_de_Man_dans_la_r%C3%A9gion_du_Tonkpi_02.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/Woman_with_watering_can,_Dent_de_Man.jpg/1280px-Woman_with_watering_can,_Dent_de_Man.jpg","credit":"FBilula","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Woman_with_watering_can,_Dent_de_Man.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Man,_Ivory_Coast"]'::jsonb)
