insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('assinie','CIV','Assinie',null,'coast',5.13,-3.33,'A narrow sand strip between the Aby lagoon and the Atlantic near the Ghana border.','The French first landed here in the 17th century; today its beaches and lagoon islands are a getaway from Abidjan.','Lagoon','Aby',false,true,7,'{"color":"#0A9396","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/RCI-Assinie-Ile_Napol%C3%A9on_3.jpg/1280px-RCI-Assinie-Ile_Napol%C3%A9on_3.jpg","credit":"WILLAV-FR","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RCI-Assinie-Ile_Napol%C3%A9on_3.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/RCI-Assinie-Ile_Napol%C3%A9on_4.jpg/1280px-RCI-Assinie-Ile_Napol%C3%A9on_4.jpg","credit":"WILLAV-FR","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RCI-Assinie-Ile_Napol%C3%A9on_4.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Assinie_(C%C3%B4te_d''Ivoire).jpg/1280px-Assinie_(C%C3%B4te_d''Ivoire).jpg","credit":"François-Edmond Fortier","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Assinie_(C%C3%B4te_d''Ivoire).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Assinie-Mafia"]'::jsonb)
