insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('western-chimpanzee','CIV','Western Chimpanzee',null,'fauna',5.85,-7.3,'The chimpanzee of West Africa’s forests and savannas, famous for using tools.','Critically Endangered; numbers fell by about 80% between 1990 and 2014. Taï chimps crack nuts with hammers and anvils. The pin is in Taï.','IUCN status','Critically Endangered',false,true,8,'{"color":"#5C4033","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Pan_troglodytes_verus_358759110.jpg/1280px-Pan_troglodytes_verus_358759110.jpg","credit":"Ben Costamagna","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Pan_troglodytes_verus_358759110.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/Westafrikanischer_Schimpanse_(Zoo_Magdeburg).jpg/1280px-Westafrikanischer_Schimpanse_(Zoo_Magdeburg).jpg","credit":"Fiver, der Hellseher","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Westafrikanischer_Schimpanse_(Zoo_Magdeburg).jpg"}]}'::jsonb,'Pan troglodytes verus','["https://en.wikipedia.org/wiki/Western_chimpanzee","https://www.gbif.org/species/search?q=Pan%20troglodytes%20verus"]'::jsonb)
