insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kola-nut','CIV','Kola Nut',null,'flora',6.8,-5.3,'A rainforest tree whose caffeine-rich nuts are shared as a sign of hospitality across West Africa.','Kola has been traded north across the Sahara for centuries and gave its name to cola drinks. Côte d’Ivoire is a major producer. The pin is a representative point.','Contains','Caffeine',false,true,9,'{"color":"#9B2226","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Cola_nitida_tree.JPG/1280px-Cola_nitida_tree.JPG","credit":"Michael Hermann","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Cola_nitida_tree.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Cola_nitida.jpg/1280px-Cola_nitida.jpg","credit":"Satheesan.vn","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Cola_nitida.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/Starr_080103-1440_Cola_nitida.jpg/1280px-Starr_080103-1440_Cola_nitida.jpg","credit":"Forest & Kim Starr","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Starr_080103-1440_Cola_nitida.jpg"}]}'::jsonb,'Cola nitida','["https://en.wikipedia.org/wiki/Cola_nitida","https://en.wikipedia.org/wiki/Kola_nut"]'::jsonb)
