insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kunta-kinteh-island','GMB','Kunta Kinteh Island and Related Sites',null,'heritage',13.32,-16.36,'A small island in the Gambia River with the ruins of a fort used in the Atlantic slave trade.','Formerly James Island, it was renamed after Kunta Kinteh, the ancestor in Alex Haley’s “Roots”. World Heritage Site since 2003.','Inscribed','2003',true,true,1,'{"color":"#BC4749","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Kunta_Kinteh_Island_banner.jpg/1280px-Kunta_Kinteh_Island_banner.jpg","credit":"Niels Elgaard Larsen; derivative by Jjtkk","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Kunta_Kinteh_Island_banner.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Kunta_Kinteh_Island_seen_from_Albadar_beach.jpg/1280px-Kunta_Kinteh_Island_seen_from_Albadar_beach.jpg","credit":"Kenneth Aitchison","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kunta_Kinteh_Island_seen_from_Albadar_beach.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/761/","https://en.wikipedia.org/wiki/Kunta_Kinteh_Island"]'::jsonb)
