insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('senegambian-stone-circles','GMB','Stone Circles of Senegambia',null,'heritage',13.69,-14.86,'More than 1,000 monuments of standing laterite stones along the Gambia River, in Gambia and Senegal.','Built from about the 3rd century BCE to the 16th century CE over burial sites; Wassu and Kerbatch are the best known. World Heritage Site since 2006.','Monuments','1,000+',true,true,2,'{"color":"#B5651D","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/UNESCO_Wassu_Stone_Circles_(3686688823).jpg/1280px-UNESCO_Wassu_Stone_Circles_(3686688823).jpg","credit":"Niels Broekzitter","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:UNESCO_Wassu_Stone_Circles_(3686688823).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/UNESCO_Wassu_Stone_Circles_(3687494306).jpg/1280px-UNESCO_Wassu_Stone_Circles_(3687494306).jpg","credit":"Niels Broekzitter","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:UNESCO_Wassu_Stone_Circles_(3687494306).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/UNESCO_Wassu_Stone_Circles_(3687498356).jpg/1280px-UNESCO_Wassu_Stone_Circles_(3687498356).jpg","credit":"Niels Broekzitter","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:UNESCO_Wassu_Stone_Circles_(3687498356).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1226/","https://en.wikipedia.org/wiki/Senegambian_stone_circles"]'::jsonb)
