insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('river-gambia-national-park','GMB','River Gambia National Park','Baboon Islands','river',13.64,-14.96,'Five river islands where rehabilitated chimpanzees live free, alongside hippos and crocodiles.','The Chimpanzee Rehabilitation Project has released orphaned chimps here since 1979; visitors watch only from boats.','Chimps since','1979',false,true,3,'{"color":"#2A6F97","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/b/bf/14.95875W_13.63887N.png","credit":"NASA","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:14.95875W_13.63887N.png"}],"note":"Satellite view of the Baboon Islands."}'::jsonb,null,'["https://en.wikipedia.org/wiki/River_Gambia_National_Park"]'::jsonb)
