insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('abuko','GMB','Abuko Nature Reserve',null,'forest',13.4,-16.65,'A small gallery forest near Banjul, The Gambia’s first protected area.','Protected since 1916 as a water catchment, it shelters red colobus, green monkeys, Nile crocodiles and over 250 bird species.','Protected since','1916',false,true,4,'{"color":"#3A7D44","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Gambia_abuko_001.jpg/1280px-Gambia_abuko_001.jpg","credit":"Atamari","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Gambia_abuko_001.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Gambia_abuko_002.jpg/1280px-Gambia_abuko_002.jpg","credit":"Atamari","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Gambia_abuko_002.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Gambia_abuko_007.jpg/1280px-Gambia_abuko_007.jpg","credit":"Atamari","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Gambia_abuko_007.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Abuko_Nature_Reserve"]'::jsonb)
