insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tanji','GMB','Tanji Bird Reserve',null,'coast',13.37,-16.8,'Dunes, lagoons and the Bijol Islands on the Atlantic coast, beside a busy fishing village.','Established in 1993, it covers about 612 ha and records over 300 bird species, plus nesting turtles on the islands.','Area','612 ha',false,true,5,'{"color":"#E9C46A","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/1/1a/Gambia_064_from_KG.jpg","credit":"KG (via Atamari)","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Gambia_064_from_KG.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Lavender_waxbill_(Estrilda_caerulescens).jpg/1280px-Lavender_waxbill_(Estrilda_caerulescens).jpg","credit":"Charles J. Sharp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Lavender_waxbill_(Estrilda_caerulescens).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Yellow-billed_shrike_(Corvinella_corvina_corvina).jpg/1280px-Yellow-billed_shrike_(Corvinella_corvina_corvina).jpg","credit":"Charles J. Sharp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Yellow-billed_shrike_(Corvinella_corvina_corvina).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Tanji_Bird_Reserve"]'::jsonb)
