insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('temmincks-red-colobus','GMB','Temminck’s Red Colobus',null,'fauna',13.4,-16.65,'A leaf-eating monkey with a rust-red coat, found from The Gambia to north-west Guinea.','Colobus have no thumbs, and a stomach that ferments leaves. It is Endangered; Abuko is one of the easiest places to see it. The pin is at Abuko.','IUCN status','Endangered',false,true,6,'{"color":"#BC4749","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Piliocolobus_temminckii_0003.jpg/1280px-Piliocolobus_temminckii_0003.jpg","credit":"Atamari","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Piliocolobus_temminckii_0003.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Piliocolobus_temminckii_0004.jpg/1280px-Piliocolobus_temminckii_0004.jpg","credit":"Atamari","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Piliocolobus_temminckii_0004.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Piliocolobus_temminckii_0008.jpg/1280px-Piliocolobus_temminckii_0008.jpg","credit":"Atamari","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Piliocolobus_temminckii_0008.jpg"}]}'::jsonb,'Piliocolobus badius temminckii','["https://en.wikipedia.org/wiki/Temminck''s_red_colobus","https://www.gbif.org/species/search?q=Piliocolobus%20badius"]'::jsonb)
