insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kino-tree','GMB','African Rosewood','kino tree · keno','flora',13.4,-15.6,'A savanna tree with red timber, now Endangered after a rosewood logging boom.','Trade is restricted under CITES since 2016 because illegal logging, much of it routed through Gambian ports, stripped forests in the region. The pin is a representative point.','IUCN status','Endangered',false,true,7,'{"color":"#7F2F1E","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Pterocarpus_erinaceus_%C3%A0_Savalou_au_centre_du_B%C3%A9nin.jpg/1280px-Pterocarpus_erinaceus_%C3%A0_Savalou_au_centre_du_B%C3%A9nin.jpg","credit":"Yelouassi","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pterocarpus_erinaceus_%C3%A0_Savalou_au_centre_du_B%C3%A9nin.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/B%C3%A9nin-Pterocarpus_erinaceus.jpg/1280px-B%C3%A9nin-Pterocarpus_erinaceus.jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:B%C3%A9nin-Pterocarpus_erinaceus.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Pterocarpus_erinaceus.jpg/1280px-Pterocarpus_erinaceus.jpg","credit":"Kalle.holt","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pterocarpus_erinaceus.jpg"}]}'::jsonb,'Pterocarpus erinaceus','["https://en.wikipedia.org/wiki/Pterocarpus_erinaceus","https://www.gbif.org/species/search?q=Pterocarpus%20erinaceus"]'::jsonb)
