insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('forts-and-castles-ghana','GHA','Forts and Castles of Ghana',null,'heritage',5.1,-1.24,'Fortified trading posts built along the Gold Coast between 1482 and 1786, including Elmina and Cape Coast castles.','Built by Portuguese, Dutch, Danish, Swedish, German and British traders, they held enslaved Africans in dungeons before the Atlantic crossing. World Heritage Site since 1979.','Built','1482–1786',true,true,1,'{"color":"#EDE0D4","intensity":0.85,"motion":"ripple"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/fb/Cape_Coast_Castle.webm/Cape_Coast_Castle.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/fb/Cape_Coast_Castle.webm/Cape_Coast_Castle.webm.360p.mpeg4.mov","credit":"Esthee2010","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cape_Coast_Castle.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Cape_Coast_Castle,_Cape_Coast,_Ghana.JPG/1280px-Cape_Coast_Castle,_Cape_Coast,_Ghana.JPG","credit":"Rjruiziii","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Cape_Coast_Castle,_Cape_Coast,_Ghana.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Elmina_Castle_-_Ghana.jpg/1280px-Elmina_Castle_-_Ghana.jpg","credit":"Damien Halleux Radermecker","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Elmina_Castle_-_Ghana.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Elmina_Castle_Ramparts_(3587901478).jpg/1280px-Elmina_Castle_Ramparts_(3587901478).jpg","credit":"Francisco Anzola","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Elmina_Castle_Ramparts_(3587901478).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/34/","https://en.wikipedia.org/wiki/Forts_and_castles_of_Ghana","https://en.wikipedia.org/wiki/Cape_Coast_Castle"]'::jsonb)
