insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('asante-traditional-buildings','GHA','Asante Traditional Buildings',null,'heritage',6.7,-1.6,'The last surviving shrines and houses of the Asante kingdom, around Kumasi, built of earth, timber and thatch.','Their walls carry bold relief patterns, a vocabulary shared with Adinkra symbols. Much of old Kumasi was destroyed by the British in 1874. World Heritage Site since 1980.','Buildings','10',true,true,2,'{"color":"#9B2226","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Asenemaso_Shrine_(a.k.a._Tano_Banie_Shrine).jpg/1280px-Asenemaso_Shrine_(a.k.a._Tano_Banie_Shrine).jpg","credit":"Noahalorwu","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Asenemaso_Shrine_(a.k.a._Tano_Banie_Shrine).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Kentikrono_Shrine_(1).jpg/1280px-Kentikrono_Shrine_(1).jpg","credit":"Noahalorwu","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kentikrono_Shrine_(1).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Kentikrono_Shrine_2,_Kumasi.jpg/1280px-Kentikrono_Shrine_2,_Kumasi.jpg","credit":"Joy Agyepong","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kentikrono_Shrine_2,_Kumasi.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/35/","https://en.wikipedia.org/wiki/Asante_Traditional_Buildings"]'::jsonb)
