insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kakum','GHA','Kakum National Park',null,'forest',5.35,-1.38,'Moist tropical forest near Cape Coast, crossed by a canopy walkway 30–40 m above the ground.','The 350 m walkway hangs between giant trees. The forest shelters forest elephants, Diana monkeys and hundreds of bird and butterfly species.','Area','375 km²',false,true,3,'{"color":"#1B4332","intensity":0.85,"motion":"mist"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/0/04/Drone_video_shot_of_Kakum_National_Park.webm/Drone_video_shot_of_Kakum_National_Park.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/0/04/Drone_video_shot_of_Kakum_National_Park.webm/Drone_video_shot_of_Kakum_National_Park.webm.360p.mpeg4.mov","credit":"daSupremo","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Drone_video_shot_of_Kakum_National_Park.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/KAKUM-NATIONAL-PARK-4.jpg/1280px-KAKUM-NATIONAL-PARK-4.jpg","credit":"Kobby Monies","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:KAKUM-NATIONAL-PARK-4.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Kakum_National_Park_entrance.jpg/1280px-Kakum_National_Park_entrance.jpg","credit":"daSupremo","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kakum_National_Park_entrance.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Kakum_National_Park"]'::jsonb)
