insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('wli-falls','GHA','Wli Falls',null,'waterfall',7.12,0.59,'Ghana’s highest waterfall, falling in two tiers in the forested Agumatsa hills near the Togo border.','Thousands of fruit bats roost in the cliffs around the lower fall.','Region','Volta',false,true,4,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Wli_Lower_Fall-2.jpg/1280px-Wli_Lower_Fall-2.jpg","credit":"Stig Nygaard","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Wli_Lower_Fall-2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Wli_Waterfalls.JPG/1280px-Wli_Waterfalls.JPG","credit":"Eantwiagyei","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Wli_Waterfalls.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Wli_waterfalls"]'::jsonb)
