insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-bosumtwi','GHA','Lake Bosumtwi',null,'lake',6.51,-1.41,'Ghana’s only natural lake, sitting in a meteorite impact crater about 10.5 km across.','The crater is about 1 million years old. Sacred to the Asante, the lake may be fished only from wooden planks, not boats.','Crater age','~1 million years',false,true,5,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Lake_Bosumtwi_Panorama.jpg/1280px-Lake_Bosumtwi_Panorama.jpg","credit":"Erik Cleves Kristensen","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Lake_Bosumtwi_Panorama.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Lake_Bosumtwi,_Ghana.jpg/1280px-Lake_Bosumtwi,_Ghana.jpg","credit":"Stig Nygaard","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Lake_Bosumtwi,_Ghana.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Adam_Jones_Bosumtwi_Ufer_B002.jpg/1280px-Adam_Jones_Bosumtwi_Ufer_B002.jpg","credit":"Adam Jones","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Adam_Jones_Bosumtwi_Ufer_B002.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Bosumtwi"]'::jsonb)
