insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mole-national-park','GHA','Mole National Park',null,'savanna',9.7,-1.83,'Ghana’s largest wildlife refuge, savanna woodland where elephants come to the waterholes below the motel.','It holds elephants, buffalo, antelope and over 300 bird species. The 15th-century Larabanga mosque stands nearby.','Area','~4,600 km²',false,true,6,'{"color":"#D4A017","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/7/74/Elephant.webm/Elephant.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/7/74/Elephant.webm/Elephant.webm.360p.mpeg4.mov","credit":"OJjnr","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Elephant.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Mole_National_Park,_West_Gonja_(P1100345-Pano).jpg/1280px-Mole_National_Park,_West_Gonja_(P1100345-Pano).jpg","credit":"Matti Blume","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mole_National_Park,_West_Gonja_(P1100345-Pano).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Mole_National_Park,_West_Gonja_(P1100487).jpg/1280px-Mole_National_Park,_West_Gonja_(P1100487).jpg","credit":"Matti Blume","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mole_National_Park,_West_Gonja_(P1100487).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Mole_National_Park"]'::jsonb)
