insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('grey-parrot','GHA','Grey Parrot',null,'fauna',6.2,-2,'A grey forest parrot with a red tail, famous for mimicking speech.','Trapping for the pet trade and forest loss wiped out an estimated 90–99% of Ghana’s grey parrots after 1992. The species is Endangered. The pin is a representative point.','IUCN status','Endangered',false,true,7,'{"color":"#9AA0A6","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/African_Grey_Parrot_(Psittacus_erithacus)4.jpg/1280px-African_Grey_Parrot_(Psittacus_erithacus)4.jpg","credit":"Tom Woodward","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:African_Grey_Parrot_(Psittacus_erithacus)4.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Psittacus_erithacus_-upper_body-8c.jpg/1280px-Psittacus_erithacus_-upper_body-8c.jpg","credit":"L. Miguel Bugallo Sánchez","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Psittacus_erithacus_-upper_body-8c.jpg"}]}'::jsonb,'Psittacus erithacus','["https://en.wikipedia.org/wiki/Grey_parrot","https://www.gbif.org/species/search?q=Psittacus%20erithacus"]'::jsonb)
