insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ackee','GHA','Ackee','akye (Twi)','flora',6.7,-1.6,'A West African tree whose red pods split open to show black seeds on creamy flesh.','Its name comes from the Twi word akye. Carried across the Atlantic in the slave era, it became Jamaica’s national fruit. Unripe fruit is toxic. The pin is near Kumasi.','Name from','Twi akye',false,true,8,'{"color":"#E63946","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Ackee_001.jpg/1280px-Ackee_001.jpg","credit":"Jerome Walker","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Ackee_001.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Blighia_sapida_MS_4321.jpg/1280px-Blighia_sapida_MS_4321.jpg","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Blighia_sapida_MS_4321.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Blighia_sapida_(DITSL).JPG/1280px-Blighia_sapida_(DITSL).JPG","credit":"James Steakley","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Blighia_sapida_(DITSL).JPG"}]}'::jsonb,'Blighia sapida','["https://en.wikipedia.org/wiki/Ackee","https://www.gbif.org/species/search?q=Blighia%20sapida"]'::jsonb)
