insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mount-nimba','GIN','Mount Nimba Strict Nature Reserve',null,'mountain',7.64,-8.42,'A mountain ridge rising to 1,752 m above the forest, shared by Guinea and Côte d’Ivoire.','Grassland summits over cloud forest hold many endemic species, including the viviparous Nimba toad. On the List in Danger since 1992 over iron-ore mining threats.','Highest point','1,752 m',true,true,1,'{"color":"#2D6A4F","intensity":0.85,"motion":"mist"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/d/da/Musoke_Deo_MDK-MUSO_12_This_is_a_water_fall_found_in_one_of_the_thick_forests_from_Ivory_coast,Mount_Nimba.webm/Musoke_Deo_MDK-MUSO_12_This_is_a_water_fall_found_in_one_of_the_thick_forests_from_Ivory_coast,Mount_Nimba.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/d/da/Musoke_Deo_MDK-MUSO_12_This_is_a_water_fall_found_in_one_of_the_thick_forests_from_Ivory_coast,Mount_Nimba.webm/Musoke_Deo_MDK-MUSO_12_This_is_a_water_fall_found_in_one_of_the_thick_forests_from_Ivory_coast,Mount_Nimba.webm.360p.mpeg4.mov","credit":"MDK-MUSO","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Musoke_Deo_MDK-MUSO_12_This_is_a_water_fall_found_in_one_of_the_thick_forests_from_Ivory_coast,Mount_Nimba.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Mount_Nimba_-_cloud_forests.jpg/1280px-Mount_Nimba_-_cloud_forests.jpg","credit":"Yakoo1986","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Nimba_-_cloud_forests.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Nimba_montanegrassland.jpg/1280px-Nimba_montanegrassland.jpg","credit":"Yakoo1986","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Nimba_montanegrassland.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Nimba_proteabush.jpg/1280px-Nimba_proteabush.jpg","credit":"Yakoo1986","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Nimba_proteabush.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/155/","https://en.wikipedia.org/wiki/Mount_Nimba_Strict_Nature_Reserve"]'::jsonb)
