insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('fouta-djallon','GIN','Fouta Djallon',null,'mountain',11.31,-12.3,'A highland of sandstone plateaus and waterfalls in central Guinea.','The Gambia and Senegal rivers rise here, and the Niger rises in Guinea’s southern highlands nearby, which is why Guinea is called the water tower of West Africa. Home of the Fula Imamate of Futa Jallon.','Rivers born','Gambia · Senegal',false,true,2,'{"color":"#B5502E","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Fouta_Djallon_(14625360573).jpg/1280px-Fouta_Djallon_(14625360573).jpg","credit":"Maarten van der Bent","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Fouta_Djallon_(14625360573).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Chute_de_Ditinn_%C3%A0_Dalaba.jpg/1280px-Chute_de_Ditinn_%C3%A0_Dalaba.jpg","credit":"Maarten van der Bent","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Chute_de_Ditinn_%C3%A0_Dalaba.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Fouta_Djallon_(14582293626).jpg/1280px-Fouta_Djallon_(14582293626).jpg","credit":"Maarten van der Bent","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Fouta_Djallon_(14582293626).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Fouta_Djallon"]'::jsonb)
