insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('voile-de-la-mariee','GIN','Voile de la Mariée','“the bride’s veil”','waterfall',10,-12.95,'A veil-like waterfall in the forested hills near Kindia.','Its spray spreads over a broad rock face, giving it its name. A popular trip from Conakry.','Near','Kindia',false,true,3,'{"color":"#90E0EF","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Voile_de_la_mari%C3%A9_kindia_s%C3%A9gu%C3%A9ya.jpg/1280px-Voile_de_la_mari%C3%A9_kindia_s%C3%A9gu%C3%A9ya.jpg","credit":"M keita1321","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Voile_de_la_mari%C3%A9_kindia_s%C3%A9gu%C3%A9ya.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Case_%C3%A0_la_voile_des_Marie_de_Kindia_01.jpg/1280px-Case_%C3%A0_la_voile_des_Marie_de_Kindia_01.jpg","credit":"Aboubacarkhoraa","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Case_%C3%A0_la_voile_des_Marie_de_Kindia_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Case_%C3%A0_la_voile_des_Marie_de_Kindia_06.jpg/1280px-Case_%C3%A0_la_voile_des_Marie_de_Kindia_06.jpg","credit":"Aboubacarkhoraa","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Case_%C3%A0_la_voile_des_Marie_de_Kindia_06.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Kindia"]'::jsonb)
