insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('iles-de-los','GIN','Îles de Los',null,'coast',9.46,-13.79,'Volcanic islands off Conakry with palm-lined beaches.','Their name comes from the Portuguese “Ilhas dos Ídolos”, islands of idols. The islands are the remains of a volcanic ring complex.','Name','Islands of idols',false,true,4,'{"color":"#48CAE4","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Plage_de_Roume.jpg/1280px-Plage_de_Roume.jpg","credit":"Flucco","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Plage_de_Roume.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Îles_de_Los"]'::jsonb)
