insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('nimba-toad','GIN','Western Nimba Toad',null,'fauna',7.62,-8.4,'A tiny toad that gives birth to live young, found only in the grasslands of Mount Nimba.','Females carry their young for about nine months and feed them through a kind of placental secretion, one of very few frogs or toads to do so. Critically Endangered. The pin is on Mount Nimba.','Length','~2 cm',false,true,5,'{"color":"#5C4033","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/8/8f/Nimbaphrynoides_occidentalis_gestating_female.jpg","credit":"Sandberger-Loua L, Müller H, Rödel M-O","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Nimbaphrynoides_occidentalis_gestating_female.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/1/19/Nimbaphrynoides_occidentalis_female_and_male_in_amplexus.jpg","credit":"Sandberger-Loua L, Müller H, Rödel M-O","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Nimbaphrynoides_occidentalis_female_and_male_in_amplexus.jpg"}]}'::jsonb,'Nimbaphrynoides occidentalis','["https://en.wikipedia.org/wiki/Western_Nimba_toad","https://www.gbif.org/species/search?q=Nimbaphrynoides%20occidentalis"]'::jsonb)
