insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('oil-palm','GIN','African Oil Palm',null,'flora',9.5,-12.5,'The palm of the Guinea coast, whose orange fruit gives red palm oil.','Named for Guinea in its scientific name, it is now grown across the tropics and is the world’s most-used vegetable oil. The pin is a representative point.','Native to','West Africa',false,true,6,'{"color":"#F77F00","intensity":0.85,"motion":"bloom"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/7/78/Pounding_oil_palm_for_soup.webm/Pounding_oil_palm_for_soup.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/7/78/Pounding_oil_palm_for_soup.webm/Pounding_oil_palm_for_soup.webm.360p.mpeg4.mov","credit":"Geossegawa","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pounding_oil_palm_for_soup.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Elaeis_guineensis_MS_3467.jpg/1280px-Elaeis_guineensis_MS_3467.jpg","credit":"Marco Schmidt","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Elaeis_guineensis_MS_3467.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Elaeis_guineensis_oil_palm_fruit_Portoviejo_Ecuador.jpg/1280px-Elaeis_guineensis_oil_palm_fruit_Portoviejo_Ecuador.jpg","credit":"Cayambe","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Elaeis_guineensis_oil_palm_fruit_Portoviejo_Ecuador.jpg"}]}'::jsonb,'Elaeis guineensis','["https://en.wikipedia.org/wiki/Elaeis_guineensis","https://www.gbif.org/species/search?q=Elaeis%20guineensis"]'::jsonb)
