insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bijagos','GNB','Bijagós Archipelago','Omatí Minhô','coast',11.25,-16.08,'A delta archipelago of about 88 islands, with mangroves, mudflats and sacred forests.','Its tidal flats host hundreds of thousands of migrating shorebirds, green turtles nest on its beaches, and hippos live in brackish lagoons. The matrilineal Bijagó people manage many islands as sacred. World Heritage Site since 2025.','Islands','~88',true,true,1,'{"color":"#5FA8D3","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Bubaque,_south.jpg/1280px-Bubaque,_south.jpg","credit":"R.S. Puijk","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Bubaque,_south.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Ile_de_Bubaque_-_Archipel_des_Bijagos.JPG/1280px-Ile_de_Bubaque_-_Archipel_des_Bijagos.JPG","credit":"Odile RAPEAU","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ile_de_Bubaque_-_Archipel_des_Bijagos.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Bubaque_port.jpg/1280px-Bubaque_port.jpg","credit":"Nammarci","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Bubaque_port.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1431/","https://en.wikipedia.org/wiki/Bissagos_Islands"]'::jsonb)
