insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('cacheu-mangroves','GNB','Cacheu River Mangroves',null,'wetland',12.3,-16.18,'One of the largest mangrove blocks in West Africa, along the Cacheu estuary.','Created as a natural park in 2000; manatees, crocodiles and many waterbirds live in its creeks.','Created','2000',false,true,2,'{"color":"#2D6A4F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/Parque_Natural_dos_Tarrafes_do_Rio_Cacheu_01.jpg/1280px-Parque_Natural_dos_Tarrafes_do_Rio_Cacheu_01.jpg","credit":"Joehawkins","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Parque_Natural_dos_Tarrafes_do_Rio_Cacheu_01.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Cacheu_River_Mangroves_Natural_Park"]'::jsonb)
