insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bolama','GNB','Bolama',null,'heritage',11.58,-15.48,'An island town at the edge of the Bijagós that was the capital of Portuguese Guinea until 1941.','Its colonial avenues and public buildings now stand half-ruined among mango trees, a quiet record of the colonial era.','Capital until','1941',false,true,3,'{"color":"#8B5E34","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Bolama_ruins.jpg/1280px-Bolama_ruins.jpg","credit":"Nammarci","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Bolama_ruins.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/Porto_de_Bolama,_Bolama,_Guin%C3%A9-Bissau_%E2%80%93_2018-03-02_%E2%80%93_DSCN1008.jpg/1280px-Porto_de_Bolama,_Bolama,_Guin%C3%A9-Bissau_%E2%80%93_2018-03-02_%E2%80%93_DSCN1008.jpg","credit":"Helena Maria Pestana","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Porto_de_Bolama,_Bolama,_Guin%C3%A9-Bissau_%E2%80%93_2018-03-02_%E2%80%93_DSCN1008.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Viagem_de_Bissau_para_Bolama,_Guin%C3%A9-Bissau_%E2%80%93_2018-03-02_%E2%80%93_DSCN0996.jpg/1280px-Viagem_de_Bissau_para_Bolama,_Guin%C3%A9-Bissau_%E2%80%93_2018-03-02_%E2%80%93_DSCN0996.jpg","credit":"Helena Maria Pestana","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Viagem_de_Bissau_para_Bolama,_Guin%C3%A9-Bissau_%E2%80%93_2018-03-02_%E2%80%93_DSCN0996.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Bolama"]'::jsonb)
