insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('orango-hippos','GNB','Saltwater Hippos of Orango',null,'fauna',11.12,-16.05,'Hippos that swim between islands through seawater in the Bijagós.','On Orango they live in freshwater lagoons but cross sea channels, an unusual behaviour for hippos. They are revered by the Bijagó. The pin is in Orango National Park.','Park','Orango (2000)',false,true,4,'{"color":"#8B5E34","intensity":0.85,"motion":"ripple"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/7/77/Mouth_of_a_hippopotamus_(Hippopotamus_amphibius).webm/Mouth_of_a_hippopotamus_(Hippopotamus_amphibius).webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/7/77/Mouth_of_a_hippopotamus_(Hippopotamus_amphibius).webm/Mouth_of_a_hippopotamus_(Hippopotamus_amphibius).webm.360p.mpeg4.mov","credit":"kartfamily","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Mouth_of_a_hippopotamus_(Hippopotamus_amphibius).webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Hippo_pod_edit.jpg/1280px-Hippo_pod_edit.jpg","credit":"Paul Maritz","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Hippo_pod_edit.jpg"}],"note":"Hippos photographed elsewhere — no open footage from Orango yet."}'::jsonb,'Hippopotamus amphibius','["https://en.wikipedia.org/wiki/Orango_Islands_National_Park","https://en.wikipedia.org/wiki/Hippopotamus"]'::jsonb)
