insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('red-mangrove-gnb','GNB','Red Mangrove',null,'flora',11.9,-15.9,'A mangrove on arching stilt roots that lines the creeks of Guinea-Bissau.','Mangroves cover a large share of the country’s coast, sheltering fish nurseries and storing carbon. Its seeds sprout while still on the tree. The pin is a representative point.','Seeds','Sprout on the tree',false,true,5,'{"color":"#7F4F24","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/MACOURIA_068.jpg/1280px-MACOURIA_068.jpg","credit":"Flavia Mochel","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:MACOURIA_068.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Rhizophora_racemosa_flowers.jpg/1280px-Rhizophora_racemosa_flowers.jpg","credit":"Sommerluk","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Rhizophora_racemosa_flowers.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Rhizophora_racemosa_reproduction.jpg/1280px-Rhizophora_racemosa_reproduction.jpg","credit":"Sommerluk","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Rhizophora_racemosa_reproduction.jpg"}]}'::jsonb,'Rhizophora racemosa','["https://en.wikipedia.org/wiki/Rhizophora_racemosa","https://www.gbif.org/species/search?q=Rhizophora%20racemosa"]'::jsonb)
