insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sapo-national-park','LBR','Sapo National Park',null,'forest',5.41,-8.41,'Liberia’s largest protected rainforest, in Sinoe County.','Part of the Upper Guinean forest, one of the world’s biodiversity hotspots; it shelters pygmy hippos, forest elephants and chimpanzees.','Area','~1,800 km²',false,true,1,'{"color":"#1B4332","intensity":0.85,"motion":"mist"}'::jsonb,'{"note":"No openly licensed photos of Sapo yet."}'::jsonb,null,'["https://en.wikipedia.org/wiki/Sapo_National_Park"]'::jsonb)
