insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kpatawee-falls','LBR','Kpatawee Falls',null,'waterfall',7.08,-9.83,'A forest waterfall in Bong County, a favourite weekend escape from Monrovia.','Water tumbles over granite steps into pools surrounded by rainforest.','County','Bong',false,true,2,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Front_View_of_Kpatawee_Falls.jpg/1280px-Front_View_of_Kpatawee_Falls.jpg","credit":"Bethel. Anthony Chisom","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Front_View_of_Kpatawee_Falls.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Bong_County"]'::jsonb)
