insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-piso','LBR','Lake Piso','Fisherman’s Lake','lake',6.74,-11.25,'A large tidal lagoon in Grand Cape Mount County, separated from the sea by a sand bar.','Its mangroves and beaches are a proposed protected area; Pan Am flying boats used it as a base during the Second World War.','County','Grand Cape Mount',false,true,3,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/3/3d/A_view_of_Lake_Piso,_Bomi_County.jpg","credit":"Bethel. Anthony Chisom","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:A_view_of_Lake_Piso,_Bomi_County.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/8/88/Lake_Piso,_Bomi_County.jpg","credit":"Bethel. Anthony Chisom","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Lake_Piso,_Bomi_County.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/2/21/Another_view_of_Lake_Piso,_Bomi_County.jpg","credit":"Bethel. Anthony Chisom","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Another_view_of_Lake_Piso,_Bomi_County.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Piso"]'::jsonb)
