insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('east-nimba','LBR','East Nimba Nature Reserve',null,'mountain',7.5,-8.6,'The Liberian side of the Nimba range, with montane forest above old iron-ore workings.','It protects forest linked to the Nimba World Heritage Site across the border in Guinea and Côte d’Ivoire.','County','Nimba',false,true,4,'{"color":"#52B788","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/Nimba_County,_Bush_route.jpg/1280px-Nimba_County,_Bush_route.jpg","credit":"Bethel. Anthony Chisom","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Nimba_County,_Bush_route.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Nimba_Range"]'::jsonb)
