insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('pygmy-hippo','LBR','Pygmy Hippopotamus',null,'fauna',5.3,-8.6,'A shy forest hippo about a tenth the weight of its river cousin, living alone in swamp forest.','Most of the world’s wild pygmy hippos live in Liberia. Fewer than about 2,500 remain; the species is Endangered. The pin is near Sapo.','IUCN status','Endangered',false,true,5,'{"color":"#3D405B","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/d/d4/Pygmy_hippopotamus.webm/Pygmy_hippopotamus.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/d/d4/Pygmy_hippopotamus.webm/Pygmy_hippopotamus.webm.360p.mpeg4.mov","credit":"Altes","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pygmy_hippopotamus.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Zwergflusspferd_-_Pygmy_Hippopotamus_-_Hexaprotodon_liberiensis.jpg/1280px-Zwergflusspferd_-_Pygmy_Hippopotamus_-_Hexaprotodon_liberiensis.jpg","credit":"Raimond Spekking","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Zwergflusspferd_-_Pygmy_Hippopotamus_-_Hexaprotodon_liberiensis.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/Pygmy_hippopotamus_pair.jpg/1280px-Pygmy_hippopotamus_pair.jpg","credit":"Chuckupd","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Pygmy_hippopotamus_pair.jpg"}]}'::jsonb,'Choeropsis liberiensis','["https://en.wikipedia.org/wiki/Pygmy_hippopotamus","https://www.gbif.org/species/search?q=Choeropsis%20liberiensis"]'::jsonb)
