insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('liberian-coffee','LBR','Liberian Coffee',null,'flora',6.5,-10,'A tall coffee tree from the West African forests with large, smoky-tasting beans.','It rescued coffee growing in Asia after leaf rust struck in the 19th century, and is still grown in Malaysia and the Philippines. The pin is a representative point.','Share of world coffee','~2%',false,true,6,'{"color":"#6F4E37","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/58/Coffea_liberica_(5597934575).jpg/1280px-Coffea_liberica_(5597934575).jpg","credit":"Dinesh Valke","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Coffea_liberica_(5597934575).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Liberian_Coffee_(5597839545).jpg/1280px-Liberian_Coffee_(5597839545).jpg","credit":"Dinesh Valke","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Liberian_Coffee_(5597839545).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/Coffee_tree_chary.jpg/1280px-Coffee_tree_chary.jpg","credit":"DXLINH","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Coffee_tree_chary.jpg"}]}'::jsonb,'Coffea liberica','["https://en.wikipedia.org/wiki/Coffea_liberica","https://www.gbif.org/species/search?q=Coffea%20liberica"]'::jsonb)
