insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('djenne','MLI','Old Towns of Djenné',null,'heritage',13.91,-4.55,'A mud-brick town in the inland Niger delta, crowned by the largest earthen building in the world, the Great Mosque.','Each year the whole town replasters the mosque in a festival called the Crépissage. Djenné-Djeno nearby is one of the oldest known cities south of the Sahara. World Heritage Site since 1988.','Mosque rebuilt','1907',true,true,1,'{"color":"#C8784A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/MaliDjenn%C3%A9Mosqu%C3%A9e.JPG/1280px-MaliDjenn%C3%A9Mosqu%C3%A9e.JPG","credit":"BluesyPete","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:MaliDjenn%C3%A9Mosqu%C3%A9e.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Djenn%C3%A9_banner.jpg/1280px-Djenn%C3%A9_banner.jpg","credit":"Devriese; derivative by JamesA","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Djenn%C3%A9_banner.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Djenn%C3%A9_Moschee(Dach)1990.jpg/1280px-Djenn%C3%A9_Moschee(Dach)1990.jpg","credit":"Albert Backer","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Djenn%C3%A9_Moschee(Dach)1990.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/116/","https://en.wikipedia.org/wiki/Great_Mosque_of_Djenné"]'::jsonb)
