insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('timbuktu','MLI','Timbuktu',null,'heritage',16.78,-3.01,'A desert city near the Niger that was a great centre of Islamic scholarship in the 15th and 16th centuries.','Its Djinguereber, Sankore and Sidi Yahia mosques and tens of thousands of manuscripts survive. Mausoleums destroyed in 2012 were rebuilt by local masons. World Heritage Site since 1988.','Djinguereber','1327',true,true,2,'{"color":"#E9C46A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/Djinguereber_Mosque,_Timbuktu.jpg/1280px-Djinguereber_Mosque,_Timbuktu.jpg","credit":"upyernoz","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Djinguereber_Mosque,_Timbuktu.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/02/Djinguereber_in_Timbuktu.jpg/1280px-Djinguereber_in_Timbuktu.jpg","credit":"upyernoz","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Djinguereber_in_Timbuktu.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/ASC_Leiden_-_van_Achterberg_Collection_-_05_-_29_-_Un_four_%C3%A0_pain_br%C3%BBlant_avec_la_tour_(minaret)_de_la_mosqu%C3%A9e_Djingareyber_-_Tombouctou,_Mali_-_Novembre-d%C3%A9cembre_1993.jpg/1280px-thumbnail.jpg","credit":"Angeline A. van Achterberg","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:ASC_Leiden_-_van_Achterberg_Collection_-_05_-_29_-_Un_four_%C3%A0_pain_br%C3%BBlant_avec_la_tour_(minaret)_de_la_mosqu%C3%A9e_Djingareyber_-_Tombouctou,_Mali_-_Novembre-d%C3%A9cembre_1993.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/119/","https://en.wikipedia.org/wiki/Timbuktu"]'::jsonb)
