insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bandiagara','MLI','Cliff of Bandiagara','Land of the Dogons','rock',14.33,-3.42,'A sandstone escarpment about 150 km long with Dogon villages, granaries and older Tellem cliff dwellings.','The cliff rises up to about 500 m above the plain. Dogon masks, dances and cosmology are tied to the landscape. A mixed World Heritage Site since 1989.','Length','~150 km',true,true,3,'{"color":"#8C5A3C","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Bandiagara_escarpment_1.jpg/1280px-Bandiagara_escarpment_1.jpg","credit":"Ferdinand Reus","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Bandiagara_escarpment_1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Telli_bandiagara.jpg/1280px-Telli_bandiagara.jpg","credit":"J. Drevet","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Telli_bandiagara.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Bandiagara_escarpment_2.jpg/1280px-Bandiagara_escarpment_2.jpg","credit":"Ferdinand Reus","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Bandiagara_escarpment_2.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/516/","https://en.wikipedia.org/wiki/Bandiagara_Escarpment"]'::jsonb)
