insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tomb-of-askia','MLI','Tomb of Askia',null,'heritage',16.29,-0.04,'A 17 m pyramidal mud tower in Gao, built in 1495 by Askia Mohammed, emperor of Songhai.','It shows the Sudano-Sahelian style at its most monumental, bristling with wooden beams. World Heritage Site since 2004.','Height','~17 m',true,true,4,'{"color":"#B5651D","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Tombeau_dAskia_in_Gao_by_David_Sessoms.jpg/1280px-Tombeau_dAskia_in_Gao_by_David_Sessoms.jpg","credit":"David Sessoms","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Tombeau_dAskia_in_Gao_by_David_Sessoms.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/ETH-BIB-Grabmal_von_Askia,_Gao-Tschadseeflug_1930-31-LBS_MH02-08-0549.tif/lossy-page1-1280px-ETH-BIB-Grabmal_von_Askia,_Gao-Tschadseeflug_1930-31-LBS_MH02-08-0549.tif.jpg","credit":"Walter Mittelholzer","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:ETH-BIB-Grabmal_von_Askia,_Gao-Tschadseeflug_1930-31-LBS_MH02-08-0549.tif"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/La_Dune_Rose.jpg/1280px-La_Dune_Rose.jpg","credit":"Exereo (Jonathon Hicks)","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:La_Dune_Rose.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1139/","https://en.wikipedia.org/wiki/Tomb_of_Askia"]'::jsonb)
