insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('inner-niger-delta','MLI','Inner Niger Delta','Macina','wetland',15.2,-4.1,'A huge inland floodplain where the Niger spreads into lakes and channels at the Sahara’s edge.','At its peak the flood covers up to about 20,000 km². Millions of migratory birds winter here, and Fulani herders, Bozo fishers and Bambara farmers share its seasons.','Flooded area','Up to ~20,000 km²',false,true,5,'{"color":"#2A6F97","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Wet_Season_in_the_Inner_Niger_Delta_(MODIS).jpg/1280px-Wet_Season_in_the_Inner_Niger_Delta_(MODIS).jpg","credit":"NASA GSFC (MODIS)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Wet_Season_in_the_Inner_Niger_Delta_(MODIS).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3a/Inner_Niger_Delta_(MODIS_2020-12-05).jpg/1280px-Inner_Niger_Delta_(MODIS_2020-12-05).jpg","credit":"NASA GSFC (MODIS)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Inner_Niger_Delta_(MODIS_2020-12-05).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Inner_Niger_Delta_(MODIS_2020-01-10).jpg/1280px-Inner_Niger_Delta_(MODIS_2020-01-10).jpg","credit":"NASA GSFC (MODIS)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Inner_Niger_Delta_(MODIS_2020-01-10).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Inner_Niger_Delta"]'::jsonb)
