insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('hand-of-fatima','MLI','Hand of Fatima','Gami Tondo','rock',15.33,-1.68,'Five sandstone fingers rising about 600 m above the Sahel plain near Hombori.','A famous big-wall climbing site. Nearby Hombori Tondo is Mali’s highest point at about 1,155 m.','Rise','~600 m',false,true,6,'{"color":"#C65D3B","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Hand_der_Fatima.jpg/1280px-Hand_der_Fatima.jpg","credit":"Timm Guenther","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Hand_der_Fatima.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/Hombori_Tondo_by_David_Sessoms-1.jpg/1280px-Hombori_Tondo_by_David_Sessoms-1.jpg","credit":"David Sessoms","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Hombori_Tondo_by_David_Sessoms-1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/1/18/Mali,_monts_Hombori,_dans_le_d%C3%A9sert_du_Gourma,_la_main_de_Fatima_(8438033833).jpg","credit":"Jeanne Menjoulet","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Mali,_monts_Hombori,_dans_le_d%C3%A9sert_du_Gourma,_la_main_de_Fatima_(8438033833).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Hand_of_Fatima_(rock_formation)"]'::jsonb)
