insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('gouina-falls','MLI','Gouina Falls',null,'waterfall',14.02,-11.1,'A broad, horseshoe-shaped waterfall on the Senegal River in western Mali.','The river spreads across a rock sill in a curtain about 15 m high and several hundred metres wide.','Height','~15 m',false,true,7,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Chutes_Gouina1.jpg/1280px-Chutes_Gouina1.jpg","credit":"Jacques Taberlet","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Chutes_Gouina1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Chutes_Gouina2.jpg/1280px-Chutes_Gouina2.jpg","credit":"Jacques Taberlet","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Chutes_Gouina2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Chutes_Gouina3.jpg/1280px-Chutes_Gouina3.jpg","credit":"Jacques Taberlet","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Chutes_Gouina3.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Gouina_Falls"]'::jsonb)
