insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('gourma-elephants','MLI','Desert Elephants of Gourma',null,'fauna',15.4,-1.6,'The most northerly elephants in Africa, walking a 32,000 km² circuit between waterholes in the Sahel.','They make one of the longest elephant migrations known, following rains and lakes such as Banzena. Local communities and anti-poaching patrols protect a few hundred animals. The pin is in the Gourma.','Migration range','~32,000 km²',false,true,8,'{"color":"#8C8C8C","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Loxodonta_africana_crossing_the_Zambesi.jpg/1280px-Loxodonta_africana_crossing_the_Zambesi.jpg","credit":"Hans Hillewaert","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Loxodonta_africana_crossing_the_Zambesi.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Loxodonta_africana_(Serengeti,_2009).jpg/1280px-Loxodonta_africana_(Serengeti,_2009).jpg","credit":"Yathin S Krishnappa","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Loxodonta_africana_(Serengeti,_2009).jpg"}],"note":"Elephants photographed elsewhere — no open footage from the Gourma yet."}'::jsonb,'Loxodonta africana','["https://en.wikipedia.org/wiki/African_bush_elephant","https://en.wikipedia.org/wiki/Gourma"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('shea-tree','MLI','Shea Tree','karité','flora',12.3,-6.5,'A savanna tree whose nuts give shea butter, processed mostly by women across the Sahel.','Shea trees grow wild and take decades to bear fruit; the butter is used for cooking, skin care and chocolate. The pin is a representative point in southern Mali.','First fruit','~15–20 years',false,true,9,'{"color":"#E9D8A6","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Vitellaria_paradoxa_MS_6563.JPG/1280px-Vitellaria_paradoxa_MS_6563.JPG","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Vitellaria_paradoxa_MS_6563.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/Vitellaria_paradoxa_MS_3765.jpg/1280px-Vitellaria_paradoxa_MS_3765.jpg","credit":"Marco Schmidt","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Vitellaria_paradoxa_MS_3765.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Kariten%C3%BCsse220109.JPG/1280px-Kariten%C3%BCsse220109.JPG","credit":"LC-Seminar Uni Hohenheim","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Kariten%C3%BCsse220109.JPG"}]}'::jsonb,'Vitellaria paradoxa','["https://en.wikipedia.org/wiki/Vitellaria","https://www.gbif.org/species/search?q=Vitellaria%20paradoxa"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('banc-d-arguin','MRT','Banc d''Arguin National Park',null,'coast',20.23,-16.1,'Sand dunes, islands and shallow seagrass flats where the Sahara meets the Atlantic.','Over two million shorebirds winter here. Imraguen fishermen still use lanchas, sailing boats, and work with dolphins to drive mullet into their nets. World Heritage Site since 1989.','Wintering birds','2 million+',true,true,1,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/PNBA_43.JPG/1280px-PNBA_43.JPG","credit":"Kokopelado","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:PNBA_43.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/9/95/Brest_2012_15_juillet113.JPG","credit":"Claude PERON","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Brest_2012_15_juillet113.JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/506/","https://en.wikipedia.org/wiki/Banc_d''Arguin_National_Park"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ksour-of-mauritania','MRT','Ancient Ksour of Ouadane, Chinguetti, Tichitt and Oualata',null,'heritage',20.46,-12.36,'Four caravan towns of the 11th–12th centuries, with stone houses, mosques and family libraries.','Chinguetti’s libraries still hold medieval manuscripts on law, astronomy and medicine, now threatened by advancing sand. World Heritage Site since 1996.','Towns','4',true,true,2,'{"color":"#E07A3F","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Chinguetti-Vue_Goblale_Vieille_ville.jpg/1280px-Chinguetti-Vue_Goblale_Vieille_ville.jpg","credit":"François COLIN","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Chinguetti-Vue_Goblale_Vieille_ville.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Chinguetti_Mosque.jpg/1280px-Chinguetti_Mosque.jpg","credit":"Radosław Botev","license":"CC BY 3.0 PL","source":"https://commons.wikimedia.org/wiki/File:Chinguetti_Mosque.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Chinguetti_Mosque_2007.jpg/1280px-Chinguetti_Mosque_2007.jpg","credit":"Radosław Botev","license":"CC BY 3.0 PL","source":"https://commons.wikimedia.org/wiki/File:Chinguetti_Mosque_2007.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/750/","https://en.wikipedia.org/wiki/Chinguetti"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('richat-structure','MRT','Richat Structure','Guelb er Richât · the Eye of Africa','landform',21.12,-11.4,'A target of concentric rock rings about 40 km wide in the Sahara, clearly visible from space.','Once thought to be an impact crater, it is an eroded geological dome. Astronauts have used it as a landmark since the early space missions.','Diameter','~40 km',false,true,3,'{"color":"#3D405B","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/ASTER_Richat.jpg/1280px-ASTER_Richat.jpg","credit":"NASA/GSFC/METI/ERSDAC/JAROS and U.S./Japan ASTER Science Team","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:ASTER_Richat.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Richat_Structure_-_SRTM.jpg/1280px-Richat_Structure_-_SRTM.jpg","credit":"NASA/JPL/NIMA","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Richat_Structure_-_SRTM.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/AS09-19-3050_Richat_Structure.jpg/1280px-AS09-19-3050_Richat_Structure.jpg","credit":"NASA (James Stuby)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:AS09-19-3050_Richat_Structure.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Richat_Structure"]'::jsonb)
