insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ben-amera','MRT','Ben Amera',null,'rock',21.23,-13.67,'A granite monolith rising about 633 m above the desert near the iron-ore railway.','Often described as one of the largest monoliths in the world. In 1999 sculptors carved works into the boulders of nearby Aïsha.','Height above plain','~633 m',false,true,4,'{"color":"#5C4033","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Ben_Amira_2006.jpg/1280px-Ben_Amira_2006.jpg","credit":"Les3corbiers","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Ben_Amira_2006.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Ben_Amera"]'::jsonb)
