insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('terjit-oasis','MRT','Terjit Oasis',null,'gorge',20.25,-13.1,'A palm-filled gorge in the Adrar with warm and cool springs.','Water emerges from the rock in a narrow canyon, creating shade and pools in one of the hottest regions on Earth.','Region','Adrar',false,true,5,'{"color":"#81B29A","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Oasis_In_The_Desert_(15166702115).jpg/1280px-Oasis_In_The_Desert_(15166702115).jpg","credit":"Ammar Hassan","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Oasis_In_The_Desert_(15166702115).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/Mauritania,_panor%C3%A1micas_(1997)_05.jpg/1280px-Mauritania,_panor%C3%A1micas_(1997)_05.jpg","credit":"LBM1948","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mauritania,_panor%C3%A1micas_(1997)_05.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Alioune_In_Terjit_(15143665386).jpg/1280px-Alioune_In_Terjit_(15143665386).jpg","credit":"Ammar Hassan","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Alioune_In_Terjit_(15143665386).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Terjit"]'::jsonb)
