insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('monk-seal-cap-blanc','MRT','Mediterranean Monk Seal',null,'fauna',20.77,-17.05,'One of the world’s rarest seals, living in sea caves on the Cap Blanc peninsula.','Cap Blanc holds the largest colony of the species. A toxic algal bloom killed about two-thirds of it in 1997; it has since recovered to several hundred animals. The pin is at Cap Blanc.','Largest colony','Cap Blanc',false,true,6,'{"color":"#5E6472","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Monachus_monachus_DSC_0384.jpg/1280px-Monachus_monachus_DSC_0384.jpg","credit":"Marinko Babić","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Monachus_monachus_DSC_0384.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Monachus_monachus_DSC_0057.jpg/1280px-Monachus_monachus_DSC_0057.jpg","credit":"Marinko Babić","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Monachus_monachus_DSC_0057.jpg"}]}'::jsonb,'Monachus monachus','["https://en.wikipedia.org/wiki/Mediterranean_monk_seal","https://www.gbif.org/species/search?q=Monachus%20monachus"]'::jsonb)
