insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('date-palm-adrar','MRT','Date Palm',null,'flora',20.52,-13.05,'The tree of the Saharan oases, cultivated in the Adrar for centuries.','During the guetna, the summer date harvest, families gather in oases such as Atar and Terjit. The pin is near Atar.','Harvest festival','guetna',false,true,7,'{"color":"#B07D4B","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Phoenix_dactylifera0.jpg/1280px-Phoenix_dactylifera0.jpg","credit":"MPF","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Phoenix_dactylifera0.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Phoenix_dactylifera2.jpg/1280px-Phoenix_dactylifera2.jpg","credit":"MPF","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Phoenix_dactylifera2.jpg"}]}'::jsonb,'Phoenix dactylifera','["https://en.wikipedia.org/wiki/Date_palm","https://www.gbif.org/species/search?q=Phoenix%20dactylifera"]'::jsonb)
