insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('air-and-tenere','NER','Aïr and Ténéré Natural Reserves',null,'desert',18.3,8.9,'The largest protected area in Africa, joining the volcanic Aïr Mountains with the dunes of the Ténéré.','It covers about 7.7 million ha, with Tuareg herders, rock art and relict Saharan wildlife such as addax and Barbary sheep. On the List in Danger since 1992.','Area','~77,000 km²',true,true,1,'{"color":"#E0A458","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/ISS-64_A%C3%AFr_Mountains_and_Sahara_Desert,_Niger.jpg/1280px-ISS-64_A%C3%AFr_Mountains_and_Sahara_Desert,_Niger.jpg","credit":"NASA","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:ISS-64_A%C3%AFr_Mountains_and_Sahara_Desert,_Niger.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/A%C3%AFr_Mountains_in_Niger_(MODIS).jpg/1280px-A%C3%AFr_Mountains_in_Niger_(MODIS).jpg","credit":"NASA GSFC (MODIS)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:A%C3%AFr_Mountains_in_Niger_(MODIS).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/The_A%C3%AFr_mountains_in_Niger_(MODIS_2019-12-14).jpg/1280px-The_A%C3%AFr_mountains_in_Niger_(MODIS_2019-12-14).jpg","credit":"NASA GSFC (MODIS)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:The_A%C3%AFr_mountains_in_Niger_(MODIS_2019-12-14).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/573/","https://en.wikipedia.org/wiki/Aïr_and_Ténéré_National_Nature_Reserve"]'::jsonb)
