insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('agadez','NER','Historic Centre of Agadez',null,'heritage',16.97,7.99,'The “gateway to the desert”, a Tuareg sultanate town of earthen houses and palaces.','Its 27 m mud-brick minaret is the tallest of its kind in the world. Agadez grew in the 15th–16th centuries as a caravan hub. World Heritage Site since 2013.','Minaret','~27 m',true,true,2,'{"color":"#C1440E","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Niger,_Agadez_(28),_grand_mosque,_old_city.jpg/1280px-Niger,_Agadez_(28),_grand_mosque,_old_city.jpg","credit":"Vincent van Zeijst","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Niger,_Agadez_(28),_grand_mosque,_old_city.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/Niger,_Agadez_(14),_scene_in_the_old_city.jpg/1280px-Niger,_Agadez_(14),_scene_in_the_old_city.jpg","credit":"Vincent van Zeijst","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Niger,_Agadez_(14),_scene_in_the_old_city.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Visiting_and_Learning_from_Africa%E2%80%99s_Expeditionary_Air_Bases.jpg/1280px-Visiting_and_Learning_from_Africa%E2%80%99s_Expeditionary_Air_Bases.jpg","credit":"USAFRICOM","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Visiting_and_Learning_from_Africa%E2%80%99s_Expeditionary_Air_Bases.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1268/","https://en.wikipedia.org/wiki/Agadez","https://en.wikipedia.org/wiki/Grand_Mosque_of_Agadez"]'::jsonb)
