insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('termit-massif','NER','Termit Massif',null,'mountain',16.05,11.35,'Black sandstone ridges rising from the dunes south of the Ténéré.','Part of the Termit and Tin Toumma National Nature Reserve, one of the last refuges of the addax antelope and dama gazelle.','Reserve','~100,000 km²',false,true,3,'{"color":"#3D3A4B","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/Maci%C3%A7o_de_Termit_no_N%C3%ADger.jpg/1280px-Maci%C3%A7o_de_Termit_no_N%C3%ADger.jpg","credit":"INPE (Coordenação-Geral de Observação da Terra)","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Maci%C3%A7o_de_Termit_no_N%C3%ADger.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Termit_Massif","https://en.wikipedia.org/wiki/Termit_and_Tin_Toumma_National_Nature_Reserve"]'::jsonb)
