insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('djado-plateau','NER','Djado Plateau',null,'rock',20.98,12.33,'A remote sandstone plateau in the far north-east, with abandoned ksour and rock art.','The ruined fortified villages of Djado and engravings of giraffes and cattle record its past; it is on Niger’s tentative list for World Heritage.','Region','Kawar',false,true,4,'{"color":"#B5502E","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Niger_Djado.jpg/1280px-Niger_Djado.jpg","credit":"Maireymaradi","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Niger_Djado.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Djado_Plateau"]'::jsonb)
