insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('niger-river-niamey','NER','Niger River at Niamey',null,'river',13.51,2.11,'The great river of West Africa curving past the capital, with rice fields and pirogues on its banks.','The Niger flows about 4,180 km in a great arc, from the Guinea highlands through the Sahel to the Atlantic in Nigeria.','River length','~4,180 km',false,true,5,'{"color":"#2A6F97","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Niger_river_in_Niamey.jpg/1280px-Niger_river_in_Niamey.jpg","credit":"diasUndKompott","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Niger_river_in_Niamey.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Niamey,_Niger_River_bank.jpg/1280px-Niamey,_Niger_River_bank.jpg","credit":"diasUndKompott","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Niamey,_Niger_River_bank.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Le_fleuve_Niger_(Niamey)_(5144172373).jpg/1280px-Le_fleuve_Niger_(Niamey)_(5144172373).jpg","credit":"abdallahh","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Le_fleuve_Niger_(Niamey)_(5144172373).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Niger_River"]'::jsonb)
