insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('west-african-giraffe','NER','West African Giraffe',null,'fauna',13.3,2.6,'The last giraffes of West Africa, roaming farmland around Kouré near Niamey.','Only about 50 remained in 1996. Protection by villagers lifted numbers to several hundred. The pin is at Kouré.','1996 → today','~50 → several hundred',false,true,6,'{"color":"#E9C46A","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/4/4e/Girafes_de_Koure.webm/Girafes_de_Koure.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/4/4e/Girafes_de_Koure.webm/Girafes_de_Koure.webm.360p.mpeg4.mov","credit":"UNWTO, clip extracted by Funke","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Girafes_de_Koure.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/LA_GIRAFE_PERALTA_-_R%C3%A9serve_de_Kour%C3%A9_-_Giraffa_camelopardalis_peralta.jpg/1280px-LA_GIRAFE_PERALTA_-_R%C3%A9serve_de_Kour%C3%A9_-_Giraffa_camelopardalis_peralta.jpg","credit":"Guides Peralta","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:LA_GIRAFE_PERALTA_-_R%C3%A9serve_de_Kour%C3%A9_-_Giraffa_camelopardalis_peralta.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Derni%C3%A8re_girafe_d''Afrique_de_l''Ouest_-_Girafe_peralta_-_Giraffa_camelopardalis_peralta.jpg/1280px-Derni%C3%A8re_girafe_d''Afrique_de_l''Ouest_-_Girafe_peralta_-_Giraffa_camelopardalis_peralta.jpg","credit":"Guides Peralta","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Derni%C3%A8re_girafe_d''Afrique_de_l''Ouest_-_Girafe_peralta_-_Giraffa_camelopardalis_peralta.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/La_Girafe_%22Giraffa_camelopardalis_peralta%22.jpg/1280px-La_Girafe_%22Giraffa_camelopardalis_peralta%22.jpg","credit":"Guides Peralta","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:La_Girafe_%22Giraffa_camelopardalis_peralta%22.jpg"}]}'::jsonb,'Giraffa camelopardalis peralta','["https://en.wikipedia.org/wiki/West_African_giraffe","https://www.gbif.org/species/search?q=Giraffa%20camelopardalis%20peralta"]'::jsonb)
