insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('doum-palm','NER','Doum Palm',null,'flora',14.2,5.2,'A Sahel palm that branches into forks, unusual among palms, with gingerbread-tasting fruit.','Its leaves are woven into mats and baskets across the Sahel; doum fruits were placed in Egyptian tombs. The pin is a representative point.','Also called','gingerbread tree',false,true,7,'{"color":"#7A9A3A","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Hyphaene_thebaica_MS_6652.JPG/1280px-Hyphaene_thebaica_MS_6652.JPG","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Hyphaene_thebaica_MS_6652.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Hyphaene_thebaica_(Aswan)_in_2017_,_photo_by_Hatem_Moushir_4.jpg/1280px-Hyphaene_thebaica_(Aswan)_in_2017_,_photo_by_Hatem_Moushir_4.jpg","credit":"Hatem Moushir","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Hyphaene_thebaica_(Aswan)_in_2017_,_photo_by_Hatem_Moushir_4.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Hyphaene_thebaica_(Aswan)_in_2017_,_photo_by_Hatem_Moushir_3.jpg/1280px-Hyphaene_thebaica_(Aswan)_in_2017_,_photo_by_Hatem_Moushir_3.jpg","credit":"Hatem Moushir","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Hyphaene_thebaica_(Aswan)_in_2017_,_photo_by_Hatem_Moushir_3.jpg"}]}'::jsonb,'Hyphaene thebaica','["https://en.wikipedia.org/wiki/Hyphaene_thebaica","https://www.gbif.org/species/search?q=Hyphaene%20thebaica"]'::jsonb)
