insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sukur','NGA','Sukur Cultural Landscape',null,'heritage',10.74,13.57,'A hilltop chief’s palace, terraced fields and stone-paved paths in the Mandara Mountains.','Sukur was a centre of iron-smelting and its society has shaped the hill for centuries. Africa’s first cultural landscape on the World Heritage List (1999).','Inscribed','1999',true,true,1,'{"color":"#B5651D","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Sukur_Adamawa_Nigeria.jpg/1280px-Sukur_Adamawa_Nigeria.jpg","credit":"StefanCramer","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Sukur_Adamawa_Nigeria.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/Sukur_Cultural_Landscape_(3).jpg/1280px-Sukur_Cultural_Landscape_(3).jpg","credit":"DipoTayo","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Sukur_Cultural_Landscape_(3).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Sukur_Cultural_Landscape_(4).jpg/1280px-Sukur_Cultural_Landscape_(4).jpg","credit":"DipoTayo","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Sukur_Cultural_Landscape_(4).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/938/","https://en.wikipedia.org/wiki/Sukur_Cultural_Landscape"]'::jsonb)
