insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('osun-osogbo','NGA','Osun-Osogbo Sacred Grove',null,'forest',7.76,4.55,'One of the last sacred forests of the Yoruba, home of the river goddess Osun, outside Osogbo.','Shrines and sculptures were renewed from the 1950s by Susanne Wenger and local artists. Each August the Osun-Osogbo festival draws huge crowds. World Heritage Site since 2005.','Grove','~75 ha',true,true,2,'{"color":"#008751","intensity":0.85,"motion":"mist"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/0/0a/Night_life_at_the_Ina_Oloju_merindilogun_at_the_Osun_Osogbo_Festival.webm/Night_life_at_the_Ina_Oloju_merindilogun_at_the_Osun_Osogbo_Festival.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/0/0a/Night_life_at_the_Ina_Oloju_merindilogun_at_the_Osun_Osogbo_Festival.webm/Night_life_at_the_Ina_Oloju_merindilogun_at_the_Osun_Osogbo_Festival.webm.360p.mpeg4.mov","credit":"ABORISADEADETONA","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Night_life_at_the_Ina_Oloju_merindilogun_at_the_Osun_Osogbo_Festival.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/02/OsunOsogbo_Shrine_Sunset_over_the_Osun_River.jpg/1280px-OsunOsogbo_Shrine_Sunset_over_the_Osun_River.jpg","credit":"Inyang Effiong","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:OsunOsogbo_Shrine_Sunset_over_the_Osun_River.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/First_palace_of_the_king_osogbo_at_the_osun-osogbo_sacred_grove.jpg/1280px-First_palace_of_the_king_osogbo_at_the_osun-osogbo_sacred_grove.jpg","credit":"Cheeka 2.0","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:First_palace_of_the_king_osogbo_at_the_osun-osogbo_sacred_grove.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Osun_Osogbo_Festival_01.jpg/1280px-Osun_Osogbo_Festival_01.jpg","credit":"SteadyWins","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Osun_Osogbo_Festival_01.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1118/","https://en.wikipedia.org/wiki/Osun-Osogbo_Sacred_Grove"]'::jsonb)
