insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('zuma-rock','NGA','Zuma Rock',null,'rock',9.13,7.23,'A granite dome rising about 300 m above the plain on the road from Abuja, the “gateway to Abuja”.','Rain streaks on its face are said to form a human face; the rock appears on Nigeria’s 100 naira note.','Rise','~300 m',false,true,3,'{"color":"#5C4033","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Zuma_Rock_in_the_dry_season.jpg/1280px-Zuma_Rock_in_the_dry_season.jpg","credit":"Hui Linbo","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Zuma_Rock_in_the_dry_season.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Zuma_Rock_WV_banner.jpg/1280px-Zuma_Rock_WV_banner.jpg","credit":"Mark Hillary; derivative by ויקיג''אנקי","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Zuma_Rock_WV_banner.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Zuma_rock,_Niger._Human_face_like_rock_1.jpg/1280px-Zuma_rock,_Niger._Human_face_like_rock_1.jpg","credit":"Ekenejt","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Zuma_rock,_Niger._Human_face_like_rock_1.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Zuma_Rock"]'::jsonb)
