insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('yankari','NGA','Yankari',null,'savanna',9.75,10.51,'Savanna and gallery forest in Bauchi State, fed by the clear, warm Wikki Spring.','The spring stays at about 31 °C year round. Yankari holds one of West Africa’s largest remaining elephant herds.','Wikki Spring','~31 °C',false,true,4,'{"color":"#E9C46A","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/Wikki_warm_spring_aerial_view.jpg/1280px-Wikki_warm_spring_aerial_view.jpg","credit":"Obute Wa","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Wikki_warm_spring_aerial_view.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/4/47/Wikki_warm_spring_Yankari.jpg","credit":"Aminudahiru","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Wikki_warm_spring_Yankari.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Wikki_Warm_Spring_Gate_in_Yankari_Game_Reserve_01.jpg/1280px-Wikki_Warm_Spring_Gate_in_Yankari_Game_Reserve_01.jpg","credit":"Kambai Akau","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Wikki_Warm_Spring_Gate_in_Yankari_Game_Reserve_01.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Yankari_National_Park"]'::jsonb)
