insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('obudu-plateau','NGA','Obudu Plateau',null,'mountain',6.39,9.37,'A grassy plateau around 1,575 m on the Cameroon border, with a cool climate and forest gorges.','Montane grassland and forest here are part of the Cameroon highlands, home to rare birds and primates.','Altitude','~1,575 m',false,true,5,'{"color":"#3A6EA5","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/OBUDU_MOUNTAINS_3.jpg/1280px-OBUDU_MOUNTAINS_3.jpg","credit":"Laminartosin","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:OBUDU_MOUNTAINS_3.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/1/14/Obudu_Mountains_3.jpg","credit":"Amoghale","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Obudu_Mountains_3.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Obudu_Mountain_Resort_01.jpg/1280px-Obudu_Mountain_Resort_01.jpg","credit":"Bassnificient","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Obudu_Mountain_Resort_01.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Obudu_Mountain_Resort"]'::jsonb)
