insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('erin-ijesha','NGA','Erin Ijesha Waterfalls','Olumirin','waterfall',7.57,4.9,'A seven-tier waterfall in the hills of Osun State.','Local tradition says it was discovered in 1140 by a hunter; climbers can follow the tiers up the hill.','Tiers','7',false,true,6,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Erin_Ijesha_Osun_State.jpg/1280px-Erin_Ijesha_Osun_State.jpg","credit":"Debo Adebayo","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Erin_Ijesha_Osun_State.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Erin_Ijesha_Water_fall_Osun_state_(11).jpg/1280px-Erin_Ijesha_Water_fall_Osun_state_(11).jpg","credit":"Tadekwiki","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Erin_Ijesha_Water_fall_Osun_state_(11).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Erin_Ijesha_Water_fall_Osun_state_(12).jpg/1280px-Erin_Ijesha_Water_fall_Osun_state_(12).jpg","credit":"Tadekwiki","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Erin_Ijesha_Water_fall_Osun_state_(12).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Erin_Ijesha_Waterfalls"]'::jsonb)
