insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('cross-river-gorilla','NGA','Cross River Gorilla',null,'fauna',6.25,9.3,'The rarest great ape in Africa, living in hill forests on the Nigeria–Cameroon border.','Only around 250–300 remain in small groups. Critically Endangered. The pin is near the Afi Mountain and Mbe Mountains.','Remaining','~250–300',false,true,7,'{"color":"#2F3E46","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Cross-River-Gorilla-Gorilla-gorilla-diehli).jpg/1280px-Cross-River-Gorilla-Gorilla-gorilla-diehli).jpg","credit":"Julielangford","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Cross-River-Gorilla-Gorilla-gorilla-diehli).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Cross-river-gorilla.jpg/1280px-Cross-river-gorilla.jpg","credit":"Julielangford","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Cross-river-gorilla.jpg"}]}'::jsonb,'Gorilla gorilla diehli','["https://en.wikipedia.org/wiki/Cross_River_gorilla","https://www.gbif.org/species/search?q=Gorilla%20gorilla%20diehli"]'::jsonb)
