insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('iroko','NGA','Iroko',null,'flora',7.4,3.9,'A giant hardwood of the West African forest, sacred in Yoruba and Igbo tradition.','The tree is believed to house spirits, so many are left standing; its durable timber is used for boats and furniture. The pin is a representative point.','Height','Up to ~50 m',false,true,8,'{"color":"#7F4F24","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Iroko_tree.jpg/1280px-Iroko_tree.jpg","credit":"Erik Kleves Kristensen","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Iroko_tree.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Milicia_excelsa.JPG/1280px-Milicia_excelsa.JPG","credit":"Fenrith","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Milicia_excelsa.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Iroko_wood.jpg/1280px-Iroko_wood.jpg","credit":"Abarmot","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Iroko_wood.jpg"}]}'::jsonb,'Milicia excelsa','["https://en.wikipedia.org/wiki/Milicia_excelsa","https://www.gbif.org/species/search?q=Milicia%20excelsa"]'::jsonb)
