insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('goree','SEN','Island of Gorée',null,'heritage',14.67,-17.4,'A small island off Dakar, a hub of the Atlantic slave trade from the 15th to the 19th century.','The House of Slaves and its “Door of No Return” is a place of memory and reconciliation. World Heritage Site since 1978.','Area','~18 ha',true,true,1,'{"color":"#E07A9A","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Island_of_Gor%C3%A9e,_Senegal.jpg/1280px-Island_of_Gor%C3%A9e,_Senegal.jpg","credit":"Nextdrop","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Island_of_Gor%C3%A9e,_Senegal.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Gor%C3%A9e_-_Maison_des_esclaves_(4).JPG/1280px-Gor%C3%A9e_-_Maison_des_esclaves_(4).JPG","credit":"HaguardDuNord","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Gor%C3%A9e_-_Maison_des_esclaves_(4).JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Gor%C3%A9e_-_Maison_des_esclaves,_cachot.JPG/1280px-Gor%C3%A9e_-_Maison_des_esclaves,_cachot.JPG","credit":"HaguardDuNord","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Gor%C3%A9e_-_Maison_des_esclaves,_cachot.JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/26/","https://en.wikipedia.org/wiki/Gorée"]'::jsonb)
