insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('djoudj','SEN','Djoudj National Bird Sanctuary',null,'wetland',16.36,-16.27,'A delta wetland on the Senegal River, the first green after the Sahara for migrating birds.','About 1.5 million birds use it, including great white pelicans, flamingos and aquatic warblers. World Heritage Site since 1981.','Birds','~1.5 million',true,true,2,'{"color":"#FDEF42","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Djoudj_ile_pelican.jpg/1280px-Djoudj_ile_pelican.jpg","credit":"Manu25","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Djoudj_ile_pelican.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/CormoransDjoudj.JPG/1280px-CormoransDjoudj.JPG","credit":"Ji-Elle","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:CormoransDjoudj.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/3/3c/Djoudj_-_Cormoran_(3).JPG","credit":"Remi Jouan","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Djoudj_-_Cormoran_(3).JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/25/","https://en.wikipedia.org/wiki/Djoudj_National_Bird_Sanctuary"]'::jsonb)
