insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('niokolo-koba','SEN','Niokolo-Koba National Park',null,'savanna',13.07,-12.72,'Gallery forest and savanna along the Gambia River in south-east Senegal.','Home to the Derby (giant) eland, chimpanzees, lions and hippos. It came off the List in Danger in 2024 after wildlife began to recover. World Heritage Site since 1981.','Area','~9,130 km²',true,true,3,'{"color":"#00853F","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Parc_de_Niokolo-Koba,_S%C3%A9n%C3%A9gal_-_COD260725-113.jpg/1280px-Parc_de_Niokolo-Koba,_S%C3%A9n%C3%A9gal_-_COD260725-113.jpg","credit":"COD photographer","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Parc_de_Niokolo-Koba,_S%C3%A9n%C3%A9gal_-_COD260725-113.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Parc_de_Niokolo-Koba,_S%C3%A9n%C3%A9gal_-_COD260725-058.jpg/1280px-Parc_de_Niokolo-Koba,_S%C3%A9n%C3%A9gal_-_COD260725-058.jpg","credit":"COD photographer","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Parc_de_Niokolo-Koba,_S%C3%A9n%C3%A9gal_-_COD260725-058.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Parc_de_Niokolo-Koba,_S%C3%A9n%C3%A9gal_-_COD260725-117.jpg/1280px-Parc_de_Niokolo-Koba,_S%C3%A9n%C3%A9gal_-_COD260725-117.jpg","credit":"COD photographer","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Parc_de_Niokolo-Koba,_S%C3%A9n%C3%A9gal_-_COD260725-117.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/153/","https://en.wikipedia.org/wiki/Niokolo-Koba_National_Park"]'::jsonb)
