insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('saint-louis-senegal','SEN','Island of Saint-Louis',null,'heritage',16.03,-16.5,'A colonial island town at the mouth of the Senegal River, capital of French West Africa until 1902.','Its balconied houses and the Faidherbe Bridge, opened in 1897, give it a distinctive look. World Heritage Site since 2000.','Founded','1659',true,true,4,'{"color":"#2A6F97","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Saint-Louis._Senegal.jpg/1280px-Saint-Louis._Senegal.jpg","credit":"Adjoajo","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Saint-Louis._Senegal.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Saint-Louis,_Senegal_(10042).jpg/1280px-Saint-Louis,_Senegal_(10042).jpg","credit":"Adjoajo","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Saint-Louis,_Senegal_(10042).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Saint-Louis,_Senegal_(51596).jpg/1280px-Saint-Louis,_Senegal_(51596).jpg","credit":"Adjoajo","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Saint-Louis,_Senegal_(51596).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/956/","https://en.wikipedia.org/wiki/Saint-Louis,_Senegal"]'::jsonb)
