insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('saloum-delta','SEN','Saloum Delta',null,'wetland',13.84,-16.5,'Mangrove islands, creeks and shell mounds where the Saloum meets the Atlantic.','218 shell middens, some with burial tumuli, record 2,000 years of shellfish gathering. World Heritage Site since 2011.','Shell mounds','218',true,true,5,'{"color":"#2D6A4F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/Delta_du_Sine_Saloum_-_Patrimoine_Mondial_de_L''Unesco_02.jpg/1280px-Delta_du_Sine_Saloum_-_Patrimoine_Mondial_de_L''Unesco_02.jpg","credit":"Issiaga0","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Delta_du_Sine_Saloum_-_Patrimoine_Mondial_de_L''Unesco_02.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/S%C3%A9n%C3%A9gal,_dans_le_Delta_du_Sine_Saloum_01.jpg/1280px-S%C3%A9n%C3%A9gal,_dans_le_Delta_du_Sine_Saloum_01.jpg","credit":"Issiaga0","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:S%C3%A9n%C3%A9gal,_dans_le_Delta_du_Sine_Saloum_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/S%C3%A9n%C3%A9gal,_dans_le_Delta_du_Sine_Saloum_03.jpg/1280px-S%C3%A9n%C3%A9gal,_dans_le_Delta_du_Sine_Saloum_03.jpg","credit":"Issiaga0","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:S%C3%A9n%C3%A9gal,_dans_le_Delta_du_Sine_Saloum_03.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1359/","https://en.wikipedia.org/wiki/Saloum_Delta"]'::jsonb)
