insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bassari-country','SEN','Bassari Country',null,'heritage',12.59,-12.85,'Hill villages of the Bassari, Fula and Bedik peoples in south-east Senegal.','Their terraced fields, masked initiation rites and villages show cultures adapted to this upland. World Heritage Site since 2012.','Peoples','Bassari · Fula · Bedik',true,true,6,'{"color":"#C8784A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Bassari-Berge_Salemata.JPG/1280px-Bassari-Berge_Salemata.JPG","credit":"Saemmi","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Bassari-Berge_Salemata.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/VillageBedik.jpg/1280px-VillageBedik.jpg","credit":"BluesyPete","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:VillageBedik.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/NdamaSenegal.jpg/1280px-NdamaSenegal.jpg","credit":"BluesyPete","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:NdamaSenegal.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1407/","https://en.wikipedia.org/wiki/Bassari_Country"]'::jsonb)
