insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lac-rose','SEN','Lac Rose','Lake Retba','lake',14.84,-17.24,'A shallow salt lake that turns pink in the dry season, north-east of Dakar.','The colour comes from salt-loving algae (Dunaliella salina). Salt collectors gather salt from the bottom, protecting their skin with shea butter. Long the finish of the Paris–Dakar rally.','Salt content','Up to ~40%',false,true,7,'{"color":"#E07A9A","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Lac_Rose_in_Senegal.jpg/1280px-Lac_Rose_in_Senegal.jpg","credit":"Arnault","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Lac_Rose_in_Senegal.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Lac_Rose_S%C3%A9n%C3%A9gal_03.jpg/1280px-Lac_Rose_S%C3%A9n%C3%A9gal_03.jpg","credit":"Issiaga0","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Lac_Rose_S%C3%A9n%C3%A9gal_03.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Lac_Rose_S%C3%A9n%C3%A9gal_04.jpg/1280px-Lac_Rose_S%C3%A9n%C3%A9gal_04.jpg","credit":"Issiaga0","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Lac_Rose_S%C3%A9n%C3%A9gal_04.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Retba"]'::jsonb)
