insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dindefelo-falls','SEN','Dindéfelo Falls',null,'waterfall',12.38,-12.33,'A waterfall of about 100 m dropping into a pool in the Fouta Djallon foothills near the Guinea border.','A community reserve protects the falls and the chimpanzees that live in the surrounding hills.','Drop','~100 m',false,true,8,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Dindefelo.jpg/1280px-Dindefelo.jpg","credit":"Jonas Roux","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Dindefelo.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/DindefeloFalls_01.jpg/1280px-DindefeloFalls_01.jpg","credit":"BluesyPete","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:DindefeloFalls_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/DindefeloView.jpg/1280px-DindefeloView.jpg","credit":"Dorothy Voorhees","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:DindefeloView.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Dindéfelo"]'::jsonb)
