insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lompoul-desert','SEN','Lompoul Desert',null,'desert',15.45,-16.67,'A small field of orange dunes near the Atlantic, between Dakar and Saint-Louis.','Though only about 18 km², its dunes look like the Sahara; tented camps welcome visitors.','Area','~18 km²',false,true,9,'{"color":"#F2A65A","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/2017-06_Lompoul_Desert.jpg/1280px-2017-06_Lompoul_Desert.jpg","credit":"Mich-nguyen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:2017-06_Lompoul_Desert.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Le_d%C3%A9sert_de_lompoul.jpg/1280px-Le_d%C3%A9sert_de_lompoul.jpg","credit":"Georges Hermann Njiale Njiale","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Le_d%C3%A9sert_de_lompoul.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Lompoul_sur_mer.jpg/1280px-Lompoul_sur_mer.jpg","credit":"Georges Hermann Njiale Njiale","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Lompoul_sur_mer.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lompoul"]'::jsonb)
