insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('great-white-pelican','SEN','Great White Pelican',null,'fauna',16.4,-16.25,'A huge white pelican that fishes cooperatively, herding fish in a horseshoe line.','Djoudj holds one of the largest breeding colonies in West Africa, with thousands of pairs. The pin is at Djoudj.','Wingspan','Up to ~3.5 m',false,true,10,'{"color":"#F4F1DE","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/P%C3%A9licans_au_Parc_national_du_Djoudj.jpg/1280px-P%C3%A9licans_au_Parc_national_du_Djoudj.jpg","credit":"Ji-Elle","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:P%C3%A9licans_au_Parc_national_du_Djoudj.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/b/b5/Djoudj_-_Pelican_(2).JPG","credit":"Remi Jouan","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Djoudj_-_Pelican_(2).JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/0/01/Djoudj_-_Pelican_(1).JPG","credit":"Remi Jouan","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Djoudj_-_Pelican_(1).JPG"}]}'::jsonb,'Pelecanus onocrotalus','["https://en.wikipedia.org/wiki/Great_white_pelican","https://www.gbif.org/species/search?q=Pelecanus%20onocrotalus"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('baobab-senegal','SEN','Baobab','guy (Wolof)','flora',14.45,-16.95,'Senegal’s national tree: a massive trunk that stores water, with leaves, fruit and bark all put to use.','Baobabs can live well over 1,000 years. Their fruit pulp, bouye, is made into a drink. The baobab appears on Senegal’s coat of arms. The pin is near Thiès.','Lifespan','1,000+ years',false,true,11,'{"color":"#C8784A","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/Adansonia_digitata_Baobab.JPG/1280px-Adansonia_digitata_Baobab.JPG","credit":"Yoky","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Adansonia_digitata_Baobab.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Adansonia_digitata_MS_6682.JPG/1280px-Adansonia_digitata_MS_6682.JPG","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Adansonia_digitata_MS_6682.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Adansonia_digitata_MS_6682-2.JPG/1280px-Adansonia_digitata_MS_6682-2.JPG","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Adansonia_digitata_MS_6682-2.JPG"}]}'::jsonb,'Adansonia digitata','["https://en.wikipedia.org/wiki/Adansonia_digitata","https://www.gbif.org/species/search?q=Adansonia%20digitata"]'::jsonb)
