insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('gola-tiwai','SLE','Gola-Tiwai Complex',null,'forest',7.5,-10.92,'Sierra Leone’s largest tract of lowland rainforest, joined with Tiwai Island in the Moa River.','It shelters pygmy hippos, forest elephants, chimpanzees and Endangered birds such as the white-necked rockfowl. Sierra Leone’s first World Heritage Site (2025).','Inscribed','2025',true,true,1,'{"color":"#1EB53A","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Blackcap_Illadopsis_Illadopsis_cleaveri_in_the_Gola_Rainforest_NP,_Sierra_Leone.png/1280px-Blackcap_Illadopsis_Illadopsis_cleaveri_in_the_Gola_Rainforest_NP,_Sierra_Leone.png","credit":"Barry Reed","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Blackcap_Illadopsis_Illadopsis_cleaveri_in_the_Gola_Rainforest_NP,_Sierra_Leone.png"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/18/Odontobatrachus_natator_collage.jpg/1280px-Odontobatrachus_natator_collage.jpg","credit":"Michael F. Barej et al.","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Odontobatrachus_natator_collage.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1746/","https://en.wikipedia.org/wiki/Gola_Rainforest_National_Park"]'::jsonb)
