insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tiwai-island','SLE','Tiwai Island',null,'river',7.54,-11.35,'A forested island in the Moa River, run as a sanctuary by local communities.','It has one of the highest densities of primates in the world, with 11 species including the Diana monkey.','Primate species','11',false,true,2,'{"color":"#0072C6","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Tiwai_Island_-_flickr_(banner).jpg/1280px-Tiwai_Island_-_flickr_(banner).jpg","credit":"Dorothy Voorhees","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Tiwai_Island_-_flickr_(banner).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Tiwai_Island"]'::jsonb)
