insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('outamba-kilimi','SLE','Outamba-Kilimi National Park',null,'savanna',9.77,-12.03,'Savanna, rivers and forest in the north-west, near the Guinea border.','Sierra Leone’s first national park, with hippos, chimpanzees and elephants along the Little Scarcies River.','Declared','1995',false,true,3,'{"color":"#F4D35E","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Outamba_Kilimi_Park_Sierra_Leone.JPG/1280px-Outamba_Kilimi_Park_Sierra_Leone.JPG","credit":"Leasmhar","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Outamba_Kilimi_Park_Sierra_Leone.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Outamba_Mountain_Sierra_Leone.JPG/1280px-Outamba_Mountain_Sierra_Leone.JPG","credit":"Leasmhar","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Outamba_Mountain_Sierra_Leone.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/18/Musa,_Outamba_Kilimi_Canoe_Guide.JPG/1280px-Musa,_Outamba_Kilimi_Canoe_Guide.JPG","credit":"Leasmhar","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Musa,_Outamba_Kilimi_Canoe_Guide.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Outamba-Kilimi_National_Park"]'::jsonb)
