insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mount-bintumani','SLE','Mount Bintumani','Loma Mansa','mountain',9.22,-11.12,'The highest peak in West Africa west of Mount Cameroon, at 1,945 m in the Loma Mountains.','Its summit grassland rises above montane forest; the source of the Niger lies just across the border in Guinea.','Height','1,945 m',false,true,4,'{"color":"#6B4226","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Mount_Bintumani_1992_or_93_(3).jpg/1280px-Mount_Bintumani_1992_or_93_(3).jpg","credit":"sierra-leone143","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Bintumani_1992_or_93_(3).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Mount_Bintumani_1992_or_93_(4).jpg/1280px-Mount_Bintumani_1992_or_93_(4).jpg","credit":"sierra-leone143","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Bintumani_1992_or_93_(4).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Mount_Bintumani_1992_or_93_(2).jpg/1280px-Mount_Bintumani_1992_or_93_(2).jpg","credit":"sierra-leone143","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Bintumani_1992_or_93_(2).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Mount_Bintumani"]'::jsonb)
