insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('banana-islands','SLE','Banana Islands',null,'coast',8.12,-13.22,'Three small islands off the Freetown Peninsula, with reefs and old colonial ruins.','Settled in the 19th century by freed Africans, the islands keep a quiet village life and clear diving waters.','Islands','3',false,true,5,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"note":"No openly licensed photos of the islands yet."}'::jsonb,null,'["https://en.wikipedia.org/wiki/Banana_Islands"]'::jsonb)
