insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('diana-monkey','SLE','Diana Monkey',null,'fauna',7.55,-11.35,'A striking black monkey with a white beard and crescent on its brow, living high in the canopy.','Its alarm calls distinguish leopards from eagles, and other monkeys listen in. Endangered. The pin is at Tiwai Island.','IUCN status','Endangered',false,true,6,'{"color":"#2B2D42","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/f4/Cercopithecidae_-_Cercopithecus_diana_-_Diana_monkey.webm/Cercopithecidae_-_Cercopithecus_diana_-_Diana_monkey.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/f4/Cercopithecidae_-_Cercopithecus_diana_-_Diana_monkey.webm/Cercopithecidae_-_Cercopithecus_diana_-_Diana_monkey.webm.360p.mpeg4.mov","credit":"Hectonichus","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cercopithecidae_-_Cercopithecus_diana_-_Diana_monkey.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/Cercopithecus_diana.jpg/1280px-Cercopithecus_diana.jpg","credit":"Greg Hume","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Cercopithecus_diana.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Cercopithecus_diana_2_(Wroclaw_zoo).JPG/1280px-Cercopithecus_diana_2_(Wroclaw_zoo).JPG","credit":"Guérin Nicolas","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Cercopithecus_diana_2_(Wroclaw_zoo).JPG"}]}'::jsonb,'Cercopithecus diana','["https://en.wikipedia.org/wiki/Diana_monkey","https://www.gbif.org/species/search?q=Cercopithecus%20diana"]'::jsonb)
