insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('freetown-cotton-tree','SLE','Freetown Cotton Tree',null,'flora',8.49,-13.24,'A giant kapok tree that stood for centuries at the heart of Freetown until a storm felled it in May 2024.','Freed Africans who founded Freetown in 1792 are said to have prayed beneath it. Kapok trees bear pods of silky fibre once used to stuff life jackets. The pin is in Freetown.','Fell','May 2024',false,true,7,'{"color":"#E9F5DB","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Cotton_Tree_(Sierra_Leone).jpg/1280px-Cotton_Tree_(Sierra_Leone).jpg","credit":"Christian Trede","license":"CC BY-SA 2.0 DE","source":"https://commons.wikimedia.org/wiki/File:Cotton_Tree_(Sierra_Leone).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Freetownstreet.jpg/1280px-Freetownstreet.jpg","credit":"Aranae","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Freetownstreet.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Kapok_on_a_branch_of_Ceiba_pentandra_(white_silk-cotton_tree).jpg/1280px-Kapok_on_a_branch_of_Ceiba_pentandra_(white_silk-cotton_tree).jpg","credit":"Basile Morin","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kapok_on_a_branch_of_Ceiba_pentandra_(white_silk-cotton_tree).jpg"}]}'::jsonb,'Ceiba pentandra','["https://en.wikipedia.org/wiki/Cotton_Tree_(Sierra_Leone)","https://www.gbif.org/species/search?q=Ceiba%20pentandra"]'::jsonb)
