insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('koutammakou','TGO','Koutammakou, the Land of the Batammariba',null,'heritage',10.07,1.13,'A landscape of takienta, mud tower-houses with granaries on top, in north-east Togo and north-west Benin.','The Batammariba build each house as a small fortress and a symbol of their cosmos. World Heritage Site since 2004, extended into Benin in 2023.','Inscribed','2004',true,true,1,'{"color":"#B5502E","intensity":0.85,"motion":"orbit"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/8/8e/Koutammakou_fan_palm_1.webm/Koutammakou_fan_palm_1.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/8/8e/Koutammakou_fan_palm_1.webm/Koutammakou_fan_palm_1.webm.360p.mpeg4.mov","credit":"Bagnagnibay téné","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Koutammakou_fan_palm_1.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Alyssa_K._Barry_Koutammakou,Togo.jpg/1280px-Alyssa_K._Barry_Koutammakou,Togo.jpg","credit":"Kalyss","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Alyssa_K._Barry_Koutammakou,Togo.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Alyssa_K._Barry_Koutammakou,Togo_(banner).jpg/1280px-Alyssa_K._Barry_Koutammakou,Togo_(banner).jpg","credit":"Kalyss","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Alyssa_K._Barry_Koutammakou,Togo_(banner).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1140/","https://en.wikipedia.org/wiki/Koutammakou"]'::jsonb)
