insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('fazao-malfakassa','TGO','Fazao-Malfakassa National Park',null,'savanna',9,1,'Togo’s largest national park: wooded hills, savanna and waterfalls in the centre of the country.','It shelters forest elephants, buffalo and many primates, in a park restored with community support.','Area','~1,920 km²',false,true,2,'{"color":"#006A4E","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Paysage_du_Parc_National_Fazao-Malfakassa_02.jpg/1280px-Paysage_du_Parc_National_Fazao-Malfakassa_02.jpg","credit":"Layéniba","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Paysage_du_Parc_National_Fazao-Malfakassa_02.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Coin_d''abreuvages_pour_les_animaux_du_parc_Malfakassa_et_Fazao_04.jpg/1280px-Coin_d''abreuvages_pour_les_animaux_du_parc_Malfakassa_et_Fazao_04.jpg","credit":"Dark Cam04","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Coin_d''abreuvages_pour_les_animaux_du_parc_Malfakassa_et_Fazao_04.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/H%C3%A9t%C3%A9rotis_%C3%A0_feuilles_rondes_dans_le_parc_Malfakassa_et_Fazao_02.jpg/1280px-H%C3%A9t%C3%A9rotis_%C3%A0_feuilles_rondes_dans_le_parc_Malfakassa_et_Fazao_02.jpg","credit":"Dark Cam04","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:H%C3%A9t%C3%A9rotis_%C3%A0_feuilles_rondes_dans_le_parc_Malfakassa_et_Fazao_02.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Fazao_Malfakassa_National_Park"]'::jsonb)
