insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kpime-falls','TGO','Kpimé Falls',null,'waterfall',6.95,0.66,'A forest waterfall near Kpalimé, in the green coffee and cocoa hills of the Plateaux.','The hills around Kpalimé are famous for butterflies and for Mount Agou, Togo’s highest peak.','Region','Plateaux',false,true,3,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Cascade_de_Kpim%C3%A9_7.jpg/1280px-Cascade_de_Kpim%C3%A9_7.jpg","credit":"Ak9visuelmind","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cascade_de_Kpim%C3%A9_7.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Cascade_de_Kpim%C3%A9_6.jpg/1280px-Cascade_de_Kpim%C3%A9_6.jpg","credit":"Ak9visuelmind","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cascade_de_Kpim%C3%A9_6.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Cascade_de_Kpim%C3%A9_5.jpg/1280px-Cascade_de_Kpim%C3%A9_5.jpg","credit":"Ak9visuelmind","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cascade_de_Kpim%C3%A9_5.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Kpalimé"]'::jsonb)
