insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-togo','TGO','Lake Togo',null,'lake',6.25,1.42,'A coastal lagoon behind the sand bar east of Lomé, which gave the country its name.','In 1884 a treaty signed at Togoville, on its shore, began the German protectorate, and the town’s name passed to the whole country.','Treaty','1884',false,true,4,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Pirogue_moderne_sur_le_lac_Togo.jpg/1280px-Pirogue_moderne_sur_le_lac_Togo.jpg","credit":"Yelouassi","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pirogue_moderne_sur_le_lac_Togo.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Mangrove_au_Togo.jpg/1280px-Mangrove_au_Togo.jpg","credit":"Yelouassi","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mangrove_au_Togo.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Togo"]'::jsonb)
