insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mona-monkey','TGO','Mona Monkey',null,'fauna',6.9,0.6,'A lively monkey with a white rump patch, common in the forests and mangroves of the Gulf of Guinea.','Mona monkeys live in groups and are protected as sacred in some villages of Togo, Ghana and Benin. The pin is near Kpalimé.','Range','Ghana to Cameroon',false,true,5,'{"color":"#8B5E34","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d8/Cercopithecus_mona_469766723.jpg/1280px-Cercopithecus_mona_469766723.jpg","credit":"martin ingemansson","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Cercopithecus_mona_469766723.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Mona_monkey_(Cercopithecus_mona).jpg/1280px-Mona_monkey_(Cercopithecus_mona).jpg","credit":"Charles J. Sharp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mona_monkey_(Cercopithecus_mona).jpg"}]}'::jsonb,'Cercopithecus mona','["https://en.wikipedia.org/wiki/Mona_monkey","https://www.gbif.org/species/search?q=Cercopithecus%20mona"]'::jsonb)
