insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('red-silk-cotton-tree','TGO','Red-flowered Silk-cotton Tree',null,'flora',9.5,1.2,'A savanna tree that flowers bright red on bare branches in the dry season.','Its flowers feed birds and are cooked in sauces; its kapok-like fibre stuffs cushions. The pin is a representative point.','Flowers','Dry season',false,true,6,'{"color":"#D62828","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Bombax_costatum_0001.jpg/1280px-Bombax_costatum_0001.jpg","credit":"Atamari","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Bombax_costatum_0001.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Bombax_costatum_0002.jpg/1280px-Bombax_costatum_0002.jpg","credit":"Atamari","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Bombax_costatum_0002.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Bombax_costatum_0003.jpg/1280px-Bombax_costatum_0003.jpg","credit":"Atamari","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Bombax_costatum_0003.jpg"}]}'::jsonb,'Bombax costatum','["https://en.wikipedia.org/wiki/Bombax_costatum","https://www.gbif.org/species/search?q=Bombax%20costatum"]'::jsonb)
