insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mbanza-kongo','AGO','Mbanza Kongo',null,'heritage',-6.27,14.25,'The capital of the Kingdom of Kongo, one of the largest states of southern Africa from the 14th to the 19th century.','Renamed São Salvador after the king converted, it holds the ruins of Kulumbimbi, one of the oldest churches in sub-Saharan Africa. Angola’s first World Heritage Site (2017).','Inscribed','2017',true,true,1,'{"color":"#C1121F","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/The_Bansa,_or_residence_of_the_King_of_Kongo,_called_St._Salvador_(M''Banza_Kongo),_Astley_1745.jpg/1280px-The_Bansa,_or_residence_of_the_King_of_Kongo,_called_St._Salvador_(M''Banza_Kongo),_Astley_1745.jpg","credit":"Thomas Astley (1745)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:The_Bansa,_or_residence_of_the_King_of_Kongo,_called_St._Salvador_(M''Banza_Kongo),_Astley_1745.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Tomada_da_cidade_de_S%C3%A3o_Salvador_s%C3%A9culo_XVIII_(panor%C3%A2mico).jpg/1280px-Tomada_da_cidade_de_S%C3%A3o_Salvador_s%C3%A9culo_XVIII_(panor%C3%A2mico).jpg","credit":"Unknown 18th-century artist","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Tomada_da_cidade_de_S%C3%A3o_Salvador_s%C3%A9culo_XVIII_(panor%C3%A2mico).jpg"}],"note":"Historic views of São Salvador — no recent open photos of the site yet."}'::jsonb,null,'["https://whc.unesco.org/en/list/1511/","https://en.wikipedia.org/wiki/M''banza-Kongo"]'::jsonb)
