insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kalandula-falls','AGO','Kalandula Falls',null,'waterfall',-9.08,16,'A horseshoe of waterfalls on the Lucala River, about 105 m high and 400 m wide.','One of the largest waterfalls in Africa by volume, especially in the rainy season.','Height','~105 m',false,true,2,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Kalandula_Falls_Pan.jpg/1280px-Kalandula_Falls_Pan.jpg","credit":"Zorglub","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Kalandula_Falls_Pan.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Kalandula_Falls_C.jpg/1280px-Kalandula_Falls_C.jpg","credit":"Zorglub","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Kalandula_Falls_C.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Kalandula_waterfalls_of_the_Lucala-River_in_Malange,_Angola.JPG/1280px-Kalandula_waterfalls_of_the_Lucala-River_in_Malange,_Angola.JPG","credit":"Paulo César Santos","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Kalandula_waterfalls_of_the_Lucala-River_in_Malange,_Angola.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Kalandula_Falls"]'::jsonb)
