insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tundavala-gap','AGO','Tundavala Gap',null,'gorge',-14.82,13.4,'A sheer escarpment edge near Lubango where the highlands drop more than 1,000 m towards the Namib.','On clear days the view runs far across the coastal plain; the gap sits at about 2,200 m.','Drop','~1,000 m',false,true,3,'{"color":"#3D405B","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Tundavala_panorama.jpg/1280px-Tundavala_panorama.jpg","credit":"SangeevP","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Tundavala_panorama.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Tundavala_Gap.jpg/1280px-Tundavala_Gap.jpg","credit":"tim kubacki","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Tundavala_Gap.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Tundavala"]'::jsonb)
