insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('serra-da-leba','AGO','Serra da Leba Pass',null,'mountain',-15.07,13.25,'A road of tight hairpin bends that drops down the escarpment from Lubango to Namibe.','Built in the 1970s, the pass is one of Angola’s best-known landmarks, a ribbon of switchbacks on a near-vertical slope.','Built','1970s',false,true,4,'{"color":"#F4A261","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Serra_da_Leba-Road.jpg/1280px-Serra_da_Leba-Road.jpg","credit":"Valmir144","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Serra_da_Leba-Road.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/Lubango-Namibe_landscape.jpg/1280px-Lubango-Namibe_landscape.jpg","credit":"Erik Cleves Kristensen","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Lubango-Namibe_landscape.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Serra_da_Leba"]'::jsonb)
