insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('pungo-andongo','AGO','Black Rocks of Pungo Andongo','Pedras Negras','rock',-9.67,15.58,'Giant dark rock towers rising from the savanna in Malanje.','Legend says footprints in the rock belong to Queen Nzinga, who resisted Portuguese conquest in the 17th century.','Province','Malanje',false,true,5,'{"color":"#2B2D42","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Pungo_Andongo,_Malange,_Angola2.JPG/1280px-Pungo_Andongo,_Malange,_Angola2.JPG","credit":"Paulo César Santos","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Pungo_Andongo,_Malange,_Angola2.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Pungo_Andongo,_Malange,_Angola.JPG/1280px-Pungo_Andongo,_Malange,_Angola.JPG","credit":"Paulo César Santos","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Pungo_Andongo,_Malange,_Angola.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b7/Pungo_Andongo,_Malange,_Angola,_2008.JPG/1280px-Pungo_Andongo,_Malange,_Angola,_2008.JPG","credit":"Paulo César Santos","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Pungo_Andongo,_Malange,_Angola,_2008.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Pungo_Andongo"]'::jsonb)
