insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('giant-sable','AGO','Giant Sable Antelope','palanca negra gigante','fauna',-9.5,17.1,'A black antelope with sweeping horns up to about 1.5 m, found only in central Angola. A national symbol.','Thought lost during the civil war, it was rediscovered by camera traps in 2005 in Cangandala. Critically Endangered. The pin is in Cangandala National Park.','Rediscovered','2005',false,true,6,'{"color":"#2B2D42","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Giant_Sable_Antelope_(22018702922).jpg/1280px-Giant_Sable_Antelope_(22018702922).jpg","credit":"Thomas Quine","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Giant_Sable_Antelope_(22018702922).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/d/de/Museu_de_Hist%C3%B3ria_Natural_in_Luanda_-_Angola_2015.jpg","credit":"David Stanley","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Museu_de_Hist%C3%B3ria_Natural_in_Luanda_-_Angola_2015.jpg"}],"note":"Museum dioramas — the wild herds are rarely photographed."}'::jsonb,'Hippotragus niger variani','["https://en.wikipedia.org/wiki/Giant_sable_antelope","https://www.gbif.org/species/search?q=Hippotragus%20niger%20variani"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mopane','AGO','Mopane',null,'flora',-16.5,14.5,'A tree of hot, dry valleys with butterfly-shaped leaves that fold together in the midday heat.','Mopane worms, the caterpillars that feed on it, are a protein-rich delicacy across southern Africa. The pin is in southern Angola.','Leaves','Butterfly-shaped',false,true,7,'{"color":"#8AB17D","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Mopane.JPG/1280px-Mopane.JPG","credit":"Teo Gómez","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Mopane.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Colophospermum_mopane_arbre_MHNT.jpg/1280px-Colophospermum_mopane_arbre_MHNT.jpg","credit":"Roger Culos","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Colophospermum_mopane_arbre_MHNT.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Colophospermum_mopane_feuilles_MHNT.jpg/1280px-Colophospermum_mopane_feuilles_MHNT.jpg","credit":"Roger Culos","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Colophospermum_mopane_feuilles_MHNT.jpg"}]}'::jsonb,'Colophospermum mopane','["https://en.wikipedia.org/wiki/Colophospermum","https://www.gbif.org/species/search?q=Colophospermum%20mopane"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dja-reserve','CMR','Dja Faunal Reserve',null,'forest',3,13,'One of the largest and best-protected rainforests in Africa, almost encircled by the Dja River.','It holds gorillas, chimpanzees, forest elephants and over 100 other mammal species. World Heritage Site since 1987.','Area','~5,260 km²',true,true,1,'{"color":"#007A5E","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Dja_River_view.JPG/1280px-Dja_River_view.JPG","credit":"Amcaja","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Dja_River_view.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Dja_River_and_pirogue.JPG/1280px-Dja_River_and_pirogue.JPG","credit":"Amcaja","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Dja_River_and_pirogue.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Crossing_the_Dja_on_a_ferry.jpg/1280px-Crossing_the_Dja_on_a_ferry.jpg","credit":"Wikimedia Commons contributor","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Crossing_the_Dja_on_a_ferry.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/407/","https://en.wikipedia.org/wiki/Dja_Faunal_Reserve"]'::jsonb)
