insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('diy-gid-biy','CMR','Diy-Gid-Biy of the Mandara Mountains',null,'heritage',10.88,13.78,'Sixteen dry-stone hilltop sites in the Mandara Mountains, built between about the 12th and 17th centuries.','Their builders are unknown; the name means “ruins of the chief’s house” in the Mafa language. Volcanic plugs such as Rhumsiki rise nearby. World Heritage Site since 2025.','Sites','16',true,true,2,'{"color":"#5C4033","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/3/3c/Rhumsiki_Peak.jpg","credit":"Amcaja","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Rhumsiki_Peak.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Rhumsiki_with_Kapsiki_Peak_(after_sunrise),_Far_North_Province_of_Cameroon.jpg/1280px-Rhumsiki_with_Kapsiki_Peak_(after_sunrise),_Far_North_Province_of_Cameroon.jpg","credit":"Alfred Weidinger","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Rhumsiki_with_Kapsiki_Peak_(after_sunrise),_Far_North_Province_of_Cameroon.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Kapsiki_home_in_Rhumsiki.jpg/1280px-Kapsiki_home_in_Rhumsiki.jpg","credit":"Amcaja","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Kapsiki_home_in_Rhumsiki.jpg"}],"note":"The Mandara Mountains near Rhumsiki — no open photos of the stone sites themselves yet."}'::jsonb,null,'["https://whc.unesco.org/en/list/1745/","https://en.wikipedia.org/wiki/Diy-Gid-Biy"]'::jsonb)
