insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mount-cameroon','CMR','Mount Cameroon','Mongo ma Ndemi','volcano',4.22,9.17,'An active volcano rising to 4,040 m straight from the Atlantic shore, the highest peak in West and Central Africa.','Its seaward slopes are among the wettest places on Earth. Each year runners race to the summit and back in the Race of Hope.','Height','4,040 m',false,true,3,'{"color":"#CE1126","intensity":0.85,"motion":"mist"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/a/ae/Cameroon_Mountain_Race.webm/Cameroon_Mountain_Race.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/a/ae/Cameroon_Mountain_Race.webm/Cameroon_Mountain_Race.webm.360p.mpeg4.mov","credit":"Eyongblaise","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cameroon_Mountain_Race.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/Mount_Cameroon_from_douala_Cameroon.jpg/1280px-Mount_Cameroon_from_douala_Cameroon.jpg","credit":"Blaizo 237","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Cameroon_from_douala_Cameroon.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Mount_Cameroon_hut_2.jpg/1280px-Mount_Cameroon_hut_2.jpg","credit":"Betterfoto","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Cameroon_hut_2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Mount_Cameroon_(ASTER).jpg/1280px-Mount_Cameroon_(ASTER).jpg","credit":"NASA/METI/AIST/Japan Space Systems and U.S./Japan ASTER Science Team","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Mount_Cameroon_(ASTER).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Mount_Cameroon"]'::jsonb)
