insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-nyos','CMR','Lake Nyos',null,'lake',6.44,10.3,'A crater lake whose dissolved carbon dioxide burst out in 1986, suffocating about 1,700 people and their animals.','It is one of only three lakes known to have this kind of “limnic eruption”. Pipes now vent the gas from the deep water.','Disaster','1986',false,true,4,'{"color":"#2A9D8F","intensity":0.85,"motion":"sink"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/Lake_nyos_co2_vent.jpg/1280px-Lake_nyos_co2_vent.jpg","credit":"Bill Evans, USGS","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Lake_nyos_co2_vent.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Nyos","https://en.wikipedia.org/wiki/Lake_Nyos_disaster"]'::jsonb)
