insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lobe-falls','CMR','Lobé Falls',null,'waterfall',2.88,9.9,'A waterfall that tumbles directly into the Atlantic Ocean near Kribi.','Waterfalls falling straight into the sea are rare; fishermen’s pirogues paddle right up to the falls.','Falls into','The Atlantic',false,true,5,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Chutes-Lob%C3%A9-Kribi.JPG/1280px-Chutes-Lob%C3%A9-Kribi.JPG","credit":"Ophelio13","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Chutes-Lob%C3%A9-Kribi.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Chutes-Lob%C3%A9-Kribi2.JPG/1280px-Chutes-Lob%C3%A9-Kribi2.JPG","credit":"Ophelio13","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Chutes-Lob%C3%A9-Kribi2.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Chutes-de-la-Lob%C3%A93.JPG/1280px-Chutes-de-la-Lob%C3%A93.JPG","credit":"Ophelio13","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Chutes-de-la-Lob%C3%A93.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lobé_Falls"]'::jsonb)
