insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('waza','CMR','Waza National Park',null,'savanna',11.33,14.73,'Sahelian savanna and floodplain near Lake Chad, with elephants, giraffes and lions.','Its seasonal waterholes concentrate wildlife in the dry season; it is also a UNESCO biosphere reserve.','Area','~1,700 km²',false,true,6,'{"color":"#FCD116","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Waza-NP-Elephant.jpg/1280px-Waza-NP-Elephant.jpg","credit":"Albert Backer","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Waza-NP-Elephant.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Waza-NP-Giraffes.jpg/1280px-Waza-NP-Giraffes.jpg","credit":"Albert Backer","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Waza-NP-Giraffes.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/A_herd_of_Camels_off_the_Northern_part_of_the_Waza_National_Park_02.jpg/1280px-A_herd_of_Camels_off_the_Northern_part_of_the_Waza_National_Park_02.jpg","credit":"Adesolive","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:A_herd_of_Camels_off_the_Northern_part_of_the_Waza_National_Park_02.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Waza_National_Park"]'::jsonb)
