insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('goliath-frog','CMR','Goliath Frog',null,'fauna',4.1,10.2,'The largest frog on Earth, up to about 32 cm long and over 3 kg, living in fast rivers of Cameroon and Equatorial Guinea.','Males move stones to build nesting pools for their eggs. Endangered. The pin is in the Sanaga basin.','Weight','Up to ~3.3 kg',false,true,7,'{"color":"#3A5A40","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Conraua_goliath_360001369.jpg/1280px-Conraua_goliath_360001369.jpg","credit":"Ryan van Huyssteen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Conraua_goliath_360001369.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Goliath_Frog.jpg/1280px-Goliath_Frog.jpg","credit":"Ryan Somma","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Goliath_Frog.jpg"}]}'::jsonb,'Conraua goliath','["https://en.wikipedia.org/wiki/Goliath_frog","https://www.gbif.org/species/search?q=Conraua%20goliath"]'::jsonb)
