insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('african-cherry','CMR','African Cherry','pygeum','flora',6,10.5,'A montane forest tree whose bark is used in medicine for prostate conditions.','Heavy bark-stripping for export led to its listing under CITES; Cameroon’s highlands are a major source. The pin is a representative point.','Height','Up to ~40 m',false,true,8,'{"color":"#7F4F24","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Prunus_africana_MS_3588.jpg/1280px-Prunus_africana_MS_3588.jpg","credit":"Marco Schmidt","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Prunus_africana_MS_3588.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Red_stinkwood_-_US_Botanic_Gardens_-_Stierch.jpg/1280px-Red_stinkwood_-_US_Botanic_Gardens_-_Stierch.jpg","credit":"Sarah Stierch","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Red_stinkwood_-_US_Botanic_Gardens_-_Stierch.jpg"}]}'::jsonb,'Prunus africana','["https://en.wikipedia.org/wiki/Prunus_africana","https://www.gbif.org/species/search?q=Prunus%20africana"]'::jsonb)
