insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('manovo-gounda-st-floris','CAF','Manovo-Gounda St Floris National Park',null,'savanna',9,21.5,'Wide floodplain savanna in the north, once one of Africa’s richest wildlife areas.','Poaching devastated its rhinos and elephants; it has been on the List in Danger since 1997. World Heritage Site since 1988.','Area','~17,400 km²',true,true,1,'{"color":"#E9C46A","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/Manovo.jpg/1280px-Manovo.jpg","credit":"Garoa larrañeta","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Manovo.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/475/","https://en.wikipedia.org/wiki/Manovo-Gounda_St._Floris_National_Park"]'::jsonb)
