insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dzanga-bai','CAF','Dzanga Bai',null,'wetland',2.95,16.38,'A mineral-rich forest clearing where up to about 100 forest elephants gather at once.','Researchers have recorded thousands of individual elephants here since 1990. It lies in Dzanga-Sangha, part of the Sangha Trinational World Heritage Site.','Elephants at once','Up to ~100',false,true,2,'{"color":"#C8784A","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/26/Dzanga_Bai_panorama_with_forest_elephants_-_August_2018_01.webm/Dzanga_Bai_panorama_with_forest_elephants_-_August_2018_01.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/26/Dzanga_Bai_panorama_with_forest_elephants_-_August_2018_01.webm/Dzanga_Bai_panorama_with_forest_elephants_-_August_2018_01.webm.360p.mpeg4.mov","credit":"JosepMGracia","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Dzanga_Bai_panorama_with_forest_elephants_-_August_2018_01.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Dzanga_Bai_forest_clearing_with_African_forest_elephants,_Central_African_Republic.jpg/1280px-Dzanga_Bai_forest_clearing_with_African_forest_elephants,_Central_African_Republic.jpg","credit":"JosepMGracia","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Dzanga_Bai_forest_clearing_with_African_forest_elephants,_Central_African_Republic.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Young_African_forest_elephant_at_Dzanga_Bai.jpg/1280px-Young_African_forest_elephant_at_Dzanga_Bai.jpg","credit":"JosepMGracia","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Young_African_forest_elephant_at_Dzanga_Bai.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Dzanga_Bai_at_sunrise,_Central_African_Republic.jpg/1280px-Dzanga_Bai_at_sunrise,_Central_African_Republic.jpg","credit":"JosepMGracia","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Dzanga_Bai_at_sunrise,_Central_African_Republic.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Dzanga-Sangha_Special_Reserve","https://whc.unesco.org/en/list/1380/"]'::jsonb)
