insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('boali-falls','CAF','Boali Falls',null,'waterfall',4.8,18.12,'A curtain of water about 50 m high on the Mbali River, north-west of Bangui.','A hydroelectric plant here supplies much of Bangui’s power; in the rainy season the falls spread wide.','Height','~50 m',false,true,3,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Les_Chutes_de_Boali_001.jpg/1280px-Les_Chutes_de_Boali_001.jpg","credit":"Zakalingba","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Les_Chutes_de_Boali_001.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Visite_touristique_des_Chutes_de_Boali.jpg/1280px-Visite_touristique_des_Chutes_de_Boali.jpg","credit":"Zakalingba","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Visite_touristique_des_Chutes_de_Boali.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Une_grotte_%C3%A0_c%C3%B4t%C3%A9_des_chutes_de_boali.jpg/1280px-Une_grotte_%C3%A0_c%C3%B4t%C3%A9_des_chutes_de_boali.jpg","credit":"Zakalingba","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Une_grotte_%C3%A0_c%C3%B4t%C3%A9_des_chutes_de_boali.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Boali"]'::jsonb)
