insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ubangi-river','CAF','Ubangi River','Oubangui','river',4.36,18.6,'The great river that forms the border with DR Congo, flowing past Bangui to join the Congo.','It is the largest right-bank tributary of the Congo and the country’s main route to the sea.','Length','~1,060 km',false,true,4,'{"color":"#264653","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/IMG_Zongo_on_the_Ubangi_river,_Friday_16,_1985;_Bangui_on_the_other_side_of_the_river;_author_JC.jpg/1280px-IMG_Zongo_on_the_Ubangi_river,_Friday_16,_1985;_Bangui_on_the_other_side_of_the_river;_author_JC.jpg","credit":"Jeanmarteauenbois","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:IMG_Zongo_on_the_Ubangi_river,_Friday_16,_1985;_Bangui_on_the_other_side_of_the_river;_author_JC.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Ubangi_River"]'::jsonb)
