insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('forest-elephant','CAF','African Forest Elephant',null,'fauna',2.95,16.38,'A smaller elephant of the rainforest with straight, downward-pointing tusks.','Recognised as a separate species, it spreads the seeds of many trees. Critically Endangered after heavy ivory poaching. The pin is at Dzanga Bai.','IUCN status','Critically Endangered',false,true,5,'{"color":"#6C757D","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Loxodontacyclotis.jpg/1280px-Loxodontacyclotis.jpg","credit":"Thomas Breuer","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Loxodontacyclotis.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/L''%C3%A9l%C3%A9phant_de_for%C3%AAt_d''Afrique_(Loxodonta_cyclotis).jpg/1280px-L''%C3%A9l%C3%A9phant_de_for%C3%AAt_d''Afrique_(Loxodonta_cyclotis).jpg","credit":"Christian Vigna","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:L''%C3%A9l%C3%A9phant_de_for%C3%AAt_d''Afrique_(Loxodonta_cyclotis).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Loxodonta_cyclotis_3970045.jpg/1280px-Loxodonta_cyclotis_3970045.jpg","credit":"Matt Muir","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Loxodonta_cyclotis_3970045.jpg"}]}'::jsonb,'Loxodonta cyclotis','["https://en.wikipedia.org/wiki/African_forest_elephant","https://www.gbif.org/species/search?q=Loxodonta%20cyclotis"]'::jsonb)
