insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('koko-gnetum','CAF','Koko','eru · okok','flora',3.8,17.5,'A forest vine whose leaves are sliced thin and cooked as a favourite green across Central Africa.','Gathered wild and traded across borders, it is a key source of income for forest families. The pin is a representative point.','Eaten as','Leafy green',false,true,6,'{"color":"#3E9A00","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Gnetum_africanum_Leaves_(Eru_ou_Okok).jpg/1280px-Gnetum_africanum_Leaves_(Eru_ou_Okok).jpg","credit":"Minette Lontsie","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Gnetum_africanum_Leaves_(Eru_ou_Okok).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Gnetum_africanum_MS_3428.jpg/1280px-Gnetum_africanum_MS_3428.jpg","credit":"Marco Schmidt","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Gnetum_africanum_MS_3428.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Gnetum_africanum_Leaves_(Eru,_Okok).jpg/1280px-Gnetum_africanum_Leaves_(Eru,_Okok).jpg","credit":"Minette Lontsie","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Gnetum_africanum_Leaves_(Eru,_Okok).jpg"}]}'::jsonb,'Gnetum africanum','["https://en.wikipedia.org/wiki/Gnetum_africanum","https://www.gbif.org/species/search?q=Gnetum%20africanum"]'::jsonb)
