insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lakes-of-ounianga','TCD','Lakes of Ounianga',null,'lake',19.05,20.51,'Eighteen lakes in the Sahara, fed by fossil groundwater, in one of the driest places on Earth.','Some are fresh, others salty and red with algae; floating reeds slow evaporation. World Heritage Site since 2012.','Lakes','18',true,true,1,'{"color":"#C60C30","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/5/56/Red_Waters_of_Lake_Motro_(24468521226).jpg","credit":"David Stanley","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Red_Waters_of_Lake_Motro_(24468521226).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/c/c6/Lake_Motro_(24383699102).jpg","credit":"David Stanley","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Lake_Motro_(24383699102).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/c/c3/Lake_Teli_(24455091546).jpg","credit":"David Stanley","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Lake_Teli_(24455091546).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1400/","https://en.wikipedia.org/wiki/Lakes_of_Ounianga"]'::jsonb)
