insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ennedi-massif','TCD','Ennedi Massif',null,'rock',17.04,21.86,'A sandstone plateau of arches, pillars and canyons in north-east Chad.','Gueltas such as Guelta d’Archei shelter some of the last Saharan crocodiles, and the rock shelters hold thousands of paintings. Mixed World Heritage Site since 2016.','Inscribed','2016',true,true,2,'{"color":"#E07A3F","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Camels_in_the_Labyrinthe_(Maze)_sandstone_area_of_the_Ennedi,_Chad_(42405451704).jpg/1280px-Camels_in_the_Labyrinthe_(Maze)_sandstone_area_of_the_Ennedi,_Chad_(42405451704).jpg","credit":"Valerian Guillot","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Camels_in_the_Labyrinthe_(Maze)_sandstone_area_of_the_Ennedi,_Chad_(42405451704).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Guelta_Maya,_Ennedi,_Tschad.jpg/1280px-Guelta_Maya,_Ennedi,_Tschad.jpg","credit":"Sven.oehm","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Guelta_Maya,_Ennedi,_Tschad.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Felsbildzeichnung_im_Ennedi,_Terkei.jpg/1280px-Felsbildzeichnung_im_Ennedi,_Terkei.jpg","credit":"Sven.oehm","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Felsbildzeichnung_im_Ennedi,_Terkei.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1475/","https://en.wikipedia.org/wiki/Ennedi_Plateau"]'::jsonb)
