insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('zakouma','TCD','Zakouma National Park',null,'savanna',10.85,19.65,'Floodplain savanna in south-east Chad where elephant numbers are rising again after a poaching crisis.','Managed with African Parks since 2010, it has seen elephant herds grow and lions and black rhinos return.','Area','~3,000 km²',false,true,3,'{"color":"#FECB00","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Girafe_du_parc_national_de_Zakouma.jpg/1280px-Girafe_du_parc_national_de_Zakouma.jpg","credit":"Fatakaya","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Girafe_du_parc_national_de_Zakouma.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Buffle_solitaire_au_Parc_national_de_Zakouma.jpg/1280px-Buffle_solitaire_au_Parc_national_de_Zakouma.jpg","credit":"Fatakaya","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Buffle_solitaire_au_Parc_national_de_Zakouma.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Vue_sur_le_camp_visiteur_%C3%A0_Zakouma.jpg/1280px-Vue_sur_le_camp_visiteur_%C3%A0_Zakouma.jpg","credit":"Fatakaya","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Vue_sur_le_camp_visiteur_%C3%A0_Zakouma.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Zakouma_National_Park"]'::jsonb)
