insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-chad','TCD','Lake Chad',null,'lake',13.1,14.53,'A shallow lake shared by Chad, Cameroon, Niger and Nigeria, famous for its dramatic changes in size.','It shrank from about 25,000 km² in the 1960s to a fraction of that, and swells and shrinks with the rains, supporting millions of people.','1960s area','~25,000 km²',false,true,4,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/A_serene_lake_chad_shore.jpg/1280px-A_serene_lake_chad_shore.jpg","credit":"Coolthoom1","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:A_serene_lake_chad_shore.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/Lake_Chad_from_Apollo_7.jpg/1280px-Lake_Chad_from_Apollo_7.jpg","credit":"NASA","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Lake_Chad_from_Apollo_7.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/An_evergreen_lake_chad_shore.jpg/1280px-An_evergreen_lake_chad_shore.jpg","credit":"Coolthoom1","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:An_evergreen_lake_chad_shore.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Chad"]'::jsonb)
