insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('emi-koussi','TCD','Emi Koussi',null,'volcano',19.79,18.55,'The highest peak of the Sahara at 3,415 m, a huge shield volcano in the Tibesti Mountains.','Its summit caldera is about 15 km wide, and the Tibesti’s volcanoes are among the least visited on Earth.','Height','3,415 m',false,true,5,'{"color":"#3D3A4B","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Tibesti_east_of_bardai.jpg/1280px-Tibesti_east_of_bardai.jpg","credit":"Michael Kerling","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Tibesti_east_of_bardai.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Tibesti_Mountains.jpg/1280px-Tibesti_Mountains.jpg","credit":"European Space Agency","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Tibesti_Mountains.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Emi_Koussi","https://en.wikipedia.org/wiki/Tibesti_Mountains"]'::jsonb)
