insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kordofan-giraffe','TCD','Kordofan Giraffe',null,'fauna',10.85,19.65,'A giraffe of the central African savannas, with pale patches and spotted legs.','Zakouma holds one of its largest remaining populations. Critically Endangered. The pin is in Zakouma.','IUCN status','Critically Endangered',false,true,6,'{"color":"#C8784A","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/9/93/Kordofan-Giraffe_(Zoo_Dresden)_(9).webm/Kordofan-Giraffe_(Zoo_Dresden)_(9).webm.480p.vp9.webm","credit":"Fiver, der Hellseher","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kordofan-Giraffe_(Zoo_Dresden)_(9).webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/1/12/Giraffa_camelopardalis_antiquorum_(Vincennes_Zoo)_4.jpg","credit":"Mathae","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Giraffa_camelopardalis_antiquorum_(Vincennes_Zoo)_4.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/f/fe/Giraffa_camelopardalis_antiquorum_(Vincennes_Zoo)1.jpg","credit":"Mathae","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Giraffa_camelopardalis_antiquorum_(Vincennes_Zoo)1.jpg"}],"note":"Zoo animals — Kordofan giraffes in the wild live in Zakouma and Garamba."}'::jsonb,'Giraffa camelopardalis antiquorum','["https://en.wikipedia.org/wiki/Kordofan_giraffe","https://www.gbif.org/species/search?q=Giraffa%20camelopardalis%20antiquorum"]'::jsonb)
