insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('desert-date','TCD','Desert Date','hidjlidj','flora',13.5,18,'A spiny Sahel tree whose sweet-bitter fruit, oil and leaves are used in food and medicine.','It thrives where few other trees can, and is one of the species planted for Africa’s Great Green Wall. The pin is a representative point.','Planted for','Great Green Wall',false,true,7,'{"color":"#B07D4B","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Balanites_aegyptiaca_0730.jpg/1280px-Balanites_aegyptiaca_0730.jpg","credit":"Marco Schmidt","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Balanites_aegyptiaca_0730.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Balanites_aegyptiaca_MS4917.JPG/1280px-Balanites_aegyptiaca_MS4917.JPG","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Balanites_aegyptiaca_MS4917.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Balanites_aegyptiaca_MHNT.BOT.2009.13.5.jpg/1280px-Balanites_aegyptiaca_MHNT.BOT.2009.13.5.jpg","credit":"Roger Culos","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Balanites_aegyptiaca_MHNT.BOT.2009.13.5.jpg"}]}'::jsonb,'Balanites aegyptiaca','["https://en.wikipedia.org/wiki/Balanites_aegyptiaca","https://www.gbif.org/species/search?q=Balanites%20aegyptiaca"]'::jsonb)
