insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('virunga','COD','Virunga National Park',null,'mountain',-0.92,29.17,'Africa’s oldest national park (1925), from lava plains and active volcanoes to the glaciers of the Rwenzori.','It shelters about a third of the world’s mountain gorillas, along with hippos on Lake Edward. On the List in Danger since 1994.','Founded','1925',true,true,1,'{"color":"#1B4332","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Virunga_01.jpg/1280px-Virunga_01.jpg","credit":"Ad Meskens","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Virunga_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/be/Virunga_Mountain_Gorilla.jpg/1280px-Virunga_Mountain_Gorilla.jpg","credit":"Cai Tjeenk Willink","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Virunga_Mountain_Gorilla.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Virunga_03.jpg/1280px-Virunga_03.jpg","credit":"Ad Meskens","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Virunga_03.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/63/","https://en.wikipedia.org/wiki/Virunga_National_Park"]'::jsonb)
