insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('garamba','COD','Garamba National Park',null,'savanna',4,29.25,'Savanna and gallery forest on the South Sudan border, one of Africa’s oldest parks.','It was the last stronghold of the northern white rhino in the wild. It still holds Kordofan giraffes and elephants. World Heritage Site since 1980.','Founded','1938',true,true,2,'{"color":"#F7D618","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7e/Kordofan_giraffe_in_Garamba_National_Park.jpg/1280px-Kordofan_giraffe_in_Garamba_National_Park.jpg","credit":"Matthew Luizza / U.S. Fish and Wildlife Service","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Kordofan_giraffe_in_Garamba_National_Park.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Ian_and_Rangers_Garamba_National_Park,_Congo_2003.jpg/1280px-Ian_and_Rangers_Garamba_National_Park,_Congo_2003.jpg","credit":"Ian J. Saunders","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ian_and_Rangers_Garamba_National_Park,_Congo_2003.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/136/","https://en.wikipedia.org/wiki/Garamba_National_Park"]'::jsonb)
