insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kahuzi-biega','COD','Kahuzi-Biega National Park',null,'forest',-2.5,28.75,'Montane and lowland forest west of Lake Kivu, dominated by the extinct volcanoes Kahuzi and Biega.','It protects the eastern lowland (Grauer’s) gorilla, the largest gorilla subspecies. On the List in Danger since 1997.','Gorilla','Grauer’s',true,true,3,'{"color":"#2D6A4F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/Kahuzi_Biega_National_Park_Banner.jpg/1280px-Kahuzi_Biega_National_Park_Banner.jpg","credit":"Joe McKenna","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Kahuzi_Biega_National_Park_Banner.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Kahuzi-Biega_National_Park_(39423247372).jpg/1280px-Kahuzi-Biega_National_Park_(39423247372).jpg","credit":"USDA Forest Service","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Kahuzi-Biega_National_Park_(39423247372).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Kahuzi-Biega_National_Park_(39423247252).jpg/1280px-Kahuzi-Biega_National_Park_(39423247252).jpg","credit":"USDA Forest Service","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Kahuzi-Biega_National_Park_(39423247252).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/137/","https://en.wikipedia.org/wiki/Kahuzi-Biega_National_Park"]'::jsonb)
