insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('salonga','COD','Salonga National Park',null,'forest',-2,21,'Africa’s largest tropical rainforest reserve, reachable only by river.','It covers about 36,000 km² and is home to the bonobo, forest elephant and Congo peafowl. Removed from the List in Danger in 2021.','Area','~36,000 km²',true,true,4,'{"color":"#52B788","intensity":0.85,"motion":"mist"}'::jsonb,'{"note":"No openly licensed photos of Salonga yet."}'::jsonb,null,'["https://whc.unesco.org/en/list/280/","https://en.wikipedia.org/wiki/Salonga_National_Park"]'::jsonb)
