insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('nyiragongo','COD','Nyiragongo',null,'volcano',-1.52,29.25,'An active volcano above Goma, with one of the largest lava lakes on Earth in its crater.','Its lava is unusually fluid; eruptions in 1977, 2002 and 2021 sent flows towards the city.','Height','3,470 m',false,true,6,'{"color":"#CE1021","intensity":0.85,"motion":"sink"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/Lava_Lake_Nyiragongo_2.jpg/1280px-Lava_Lake_Nyiragongo_2.jpg","credit":"Cai Tjeenk Willink","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Lava_Lake_Nyiragongo_2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/An_aerial_view_of_the_towering_volcanic_peak_of_Mt._Nyiragongo.jpg/1280px-An_aerial_view_of_the_towering_volcanic_peak_of_Mt._Nyiragongo.jpg","credit":"MONUSCO / Neil Wetmore","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:An_aerial_view_of_the_towering_volcanic_peak_of_Mt._Nyiragongo.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Mount_Nyiragongo"]'::jsonb)
