insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('boyoma-falls','COD','Boyoma Falls',null,'waterfall',0.49,25.21,'Seven cataracts on the upper Congo near Kisangani, over about 100 km of river.','By the volume of water, they are often cited as the largest waterfalls in the world. Wagenya fishermen fish them with wooden tripods and basket traps.','Cataracts','7',false,true,7,'{"color":"#007FFF","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Zaire_kisangani_stroom_12_copy.jpg/1280px-Zaire_kisangani_stroom_12_copy.jpg","credit":"Ad Meskens","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Zaire_kisangani_stroom_12_copy.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Zaire_kisangani_stroom_11_copy.jpg/1280px-Zaire_kisangani_stroom_11_copy.jpg","credit":"Ad Meskens","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Zaire_kisangani_stroom_11_copy.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Zaire_kisangani_stroom_14_copy.jpg/1280px-Zaire_kisangani_stroom_14_copy.jpg","credit":"Ad Meskens","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Zaire_kisangani_stroom_14_copy.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Boyoma_Falls"]'::jsonb)
