insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('livingstone-falls','COD','Livingstone Falls',null,'river',-4.32,15.21,'A chain of huge rapids where the Congo drops about 270 m on its way from Kinshasa to the sea.','The rapids stopped navigation upstream, so early travellers had to go overland. Some stretches are among the deepest river channels known.','Drop','~270 m',false,true,8,'{"color":"#2A6F97","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Fleuve_Congo_Kinshasa_1.JPG/1280px-Fleuve_Congo_Kinshasa_1.JPG","credit":"Serein","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Fleuve_Congo_Kinshasa_1.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Fleuve_Congo_Kinshasa_4.JPG/1280px-Fleuve_Congo_Kinshasa_4.JPG","credit":"Serein","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Fleuve_Congo_Kinshasa_4.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Fleuve_Congo_Kinshasa_7.JPG/1280px-Fleuve_Congo_Kinshasa_7.JPG","credit":"Serein","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Fleuve_Congo_Kinshasa_7.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Livingstone_Falls"]'::jsonb)
