insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bonobo','COD','Bonobo',null,'fauna',-2,21.5,'The great ape found only south of the Congo River, our closest living relative along with the chimpanzee.','Bonobo societies are led by females and settle tension through social bonds rather than fighting. Endangered. The pin is in the Salonga area.','Found only in','DR Congo',false,true,9,'{"color":"#3D405B","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/27/Bonobo_chimpanzees_having_fun.webm/Bonobo_chimpanzees_having_fun.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/27/Bonobo_chimpanzees_having_fun.webm/Bonobo_chimpanzees_having_fun.webm.360p.mpeg4.mov","credit":"Rob Bixby","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Bonobo_chimpanzees_having_fun.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Pan_paniscus_(Bonobo_baby_and_mother).jpg/1280px-Pan_paniscus_(Bonobo_baby_and_mother).jpg","credit":"Nick Hobgood","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Pan_paniscus_(Bonobo_baby_and_mother).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Bonobo-04.jpg/1280px-Bonobo-04.jpg","credit":"Greg Hume","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Bonobo-04.jpg"}]}'::jsonb,'Pan paniscus','["https://en.wikipedia.org/wiki/Bonobo","https://www.gbif.org/species/search?q=Pan%20paniscus"]'::jsonb)
