insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('limbali','COD','Limbali',null,'flora',1.4,28.6,'A canopy tree that forms almost single-species forests along the rivers of the Congo basin.','Limbali stands cast deep shade and drop large seeds that sprout under their parents, letting one species dominate a whole forest. The pin is in the Ituri.','Forms','Single-species forests',false,true,10,'{"color":"#F7D618","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Gilbertiodendron_dewevrei_01.jpg/1280px-Gilbertiodendron_dewevrei_01.jpg","credit":"Xander van der Burgt","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Gilbertiodendron_dewevrei_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Gilbertiodendron_dewevrei_03.jpg/1280px-Gilbertiodendron_dewevrei_03.jpg","credit":"Xander van der Burgt","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Gilbertiodendron_dewevrei_03.jpg"}]}'::jsonb,'Gilbertiodendron dewevrei','["https://en.wikipedia.org/wiki/Gilbertiodendron_dewevrei","https://www.gbif.org/species/search?q=Gilbertiodendron%20dewevrei"]'::jsonb)
