insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sangha-trinational','COG','Sangha Trinational',null,'forest',2.61,16.55,'Some 7,500 km² of rainforest joining parks in Congo, Cameroon and the Central African Republic.','Its clearings attract forest elephants, gorillas and bongos. Researchers here filmed wild gorillas using sticks as tools. World Heritage Site since 2012.','Countries','3',true,true,1,'{"color":"#009543","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Flooded_forest_channel_in_the_Black_Forest,_Republic_of_the_Congo.jpg/1280px-Flooded_forest_channel_in_the_Black_Forest,_Republic_of_the_Congo.jpg","credit":"JosepMGracia","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Flooded_forest_channel_in_the_Black_Forest,_Republic_of_the_Congo.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Gorilla_tool_use.png/1280px-Gorilla_tool_use.png","credit":"Breuer, Ndoundou-Hockemba & Fishlock (PLoS Biology)","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Gorilla_tool_use.png"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Loxodontacyclotis.jpg/1280px-Loxodontacyclotis.jpg","credit":"Thomas Breuer","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Loxodontacyclotis.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1380/","https://en.wikipedia.org/wiki/Sangha_Trinational"]'::jsonb)
