insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('odzala-kokoua','COG','Forest Massif of Odzala-Kokoua',null,'forest',0.8,14.9,'Rainforest and savanna clearings in north-west Congo with one of Africa’s densest gorilla populations.','Protected since 1935, one of Africa’s oldest parks, it holds western lowland gorillas, chimpanzees and forest elephants. World Heritage Site since 2023.','Protected since','1935',true,true,2,'{"color":"#1B4332","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/18/Primage2.jpg/1280px-Primage2.jpg","credit":"Leighcn","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Primage2.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/692/","https://en.wikipedia.org/wiki/Odzala-Kokoua_National_Park"]'::jsonb)
