insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('congo-rapids-brazzaville','COG','Congo Rapids at Brazzaville',null,'river',-4.29,15.25,'The Congo River leaves Malebo Pool in thundering rapids between Brazzaville and Kinshasa.','The two capitals face each other across the river, the closest pair of capitals in the world apart from Rome and Vatican City.','Capitals apart','~1.6 km',false,true,3,'{"color":"#2A6F97","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Fishermen_of_the_Congo_Basin_4.jpg/1280px-Fishermen_of_the_Congo_Basin_4.jpg","credit":"Cethuyghe","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Fishermen_of_the_Congo_Basin_4.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Congo_River"]'::jsonb)
