insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('conkouati-douli','COG','Conkouati-Douli National Park',null,'coast',-3.9,11.47,'A coastal park of lagoons, savanna and forest where turtles nest and chimpanzees are released.','It is one of the most diverse protected areas in Congo, from the ocean to the Mayombe mountains.','Area','~5,000 km²',false,true,4,'{"color":"#48CAE4","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Conkouati_douli.jpg/1280px-Conkouati_douli.jpg","credit":"Stevy08","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Conkouati_douli.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Paysage_du_parc_conkouati_03.jpg/1280px-Paysage_du_parc_conkouati_03.jpg","credit":"Kezhy Chan","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Paysage_du_parc_conkouati_03.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Paysage_du_parc_conkouati_02.jpg/1280px-Paysage_du_parc_conkouati_02.jpg","credit":"Kezhy Chan","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Paysage_du_parc_conkouati_02.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Conkouati-Douli_National_Park"]'::jsonb)
