insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('western-lowland-gorilla','COG','Western Lowland Gorilla',null,'fauna',0.8,14.9,'The most numerous gorilla, living in the swamp and lowland forests of the Congo basin.','Most of the world’s western lowland gorillas live in Congo and Gabon, but Ebola and poaching have cut numbers sharply. Critically Endangered. The pin is in Odzala.','IUCN status','Critically Endangered',false,true,5,'{"color":"#2F3E46","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/1/13/Western_lowland_gorillas_(mom_and_baby).webm/Western_lowland_gorillas_(mom_and_baby).webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/1/13/Western_lowland_gorillas_(mom_and_baby).webm/Western_lowland_gorillas_(mom_and_baby).webm.360p.mpeg4.mov","credit":"Madeline","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Western_lowland_gorillas_(mom_and_baby).webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Gorilla_gorilla_gorilla_(Gorille_des_plaines_de_l''Ouest)_-_458.jpg/1280px-Gorilla_gorilla_gorilla_(Gorille_des_plaines_de_l''Ouest)_-_458.jpg","credit":"Medium69 (William Crochot)","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Gorilla_gorilla_gorilla_(Gorille_des_plaines_de_l''Ouest)_-_458.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Western_Lowland_Gorilla_at_Bronx_Zoo_4.jpg/1280px-Western_Lowland_Gorilla_at_Bronx_Zoo_4.jpg","credit":"Fred Hsu","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Western_Lowland_Gorilla_at_Bronx_Zoo_4.jpg"}]}'::jsonb,'Gorilla gorilla gorilla','["https://en.wikipedia.org/wiki/Western_lowland_gorilla","https://www.gbif.org/species/search?q=Gorilla%20gorilla%20gorilla"]'::jsonb)
