insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('african-tulip-tree','COG','African Tulip Tree',null,'flora',-4.2,15.3,'A forest tree with fiery orange cup-shaped flowers, native to tropical Central and West Africa.','Planted in gardens across the tropics, it is invasive in some islands. Its flower cups hold rain and nectar for birds. The pin is near Brazzaville.','Flowers','Orange-red',false,true,6,'{"color":"#F3722C","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/African_Tulip_Tree_(Spathodea_campanulata).jpg/1280px-African_Tulip_Tree_(Spathodea_campanulata).jpg","credit":"Mokkie","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:African_Tulip_Tree_(Spathodea_campanulata).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/African_Tulip_Tree_(Spathodea_campanulata)_1.jpg/1280px-African_Tulip_Tree_(Spathodea_campanulata)_1.jpg","credit":"Mokkie","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:African_Tulip_Tree_(Spathodea_campanulata)_1.jpg"}]}'::jsonb,'Spathodea campanulata','["https://en.wikipedia.org/wiki/Spathodea","https://www.gbif.org/species/search?q=Spathodea%20campanulata"]'::jsonb)
