insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('pico-basile','GNQ','Pico Basilé',null,'volcano',3.59,8.76,'The highest point of Equatorial Guinea at 3,011 m, a volcano rising over Malabo on Bioko.','Cloud forest on its slopes is home to endemic birds and primates found only on Bioko.','Height','3,011 m',false,true,1,'{"color":"#2B2D42","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Pico_Basil%C3%A9.jpg/1280px-Pico_Basil%C3%A9.jpg","credit":"Serge Moons","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Pico_Basil%C3%A9.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Pico_Basilé"]'::jsonb)
