insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('monte-alen','GNQ','Monte Alén National Park',null,'forest',1.53,10.11,'The largest park in mainland Equatorial Guinea, a rainforest of rivers and granite peaks.','It holds gorillas, chimpanzees, forest elephants and many butterflies, across about 2,000 km².','Area','~2,000 km²',false,true,2,'{"color":"#3E9A00","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Nationalpark_Monte_Al%C3%A9n.jpg/1280px-Nationalpark_Monte_Al%C3%A9n.jpg","credit":"Mehlauge","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Nationalpark_Monte_Al%C3%A9n.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Euphaedra_eleus_eleus_(Eleus_Orange_Forester).jpg/1280px-Euphaedra_eleus_eleus_(Eleus_Orange_Forester).jpg","credit":"Kristof Zyskowski & Yulia Bereshpolova","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Euphaedra_eleus_eleus_(Eleus_Orange_Forester).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Monte_Alén_National_Park"]'::jsonb)
