insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bioko-drill','GNQ','Bioko Drill',null,'fauna',3.3,8.6,'A short-tailed forest monkey related to the mandrill, with a black face and red lower lip.','The drill is one of Africa’s most endangered primates; the Bioko form lives only on the island, threatened by bushmeat hunting. The pin is in southern Bioko.','IUCN status','Endangered',false,true,4,'{"color":"#5C4033","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Mandrillus_leucophaeus_poensis_56247506.jpg/1280px-Mandrillus_leucophaeus_poensis_56247506.jpg","credit":"Chris Quirin","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Mandrillus_leucophaeus_poensis_56247506.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Mandrillus_leucophaeus_poensis_56247487.jpg/1280px-Mandrillus_leucophaeus_poensis_56247487.jpg","credit":"Chris Quirin","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Mandrillus_leucophaeus_poensis_56247487.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Mandrillus_leucophaeus_poensis_63853104.jpg/1280px-Mandrillus_leucophaeus_poensis_63853104.jpg","credit":"Chris Quirin","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Mandrillus_leucophaeus_poensis_63853104.jpg"}]}'::jsonb,'Mandrillus leucophaeus poensis','["https://en.wikipedia.org/wiki/Drill_(animal)","https://www.gbif.org/species/search?q=Mandrillus%20leucophaeus"]'::jsonb)
