insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ceiba-god-tree','GNQ','God Tree','árbol de Dios','flora',3.75,8.78,'A giant silk-cotton tree, the emblem on Equatorial Guinea’s coat of arms.','Tradition holds that an early treaty between Spain and a local ruler was signed beneath such a tree. Kapok trees can top 60 m. The pin is near Malabo.','Height','Up to ~60 m',false,true,5,'{"color":"#E9F5DB","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Ilet_la_M%C3%A8re_Ceiba_pentandra_fromager_2013.jpg/1280px-Ilet_la_M%C3%A8re_Ceiba_pentandra_fromager_2013.jpg","credit":"Cayambe","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Ilet_la_M%C3%A8re_Ceiba_pentandra_fromager_2013.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/Ceiba_pentandra_-_Jardim_Bot%C3%A2nico_da_Madeira_01.jpg/1280px-Ceiba_pentandra_-_Jardim_Bot%C3%A2nico_da_Madeira_01.jpg","credit":"H. Zell","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Ceiba_pentandra_-_Jardim_Bot%C3%A2nico_da_Madeira_01.jpg"}]}'::jsonb,'Ceiba pentandra','["https://en.wikipedia.org/wiki/Coat_of_arms_of_Equatorial_Guinea","https://www.gbif.org/species/search?q=Ceiba%20pentandra"]'::jsonb)
