insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lope-okanda','GAB','Lopé-Okanda',null,'forest',-0.5,11.5,'Rainforest and relict savannas along the Ogooué, with traces of people stretching back 400,000 years.','Around 1,800 rock engravings and Iron Age sites lie among mandrill troops of up to several hundred. Mixed World Heritage Site since 2007.','Rock engravings','~1,800',true,true,1,'{"color":"#009E60","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Lop%C3%A9_National_Park_river_panorama.jpg/1280px-Lop%C3%A9_National_Park_river_panorama.jpg","credit":"FX","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Lop%C3%A9_National_Park_river_panorama.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Lop%C3%A9_National_Park_village_panorama.jpg/1280px-Lop%C3%A9_National_Park_village_panorama.jpg","credit":"FX","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Lop%C3%A9_National_Park_village_panorama.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1147/","https://en.wikipedia.org/wiki/Lopé_National_Park"]'::jsonb)
