insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ivindo','GAB','Ivindo National Park',null,'waterfall',0.09,12.63,'Blackwater rivers and waterfalls such as Kongou in the heart of Gabon’s forest.','The Langoué Bai clearing draws forest elephants and gorillas. World Heritage Site since 2021.','Inscribed','2021',true,true,2,'{"color":"#3A75C4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Waterfall_ivindo_gabon.jpg/1280px-Waterfall_ivindo_gabon.jpg","credit":"Jefe Le Gran","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Waterfall_ivindo_gabon.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Elephants_running_in_a_stream.jpg/1280px-Elephants_running_in_a_stream.jpg","credit":"Ngangorica","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Elephants_running_in_a_stream.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Tagoue_and_other_elephants.jpg/1280px-Tagoue_and_other_elephants.jpg","credit":"Ngangorica","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Tagoue_and_other_elephants.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1653/","https://en.wikipedia.org/wiki/Ivindo_National_Park"]'::jsonb)
