insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('loango','GAB','Loango National Park',null,'coast',-2.17,9.57,'Lagoons, forest and beaches where elephants, buffalo and hippos walk on the sand.','Called “Africa’s last Eden”; hippos have been filmed swimming in the surf, and humpback whales pass offshore.','Created','2002',false,true,3,'{"color":"#E07A3F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c1/Wild_Western_Lowland_gorilla_and_his_family_foraging_for_figs.webm/Wild_Western_Lowland_gorilla_and_his_family_foraging_for_figs.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c1/Wild_Western_Lowland_gorilla_and_his_family_foraging_for_figs.webm/Wild_Western_Lowland_gorilla_and_his_family_foraging_for_figs.webm.360p.mpeg4.mov","credit":"TheLeftCoast","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Wild_Western_Lowland_gorilla_and_his_family_foraging_for_figs.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Loango_National_Park.jpg/1280px-Loango_National_Park.jpg","credit":"Emailsson","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Loango_National_Park.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Gabon_Loango_National_Park_Elephant_with_offspring.jpeg/1280px-Gabon_Loango_National_Park_Elephant_with_offspring.jpeg","credit":"Kurt Dundy","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Gabon_Loango_National_Park_Elephant_with_offspring.jpeg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Gabon_Loango_National_Park_Wild_Buffalo_Single.jpeg/1280px-Gabon_Loango_National_Park_Wild_Buffalo_Single.jpeg","credit":"Kurt Dundy","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Gabon_Loango_National_Park_Wild_Buffalo_Single.jpeg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Loango_National_Park"]'::jsonb)
