insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('pongara','GAB','Pongara National Park',null,'coast',0.12,9.63,'Mangroves and beaches across the estuary from Libreville.','Its beaches are among the most important leatherback turtle nesting sites in the world.','Turtles','Leatherbacks',false,true,4,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Parc_national_de_Pongara.jpg/1280px-Parc_national_de_Pongara.jpg","credit":"Allmania23","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Parc_national_de_Pongara.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/PongaraLodge.jpg/1280px-PongaraLodge.jpg","credit":"Allmania23","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:PongaraLodge.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Pongara_National_Park"]'::jsonb)
