insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('monts-de-cristal','GAB','Monts de Cristal',null,'mountain',0.5,10.5,'Misty low mountains near the Equatorial Guinea border, among the richest plant areas in Africa.','Botanists have recorded many endemic begonias and orchids here.','Known for','Begonias · orchids',false,true,5,'{"color":"#1B4332","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/b/b3/Vue_de_Monts_de_Cristal.jpg","credit":"Nitoni Noio","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Vue_de_Monts_de_Cristal.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/d/d7/Parc_national_des_Monts_de_Cristal_banni%C3%A8re.jpg","credit":"Nitoni Noio","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Parc_national_des_Monts_de_Cristal_banni%C3%A8re.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Monts_de_Cristal_National_Park"]'::jsonb)
