insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mandrill','GAB','Mandrill',null,'fauna',-0.6,11.6,'The most colourful primate, with a red and blue face, living in large forest troops.','Lopé hosts “hordes” of more than 800 mandrills, the largest groups of any primate apart from humans. The pin is in Lopé.','Largest hordes','800+',false,true,6,'{"color":"#E63946","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/d/df/Mandrill_(Zoo_Dresden).webm/Mandrill_(Zoo_Dresden).webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/d/df/Mandrill_(Zoo_Dresden).webm/Mandrill_(Zoo_Dresden).webm.360p.mpeg4.mov","credit":"Fiver, der Hellseher","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mandrill_(Zoo_Dresden).webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Mandrill_July_2019-1.jpg/1280px-Mandrill_July_2019-1.jpg","credit":"Alvesgaspar","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mandrill_July_2019-1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Mandrill_at_SF_Zoo.jpg/1280px-Mandrill_at_SF_Zoo.jpg","credit":"Sanjay Acharya","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mandrill_at_SF_Zoo.jpg"}]}'::jsonb,'Mandrillus sphinx','["https://en.wikipedia.org/wiki/Mandrill","https://www.gbif.org/species/search?q=Mandrillus%20sphinx"]'::jsonb)
