insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('okoume','GAB','Okoumé',null,'flora',-0.7,10.2,'Gabon’s signature timber tree, a tall softwood of the coastal forest.','For a century it was the backbone of Gabon’s economy, shipped for plywood; since 2010 Gabon has required logs to be processed in the country. The pin is a representative point.','Raw log export ban','2010',false,true,7,'{"color":"#B07D4B","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Abattage_d''un_okoum%C3%A9_en_Afrique_%C3%A9quatoriale_fran%C3%A7aise_-_btv1b101033272.jpg/1280px-Abattage_d''un_okoum%C3%A9_en_Afrique_%C3%A9quatoriale_fran%C3%A7aise_-_btv1b101033272.jpg","credit":"Bibliothèque nationale de France","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Abattage_d''un_okoum%C3%A9_en_Afrique_%C3%A9quatoriale_fran%C3%A7aise_-_btv1b101033272.jpg"}],"note":"An okoumé being felled in French Equatorial Africa, early 20th century."}'::jsonb,'Aucoumea klaineana','["https://en.wikipedia.org/wiki/Aucoumea","https://www.gbif.org/species/search?q=Aucoumea%20klaineana"]'::jsonb)
