insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('rocas-sao-tome','STP','The Roças of São Tomé and Príncipe',null,'heritage',0.38,6.7,'Plantation estates that made the islands among the world’s top cocoa producers in the early 1900s, built on forced labour.','Hospitals, workers’ quarters and drying sheds survive at roças such as Agostinho Neto. Inscribed in 2026 as a record of colonial agriculture and forced migration.','Inscribed','2026',true,true,1,'{"color":"#5C4033","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Ro%C3%A7a_Agostinho_Neto_(S%C3%A3o_Tom%C3%A9)_(2).jpg/1280px-Ro%C3%A7a_Agostinho_Neto_(S%C3%A3o_Tom%C3%A9)_(2).jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ro%C3%A7a_Agostinho_Neto_(S%C3%A3o_Tom%C3%A9)_(2).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Ro%C3%A7a_Agostinho_Neto_(S%C3%A3o_Tom%C3%A9)_(1).jpg/1280px-Ro%C3%A7a_Agostinho_Neto_(S%C3%A3o_Tom%C3%A9)_(1).jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ro%C3%A7a_Agostinho_Neto_(S%C3%A3o_Tom%C3%A9)_(1).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Ro%C3%A7a_Agostinho_Neto_(S%C3%A3o_Tom%C3%A9)_(3).jpg/1280px-Ro%C3%A7a_Agostinho_Neto_(S%C3%A3o_Tom%C3%A9)_(3).jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ro%C3%A7a_Agostinho_Neto_(S%C3%A3o_Tom%C3%A9)_(3).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1750/","https://en.wikipedia.org/wiki/Roça"]'::jsonb)
