insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('pico-cao-grande','STP','Pico Cão Grande',null,'rock',0.12,6.57,'A needle of volcanic rock rising about 370 m above the forest of southern São Tomé.','It is a volcanic plug, the hardened core of an old volcano; its sheer sides were first climbed in 1991.','Rises','~370 m',false,true,2,'{"color":"#2B2D42","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Pico_C%C3%A3o_Grande.jpg/1280px-Pico_C%C3%A3o_Grande.jpg","credit":"Philippe Bourachot","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Pico_C%C3%A3o_Grande.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/C%C3%A3o_Grande_et_C%C3%A3o_Pequeno_%C3%A0_S%C3%A3o_Tom%C3%A9_(3).jpg/1280px-C%C3%A3o_Grande_et_C%C3%A3o_Pequeno_%C3%A0_S%C3%A3o_Tom%C3%A9_(3).jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:C%C3%A3o_Grande_et_C%C3%A3o_Pequeno_%C3%A0_S%C3%A3o_Tom%C3%A9_(3).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/S%C3%A3o_Tom%C3%A9_(13685526293).jpg/1280px-S%C3%A3o_Tom%C3%A9_(13685526293).jpg","credit":"seriykotik1970","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:S%C3%A3o_Tom%C3%A9_(13685526293).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Pico_Cão_Grande"]'::jsonb)
