insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('obo-natural-park','STP','Obô Natural Park',null,'forest',0.25,6.6,'Cloud forest and lowland rainforest covering much of the interior of both islands.','The islands have exceptional numbers of endemic birds, frogs and plants for their size, many protected here.','Covers','~30% of the country',false,true,3,'{"color":"#12AD2B","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Philothamnus_thomensis._Endemic_snake_of_S%C3%A3o_Tom%C3%A9_in_the_Ob%C3%B4_Natural_Park.jpg/1280px-Philothamnus_thomensis._Endemic_snake_of_S%C3%A3o_Tom%C3%A9_in_the_Ob%C3%B4_Natural_Park.jpg","credit":"FrankBanalis","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Philothamnus_thomensis._Endemic_snake_of_S%C3%A3o_Tom%C3%A9_in_the_Ob%C3%B4_Natural_Park.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Allophylus_africanus_%C3%A0_S%C3%A3o_Tom%C3%A9_(2).jpg/1280px-Allophylus_africanus_%C3%A0_S%C3%A3o_Tom%C3%A9_(2).jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Allophylus_africanus_%C3%A0_S%C3%A3o_Tom%C3%A9_(2).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Obô_Natural_Park_of_São_Tomé"]'::jsonb)
