insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('boca-do-inferno','STP','Boca do Inferno','“mouth of hell”','coast',0.15,6.75,'A blowhole on the east coast where Atlantic waves surge through a lava tunnel.','Spray bursts high from the black volcanic rock at high tide.','Rock','Basalt lava',false,true,4,'{"color":"#48CAE4","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Boca_do_Inferno_(S%C3%A3o_Tom%C3%A9)_(3).jpg/1280px-Boca_do_Inferno_(S%C3%A3o_Tom%C3%A9)_(3).jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Boca_do_Inferno_(S%C3%A3o_Tom%C3%A9)_(3).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/2012SaoTome-49_(8042901010).jpg/1280px-2012SaoTome-49_(8042901010).jpg","credit":"Helena Van Eykeren","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:2012SaoTome-49_(8042901010).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/Boca_do_Inferno_(S%C3%A3o_Tom%C3%A9)_(2).jpg/1280px-Boca_do_Inferno_(S%C3%A3o_Tom%C3%A9)_(2).jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Boca_do_Inferno_(S%C3%A3o_Tom%C3%A9)_(2).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/São_Tomé_Island"]'::jsonb)
