insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('giant-begonia','STP','Giant Begonia','bléblé','flora',0.28,6.6,'A begonia that grows taller than a person, found only on São Tomé.','Its stems can reach about 2–3 m, among the largest of any begonia. The pin is in the cloud forest.','Height','~2–3 m',false,true,6,'{"color":"#D21034","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Leal_Begonia_baccata_Sao_Tom%C3%A9_(2).jpg/1280px-Leal_Begonia_baccata_Sao_Tom%C3%A9_(2).jpg","credit":"Mleal002","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Leal_Begonia_baccata_Sao_Tom%C3%A9_(2).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/Conservatoire_du_b%C3%A9gonia_2015._Begonia_baccata_01.JPG/1280px-Conservatoire_du_b%C3%A9gonia_2015._Begonia_baccata_01.JPG","credit":"Salix","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Conservatoire_du_b%C3%A9gonia_2015._Begonia_baccata_01.JPG"}]}'::jsonb,'Begonia baccata','["https://en.wikipedia.org/wiki/Begonia_baccata","https://www.gbif.org/species/search?q=Begonia%20baccata"]'::jsonb)
