insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kibira','BDI','Kibira National Park',null,'forest',-2.91,29.43,'Montane rainforest on the Congo–Nile ridge in the north-west, continuous with Rwanda’s Nyungwe forest.','It protects the headwaters of many rivers and shelters chimpanzees and colobus monkeys; tea estates line its edges.','Area','~400 km²',false,true,1,'{"color":"#1EB53A","intensity":0.85,"motion":"mist"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/7/71/Source_et_chute_de_l''eau_de_NYABIHONDO_(_dans_le_parc_national_de_Kibira).mpg/Source_et_chute_de_l''eau_de_NYABIHONDO_(_dans_le_parc_national_de_Kibira).mpg.480p.vp9.webm","credit":"NIHEREWENIMANA Richard","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Source_et_chute_de_l''eau_de_NYABIHONDO_(_dans_le_parc_national_de_Kibira).mpg","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Kibira_national_park.jpg/1280px-Kibira_national_park.jpg","credit":"KUBWIMANA Bienvenu","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kibira_national_park.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Kibira_National_Parc.jpg/1280px-Kibira_National_Parc.jpg","credit":"NZISABIRA Léopold","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kibira_National_Parc.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Le_sol_du_parc_national_de_la_kibira_%C3%A0_Bugarama.jpg/1280px-Le_sol_du_parc_national_de_la_kibira_%C3%A0_Bugarama.jpg","credit":"NZISABIRA Léopold","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Le_sol_du_parc_national_de_la_kibira_%C3%A0_Bugarama.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Kibira_National_Park"]'::jsonb)
