insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('rusizi','BDI','Rusizi National Park',null,'wetland',-3.33,29.27,'The delta where the Rusizi River enters Lake Tanganyika, just outside Bujumbura.','Hippos, sitatunga and huge Nile crocodiles live among papyrus and palms, within sight of the capital.','Near','Bujumbura',false,true,2,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/RusiziRiver.jpg/1280px-RusiziRiver.jpg","credit":"Amakuru","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:RusiziRiver.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Le_chemin_de_la_rivi%C3%A8re_Rusizi.jpg/1280px-Le_chemin_de_la_rivi%C3%A8re_Rusizi.jpg","credit":"Ajil12","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Le_chemin_de_la_rivi%C3%A8re_Rusizi.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Rusizi_National_Park"]'::jsonb)
