insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('karera-falls','BDI','Karera Falls',null,'waterfall',-3.83,30.08,'A series of waterfalls tumbling down a forested hillside in south-east Burundi.','The falls are a protected natural monument near Rutana, and a popular local destination.','Province','Rutana',false,true,3,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Karera_01546.jpg/1280px-Karera_01546.jpg","credit":"NIHEREWENIMANA Richard","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Karera_01546.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/KARERA_II.jpg/1280px-KARERA_II.jpg","credit":"NIHEREWENIMANA Richard","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:KARERA_II.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/4_KARERA_II.jpg/1280px-4_KARERA_II.jpg","credit":"NIHEREWENIMANA Richard","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:4_KARERA_II.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Chutes_de_la_Karera"]'::jsonb)
