insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-tanganyika-burundi','BDI','Lake Tanganyika',null,'lake',-3.4,29.33,'The longest freshwater lake in the world, about 670 km, shared by four countries.','Some of its water is millions of years old, and hundreds of fish species live nowhere else. Bujumbura’s beaches sit at its northern tip.','Length','~670 km',false,true,4,'{"color":"#2A6F97","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Bujumbura_&_Lake_Tanganyika.JPG/1280px-Bujumbura_&_Lake_Tanganyika.JPG","credit":"Andreas31","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Bujumbura_&_Lake_Tanganyika.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Tanganyika"]'::jsonb)
