insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('nile-crocodile-burundi','BDI','Nile Crocodile',null,'fauna',-3.3,29.28,'Africa’s largest crocodile, abundant in the Rusizi delta.','A giant male nicknamed “Gustave”, said to be about 6 m long, became famous on the Rusizi in the 1990s and 2000s. The pin is in Rusizi.','Length','Up to ~5–6 m',false,true,5,'{"color":"#4C6B3C","intensity":0.85,"motion":"ripple"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/55/Nile_Crocodile_(Crocodylus_niloticus)_swallowing_a_Tilapia.webm/Nile_Crocodile_(Crocodylus_niloticus)_swallowing_a_Tilapia.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/55/Nile_Crocodile_(Crocodylus_niloticus)_swallowing_a_Tilapia.webm/Nile_Crocodile_(Crocodylus_niloticus)_swallowing_a_Tilapia.webm.360p.mpeg4.mov","credit":"Bernard Dupont","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Nile_Crocodile_(Crocodylus_niloticus)_swallowing_a_Tilapia.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Nile_crocodile_head.jpg/1280px-Nile_crocodile_head.jpg","credit":"Leigh Bedford","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Nile_crocodile_head.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/CrocoLoco-swimming-01.jpg/1280px-CrocoLoco-swimming-01.jpg","credit":"MathKnight and Zachi Evenor","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:CrocoLoco-swimming-01.jpg"}]}'::jsonb,'Crocodylus niloticus','["https://en.wikipedia.org/wiki/Nile_crocodile","https://en.wikipedia.org/wiki/Gustave_(crocodile)"]'::jsonb)
