insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('papyrus','BDI','Papyrus',null,'flora',-3.32,29.27,'A giant sedge that forms floating swamps along Africa’s lakes and rivers.','Ancient Egyptians made paper from it; today papyrus swamps filter water and shelter shoebills and sitatunga. The pin is in the Rusizi delta.','Height','Up to ~5 m',false,true,6,'{"color":"#6A994E","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Cyperus_papyrus-pjt2.jpg/1280px-Cyperus_papyrus-pjt2.jpg","credit":"pjt56","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Cyperus_papyrus-pjt2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Cyperus_papyrus-pjt3.jpg/1280px-Cyperus_papyrus-pjt3.jpg","credit":"pjt56","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Cyperus_papyrus-pjt3.jpg"}]}'::jsonb,'Cyperus papyrus','["https://en.wikipedia.org/wiki/Cyperus_papyrus","https://www.gbif.org/species/search?q=Cyperus%20papyrus"]'::jsonb)
