insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('comoros-sultanate-medinas','COM','Medinas of the Historic Sultanates',null,'heritage',-11.7,43.25,'Old stone towns of the Comorian sultanates, with mosques, palaces and narrow lanes.','They grew from Swahili trading networks linking Africa, Arabia and Madagascar. Inscribed in 2026, the Comoros’ first World Heritage Site.','Inscribed','2026',true,true,1,'{"color":"#3A75C4","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Moroni_Medina_Comoros_1.jpg/1280px-Moroni_Medina_Comoros_1.jpg","credit":"Radosław Botev","license":"CC BY 3.0 PL","source":"https://commons.wikimedia.org/wiki/File:Moroni_Medina_Comoros_1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Moroni_Medina_Comoros_2.jpg/1280px-Moroni_Medina_Comoros_2.jpg","credit":"Radosław Botev","license":"CC BY 3.0 PL","source":"https://commons.wikimedia.org/wiki/File:Moroni_Medina_Comoros_2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Moroni_rain_2.jpg/1280px-Moroni_rain_2.jpg","credit":"Radosław Botev","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Moroni_rain_2.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1768/","https://en.wikipedia.org/wiki/Comoros"]'::jsonb)
