insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mount-karthala','COM','Mount Karthala',null,'volcano',-11.76,43.35,'An active shield volcano that forms most of Grande Comore, rising to 2,361 m.','It has erupted more than 20 times since the 19th century, most recently in 2005–2007, when ash fell across the island.','Height','2,361 m',false,true,2,'{"color":"#2B2D42","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Hiking_to_Karthala_crater.jpg/1280px-Hiking_to_Karthala_crater.jpg","credit":"Rokaso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Hiking_to_Karthala_crater.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Karthala_MODIS_20051125.jpg/1280px-Karthala_MODIS_20051125.jpg","credit":"Jeff Schmaltz, NASA GSFC (MODIS)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Karthala_MODIS_20051125.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Mount_Karthala"]'::jsonb)
