insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('coelacanth','COM','Coelacanth','gombessa','fauna',-11.9,43.2,'A “living fossil” fish thought extinct for 66 million years until one was caught off South Africa in 1938.','The Comoros hold the main known population, living in caves 150–250 m deep off Grande Comore. Critically Endangered. The pin is off Grande Comore.','Rediscovered','1938',false,true,5,'{"color":"#264653","intensity":0.85,"motion":"sink"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Latimeria_chalumnae.jpg/1280px-Latimeria_chalumnae.jpg","credit":"Citron","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Latimeria_chalumnae.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Comoran_Coelacanth_Latimeria_chalumnae_Comoros_Pavilion_Expo_2020_Dubai_Photo_by_Prof_Dr_Norman_Ali_Khalaf.jpg/1280px-Comoran_Coelacanth_Latimeria_chalumnae_Comoros_Pavilion_Expo_2020_Dubai_Photo_by_Prof_Dr_Norman_Ali_Khalaf.jpg","credit":"JaffaFalcon","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Comoran_Coelacanth_Latimeria_chalumnae_Comoros_Pavilion_Expo_2020_Dubai_Photo_by_Prof_Dr_Norman_Ali_Khalaf.jpg"}]}'::jsonb,'Latimeria chalumnae','["https://en.wikipedia.org/wiki/West_Indian_Ocean_coelacanth","https://www.gbif.org/species/search?q=Latimeria%20chalumnae"]'::jsonb)
