insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ylang-ylang','COM','Ylang-ylang',null,'flora',-12.25,44.4,'A tree with drooping yellow flowers whose oil is a base note of famous perfumes.','Brought from Asia, it made the Comoros one of the world’s top producers of ylang-ylang oil; the archipelago is called the Perfume Islands. The pin is on Anjouan.','Known as','Perfume Islands',false,true,6,'{"color":"#FFC61E","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f5/Cananga_odorata_flowers.jpg/1280px-Cananga_odorata_flowers.jpg","credit":"B.navez","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Cananga_odorata_flowers.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Cananga_odorata_02.JPG/1280px-Cananga_odorata_02.JPG","credit":"Prenn","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Cananga_odorata_02.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Ylang-ylang_(Cananga_odorata)_in_the_Philippines_01.jpg/1280px-Ylang-ylang_(Cananga_odorata)_in_the_Philippines_01.jpg","credit":"Obsidian Soul","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Ylang-ylang_(Cananga_odorata)_in_the_Philippines_01.jpg"}]}'::jsonb,'Cananga odorata','["https://en.wikipedia.org/wiki/Cananga_odorata","https://www.gbif.org/species/search?q=Cananga%20odorata"]'::jsonb)
