insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-assal','DJI','Lake Assal',null,'lake',11.65,42.42,'A crater lake 155 m below sea level, the lowest point in Africa.','It is about ten times saltier than the sea; a crust of white salt rings its turquoise water.','Below sea level','155 m',false,true,1,'{"color":"#F5F1E6","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3a/Lake_Assal_1-Djibouti.jpg/1280px-Lake_Assal_1-Djibouti.jpg","credit":"Fishercd","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Lake_Assal_1-Djibouti.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8f/Lake_Assal_2-Djibouti.jpg/1280px-Lake_Assal_2-Djibouti.jpg","credit":"Fishercd","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Lake_Assal_2-Djibouti.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Lake_Assal_3-Djibouti.jpg/1280px-Lake_Assal_3-Djibouti.jpg","credit":"Fishercd","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Lake_Assal_3-Djibouti.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Assal_(Djibouti)"]'::jsonb)
