insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lac-abbe','DJI','Lake Abbe',null,'lake',11.17,41.78,'A salt lake on the Ethiopian border, ringed by limestone chimneys that let off steam.','The chimneys, up to about 50 m tall, formed where hot springs met the lake; flamingos feed in the shallows.','Chimneys','Up to ~50 m',false,true,2,'{"color":"#B5651D","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Abbe-4-wiki.jpg/1280px-Abbe-4-wiki.jpg","credit":"jbcombes","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Abbe-4-wiki.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Abbe-8.jpg/1280px-Abbe-8.jpg","credit":"jbcombes","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Abbe-8.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Abbe-3.jpg/1280px-Abbe-3.jpg","credit":"jbcombes","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Abbe-3.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Abbe"]'::jsonb)
