insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('day-forest','DJI','Day Forest','Forêt du Day','forest',11.8,42.68,'A relict juniper forest in the Goda Mountains, a green island in a desert country.','It is home to the Djibouti francolin, a Critically Endangered bird found almost nowhere else.','Endemic bird','Djibouti francolin',false,true,3,'{"color":"#12AD2B","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/For%C3%AAt_de_Day.jpg/1280px-For%C3%AAt_de_Day.jpg","credit":"Singlab","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:For%C3%AAt_de_Day.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/98/Goda_Mountains_-_National_Park_of_For%C3%AAt_du_Day.jpg/1280px-Goda_Mountains_-_National_Park_of_For%C3%AAt_du_Day.jpg","credit":"Singlab","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Goda_Mountains_-_National_Park_of_For%C3%AAt_du_Day.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Day_Forest_National_Park"]'::jsonb)
