insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ghoubbet','DJI','Ghoubbet al-Kharab',null,'coast',11.53,42.6,'A deep bay at the end of the Gulf of Tadjoura, where the African and Arabian plates pull apart.','The rift here is widening by about 1–2 cm a year; volcanoes and fissures line its shores.','Spreading','~1–2 cm/yr',false,true,4,'{"color":"#6AB2E7","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Goubet.jpg/1280px-Goubet.jpg","credit":"Benlilkon93","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Goubet.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Che%C3%AFk-Sa%C3%AFd._5,_Ghubbet_Kharab_-_(mission)_Caspari_;_(aquarelle_reprod._par)_Molteni_(pour_la_conf%C3%A9rence_donn%C3%A9e_par)_Caspari_-_btv1b532512743.jpg/1280px-Che%C3%AFk-Sa%C3%AFd._5,_Ghubbet_Kharab_-_(mission)_Caspari_;_(aquarelle_reprod._par)_Molteni_(pour_la_conf%C3%A9rence_donn%C3%A9e_par)_Caspari_-_btv1b532512743.jpg","credit":"Édouard Caspari (watercolour)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Che%C3%AFk-Sa%C3%AFd._5,_Ghubbet_Kharab_-_(mission)_Caspari_;_(aquarelle_reprod._par)_Molteni_(pour_la_conf%C3%A9rence_donn%C3%A9e_par)_Caspari_-_btv1b532512743.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Ghoubbet-el-Kharab"]'::jsonb)
