insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('whale-shark-djibouti','DJI','Whale Shark',null,'fauna',11.65,42.95,'The world’s largest fish, which gathers in the Gulf of Tadjoura each winter.','Mostly young males arrive from about October to February to feed on plankton close to shore. Endangered. The pin is in the Gulf of Tadjoura.','Season','~Oct–Feb',false,true,5,'{"color":"#6AB2E7","intensity":0.85,"motion":"ripple"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/7/7e/Swimming_with_a_whale_shark_(Rhincodon_typus)_(no_audio).webm/Swimming_with_a_whale_shark_(Rhincodon_typus)_(no_audio).webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/7/7e/Swimming_with_a_whale_shark_(Rhincodon_typus)_(no_audio).webm/Swimming_with_a_whale_shark_(Rhincodon_typus)_(no_audio).webm.360p.mpeg4.mov","credit":"David Rojo","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Swimming_with_a_whale_shark_(Rhincodon_typus)_(no_audio).webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Rhincodon_typus_fgbnms.jpg/1280px-Rhincodon_typus_fgbnms.jpg","credit":"FGBNMS/Eckert","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Rhincodon_typus_fgbnms.jpg"}]}'::jsonb,'Rhincodon typus','["https://en.wikipedia.org/wiki/Whale_shark","https://www.gbif.org/species/search?q=Rhincodon%20typus"]'::jsonb)
