insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('african-pencil-cedar','DJI','African Pencil Cedar',null,'flora',11.8,42.65,'A tall juniper of East Africa’s highlands, forming the Day Forest.','It is the tallest juniper in the world, and the only juniper native south of the equator. The pin is in the Day Forest.','Height','Up to ~40 m',false,true,6,'{"color":"#2F5D50","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Juniperus_procera_Kenya1.jpg/1280px-Juniperus_procera_Kenya1.jpg","credit":"Robert L. Anderson, USDA Forest Service","license":"CC BY 3.0 US","source":"https://commons.wikimedia.org/wiki/File:Juniperus_procera_Kenya1.jpg"}]}'::jsonb,'Juniperus procera','["https://en.wikipedia.org/wiki/Juniperus_procera","https://www.gbif.org/species/search?q=Juniperus%20procera"]'::jsonb)
