insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dahlak','ERI','Dahlak Archipelago',null,'coast',15.83,40.2,'Two large and more than 120 small islands in the Red Sea off Massawa.','Its reefs are among the least disturbed in the Red Sea; Dahlak Kebir holds old cisterns and early Islamic tombstones.','Islands','120+',false,true,2,'{"color":"#4189DD","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/Dahlak_Islands_ISS042.jpg/1280px-Dahlak_Islands_ISS042.jpg","credit":"ISS Expedition 42 crew (NASA)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Dahlak_Islands_ISS042.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Farasan_and_Dahlak_Islands_ISS042.jpg/1280px-Farasan_and_Dahlak_Islands_ISS042.jpg","credit":"ISS Expedition 42 crew (NASA)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Farasan_and_Dahlak_Islands_ISS042.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Dahlak_Archipelago"]'::jsonb)
