insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('debre-bizen','ERI','Debre Bizen',null,'heritage',15.33,39.08,'A 14th-century Orthodox monastery on a mountaintop at about 2,400 m.','Founded around 1368, it holds a famed library of manuscripts; women are not allowed to enter.','Founded','~1368',false,true,4,'{"color":"#C8784A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Debre_Bizen.jpg/1280px-Debre_Bizen.jpg","credit":"Grullab","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Debre_Bizen.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Debre_Bizen"]'::jsonb)
