insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('african-wild-ass','ERI','African Wild Ass',null,'fauna',13.8,41.3,'The wild ancestor of the domestic donkey, surviving in the Danakil desert.','Fewer than about 600 remain, mostly in Eritrea and Ethiopia; it is Critically Endangered. The pin is in the Danakil.','IUCN status','Critically Endangered',false,true,5,'{"color":"#C2B280","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Somali_wild_ass_pair.jpg/1280px-Somali_wild_ass_pair.jpg","credit":"The Land","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Somali_wild_ass_pair.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Equus_africanus_somaliensis_2.jpg/1280px-Equus_africanus_somaliensis_2.jpg","credit":"Ericj","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Equus_africanus_somaliensis_2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/African_wild_Ass.jpg/1280px-African_wild_Ass.jpg","credit":"päts","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:African_wild_Ass.jpg"}]}'::jsonb,'Equus africanus','["https://en.wikipedia.org/wiki/African_wild_ass","https://www.gbif.org/species/search?q=Equus%20africanus"]'::jsonb)
