insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ombet-dragon-tree','ERI','Ombet Dragon Tree',null,'flora',16,38.5,'A dragon tree of the Red Sea hills with clusters of sword-shaped leaves.','Its red resin was traded as dragon’s blood. It is Endangered because of drought and grazing. The pin is a representative point.','IUCN status','Endangered',false,true,6,'{"color":"#8AB17D","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Dracaena_ombet_subsp._schizantha_kz01.jpg/1280px-Dracaena_ombet_subsp._schizantha_kz01.jpg","credit":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Dracaena_ombet_subsp._schizantha_kz01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Dracaena_ombet_Djibouti.jpg/1280px-Dracaena_ombet_Djibouti.jpg","credit":"Plantsman","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Dracaena_ombet_Djibouti.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Dracaena_ombet_subsp._schizantha_kz02.jpg/1280px-Dracaena_ombet_subsp._schizantha_kz02.jpg","credit":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Dracaena_ombet_subsp._schizantha_kz02.jpg"}]}'::jsonb,'Dracaena ombet','["https://en.wikipedia.org/wiki/Dracaena_ombet","https://www.gbif.org/species/search?q=Dracaena%20ombet"]'::jsonb)
