insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('simien-mountains','ETH','Simien National Park',null,'mountain',13.18,38.07,'Jagged peaks and sheer escarpments rising to Ras Dashen, Ethiopia’s highest point at 4,550 m.','Home to the walia ibex, found nowhere else, and gelada monkeys. It came off the List in Danger in 2017. World Heritage Site since 1978.','Highest point','4,550 m',true,true,1,'{"color":"#078930","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Simien_Mountains.jpg/1280px-Simien_Mountains.jpg","credit":"Dave Watts","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Simien_Mountains.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Simien_mountains.jpg/1280px-Simien_mountains.jpg","credit":"Indrik myneur","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Simien_mountains.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Canis_simensis_-Simien_Mountains,_Ethiopia-8.jpg/1280px-Canis_simensis_-Simien_Mountains,_Ethiopia-8.jpg","credit":"Harri J","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Canis_simensis_-Simien_Mountains,_Ethiopia-8.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/9/","https://en.wikipedia.org/wiki/Simien_Mountains_National_Park"]'::jsonb)
