insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lalibela','ETH','Rock-Hewn Churches, Lalibela',null,'heritage',12.03,39.04,'Eleven churches carved down into solid rock in the 12th–13th centuries, still in daily use.','King Lalibela planned the site as a “New Jerusalem”; the cross-shaped Bete Giyorgis is its most famous church. World Heritage Site since 1978.','Churches','11',true,true,2,'{"color":"#DA121A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Bete_Giyorgis_Lalibela.jpg/1280px-Bete_Giyorgis_Lalibela.jpg","credit":"Hulivili","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Bete_Giyorgis_Lalibela.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Bete_Giyorgis_01.jpg/1280px-Bete_Giyorgis_01.jpg","credit":"Bernard Gagnon","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Bete_Giyorgis_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Bete_Giyorgis_02.jpg/1280px-Bete_Giyorgis_02.jpg","credit":"Bernard Gagnon","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Bete_Giyorgis_02.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/18/","https://en.wikipedia.org/wiki/Lalibela"]'::jsonb)
