insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('fasil-ghebbi','ETH','Fasil Ghebbi',null,'heritage',12.61,37.47,'The fortress-city of Gondar, seat of Ethiopian emperors in the 16th and 17th centuries.','Its castles mix Nubian, Arab and Portuguese-influenced styles. World Heritage Site since 1979.','Founded','1630s',true,true,3,'{"color":"#B5651D","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Fasil_Ghebbi,_Gondar_Region-107593.jpg/1280px-Fasil_Ghebbi,_Gondar_Region-107593.jpg","credit":"Francesco Bandarin","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Fasil_Ghebbi,_Gondar_Region-107593.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Fasil_Ghebbi,_Gondar_Region-139582.jpg/1280px-Fasil_Ghebbi,_Gondar_Region-139582.jpg","credit":"Francesco Bandarin","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Fasil_Ghebbi,_Gondar_Region-139582.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Fasil_Ghebbi,_Gondar_Region-139583.jpg/1280px-Fasil_Ghebbi,_Gondar_Region-139583.jpg","credit":"Francesco Bandarin","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Fasil_Ghebbi,_Gondar_Region-139583.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/19/","https://en.wikipedia.org/wiki/Fasil_Ghebbi"]'::jsonb)
