insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('aksum','ETH','Aksum',null,'heritage',14.12,38.73,'The heart of the Aksumite Empire, one of the great powers of the ancient world, with giant stone stelae.','Its stelae are among the tallest single stones ever raised; one, taken to Rome in 1937, was returned in 2005. World Heritage Site since 1980.','Tallest stele','~33 m (fallen)',true,true,4,'{"color":"#FCDD09","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Main_Stelae_Field_at_Sunset_-_Axum_(Aksum)_-_Ethiopia_(8702243506).jpg/1280px-Main_Stelae_Field_at_Sunset_-_Axum_(Aksum)_-_Ethiopia_(8702243506).jpg","credit":"Adam Jones","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Main_Stelae_Field_at_Sunset_-_Axum_(Aksum)_-_Ethiopia_(8702243506).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Stelae,_Aksum,_Ethiopia_(7158408756).jpg/1280px-Stelae,_Aksum,_Ethiopia_(7158408756).jpg","credit":"Rod Waddington","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Stelae,_Aksum,_Ethiopia_(7158408756).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Aksum-107529.jpg/1280px-Aksum-107529.jpg","credit":"Jim Williams","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Aksum-107529.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/15/","https://en.wikipedia.org/wiki/Aksum"]'::jsonb)
