insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lower-valley-awash','ETH','Lower Valley of the Awash',null,'heritage',11.1,40.58,'The Afar badlands where “Lucy”, a 3.2-million-year-old human ancestor, was found in 1974.','Fossils from Hadar and nearby sites have transformed our understanding of human evolution. World Heritage Site since 1980.','Lucy','~3.2 million years',true,true,5,'{"color":"#C8784A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/e/e0/Reconstruction_of_the_fossil_skeleton_of_%22Lucy%22_the_Australopithecus_afarensis.jpg","credit":"120","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Reconstruction_of_the_fossil_skeleton_of_%22Lucy%22_the_Australopithecus_afarensis.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Lucy_(Frankfurt_am_Main).jpg/1280px-Lucy_(Frankfurt_am_Main).jpg","credit":"Gerbil","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Lucy_(Frankfurt_am_Main).jpg"}],"note":"Lucy (replica), found at Hadar in 1974 — no open photos of the valley itself yet."}'::jsonb,null,'["https://whc.unesco.org/en/list/10/","https://en.wikipedia.org/wiki/Lucy_(Australopithecus)"]'::jsonb)
