insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('tiya','ETH','Tiya',null,'heritage',8.43,38.62,'A field of 36 carved stone stelae south of Addis Ababa.','Carved with swords and symbols, they mark graves of a little-known ancient culture. World Heritage Site since 1980.','Stelae','36',true,true,6,'{"color":"#5C4033","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Tiya_stelae.jpg/1280px-Tiya_stelae.jpg","credit":"Philip Kromer (mrflip)","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Tiya_stelae.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/Tiya_vue_d''ensemble.JPG/1280px-Tiya_vue_d''ensemble.JPG","credit":"Julien Demade","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Tiya_vue_d''ensemble.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Tiya_Stelae_Field,_ca._1300_(4)_(28510656033).jpg/1280px-Tiya_Stelae_Field,_ca._1300_(4)_(28510656033).jpg","credit":"Richard Mortel","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Tiya_Stelae_Field,_ca._1300_(4)_(28510656033).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/12/","https://en.wikipedia.org/wiki/Tiya_(archaeological_site)"]'::jsonb)
