insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lower-valley-omo','ETH','Lower Valley of the Omo',null,'river',5.5,36,'A river valley in the south-west where some of the oldest fossils of Homo sapiens were found.','The Omo Kibish fossils are about 230,000 years old or more. The valley is home to many peoples, including the Mursi and Hamar. World Heritage Site since 1980.','Omo I fossil','~230,000 years',true,true,7,'{"color":"#2A6F97","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/OmoRiver1.jpg/1280px-OmoRiver1.jpg","credit":"MauritsV","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:OmoRiver1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Upper_Omo_River,_Ethiopia_(9730579586).jpg/1280px-Upper_Omo_River,_Ethiopia_(9730579586).jpg","credit":"Rod Waddington","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Upper_Omo_River,_Ethiopia_(9730579586).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Etiopia_-_omo_river_valley_DSC_2835_(43).jpg/1280px-Etiopia_-_omo_river_valley_DSC_2835_(43).jpg","credit":"Gianfranco Gori","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Etiopia_-_omo_river_valley_DSC_2835_(43).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/17/","https://en.wikipedia.org/wiki/Omo_remains"]'::jsonb)
