insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('harar-jugol','ETH','Harar Jugol',null,'heritage',9.31,42.13,'A walled Muslim city in the east with 82 mosques and colourful painted houses.','Harar is often called the fourth holy city of Islam. At night men feed wild hyenas at the city walls. World Heritage Site since 2006.','Mosques','82',true,true,8,'{"color":"#6AB2E7","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Town_of_Harar_with_Citywall.jpg/1280px-Town_of_Harar_with_Citywall.jpg","credit":"Wikimedia Commons contributor","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Town_of_Harar_with_Citywall.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Harar,_albero_monumentale_02.jpg/1280px-Harar,_albero_monumentale_02.jpg","credit":"Sailko","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Harar,_albero_monumentale_02.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Facade_with_Harar_Beer_Sign_-_Old_City_(Jugal)_-_Harar_-_Ethiopia_(8749454113).jpg/1280px-Facade_with_Harar_Beer_Sign_-_Old_City_(Jugal)_-_Harar_-_Ethiopia_(8749454113).jpg","credit":"Adam Jones","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Facade_with_Harar_Beer_Sign_-_Old_City_(Jugal)_-_Harar_-_Ethiopia_(8749454113).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1189/","https://en.wikipedia.org/wiki/Harar"]'::jsonb)
