insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('konso','ETH','Konso Cultural Landscape',null,'heritage',5.3,37.4,'Dry-stone terraces and walled hilltop towns built over 400 years and more.','Carved wooden waka grave markers honour heroes. A living farming tradition has kept the terraces working. World Heritage Site since 2011.','Inscribed','2011',true,true,9,'{"color":"#B07D4B","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Konso_village_in_the_Cultural_Landscape_of_Konso.jpg/1280px-Konso_village_in_the_Cultural_Landscape_of_Konso.jpg","credit":"JosepMGracia","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Konso_village_in_the_Cultural_Landscape_of_Konso.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Konso_village_02.jpg/1280px-Konso_village_02.jpg","credit":"Bernard Gagnon","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Konso_village_02.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Marketplace_in_the_Ethiopian_town_of_Konso.jpg/1280px-Marketplace_in_the_Ethiopian_town_of_Konso.jpg","credit":"Ondřej Havelka","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Marketplace_in_the_Ethiopian_town_of_Konso.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1333/","https://en.wikipedia.org/wiki/Konso_people"]'::jsonb)
