insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bale-mountains','ETH','Bale Mountains National Park',null,'mountain',6.67,39.67,'The largest area of Afroalpine habitat in Africa, on the Sanetti Plateau.','Home to the largest population of the Ethiopian wolf, the mountain nyala and the giant mole rat. World Heritage Site since 2023.','Inscribed','2023',true,true,10,'{"color":"#2D6A4F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Bale_Mountains_National_Park_(43)_(28661166634).jpg/1280px-Bale_Mountains_National_Park_(43)_(28661166634).jpg","credit":"Richard Mortel","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Bale_Mountains_National_Park_(43)_(28661166634).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Bale_mountains_two-horned_chameleon_(Trioceros_balebicornutus).jpg/1280px-Bale_mountains_two-horned_chameleon_(Trioceros_balebicornutus).jpg","credit":"Charles J. Sharp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Bale_mountains_two-horned_chameleon_(Trioceros_balebicornutus).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/111/","https://en.wikipedia.org/wiki/Bale_Mountains_National_Park"]'::jsonb)
