insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('gedeo','ETH','Gedeo Cultural Landscape',null,'heritage',6.17,38.33,'Agroforests of enset, coffee and native trees on the steep slopes of the Gedeo highlands, with sacred sites and carved stelae.','The Gedeo have managed this multi-layered forest-garden for generations. World Heritage Site since 2023.','Inscribed','2023',true,true,11,'{"color":"#6F4E37","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Irgachefe_coffee%E3%80%81Ethiopia.jpg/1280px-Irgachefe_coffee%E3%80%81Ethiopia.jpg","credit":"Yoshi Canopus","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Irgachefe_coffee%E3%80%81Ethiopia.jpg"}],"note":"Yirgacheffe coffee, grown in the Gedeo zone — no open photos of the agroforests yet."}'::jsonb,null,'["https://whc.unesco.org/en/list/1641/","https://en.wikipedia.org/wiki/Gedeo_Zone"]'::jsonb)
