insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('melka-kunture','ETH','Melka Kunture and Balchit',null,'heritage',8.7,38.6,'Prehistoric sites on the upper Awash, with stone tools and fossils spanning about two million years.','The nearby Balchit obsidian outcrop supplied tool-makers for hundreds of thousands of years. World Heritage Site since 2024.','Inscribed','2024',true,true,12,'{"color":"#8C5A3C","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Melka_Kunture_Prehistoric_Site_(29125411875).jpg/1280px-Melka_Kunture_Prehistoric_Site_(29125411875).jpg","credit":"Richard Mortel","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Melka_Kunture_Prehistoric_Site_(29125411875).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Pierre_taill%C3%A9e_Melka_Kunture_%C3%89thiopie.jpg/1280px-Pierre_taill%C3%A9e_Melka_Kunture_%C3%89thiopie.jpg","credit":"Didier Descouens","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pierre_taill%C3%A9e_Melka_Kunture_%C3%89thiopie.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/13/","https://en.wikipedia.org/wiki/Melka_Kunture"]'::jsonb)
