insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dallol','ETH','Dallol',null,'landform',14.24,40.3,'Acid pools and yellow-green salt terraces over a volcano in the Danakil Depression, more than 100 m below sea level.','Dallol has the highest average annual temperature recorded for an inhabited place. Afar caravans still cut salt slabs here.','Below sea level','~125 m',false,true,13,'{"color":"#FCDD09","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Dallol-Ethiopie_(5).jpg/1280px-Dallol-Ethiopie_(5).jpg","credit":"Ji-Elle","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Dallol-Ethiopie_(5).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Dallol-2001.jpg/1280px-Dallol-2001.jpg","credit":"Hervé Sthioul","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Dallol-2001.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Dallol-Ethiopie_(4).jpg/1280px-Dallol-Ethiopie_(4).jpg","credit":"Ji-Elle","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Dallol-Ethiopie_(4).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Dallol_(hydrothermal_system)","https://en.wikipedia.org/wiki/Danakil_Depression"]'::jsonb)
