insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('erta-ale','ETH','Erta Ale',null,'volcano',13.61,40.66,'A shield volcano whose summit crater has held a lava lake for decades.','It is one of very few volcanoes with a long-lived lava lake; the name means “smoking mountain” in Afar.','Name means','“Smoking mountain”',false,true,14,'{"color":"#DA121A","intensity":0.85,"motion":"sink"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/c/cd/Erta_Ale_Volcano,_Ethiopia.webm/Erta_Ale_Volcano,_Ethiopia.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/c/cd/Erta_Ale_Volcano,_Ethiopia.webm/Erta_Ale_Volcano,_Ethiopia.webm.360p.mpeg4.mov","credit":"Alton Chang","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Erta_Ale_Volcano,_Ethiopia.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Erta-ale_lac-de-lave_2001.jpg/1280px-Erta-ale_lac-de-lave_2001.jpg","credit":"Hervé Sthioul","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Erta-ale_lac-de-lave_2001.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Erta_Ale_491.jpg/1280px-Erta_Ale_491.jpg","credit":"Rolf Cosar","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Erta_Ale_491.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Erta_Ale-12.JPG/1280px-Erta_Ale-12.JPG","credit":"Rolf Cosar","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Erta_Ale-12.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Erta_Ale"]'::jsonb)
