insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('blue-nile-falls','ETH','Blue Nile Falls','Tis Abay · “great smoke”','waterfall',11.49,37.59,'The Blue Nile drops about 37–45 m in a broad curtain below Lake Tana.','Dams upstream now reduce the flow much of the year; in the rains the falls still roar. A 17th-century stone bridge crosses the gorge nearby.','Height','~37–45 m',false,true,15,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Blue_Nile_Falls_01.jpg/1280px-Blue_Nile_Falls_01.jpg","credit":"Giustino","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Blue_Nile_Falls_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Blue_Nile_Falls-03,_by_CT_Snow.jpg/1280px-Blue_Nile_Falls-03,_by_CT_Snow.jpg","credit":"CT Snow","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Blue_Nile_Falls-03,_by_CT_Snow.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b7/Blue_Nile_Falls_03.jpg/1280px-Blue_Nile_Falls_03.jpg","credit":"Giustino","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Blue_Nile_Falls_03.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Blue_Nile_Falls"]'::jsonb)
