insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ethiopian-wolf','ETH','Ethiopian Wolf',null,'fauna',6.85,39.85,'Africa’s rarest carnivore, a red wolf of the Afroalpine meadows that hunts giant mole rats.','Only around 500 adults remain, about half of them in the Bale Mountains. Endangered. The pin is on the Sanetti Plateau.','Adults left','~500',false,true,16,'{"color":"#C1440E","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Canis_simensis_Bale_Mountains_National_Park_9.jpg/1280px-Canis_simensis_Bale_Mountains_National_Park_9.jpg","credit":"Laika ac","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Canis_simensis_Bale_Mountains_National_Park_9.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Canis_simensis_Bale_Mountains_National_Park_5.jpg/1280px-Canis_simensis_Bale_Mountains_National_Park_5.jpg","credit":"Laika ac","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Canis_simensis_Bale_Mountains_National_Park_5.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Canis_simensis_Bale_Mountains_National_Park_10.jpg/1280px-Canis_simensis_Bale_Mountains_National_Park_10.jpg","credit":"Laika ac","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Canis_simensis_Bale_Mountains_National_Park_10.jpg"}]}'::jsonb,'Canis simensis','["https://en.wikipedia.org/wiki/Ethiopian_wolf","https://www.gbif.org/species/search?q=Canis%20simensis"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('arabica-coffee','ETH','Arabica Coffee','buna','flora',7.3,36.1,'The coffee plant that grows wild in the montane forests of south-west Ethiopia, its birthplace.','Legend says a goatherd named Kaldi noticed its effect on his goats. Ethiopia’s coffee ceremony is a daily ritual. The pin is near Kafa.','Origin','Ethiopian forests',false,true,17,'{"color":"#6F4E37","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/20210529_Coffea_arabica_blossom_009.jpg/1280px-20210529_Coffea_arabica_blossom_009.jpg","credit":"Zinnmann","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:20210529_Coffea_arabica_blossom_009.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Young_tree_of_Coffea_arabica.jpg/1280px-Young_tree_of_Coffea_arabica.jpg","credit":"小石川人晃","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Young_tree_of_Coffea_arabica.jpg"}]}'::jsonb,'Coffea arabica','["https://en.wikipedia.org/wiki/Coffea_arabica","https://www.gbif.org/species/search?q=Coffea%20arabica"]'::jsonb)
