insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mount-kenya','KEN','Mount Kenya National Park',null,'mountain',-0.15,37.31,'Africa’s second-highest mountain, an extinct volcano with glaciers on the equator.','Batian rises to 5,199 m. Giant groundsels and lobelias grow on its alpine slopes. World Heritage Site since 1997.','Height','5,199 m',true,true,1,'{"color":"#2B2D42","intensity":0.85,"motion":"mist"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c6/Mount_Kenya_hike_impressions.webm/Mount_Kenya_hike_impressions.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c6/Mount_Kenya_hike_impressions.webm/Mount_Kenya_hike_impressions.webm.360p.mpeg4.mov","credit":"Nastasia Knizhnikova","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Kenya_hike_impressions.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/Mount_kenya.JPG/1280px-Mount_kenya.JPG","credit":"Ruud Zwart","license":"CC BY-SA 2.5 NL","source":"https://commons.wikimedia.org/wiki/File:Mount_kenya.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Mount_Kenya.jpg/1280px-Mount_Kenya.jpg","credit":"Hdahlmo","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Mount_Kenya.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Mount_kenya_closeup_nasa.JPG/1280px-Mount_kenya_closeup_nasa.JPG","credit":"NASA Johnson Space Center","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Mount_kenya_closeup_nasa.JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/800/","https://en.wikipedia.org/wiki/Mount_Kenya"]'::jsonb)
