insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-turkana','KEN','Lake Turkana National Parks',null,'lake',3.05,36.5,'The world’s largest permanent desert lake and largest alkaline lake, the “Jade Sea”.','Its shores at Koobi Fora have yielded many hominin fossils, and Central Island hosts thousands of Nile crocodiles. On the List in Danger since 2018.','Length','~290 km',true,true,2,'{"color":"#2A9D8F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/LakeTurkanaSouthIsland.jpg/1280px-LakeTurkanaSouthIsland.jpg","credit":"Doron","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:LakeTurkanaSouthIsland.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Lake_Turkana_South.jpg/1280px-Lake_Turkana_South.jpg","credit":"Kreuzschnabel","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Lake_Turkana_South.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/801/","https://en.wikipedia.org/wiki/Lake_Turkana"]'::jsonb)
