insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lamu','KEN','Lamu Old Town',null,'heritage',-2.27,40.9,'The oldest and best-preserved Swahili town in East Africa, with coral-stone houses and carved doors.','There are almost no cars; donkeys and dhows are still part of daily life. World Heritage Site since 2001.','Inscribed','2001',true,true,3,'{"color":"#F4E3C1","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/Lamu_town_on_Lamu_Island_in_Kenya.JPG/1280px-Lamu_town_on_Lamu_Island_in_Kenya.JPG","credit":"Magnus Kjaergaard","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Lamu_town_on_Lamu_Island_in_Kenya.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Lamu_coast.jpg/1280px-Lamu_coast.jpg","credit":"MysteryBee","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Lamu_coast.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Lamu_Town.jpg/1280px-Lamu_Town.jpg","credit":"MysteryBee","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Lamu_Town.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1055/","https://en.wikipedia.org/wiki/Lamu"]'::jsonb)
