insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('fort-jesus','KEN','Fort Jesus, Mombasa',null,'heritage',-4.06,39.68,'A Portuguese fortress built in 1593–96 to guard the old port of Mombasa.','Designed by the Italian architect Giovanni Battista Cairati, it changed hands many times between Portuguese, Omani and British. World Heritage Site since 2011.','Built','1593–1596',true,true,5,'{"color":"#BB0000","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Fort_Jesus,_Mombasa1.jpg/1280px-Fort_Jesus,_Mombasa1.jpg","credit":"Chris huh","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Fort_Jesus,_Mombasa1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/02/The_Fort_Jesus_Mombasa,_Kenya.JPG/1280px-The_Fort_Jesus_Mombasa,_Kenya.JPG","credit":"Zahra Abdulmajid","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:The_Fort_Jesus_Mombasa,_Kenya.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/The_Anchor_at_Fort_Jesus_Mombasa,_Kenya.JPG/1280px-The_Anchor_at_Fort_Jesus_Mombasa,_Kenya.JPG","credit":"Zahra Abdulmajid","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:The_Anchor_at_Fort_Jesus_Mombasa,_Kenya.JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1295/","https://en.wikipedia.org/wiki/Fort_Jesus"]'::jsonb)
