insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kenya-lake-system','KEN','Kenya Lake System in the Great Rift Valley',null,'lake',0.25,36.1,'Lakes Bogoria, Nakuru and Elementaita: shallow alkaline lakes on the Rift Valley floor.','They are the most important feeding ground for lesser flamingos in the world; Bogoria also has geysers and hot springs. World Heritage Site since 2011.','Lakes','3',true,true,6,'{"color":"#E07A9A","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Lake_Bogoria_2011.jpg/1280px-Lake_Bogoria_2011.jpg","credit":"Arthur Buliva","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Lake_Bogoria_2011.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/200812_kenya-107_(3213939312).jpg/1280px-200812_kenya-107_(3213939312).jpg","credit":"Franco Pecchio","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:200812_kenya-107_(3213939312).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/Lake_bogoria_view.jpg/1280px-Lake_bogoria_view.jpg","credit":"Geomurki","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Lake_bogoria_view.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1060/","https://en.wikipedia.org/wiki/Lake_Bogoria"]'::jsonb)
