insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('hells-gate-kenya','KEN','Hell’s Gate National Park',null,'gorge',-0.92,36.31,'Cliffs, volcanic plugs and a steaming gorge near Lake Naivasha that can be explored on foot or by bike.','The landscape helped inspire “The Lion King”; geothermal power stations tap the heat underground.','Created','1984',false,true,11,'{"color":"#C1440E","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Hell''s_Gate,_Kenya_(16213882255).jpg/1280px-Hell''s_Gate,_Kenya_(16213882255).jpg","credit":"Ninara","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Hell''s_Gate,_Kenya_(16213882255).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Hell''s_Gate_National_Park_(Kenya)_02.jpg/1280px-Hell''s_Gate_National_Park_(Kenya)_02.jpg","credit":"Superchilum","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Hell''s_Gate_National_Park_(Kenya)_02.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Hell''s_Gate_National_Park_(Kenya)_03.jpg/1280px-Hell''s_Gate_National_Park_(Kenya)_03.jpg","credit":"Superchilum","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Hell''s_Gate_National_Park_(Kenya)_03.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Hell''s_Gate_National_Park"]'::jsonb)
