insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('grevys-zebra','KEN','Grévy’s Zebra',null,'fauna',0.6,37.55,'The largest wild horse, with narrow stripes and a white belly, living in northern Kenya’s drylands.','About 3,000 remain, almost all in Kenya. Endangered. The pin is in Samburu.','Remaining','~3,000',false,true,12,'{"color":"#2B2D42","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Equus_grevyi_in_Samburu.jpg/1280px-Equus_grevyi_in_Samburu.jpg","credit":"Jesse Hull","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Equus_grevyi_in_Samburu.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Equus_grevyi_in_Kenya_(male).jpg/1280px-Equus_grevyi_in_Kenya_(male).jpg","credit":"Kevin Walsh","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Equus_grevyi_in_Kenya_(male).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Equus_grevyi_(aka).jpg/1280px-Equus_grevyi_(aka).jpg","credit":"André Karwath","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Equus_grevyi_(aka).jpg"}]}'::jsonb,'Equus grevyi','["https://en.wikipedia.org/wiki/Grévy''s_zebra","https://www.gbif.org/species/search?q=Equus%20grevyi"]'::jsonb)
