insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('whistling-thorn','KEN','Whistling Thorn',null,'flora',0.3,36.9,'An acacia whose swollen thorns whistle in the wind when ants have bored holes in them.','Ants living in the thorns defend the tree against elephants; where invasive ants took over, lions changed how they hunt. The pin is in Laikipia.','Defended by','Ants',false,true,13,'{"color":"#8AB17D","intensity":0.85,"motion":"bloom"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/a/a8/So_beeinflussen_sich_Lebewesen_untereinander.webm/So_beeinflussen_sich_Lebewesen_untereinander.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/a/a8/So_beeinflussen_sich_Lebewesen_untereinander.webm/So_beeinflussen_sich_Lebewesen_untereinander.webm.360p.mpeg4.mov","credit":"ZDF/Terra X/Malte Jessl/Martin Schaaf/Maximilian Heß","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:So_beeinflussen_sich_Lebewesen_untereinander.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Flora_of_Tanzania_2751_Nevit.jpg/1280px-Flora_of_Tanzania_2751_Nevit.jpg","credit":"Nevit Dilmen","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Flora_of_Tanzania_2751_Nevit.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Flora_of_Tanzania_2761_Nevit.jpg/1280px-Flora_of_Tanzania_2761_Nevit.jpg","credit":"Nevit Dilmen","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Flora_of_Tanzania_2761_Nevit.jpg"}]}'::jsonb,'Vachellia drepanolobium','["https://en.wikipedia.org/wiki/Vachellia_drepanolobium","https://www.gbif.org/species/search?q=Vachellia%20drepanolobium"]'::jsonb)
