insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('andrefana-dry-forests','MDG','Andrefana Dry Forests','Tsingy de Bemaraha · Ankarana','rock',-18.9,44.8,'Forests of razor-sharp limestone pinnacles, the tsingy, cut by canyons and caves.','Tsingy means “where one cannot walk barefoot”. The site was extended in 2023 to take in Ankarana and other dry forests. World Heritage Site since 1990.','Extended','2023',true,true,1,'{"color":"#B5651D","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Tsingy_de_Bemaraha_Strict_Nature_Reserve.jpg/1280px-Tsingy_de_Bemaraha_Strict_Nature_Reserve.jpg","credit":"ASMaloney","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Tsingy_de_Bemaraha_Strict_Nature_Reserve.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Tsingy_de_Bemaraha_156.jpg/1280px-Tsingy_de_Bemaraha_156.jpg","credit":"Olivier Lejade","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Tsingy_de_Bemaraha_156.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Tsingys_d_Ankarana_MS6044.jpg/1280px-Tsingys_d_Ankarana_MS6044.jpg","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Tsingys_d_Ankarana_MS6044.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/494/","https://en.wikipedia.org/wiki/Tsingy_de_Bemaraha_National_Park"]'::jsonb)
