insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ambohimanga','MDG','Royal Hill of Ambohimanga',null,'heritage',-18.76,47.56,'The fortified hilltop city of the Merina kings, sacred for over 500 years.','Royal tombs, a wooden palace and sacred forest remain; pilgrims still come to make offerings. World Heritage Site since 2001.','Inscribed','2001',true,true,2,'{"color":"#FC3D32","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Ambohimanga_14.jpg/1280px-Ambohimanga_14.jpg","credit":"Olivier Lejade","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Ambohimanga_14.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Ambohimanga_43.jpg/1280px-Ambohimanga_43.jpg","credit":"Olivier Lejade","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Ambohimanga_43.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Ambohimanga_30.jpg/1280px-Ambohimanga_30.jpg","credit":"Olivier Lejade","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Ambohimanga_30.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/950/","https://en.wikipedia.org/wiki/Ambohimanga"]'::jsonb)
