insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('atsinanana-rainforests','MDG','Rainforests of the Atsinanana',null,'forest',-21.25,47.42,'Six national parks along Madagascar’s eastern rainforest, from Marojejy to Andohahela.','They hold many endemic lemurs, chameleons and frogs. On the List in Danger since 2010 because of illegal rosewood logging.','Parks','6',true,true,3,'{"color":"#007E3A","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/be/Mist_over_Ranomafana_National_Park_(15719448688).jpg/1280px-Mist_over_Ranomafana_National_Park_(15719448688).jpg","credit":"Brian Gratwicke","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Mist_over_Ranomafana_National_Park_(15719448688).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Calumma_nasutum,_Ranomafana_National_Park.jpg/1280px-Calumma_nasutum,_Ranomafana_National_Park.jpg","credit":"gripso_banana_prune","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Calumma_nasutum,_Ranomafana_National_Park.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Ranomafana_-_Andriamamovoka_falls.jpg/1280px-Ranomafana_-_Andriamamovoka_falls.jpg","credit":"Hardscarf","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Ranomafana_-_Andriamamovoka_falls.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1257/","https://en.wikipedia.org/wiki/Rainforests_of_the_Atsinanana"]'::jsonb)
