insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('isalo','MDG','Isalo National Park',null,'gorge',-22.56,45.4,'Eroded sandstone massifs, canyons and natural pools in the south-west.','Ring-tailed lemurs and sifakas live in its canyons; the Bara people bury their dead in its cliffs.','Area','~815 km²',false,true,4,'{"color":"#E07A3F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Isalo_canyons.jpg/1280px-Isalo_canyons.jpg","credit":"Moongateclimber","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Isalo_canyons.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Isalo_National_Park_01.jpg/1280px-Isalo_National_Park_01.jpg","credit":"Bernard Gagnon","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Isalo_National_Park_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Eulemur_rufifrons,_Isalo_National_Park_2007-03-01.jpg/1280px-Eulemur_rufifrons,_Isalo_National_Park_2007-03-01.jpg","credit":"Bernard Gagnon","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Eulemur_rufifrons,_Isalo_National_Park_2007-03-01.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Isalo_National_Park"]'::jsonb)
