insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('andasibe-mantadia','MDG','Andasibe-Mantadia National Park',null,'forest',-18.94,48.41,'Rainforest east of Antananarivo, home of the indri, the largest living lemur.','Indri groups sing loud wailing songs that carry for kilometres across the forest each morning.','Area','~155 km²',false,true,5,'{"color":"#2D6A4F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Andasibe_National_Park,_Madagascar_(4027581120).jpg/1280px-Andasibe_National_Park,_Madagascar_(4027581120).jpg","credit":"Brussels","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Andasibe_National_Park,_Madagascar_(4027581120).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Mante,_Andasibe_Madagascar.jpg/1280px-Mante,_Andasibe_Madagascar.jpg","credit":"Cactus0625","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mante,_Andasibe_Madagascar.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Andasibe-Mantadia_National_Park"]'::jsonb)
