insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('avenue-of-the-baobabs','MDG','Avenue of the Baobabs',null,'flora',-20.25,44.42,'A dirt road near Morondava lined by giant Grandidier’s baobabs up to about 30 m tall.','The trees, some hundreds of years old, are remnants of a forest cleared for farming. It became a protected area in 2015.','Tree height','Up to ~30 m',false,true,6,'{"color":"#E9C46A","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/Sunset_on_the_Avenue_of_the_Baobabs.jpg/1280px-Sunset_on_the_Avenue_of_the_Baobabs.jpg","credit":"Gavinevans","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Sunset_on_the_Avenue_of_the_Baobabs.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Avenue_of_the_Baobabs_at_Sunset.jpg/1280px-Avenue_of_the_Baobabs_at_Sunset.jpg","credit":"Gavinevans","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Avenue_of_the_Baobabs_at_Sunset.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Adansonia_grandidieri_Pat_Hooper.jpg/1280px-Adansonia_grandidieri_Pat_Hooper.jpg","credit":"Pat Hooper","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Adansonia_grandidieri_Pat_Hooper.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Avenue_of_the_Baobabs","https://en.wikipedia.org/wiki/Adansonia_grandidieri"]'::jsonb)
