insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ring-tailed-lemur','MDG','Ring-tailed Lemur',null,'fauna',-22.5,45.35,'Madagascar’s best-known lemur, living in female-led troops in the south.','Troops sunbathe each morning, and males hold “stink fights” by waving scented tails. Endangered. The pin is in Isalo.','IUCN status','Endangered',false,true,7,'{"color":"#5E6472","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/58/Ring-tailed_lemurs_(Lemur_catta).webm/Ring-tailed_lemurs_(Lemur_catta).webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/58/Ring-tailed_lemurs_(Lemur_catta).webm/Ring-tailed_lemurs_(Lemur_catta).webm.360p.mpeg4.mov","credit":"The Nature Box","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Ring-tailed_lemurs_(Lemur_catta).webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Ring_tailed_lemur_and_twins.jpg/1280px-Ring_tailed_lemur_and_twins.jpg","credit":"Sannse","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Ring_tailed_lemur_and_twins.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Katta_Lemur_catta.jpg/1280px-Katta_Lemur_catta.jpg","credit":"Richard Bartz","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Katta_Lemur_catta.jpg"}]}'::jsonb,'Lemur catta','["https://en.wikipedia.org/wiki/Ring-tailed_lemur","https://www.gbif.org/species/search?q=Lemur%20catta"]'::jsonb)
