insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('madagascar-periwinkle','MDG','Madagascar Periwinkle',null,'flora',-25,46.9,'A small pink-flowered plant from Madagascar that gave the world two important cancer drugs.','Vinblastine and vincristine, from its leaves, transformed survival rates for childhood leukaemia and Hodgkin’s lymphoma. The pin is in the south-east.','Medicines','Vinblastine · vincristine',false,true,8,'{"color":"#E07A9A","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Catharanthus_roseus-IMG_5432.jpg/1280px-Catharanthus_roseus-IMG_5432.jpg","credit":"C T Johansson","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Catharanthus_roseus-IMG_5432.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Catharanthus_roseus_26_10_2009.jpg/1280px-Catharanthus_roseus_26_10_2009.jpg","credit":"Joydeep","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Catharanthus_roseus_26_10_2009.jpg"}]}'::jsonb,'Catharanthus roseus','["https://en.wikipedia.org/wiki/Catharanthus_roseus","https://www.gbif.org/species/search?q=Catharanthus%20roseus"]'::jsonb)
