insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('aapravasi-ghat','MUS','Aapravasi Ghat',null,'heritage',-20.16,57.5,'The immigration depot in Port Louis where indentured labourers landed from 1834.','About half a million people, mostly from India, came through it: the start of the “great experiment” of indentured labour after slavery. World Heritage Site since 2006.','Arrivals','~0.5 million',true,true,1,'{"color":"#1A206D","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Aapravasi_Ghat_2019-09-27_(2).jpg/1280px-Aapravasi_Ghat_2019-09-27_(2).jpg","credit":"Z thomas","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Aapravasi_Ghat_2019-09-27_(2).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Aapravasi_Ghat_2019-09-27_(1).jpg/1280px-Aapravasi_Ghat_2019-09-27_(1).jpg","credit":"Z thomas","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Aapravasi_Ghat_2019-09-27_(1).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/Aapravasi_Ghat_2019-09-27_(4).jpg/1280px-Aapravasi_Ghat_2019-09-27_(4).jpg","credit":"Z thomas","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Aapravasi_Ghat_2019-09-27_(4).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1227/","https://en.wikipedia.org/wiki/Aapravasi_Ghat"]'::jsonb)
