insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('le-morne','MUS','Le Morne Cultural Landscape',null,'mountain',-20.45,57.33,'A basalt mountain on the south-west tip of Mauritius, used as a refuge by people escaping slavery.','Its caves and summit sheltered maroons in the 18th and early 19th centuries; it is a symbol of resistance. World Heritage Site since 2008.','Height','556 m',true,true,2,'{"color":"#00A551","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Le_Morne_Brabant.jpg/1280px-Le_Morne_Brabant.jpg","credit":"LisanneD","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Le_Morne_Brabant.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/Ebony_Forest_Chamarel_-_View_of_Le_Morne_3.jpg/1280px-Ebony_Forest_Chamarel_-_View_of_Le_Morne_3.jpg","credit":"S Molteno","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ebony_Forest_Chamarel_-_View_of_Le_Morne_3.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Ebony_Forest_Chamarel_-_View_of_Le_Morne_2.jpg/1280px-Ebony_Forest_Chamarel_-_View_of_Le_Morne_2.jpg","credit":"S Molteno","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ebony_Forest_Chamarel_-_View_of_Le_Morne_2.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1259/","https://en.wikipedia.org/wiki/Le_Morne_Brabant"]'::jsonb)
