insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('seven-coloured-earths','MUS','Seven Coloured Earths','Terres des Sept Couleurs','landform',-20.44,57.37,'Dunes of red, brown, violet, green, blue, purple and yellow sand near Chamarel.','The colours come from weathered volcanic basalt rich in iron and aluminium; the sands are said to settle back into layers when mixed.','Colours','7',false,true,3,'{"color":"#EA2839","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Seven_coloured_earths_mauritius.jpg/1280px-Seven_coloured_earths_mauritius.jpg","credit":"Moongateclimber","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Seven_coloured_earths_mauritius.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Seven_Coloured_Earths_-_1.jpg/1280px-Seven_Coloured_Earths_-_1.jpg","credit":"Jean-Marc Astesana","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Seven_Coloured_Earths_-_1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Seven_Coloured_Earths_-_5.jpg/1280px-Seven_Coloured_Earths_-_5.jpg","credit":"mwanasimba","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Seven_Coloured_Earths_-_5.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Seven_Coloured_Earths"]'::jsonb)
