insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('black-river-gorges','MUS','Black River Gorges National Park',null,'forest',-20.42,57.42,'The last large area of native forest on Mauritius, across the south-west uplands.','It shelters the Mauritius kestrel, pink pigeon and echo parakeet, all brought back from near extinction.','Area','~67 km²',false,true,4,'{"color":"#2D6A4F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Black_River_Gorges_Panorama_(4823294261).jpg/1280px-Black_River_Gorges_Panorama_(4823294261).jpg","credit":"carrotmadman6","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Black_River_Gorges_Panorama_(4823294261).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/BlackRiverGorges.jpg/1280px-BlackRiverGorges.jpg","credit":"Mauritiustrip","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:BlackRiverGorges.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Black_River_Gorges_Rainbow_Panorama_(4823916184).jpg/1280px-Black_River_Gorges_Rainbow_Panorama_(4823916184).jpg","credit":"carrotmadman6","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Black_River_Gorges_Rainbow_Panorama_(4823916184).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Black_River_Gorges_National_Park"]'::jsonb)
