insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('blue-bay','MUS','Blue Bay Marine Park',null,'coast',-20.44,57.71,'A sheltered lagoon of coral gardens on the south-east coast.','Its brain coral formations are among the largest in the region; the 353 ha park is a Ramsar wetland.','Area','353 ha',false,true,5,'{"color":"#48CAE4","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b7/Blue_Bay_Mauritius_(23456132492).jpg/1280px-Blue_Bay_Mauritius_(23456132492).jpg","credit":"Lukas von Daeniken","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Blue_Bay_Mauritius_(23456132492).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Blue_bay_Mauritius_2019-10-01.jpg/1280px-Blue_bay_Mauritius_2019-10-01.jpg","credit":"Z thomas","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Blue_bay_Mauritius_2019-10-01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Blue_bay_Mauritius_2019-10-01_2.jpg/1280px-Blue_bay_Mauritius_2019-10-01_2.jpg","credit":"Z thomas","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Blue_bay_Mauritius_2019-10-01_2.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Blue_Bay_Marine_Park"]'::jsonb)
