insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mauritius-kestrel','MUS','Mauritius Kestrel',null,'fauna',-20.42,57.43,'A small forest falcon found only on Mauritius.','In 1974 only four wild birds were known, one of the rarest birds ever. Captive breeding and release brought numbers to several hundred. The pin is in Black River Gorges.','1974','4 birds',false,true,6,'{"color":"#8B5E34","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Mauritius_kestrel_(Falco_punctatus).jpg/1280px-Mauritius_kestrel_(Falco_punctatus).jpg","credit":"Charles J. Sharp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mauritius_kestrel_(Falco_punctatus).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Mauritius_Kestrel.jpg/1280px-Mauritius_Kestrel.jpg","credit":"Josh Noseworthy","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Mauritius_Kestrel.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Falco_newtoni,_punctatus_&_araea.jpg/1280px-Falco_newtoni,_punctatus_&_araea.jpg","credit":"John Gerrard Keulemans","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Falco_newtoni,_punctatus_&_araea.jpg"}]}'::jsonb,'Falco punctatus','["https://en.wikipedia.org/wiki/Mauritius_kestrel","https://www.gbif.org/species/search?q=Falco%20punctatus"]'::jsonb)
