insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('trochetia-boutoniana','MUS','Boucle d’Oreille',null,'flora',-20.45,57.33,'The national flower of Mauritius: red bell-shaped flowers like earrings, found wild only on Le Morne.','Its Creole name means “earring”. The wild population is tiny, but it is grown in gardens. The pin is on Le Morne.','Wild only on','Le Morne',false,true,7,'{"color":"#EA2839","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Trochetia_boutoniana,_Conservatoire_botanique_national_de_Brest_01.jpg/1280px-Trochetia_boutoniana,_Conservatoire_botanique_national_de_Brest_01.jpg","credit":"El Funcionario","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Trochetia_boutoniana,_Conservatoire_botanique_national_de_Brest_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Trochetia_boutoniana_tree.jpg/1280px-Trochetia_boutoniana_tree.jpg","credit":"Citron","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Trochetia_boutoniana_tree.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Trochetia_boutoniana_leaf.jpg/1280px-Trochetia_boutoniana_leaf.jpg","credit":"Citron","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Trochetia_boutoniana_leaf.jpg"}]}'::jsonb,'Trochetia boutoniana','["https://en.wikipedia.org/wiki/Trochetia_boutoniana","https://www.gbif.org/species/search?q=Trochetia%20boutoniana"]'::jsonb)
