insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('rwanda-genocide-memorials','RWA','Memorial Sites of the Genocide','Nyamata · Murambi · Gisozi · Bisesero','heritage',-1.93,30.06,'Four sites that remember the genocide against the Tutsi in 1994, when about a million people were killed in 100 days.','The Kigali Genocide Memorial at Gisozi holds the remains of over 250,000 people. The sites are places of memory and education. World Heritage Site since 2023.','Inscribed','2023',true,true,1,'{"color":"#3D405B","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Grounds_of_Kigali_Genocide_Memorial_with_City_in_the_Distance_-_Kigali_-_Rwanda.jpg/1280px-Grounds_of_Kigali_Genocide_Memorial_with_City_in_the_Distance_-_Kigali_-_Rwanda.jpg","credit":"Adam Jones","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Grounds_of_Kigali_Genocide_Memorial_with_City_in_the_Distance_-_Kigali_-_Rwanda.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/9/94/Kigali_Genocide_Memorial_(6817416755).jpg","credit":"Martijn Munneke","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Kigali_Genocide_Memorial_(6817416755).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1586/","https://en.wikipedia.org/wiki/Kigali_Genocide_Memorial"]'::jsonb)
