insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('nyungwe','RWA','Nyungwe National Park',null,'forest',-2.47,29.2,'One of Africa’s oldest montane rainforests, on the Congo–Nile divide in the south-west.','It holds 13 primate species, including chimpanzees and large troops of Angolan colobus, and a canopy walkway. World Heritage Site since 2023.','Primate species','13',true,true,2,'{"color":"#20603D","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Nyungwe_Foprest_panorama.jpg/1280px-Nyungwe_Foprest_panorama.jpg","credit":"Guswen","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Nyungwe_Foprest_panorama.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Nyungwe_rahvuspark_Landsat_19jul86.jpg/1280px-Nyungwe_rahvuspark_Landsat_19jul86.jpg","credit":"NASA Earth Observatory","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Nyungwe_rahvuspark_Landsat_19jul86.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1697/","https://en.wikipedia.org/wiki/Nyungwe_Forest"]'::jsonb)
