insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('volcanoes-national-park','RWA','Volcanoes National Park',null,'volcano',-1.47,29.49,'Five of the Virunga volcanoes, cloaked in bamboo and montane forest.','Dian Fossey studied mountain gorillas here from 1967; gorilla trekking now funds conservation and local communities.','Area','160 km²',false,true,3,'{"color":"#2B2D42","intensity":0.85,"motion":"mist"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/9/9b/Mountain_gorilla_(Gorilla_beringei_beringei)_climbing_a_tree.webm/Mountain_gorilla_(Gorilla_beringei_beringei)_climbing_a_tree.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/9/9b/Mountain_gorilla_(Gorilla_beringei_beringei)_climbing_a_tree.webm/Mountain_gorilla_(Gorilla_beringei_beringei)_climbing_a_tree.webm.360p.mpeg4.mov","credit":"Bettina May","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Mountain_gorilla_(Gorilla_beringei_beringei)_climbing_a_tree.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Female_and_baby_gorilla,_Volcanoes_National_Park,_Rwanda_(35825126683).jpg/1280px-Female_and_baby_gorilla,_Volcanoes_National_Park,_Rwanda_(35825126683).jpg","credit":"Derek Keats","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Female_and_baby_gorilla,_Volcanoes_National_Park,_Rwanda_(35825126683).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/6/6c/Female_Gorilla_in_Rwanda_at_the_Volcanoes_National_Park_(290812727).jpg","credit":"Derek Keats","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Female_Gorilla_in_Rwanda_at_the_Volcanoes_National_Park_(290812727).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Volcanoes_National_Park"]'::jsonb)
