insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('akagera','RWA','Akagera National Park',null,'savanna',-1.63,30.78,'Savanna, lakes and papyrus swamps along Rwanda’s eastern border.','Since 2015 lions and black and white rhinos have been reintroduced, making it a Big Five park again.','Area','1,122 km²',false,true,4,'{"color":"#FAD201","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Parc_National_d''Akagera.jpg/1280px-Parc_National_d''Akagera.jpg","credit":"Louis Dewame","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Parc_National_d''Akagera.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Topi_in_Akagera_National_Park.jpg/1280px-Topi_in_Akagera_National_Park.jpg","credit":"Braunov","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Topi_in_Akagera_National_Park.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Akagera_National_Park_antelopes.jpg/1280px-Akagera_National_Park_antelopes.jpg","credit":"Girinshuti David","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Akagera_National_Park_antelopes.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Akagera_National_Park"]'::jsonb)
