insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-kivu','RWA','Lake Kivu',null,'lake',-2,29.15,'A deep rift lake between Rwanda and DR Congo, edged by green hills and islands.','Its deep water holds vast amounts of dissolved methane, which a power plant now extracts for electricity.','Max depth','~475 m',false,true,5,'{"color":"#00A1DE","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Lake_Kivu_(20439784294).jpg/1280px-Lake_Kivu_(20439784294).jpg","credit":"MONUSCO / Abel Kavanagh","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Lake_Kivu_(20439784294).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Lake_Kivu_beach_featuring_touring_boats.jpg/1280px-Lake_Kivu_beach_featuring_touring_boats.jpg","credit":"MuitaHappy","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Lake_Kivu_beach_featuring_touring_boats.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Kivu"]'::jsonb)
