insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mountain-gorilla','RWA','Mountain Gorilla',null,'fauna',-1.45,29.52,'A gorilla with long thick fur, living in the cool forests of the Virungas and Bwindi.','Numbers have grown to over 1,000, a rare conservation success; it was moved from Critically Endangered to Endangered in 2018. The pin is in Volcanoes National Park.','Population','1,000+',false,true,6,'{"color":"#2F3E46","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/9/9f/Mountain_gorilla_(Gorilla_beringei_beringei)_and_his_family.webm/Mountain_gorilla_(Gorilla_beringei_beringei)_and_his_family.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/9/9f/Mountain_gorilla_(Gorilla_beringei_beringei)_and_his_family.webm/Mountain_gorilla_(Gorilla_beringei_beringei)_and_his_family.webm.360p.mpeg4.mov","credit":"JD Andrews","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Mountain_gorilla_(Gorilla_beringei_beringei)_and_his_family.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Mountain_gorilla_(Gorilla_beringei_beringei)_eating.jpg/1280px-Mountain_gorilla_(Gorilla_beringei_beringei)_eating.jpg","credit":"Charles J. Sharp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mountain_gorilla_(Gorilla_beringei_beringei)_eating.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Mountain_gorilla_(Gorilla_beringei_beringei)_10_month_baby.jpg/1280px-Mountain_gorilla_(Gorilla_beringei_beringei)_10_month_baby.jpg","credit":"Charles J. Sharp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mountain_gorilla_(Gorilla_beringei_beringei)_10_month_baby.jpg"}]}'::jsonb,'Gorilla beringei beringei','["https://en.wikipedia.org/wiki/Mountain_gorilla","https://www.gbif.org/species/search?q=Gorilla%20beringei%20beringei"]'::jsonb)
