insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('giant-lobelia','RWA','Giant Lobelia',null,'flora',-1.5,29.45,'A towering flower spike of the Afroalpine zone, growing on the high Virunga and Rwenzori slopes.','Its leaves close at night to protect the bud from frost; the flowering spike can reach several metres. The pin is on Karisimbi.','Height','Up to ~6 m',false,true,7,'{"color":"#5B6C8F","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Upper_Kachope_Lake_vegetation.jpg/1280px-Upper_Kachope_Lake_vegetation.jpg","credit":"Rafał Kozubek","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Upper_Kachope_Lake_vegetation.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/2/20/Karisimbi2.jpg","credit":"Amakuru","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Karisimbi2.jpg"}],"note":"Afroalpine giant lobelias in the Rwenzori, and Karisimbi’s slopes."}'::jsonb,'Lobelia wollastonii','["https://en.wikipedia.org/wiki/Lobelia_wollastonii","https://www.gbif.org/species/search?q=Lobelia%20wollastonii"]'::jsonb)
