insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('aldabra','SYC','Aldabra Atoll',null,'coast',-9.42,46.35,'One of the largest raised coral atolls in the world, almost untouched by people.','It is home to about 100,000 Aldabra giant tortoises, the world’s largest population. World Heritage Site since 1982.','Giant tortoises','~100,000',true,true,1,'{"color":"#003F87","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Aldabra_Atoll-108985.jpg/1280px-Aldabra_Atoll-108985.jpg","credit":"Ron Van Oers","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Aldabra_Atoll-108985.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Aldabra_Atoll-108986.jpg/1280px-Aldabra_Atoll-108986.jpg","credit":"Ron Van Oers","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Aldabra_Atoll-108986.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Aldabra_Atoll-108987.jpg/1280px-Aldabra_Atoll-108987.jpg","credit":"Ron Van Oers","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Aldabra_Atoll-108987.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/185/","https://en.wikipedia.org/wiki/Aldabra"]'::jsonb)
