insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('vallee-de-mai','SYC','Vallée de Mai Nature Reserve',null,'forest',-4.33,55.74,'A palm forest on Praslin where the coco de mer grows wild, almost unchanged since prehistoric times.','It is also home to the black parrot, found only on Praslin. World Heritage Site since 1983.','Inscribed','1983',true,true,2,'{"color":"#007A3D","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Vall%C3%A9e_de_Mai_Nature_Reserve-109524.jpg/1280px-Vall%C3%A9e_de_Mai_Nature_Reserve-109524.jpg","credit":"Leila Maziz","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Vall%C3%A9e_de_Mai_Nature_Reserve-109524.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Vall%C3%A9e_de_Mai_Nature_Reserve-109526.jpg/1280px-Vall%C3%A9e_de_Mai_Nature_Reserve-109526.jpg","credit":"Leila Maziz","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Vall%C3%A9e_de_Mai_Nature_Reserve-109526.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Vall%C3%A9e_de_Mai_Entrance.JPG/1280px-Vall%C3%A9e_de_Mai_Entrance.JPG","credit":"Dreizung","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Vall%C3%A9e_de_Mai_Entrance.JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/261/","https://en.wikipedia.org/wiki/Vallée_de_Mai"]'::jsonb)
