insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('anse-source-dargent','SYC','Anse Source d’Argent',null,'coast',-4.37,55.83,'A beach on La Digue framed by sculpted pink granite boulders and a shallow reef.','Among the most photographed beaches in the world; the granite is over 700 million years old.','Granite age','~750 million years',false,true,3,'{"color":"#FCD856","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Anse_Source_d''Argent-La_Digue-Seychellen.jpg/1280px-Anse_Source_d''Argent-La_Digue-Seychellen.jpg","credit":"Tobias Alt","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Anse_Source_d''Argent-La_Digue-Seychellen.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Anse_Source_d''Argent_2-La_Digue.jpg/1280px-Anse_Source_d''Argent_2-La_Digue.jpg","credit":"Tobias Alt","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Anse_Source_d''Argent_2-La_Digue.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Anse_Source_d''Argent_3-La_Digue.jpg/1280px-Anse_Source_d''Argent_3-La_Digue.jpg","credit":"Tobias Alt","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Anse_Source_d''Argent_3-La_Digue.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Anse_Source_d''Argent"]'::jsonb)
