insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('morne-seychellois','SYC','Morne Seychellois National Park',null,'mountain',-4.65,55.43,'The highest point of the Seychelles at 905 m, over the mist forests of Mahé.','Its cloud forest shelters pitcher plants and the jellyfish tree, once thought extinct.','Height','905 m',false,true,4,'{"color":"#2D6A4F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Morne_Seychellois_National_Park_rainforest.jpg/1280px-Morne_Seychellois_National_Park_rainforest.jpg","credit":"Radosław Botev","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Morne_Seychellois_National_Park_rainforest.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Ile_de_Mahe_-_Morne_Seychellois_(1).JPG/1280px-Ile_de_Mahe_-_Morne_Seychellois_(1).JPG","credit":"Remi Jouan","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Ile_de_Mahe_-_Morne_Seychellois_(1).JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Morne_Seychellois_NP_footpath.jpg/1280px-Morne_Seychellois_NP_footpath.jpg","credit":"Dino Sassi, Marcel Fayon (Photo Eden)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Morne_Seychellois_NP_footpath.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Morne_Seychellois_National_Park"]'::jsonb)
