insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('aride-island','SYC','Aride Island',null,'coast',-4.21,55.68,'The northernmost granite island, a nature reserve with huge seabird colonies.','More than a million seabirds of about ten species nest here, including the largest colony of lesser noddies.','Seabirds','1 million+',false,true,5,'{"color":"#48CAE4","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Seychelles_Aride_Island_Main_House_-_panoramio.jpg/1280px-Seychelles_Aride_Island_Main_House_-_panoramio.jpg","credit":"Colin J Taylor","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Seychelles_Aride_Island_Main_House_-_panoramio.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Aride_Island"]'::jsonb)
