insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('aldabra-giant-tortoise','SYC','Aldabra Giant Tortoise',null,'fauna',-9.4,46.4,'One of the largest tortoises in the world, weighing up to about 250 kg.','Individuals can live well over 150 years. Their grazing shapes Aldabra’s grasslands. The pin is on Aldabra.','Lifespan','150+ years',false,true,6,'{"color":"#7F5539","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Tortuga_gigante_de_Aldabra_(Aldabrachelys_gigantea),_isla_Changuu,_Tanzania,_2024-05-31,_DD_10.jpg/1280px-Tortuga_gigante_de_Aldabra_(Aldabrachelys_gigantea),_isla_Changuu,_Tanzania,_2024-05-31,_DD_10.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Tortuga_gigante_de_Aldabra_(Aldabrachelys_gigantea),_isla_Changuu,_Tanzania,_2024-05-31,_DD_10.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Tortuga_gigante_de_Aldabra_(Aldabrachelys_gigantea),_isla_Changuu,_Tanzania,_2024-05-31,_DD_08.jpg/1280px-Tortuga_gigante_de_Aldabra_(Aldabrachelys_gigantea),_isla_Changuu,_Tanzania,_2024-05-31,_DD_08.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Tortuga_gigante_de_Aldabra_(Aldabrachelys_gigantea),_isla_Changuu,_Tanzania,_2024-05-31,_DD_08.jpg"}],"note":"Photographed on Changuu Island, Zanzibar, where Aldabra tortoises were introduced."}'::jsonb,'Aldabrachelys gigantea','["https://en.wikipedia.org/wiki/Aldabra_giant_tortoise","https://www.gbif.org/species/search?q=Aldabrachelys%20gigantea"]'::jsonb)
