insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('coco-de-mer','SYC','Coco de Mer',null,'flora',-4.33,55.74,'A palm whose seed is the heaviest in the plant kingdom, up to about 25 kg.','It grows wild only on Praslin and Curieuse; fruits take about six years to mature. Endangered. The pin is in the Vallée de Mai.','Seed weight','Up to ~25 kg',false,true,7,'{"color":"#D62828","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Female_coco_de_mer_growth.jpg/1280px-Female_coco_de_mer_growth.jpg","credit":"WL","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Female_coco_de_mer_growth.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Lodoicea_Maldivica_A.jpg/1280px-Lodoicea_Maldivica_A.jpg","credit":"Wouter Hagens","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Lodoicea_Maldivica_A.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Coco_de_mer_leafs.jpg/1280px-Coco_de_mer_leafs.jpg","credit":"Wikimedia Commons contributor","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Coco_de_mer_leafs.jpg"}]}'::jsonb,'Lodoicea maldivica','["https://en.wikipedia.org/wiki/Lodoicea","https://www.gbif.org/species/search?q=Lodoicea%20maldivica"]'::jsonb)
