insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('laas-geel','SOM','Laas Geel',null,'rock',9.78,44.44,'Rock shelters near Hargeisa with some of the best-preserved prehistoric paintings in Africa.','Painted cattle with ceremonial robes and herders may date from roughly 5,000 years ago or more. The site is in the region administered by Somaliland.','Age','~5,000 years+',false,true,1,'{"color":"#C8784A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Laas_Geel_rock_paintings.JPG/1280px-Laas_Geel_rock_paintings.JPG","credit":"Theodor Hoffsten","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Laas_Geel_rock_paintings.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Laas_Geel,_2024.jpg/1280px-Laas_Geel,_2024.jpg","credit":"Mheidegger","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Laas_Geel,_2024.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Laas_Geel_Cave_with_Rock_Art,_September_2022.jpg/1280px-Laas_Geel_Cave_with_Rock_Art,_September_2022.jpg","credit":"Tinasimonrowe","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Laas_Geel_Cave_with_Rock_Art,_September_2022.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Laas_Geel"]'::jsonb)
