insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('cal-madow','SOM','Cal Madow',null,'mountain',10.74,47.24,'A mountain range in the north with mist forests of juniper and frankincense above the Gulf of Aden.','Its highest point, Shimbiris, rises to about 2,416 m; the range holds many endemic plants and birds.','Highest point','Shimbiris ~2,416 m',false,true,2,'{"color":"#2A9D8F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/5/58/Lamadayawaterfalls1.jpg","credit":"Abdirisak","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Lamadayawaterfalls1.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Cal_Madow"]'::jsonb)
