insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('jubba-river','SOM','Jubba River',null,'river',-0.25,42.63,'One of Somalia’s two permanent rivers, flowing from the Ethiopian highlands to the Indian Ocean.','Its valley is Somalia’s breadbasket, with bananas, maize and coconut groves.','Reaches the sea','Near Kismayo',false,true,3,'{"color":"#2A6F97","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Jubba_River_in_Goobweyn.jpg/1280px-Jubba_River_in_Goobweyn.jpg","credit":"UNSOM / UN Photo","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Jubba_River_in_Goobweyn.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Coconuts_at_Goobweyn.jpg/1280px-Coconuts_at_Goobweyn.jpg","credit":"Norkeys","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Coconuts_at_Goobweyn.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Jubba_River_in_Goobweyn2.jpg/1280px-Jubba_River_in_Goobweyn2.jpg","credit":"UNSOM / UN Photo","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Jubba_River_in_Goobweyn2.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Jubba_River"]'::jsonb)
