insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lido-beach-mogadishu','SOM','Lido Beach',null,'coast',2.06,45.36,'Mogadishu’s long white beach on the Indian Ocean, busy again with families and footballers.','Somalia has the longest coastline in mainland Africa, about 3,000 km.','National coastline','~3,000 km',false,true,4,'{"color":"#48CAE4","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/2012_10_24_AMISOM_Lido_Beach_C_(8134699094).jpg/1280px-2012_10_24_AMISOM_Lido_Beach_C_(8134699094).jpg","credit":"AMISOM Public Information","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:2012_10_24_AMISOM_Lido_Beach_C_(8134699094).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/2012_10_24_AMISOM_Lido_Beach_A_(8134663143).jpg/1280px-2012_10_24_AMISOM_Lido_Beach_A_(8134663143).jpg","credit":"AMISOM Public Information","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:2012_10_24_AMISOM_Lido_Beach_A_(8134663143).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lido_Beach_(Mogadishu)"]'::jsonb)
