insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dromedary-somalia','SOM','Dromedary Camel','geel','fauna',8.5,46.5,'The one-humped camel, at the heart of Somali herding life.','Somalia and its neighbours hold the world’s largest population of camels, prized for milk, transport and in poetry. The pin is a representative point.','Somali word','geel',false,true,5,'{"color":"#C2B280","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/4/4a/Camelus_dromedarius_-_2016-01-18.webm/Camelus_dromedarius_-_2016-01-18.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/4/4a/Camelus_dromedarius_-_2016-01-18.webm/Camelus_dromedarius_-_2016-01-18.webm.360p.mpeg4.mov","credit":"Pristurus","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Camelus_dromedarius_-_2016-01-18.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Somali_veterinary_technician_carrying_a_camel_calf_in_the_rural_of_Xudun_district,_Sool,_Somalia.jpg/1280px-Somali_veterinary_technician_carrying_a_camel_calf_in_the_rural_of_Xudun_district,_Sool,_Somalia.jpg","credit":"Cabdixamiid Xasan Cawad","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Somali_veterinary_technician_carrying_a_camel_calf_in_the_rural_of_Xudun_district,_Sool,_Somalia.jpg"}]}'::jsonb,'Camelus dromedarius','["https://en.wikipedia.org/wiki/Dromedary","https://en.wikipedia.org/wiki/Camel_milk"]'::jsonb)
