insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('frankincense','SOM','Frankincense','maydi','flora',10.8,47.5,'A tree that clings to bare limestone cliffs in the north and yields a fragrant resin.','The Horn of Africa has traded frankincense since ancient Egyptian expeditions to the “Land of Punt”. Maydi is prized as chewing gum and incense. The pin is in the Cal Madow range.','Resin traded','Since antiquity',false,true,6,'{"color":"#E9C46A","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Somalia-Boswellia_frereana-1.tif/lossy-page1-960px-Somalia-Boswellia_frereana-1.tif.jpg","credit":"Mauro Raffaelli","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Somalia-Boswellia_frereana-1.tif"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Bag_of_frankincense_at_Dubai_spice_souk.jpg/1280px-Bag_of_frankincense_at_Dubai_spice_souk.jpg","credit":"Liz Lawley","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Bag_of_frankincense_at_Dubai_spice_souk.jpg"}]}'::jsonb,'Boswellia frereana','["https://en.wikipedia.org/wiki/Boswellia_frereana","https://en.wikipedia.org/wiki/Frankincense"]'::jsonb)
