insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('boma-badingilo','SSD','Boma–Badingilo Migratory Landscape',null,'savanna',6.49,33.91,'Savannas and floodplains crossed by one of the largest land-mammal migrations on Earth.','Aerial surveys in 2023 counted about 6 million antelope, mostly white-eared kob, tiang and Mongalla gazelle. South Sudan’s first World Heritage Site (2026).','Antelope','~6 million',true,true,1,'{"color":"#FCDD09","intensity":0.85,"motion":"herd"}'::jsonb,'{"note":"No openly licensed photos or footage of the migration yet."}'::jsonb,null,'["https://whc.unesco.org/en/list/1808/","https://en.wikipedia.org/wiki/Boma_National_Park"]'::jsonb)
