insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('the-sudd','SSD','The Sudd',null,'wetland',8,31,'One of the largest wetlands in the world, where the White Nile spreads into papyrus swamps.','Its area swings between about 30,000 and 130,000 km² with the seasons. Its name means “barrier”, as it blocked Nile explorers for centuries.','Name means','“Barrier”',false,true,2,'{"color":"#078930","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Fishing_in_Sudd_wetland_-_by_CPWF_Basin_Focal_Project.jpg/1280px-Fishing_in_Sudd_wetland_-_by_CPWF_Basin_Focal_Project.jpg","credit":"Karen Conniff (CPWF)","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Fishing_in_Sudd_wetland_-_by_CPWF_Basin_Focal_Project.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Karl_Schwabe,_3_x_Afrika_(97a).jpg/1280px-Karl_Schwabe,_3_x_Afrika_(97a).jpg","credit":"Karl Schwabe","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Karl_Schwabe,_3_x_Afrika_(97a).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Sudd"]'::jsonb)
