insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('nimule','SSD','Nimule National Park',null,'river',3.7,31.95,'Riverine savanna along the White Nile where it enters South Sudan from Uganda.','Hippos, elephants and crocodiles live along the Fula rapids, and the park borders the river crossing at Nimule.','Established','1954',false,true,4,'{"color":"#2A6F97","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/The_view_of_River_Nile_from_REI_residential_areas_in_nimule_Game_Park.jpg/1280px-The_view_of_River_Nile_from_REI_residential_areas_in_nimule_Game_Park.jpg","credit":"Bior ajang","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:The_view_of_River_Nile_from_REI_residential_areas_in_nimule_Game_Park.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Nimule_National_Park"]'::jsonb)
