insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('shoebill','SSD','Shoebill',null,'fauna',7.5,30.8,'A tall grey bird with a huge shoe-shaped bill, stalking lungfish in papyrus swamps.','The Sudd holds one of the largest populations in Africa. It can stand motionless for hours before striking. Vulnerable. The pin is in the Sudd.','Height','Up to ~1.5 m',false,true,5,'{"color":"#5E6472","intensity":0.85,"motion":"orbit"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/8/80/Shoebill_(Balaeniceps_rex).webm/Shoebill_(Balaeniceps_rex).webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/8/80/Shoebill_(Balaeniceps_rex).webm/Shoebill_(Balaeniceps_rex).webm.360p.mpeg4.mov","credit":"Les Nuits Photographiques","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Shoebill_(Balaeniceps_rex).webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Balaeniceps_rex_-East_Africa-8.jpg/1280px-Balaeniceps_rex_-East_Africa-8.jpg","credit":"Eric Inafuku","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Balaeniceps_rex_-East_Africa-8.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Balaeniceps_rex_qtl3.jpg/1280px-Balaeniceps_rex_qtl3.jpg","credit":"Quartl","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Balaeniceps_rex_qtl3.jpg"}]}'::jsonb,'Balaeniceps rex','["https://en.wikipedia.org/wiki/Shoebill","https://www.gbif.org/species/search?q=Balaeniceps%20rex"]'::jsonb)
