insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('african-mahogany','SSD','African Mahogany',null,'flora',6,29.5,'A shade tree of savanna rivers, with dense reddish timber.','Its bitter bark is used in traditional medicine; it lines the streets of many towns from Senegal to South Sudan. The pin is a representative point.','Range','Senegal to Sudan',false,true,6,'{"color":"#7F4F24","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Khaya_senegalensis_MS_2037.JPG/1280px-Khaya_senegalensis_MS_2037.JPG","credit":"Marco Schmidt","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Khaya_senegalensis_MS_2037.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Khaya_senegalensis_MS_4753.JPG/1280px-Khaya_senegalensis_MS_4753.JPG","credit":"Marco Schmidt","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Khaya_senegalensis_MS_4753.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Khaya_senegalensis_MHNT.BOT.2004.0.225_Fruit.jpg/1280px-Khaya_senegalensis_MHNT.BOT.2004.0.225_Fruit.jpg","credit":"Didier Descouens","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Khaya_senegalensis_MHNT.BOT.2004.0.225_Fruit.jpg"}]}'::jsonb,'Khaya senegalensis','["https://en.wikipedia.org/wiki/Khaya_senegalensis","https://www.gbif.org/species/search?q=Khaya%20senegalensis"]'::jsonb)
