insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ngorongoro','TZA','Ngorongoro Conservation Area',null,'volcano',-3.21,35.46,'The world’s largest intact volcanic caldera, about 20 km across, full of wildlife.','Maasai herders share the area with wildlife, and Olduvai Gorge and the Laetoli footprints lie within it. Mixed World Heritage Site since 1979.','Caldera','~20 km wide',true,true,1,'{"color":"#1EB53A","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/9/9b/Africa_20120224_0706v.webm/Africa_20120224_0706v.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/9/9b/Africa_20120224_0706v.webm/Africa_20120224_0706v.webm.360p.mpeg4.mov","credit":"Don Heffernan","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Africa_20120224_0706v.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/Ngorongoro-1001-2.jpg/1280px-Ngorongoro-1001-2.jpg","credit":"Grahampurse","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ngorongoro-1001-2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Nature_of_Ngorongoro_Conservation_Area_(121).jpg/1280px-Nature_of_Ngorongoro_Conservation_Area_(121).jpg","credit":"Zenith4237","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Nature_of_Ngorongoro_Conservation_Area_(121).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/39/","https://en.wikipedia.org/wiki/Ngorongoro_Conservation_Area"]'::jsonb)
