insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kilwa-kisiwani','TZA','Ruins of Kilwa Kisiwani and Songo Mnara',null,'heritage',-8.96,39.51,'Two island towns that controlled the Indian Ocean gold and ivory trade from the 13th to the 16th century.','The Great Mosque and Husuni Kubwa palace of Kilwa were among the largest buildings of the Swahili coast. World Heritage Site since 1981.','Inscribed','1981',true,true,2,'{"color":"#B5651D","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Ruins_of_Kilwa_Kisiwani_and_Ruins_of_Songo_Mnara-127034.jpg/1280px-Ruins_of_Kilwa_Kisiwani_and_Ruins_of_Songo_Mnara-127034.jpg","credit":"Karalyn Monteil","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Ruins_of_Kilwa_Kisiwani_and_Ruins_of_Songo_Mnara-127034.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Ruins_of_Kilwa_Kisiwani_and_Ruins_of_Songo_Mnara-127035.jpg/1280px-Ruins_of_Kilwa_Kisiwani_and_Ruins_of_Songo_Mnara-127035.jpg","credit":"Karalyn Monteil","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Ruins_of_Kilwa_Kisiwani_and_Ruins_of_Songo_Mnara-127035.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Ruins_of_Kilwa_Kisiwani_and_Ruins_of_Songo_Mnara-108259.jpg/1280px-Ruins_of_Kilwa_Kisiwani_and_Ruins_of_Songo_Mnara-108259.jpg","credit":"Ron Van Oers","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Ruins_of_Kilwa_Kisiwani_and_Ruins_of_Songo_Mnara-108259.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/144/","https://en.wikipedia.org/wiki/Kilwa_Kisiwani"]'::jsonb)
