insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('serengeti','TZA','Serengeti National Park',null,'savanna',-2.4,34.6,'Endless plains where the Great Migration of wildebeest and zebra circles each year.','Over a million wildebeest follow the rains between Tanzania and Kenya. World Heritage Site since 1981.','Area','~14,750 km²',true,true,3,'{"color":"#E9C46A","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/2d/Lion_cubs_(Panthera_leo).webm/Lion_cubs_(Panthera_leo).webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/2d/Lion_cubs_(Panthera_leo).webm/Lion_cubs_(Panthera_leo).webm.360p.mpeg4.mov","credit":"Bettina May","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Lion_cubs_(Panthera_leo).webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Eastern_Serengeti_2012_05_31_2828_(7522638524).jpg/1280px-Eastern_Serengeti_2012_05_31_2828_(7522638524).jpg","credit":"Harvey Barrison","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Eastern_Serengeti_2012_05_31_2828_(7522638524).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/002_The_lion_king_Snyggve_in_the_Serengeti_National_Park_Photo_by_Giles_Laurent.jpg/1280px-002_The_lion_king_Snyggve_in_the_Serengeti_National_Park_Photo_by_Giles_Laurent.jpg","credit":"Giles Laurent","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:002_The_lion_king_Snyggve_in_the_Serengeti_National_Park_Photo_by_Giles_Laurent.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Serengeti_National_Park_2021-09_-_Polemaetus_bellicosus_-_martial_eagle.jpg/1280px-Serengeti_National_Park_2021-09_-_Polemaetus_bellicosus_-_martial_eagle.jpg","credit":"Thomas Fuhrmann","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Serengeti_National_Park_2021-09_-_Polemaetus_bellicosus_-_martial_eagle.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/156/","https://en.wikipedia.org/wiki/Serengeti_National_Park"]'::jsonb)
