insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('selous-nyerere','TZA','Selous Game Reserve','Nyerere National Park','river',-9,37.4,'One of Africa’s largest protected areas, crossed by the Rufiji River.','Elephant numbers fell sharply to poaching after 2009; it has been on the List in Danger since 2014. Part of it became Nyerere National Park in 2019.','Area','~50,000 km²',true,true,4,'{"color":"#00A3DD","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Nyerere_National_Park_(21).jpg/1280px-Nyerere_National_Park_(21).jpg","credit":"Erasmus Kamugisha","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Nyerere_National_Park_(21).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/Nyerere_National_Park_(18).jpg/1280px-Nyerere_National_Park_(18).jpg","credit":"Erasmus Kamugisha","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Nyerere_National_Park_(18).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Nyerere_National_Park_(24).jpg/1280px-Nyerere_National_Park_(24).jpg","credit":"Erasmus Kamugisha","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Nyerere_National_Park_(24).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/199/","https://en.wikipedia.org/wiki/Selous_Game_Reserve"]'::jsonb)
