insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kilimanjaro','TZA','Kilimanjaro National Park',null,'mountain',-3.07,37.35,'The highest mountain in Africa and the world’s highest free-standing mountain, rising to 5,895 m.','Its glaciers have shrunk by over 80% since 1912. Climbers pass from rainforest through moorland to arctic summit. World Heritage Site since 1987.','Height','5,895 m',true,true,5,'{"color":"#F5F5F5","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Kilimanjaro_from_Amboseli.jpg/1280px-Kilimanjaro_from_Amboseli.jpg","credit":"Sergey Pesterev","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kilimanjaro_from_Amboseli.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Mt._Kilimanjaro_12.2006.jpg/1280px-Mt._Kilimanjaro_12.2006.jpg","credit":"Wikimedia Commons contributor","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Mt._Kilimanjaro_12.2006.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/403/","https://en.wikipedia.org/wiki/Mount_Kilimanjaro"]'::jsonb)
