insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('stone-town-zanzibar','TZA','Stone Town of Zanzibar',null,'heritage',-6.16,39.19,'The old Swahili trading town of Zanzibar, with carved doors, palaces and narrow lanes.','Once the capital of the Omani sultanate and a hub of the spice and slave trades; Freddie Mercury was born here. World Heritage Site since 2000.','Inscribed','2000',true,true,6,'{"color":"#E07A3F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Departamento_de_museos_y_antig%C3%BCedades,_Stone_Town,_Zanz%C3%ADbar,_Tanzania,_2024-05-31,_DD_33-35_HDR.jpg/1280px-Departamento_de_museos_y_antig%C3%BCedades,_Stone_Town,_Zanz%C3%ADbar,_Tanzania,_2024-05-31,_DD_33-35_HDR.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Departamento_de_museos_y_antig%C3%BCedades,_Stone_Town,_Zanz%C3%ADbar,_Tanzania,_2024-05-31,_DD_33-35_HDR.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/18/Fuerte_Viejo,_Stone_Town,_Zanz%C3%ADbar,_Tanzania,_2024-05-31,_DD_32.jpg/1280px-Fuerte_Viejo,_Stone_Town,_Zanz%C3%ADbar,_Tanzania,_2024-05-31,_DD_32.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Fuerte_Viejo,_Stone_Town,_Zanz%C3%ADbar,_Tanzania,_2024-05-31,_DD_32.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Hotel_Mizingani_Seafront,_Stone_Town,_Zanz%C3%ADbar,_Tanzania,_2024-05-31,_DD_23.jpg/1280px-Hotel_Mizingani_Seafront,_Stone_Town,_Zanz%C3%ADbar,_Tanzania,_2024-05-31,_DD_23.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Hotel_Mizingani_Seafront,_Stone_Town,_Zanz%C3%ADbar,_Tanzania,_2024-05-31,_DD_23.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/173/","https://en.wikipedia.org/wiki/Stone_Town"]'::jsonb)
