insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kondoa-rock-art','TZA','Kondoa Rock-Art Sites',null,'rock',-4.72,35.83,'More than 150 painted shelters on the escarpment of the Rift Valley in central Tanzania.','Paintings span at least two millennia, from hunter-gatherers to farmers, and some shelters are still used in local ritual. World Heritage Site since 2006.','Shelters','150+',true,true,7,'{"color":"#C1440E","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Kondoa_Irangi_Rock_Paintings_(51507756351).jpg/1280px-Kondoa_Irangi_Rock_Paintings_(51507756351).jpg","credit":"Nina R","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Kondoa_Irangi_Rock_Paintings_(51507756351).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Kondoa_Irangi_Rock_Paintings_(51507978663).jpg/1280px-Kondoa_Irangi_Rock_Paintings_(51507978663).jpg","credit":"Nina R","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Kondoa_Irangi_Rock_Paintings_(51507978663).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Kondoa_Irangi_Rock_Paintings_(51507751486).jpg/1280px-Kondoa_Irangi_Rock_Paintings_(51507751486).jpg","credit":"Nina R","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Kondoa_Irangi_Rock_Paintings_(51507751486).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1183/","https://en.wikipedia.org/wiki/Kondoa_Irangi_Rock_Paintings"]'::jsonb)
