insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-natron','TZA','Lake Natron',null,'lake',-2.42,36,'A red, caustic soda lake below the volcano Ol Doinyo Lengai.','It is the main breeding site for lesser flamingos in East Africa; its alkaline water can calcify animals that die in it.','pH','Up to ~10.5',false,true,8,'{"color":"#E07A9A","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/NatronSouthSide.jpg/1280px-NatronSouthSide.jpg","credit":"Clem23","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:NatronSouthSide.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Landscape_near_Lake_Natron_(6)_(28484132322).jpg/1280px-Landscape_near_Lake_Natron_(6)_(28484132322).jpg","credit":"Richard Mortel","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Landscape_near_Lake_Natron_(6)_(28484132322).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Around_Lake_Natron_Camp_(1)_(28588319845).jpg/1280px-Around_Lake_Natron_Camp_(1)_(28588319845).jpg","credit":"Richard Mortel","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Around_Lake_Natron_Camp_(1)_(28588319845).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Natron"]'::jsonb)
