insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mahale-mountains','TZA','Mahale Mountains National Park',null,'mountain',-6.27,29.93,'Forested mountains rising from the shore of Lake Tanganyika, reachable only by boat.','Its wild chimpanzees have been studied since 1965, one of the longest chimpanzee research projects.','Chimp study since','1965',false,true,9,'{"color":"#2D6A4F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Adult_male_chimps_in_mahale.jpg/1280px-Adult_male_chimps_in_mahale.jpg","credit":"Caelio","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Adult_male_chimps_in_mahale.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/MahaleMtsNP_ETM+_2001-10-01.jpg/1280px-MahaleMtsNP_ETM+_2001-10-01.jpg","credit":"Jesse Allen, NASA Earth Observatory","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:MahaleMtsNP_ETM+_2001-10-01.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Mahale_Mountains_National_Park"]'::jsonb)
