insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ruaha','TZA','Ruaha National Park',null,'river',-7.5,35,'Baobab-studded wilderness along the Great Ruaha River, one of Tanzania’s largest parks.','It holds about a tenth of the world’s lions and large herds of elephants.','Area','~20,000 km²',false,true,10,'{"color":"#C8784A","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Ruaha_National_Park_Panorama.jpg/1280px-Ruaha_National_Park_Panorama.jpg","credit":"PJvanErp","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Ruaha_National_Park_Panorama.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Dry_Ruaha_River_and.jpg/1280px-Dry_Ruaha_River_and.jpg","credit":"Paul Shaffner","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Dry_Ruaha_River_and.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Agama_sp_in_Ruaha_National_Park,_Tanzania_(Unsplash).jpg/1280px-Agama_sp_in_Ruaha_National_Park,_Tanzania_(Unsplash).jpg","credit":"Henry Hertle","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Agama_sp_in_Ruaha_National_Park,_Tanzania_(Unsplash).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Ruaha_National_Park"]'::jsonb)
