insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lesser-flamingo','TZA','Lesser Flamingo',null,'fauna',-2.4,36.05,'The smallest and most numerous flamingo, filtering algae from soda lakes.','Most of the world’s lesser flamingos breed on Lake Natron, where few predators can reach the nests. Near Threatened. The pin is on Lake Natron.','Breeding site','Lake Natron',false,true,11,'{"color":"#E07A9A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Lesser_Flamingo_Phoeniconaias_minor_in_Tanzania_2081_cropped_Nevit.jpg/1280px-Lesser_Flamingo_Phoeniconaias_minor_in_Tanzania_2081_cropped_Nevit.jpg","credit":"Nevit Dilmen","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Lesser_Flamingo_Phoeniconaias_minor_in_Tanzania_2081_cropped_Nevit.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Natron_from_South.jpg/1280px-Natron_from_South.jpg","credit":"Clem23","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Natron_from_South.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Lesser_Flamingo_Phoeniconaias_minor_in_Tanzania_2092_Nevit.jpg/1280px-Lesser_Flamingo_Phoeniconaias_minor_in_Tanzania_2092_Nevit.jpg","credit":"Nevit Dilmen","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Lesser_Flamingo_Phoeniconaias_minor_in_Tanzania_2092_Nevit.jpg"}]}'::jsonb,'Phoeniconaias minor','["https://en.wikipedia.org/wiki/Lesser_flamingo","https://www.gbif.org/species/search?q=Phoeniconaias%20minor"]'::jsonb)
