insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('african-violet','TZA','African Violet',null,'flora',-5.1,38.6,'A small forest plant from the Usambara Mountains that became one of the world’s favourite houseplants.','Found by Baron Walter von Saint Paul in 1892, it is rare in the wild, growing on shaded rocks in a few forests. The pin is in the Usambaras.','Found','1892',false,true,12,'{"color":"#7B2CBF","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Usambara_2008-2-4a.JPG/1280px-Usambara_2008-2-4a.JPG","credit":"Hedwig Storch","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Usambara_2008-2-4a.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Usambaraveilchen_2008-1-17.JPG/1280px-Usambaraveilchen_2008-1-17.JPG","credit":"Hedwig Storch","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Usambaraveilchen_2008-1-17.JPG"}]}'::jsonb,'Streptocarpus ionanthus','["https://en.wikipedia.org/wiki/Saintpaulia","https://www.gbif.org/species/search?q=Streptocarpus%20ionanthus"]'::jsonb)
