insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bwindi','UGA','Bwindi Impenetrable National Park',null,'forest',-1.02,29.68,'Ancient montane forest on steep ridges, home to about half the world’s mountain gorillas.','It holds over 120 mammal and 350 bird species. World Heritage Site since 1994.','Inscribed','1994',true,true,1,'{"color":"#2D6A4F","intensity":0.85,"motion":"mist"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/a/af/006_Mountain_gorilla_eating_at_Bwindi_Impenetrable_Forest_National_Park_Video_by_Giles_Laurent.webm/006_Mountain_gorilla_eating_at_Bwindi_Impenetrable_Forest_National_Park_Video_by_Giles_Laurent.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/a/af/006_Mountain_gorilla_eating_at_Bwindi_Impenetrable_Forest_National_Park_Video_by_Giles_Laurent.webm/006_Mountain_gorilla_eating_at_Bwindi_Impenetrable_Forest_National_Park_Video_by_Giles_Laurent.webm.360p.mpeg4.mov","credit":"Giles Laurent","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:006_Mountain_gorilla_eating_at_Bwindi_Impenetrable_Forest_National_Park_Video_by_Giles_Laurent.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Bwindi_Impenetrable_National_Park_10.jpg/1280px-Bwindi_Impenetrable_National_Park_10.jpg","credit":"Thomas Fuhrmann","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Bwindi_Impenetrable_National_Park_10.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Bwindi_Impenetrable_National_Park-112362.jpg/1280px-Bwindi_Impenetrable_National_Park-112362.jpg","credit":"Ron Van Oers","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Bwindi_Impenetrable_National_Park-112362.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/Bwindi.JPG/1280px-Bwindi.JPG","credit":"Wikimedia Commons contributor","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Bwindi.JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/682/","https://en.wikipedia.org/wiki/Bwindi_Impenetrable_National_Park"]'::jsonb)
