insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('rwenzori','UGA','Rwenzori Mountains','Mountains of the Moon','mountain',0.4,29.95,'Glaciated peaks on the equator rising to 5,109 m, with giant heathers, groundsels and lobelias.','Often identified with Ptolemy’s “Mountains of the Moon”, a source of the Nile. World Heritage Site since 1994.','Highest peak','5,109 m',true,true,2,'{"color":"#F5F5F5","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Rwenzori_mountains_FP.jpg/1280px-Rwenzori_mountains_FP.jpg","credit":"Ingo Wölbern","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Rwenzori_mountains_FP.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Ruwenzori_Upper_Bigo_Bog.jpg/1280px-Ruwenzori_Upper_Bigo_Bog.jpg","credit":"Albert Backer","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ruwenzori_Upper_Bigo_Bog.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/Ruwenpflanzen.jpg/1280px-Ruwenpflanzen.jpg","credit":"Manuel Werner","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Ruwenpflanzen.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/684/","https://en.wikipedia.org/wiki/Rwenzori_Mountains_National_Park"]'::jsonb)
