insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kasubi-tombs','UGA','Tombs of Buganda Kings at Kasubi',null,'heritage',0.33,32.55,'The burial place of four kabakas of Buganda, under a great thatched dome on Kasubi hill.','The main tomb, Muzibu Azaala Mpanga, burned in 2010 and is being rebuilt with traditional methods; the site was placed on the List in Danger in 2010.','Kabakas buried','4',true,true,3,'{"color":"#B07D4B","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/Kampala_Kasubi_Tombs.jpg/1280px-Kampala_Kasubi_Tombs.jpg","credit":"not not phil","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Kampala_Kasubi_Tombs.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Kampalas_Kasubi_Tombs_(2064308892).jpg/1280px-Kampalas_Kasubi_Tombs_(2064308892).jpg","credit":"not not phil","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Kampalas_Kasubi_Tombs_(2064308892).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1022/","https://en.wikipedia.org/wiki/Kasubi_Tombs"]'::jsonb)
