insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('murchison-falls','UGA','Murchison Falls',null,'waterfall',2.28,31.69,'The Nile forces its way through a gap only about 7 m wide and falls 43 m.','It is one of the most powerful waterfalls in the world for its size; the park below is Uganda’s largest.','Gap','~7 m',false,true,4,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/f3/Top_of_the_Murchision_Falls_on_the_river_Nile.webm/Top_of_the_Murchision_Falls_on_the_river_Nile.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/f3/Top_of_the_Murchision_Falls_on_the_river_Nile.webm/Top_of_the_Murchision_Falls_on_the_river_Nile.webm.360p.mpeg4.mov","credit":"Chapelle musa","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Top_of_the_Murchision_Falls_on_the_river_Nile.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Murchison_Falls_from_above.jpg/1280px-Murchison_Falls_from_above.jpg","credit":"Oliver Sedlacek","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Murchison_Falls_from_above.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Murchison_Falls,_Uganda_(23475021234).jpg/1280px-Murchison_Falls,_Uganda_(23475021234).jpg","credit":"Rod Waddington","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Murchison_Falls,_Uganda_(23475021234).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/River_NIle_-_Murchison_Falls_National_Park_20190916_155547.jpg/1280px-River_NIle_-_Murchison_Falls_National_Park_20190916_155547.jpg","credit":"Josefito123","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:River_NIle_-_Murchison_Falls_National_Park_20190916_155547.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Murchison_Falls"]'::jsonb)
