insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('queen-elizabeth-np','UGA','Queen Elizabeth National Park',null,'savanna',-0.14,30.04,'Savanna, crater lakes and the Kazinga Channel between Lakes Edward and George.','Ishasha’s lions are famous for climbing fig trees; the Kazinga Channel has one of the world’s densest hippo populations.','Tree-climbing lions','Ishasha',false,true,5,'{"color":"#FCDC04","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/21/A_Drive_Through_Queen_Elizabeth_National_Park.webm/A_Drive_Through_Queen_Elizabeth_National_Park.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/21/A_Drive_Through_Queen_Elizabeth_National_Park.webm/A_Drive_Through_Queen_Elizabeth_National_Park.webm.360p.mpeg4.mov","credit":"BalukuBrian","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:A_Drive_Through_Queen_Elizabeth_National_Park.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Tree-climbing_lions_(Panthera_leo).jpg/1280px-Tree-climbing_lions_(Panthera_leo).jpg","credit":"Charles J. Sharp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Tree-climbing_lions_(Panthera_leo).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Uganda-Kob.jpg/1280px-Uganda-Kob.jpg","credit":"Frank Dickert","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Uganda-Kob.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Topi_(Damaliscus_lunatus_jimela)_female.jpg/1280px-Topi_(Damaliscus_lunatus_jimela)_female.jpg","credit":"Charles J. Sharp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Topi_(Damaliscus_lunatus_jimela)_female.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Queen_Elizabeth_National_Park"]'::jsonb)
