insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('source-of-the-nile','UGA','Source of the Nile',null,'river',0.42,33.2,'Where the White Nile flows out of Lake Victoria at Jinja.','John Hanning Speke identified it as the Nile’s source in 1862. The river then runs over 6,000 km to the Mediterranean.','Identified','1862',false,true,6,'{"color":"#2A6F97","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Jinja_source_of_Nile.jpg/1280px-Jinja_source_of_Nile.jpg","credit":"Dror Feitelson","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Jinja_source_of_Nile.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Source_of_the_Nile_-_Jinja,_Uganda_(181090963).jpg/1280px-Source_of_the_Nile_-_Jinja,_Uganda_(181090963).jpg","credit":"Daniel Aufgang","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Source_of_the_Nile_-_Jinja,_Uganda_(181090963).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Birds_of_the_Source_of_the_Nile,_Jinja.jpg/1280px-Birds_of_the_Source_of_the_Nile,_Jinja.jpg","credit":"Aacuda","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Birds_of_the_Source_of_the_Nile,_Jinja.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Jinja,_Uganda","https://en.wikipedia.org/wiki/Nile"]'::jsonb)
