insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sipi-falls','UGA','Sipi Falls',null,'waterfall',1.33,34.37,'Three waterfalls on the slopes of Mount Elgon, with coffee farms around them.','The main drop is about 100 m; the area grows Bugisu Arabica coffee.','Main drop','~100 m',false,true,7,'{"color":"#90E0EF","intensity":0.85,"motion":"cascade"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/0/02/Sipi_Falls_&_Pian_Upe_Game_Reserve2.webm/Sipi_Falls_&_Pian_Upe_Game_Reserve2.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/0/02/Sipi_Falls_&_Pian_Upe_Game_Reserve2.webm/Sipi_Falls_&_Pian_Upe_Game_Reserve2.webm.360p.mpeg4.mov","credit":"Otukei Moses","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Sipi_Falls_&_Pian_Upe_Game_Reserve2.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Sipi_Falls_Main_Drop.jpg/1280px-Sipi_Falls_Main_Drop.jpg","credit":"Quack3142","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Sipi_Falls_Main_Drop.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/98/Sipi_Falls,_Uganda.jpg/1280px-Sipi_Falls,_Uganda.jpg","credit":"Rod Waddington","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Sipi_Falls,_Uganda.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Sipi_falls_-_16640429086.jpg/1280px-Sipi_falls_-_16640429086.jpg","credit":"Gilles Bassière","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Sipi_falls_-_16640429086.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Sipi_Falls"]'::jsonb)
