insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('grey-crowned-crane','UGA','Grey Crowned Crane',null,'fauna',-0.5,30.6,'A crane with a golden crown of feathers, Uganda’s national bird, which appears on its flag.','Unusual among cranes, it roosts in trees. Wetland loss has made it Endangered. The pin is a representative point.','IUCN status','Endangered',false,true,8,'{"color":"#FCDC04","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Grey_crowned_crane,_Balearica_regulorum.jpg/1280px-Grey_crowned_crane,_Balearica_regulorum.jpg","credit":"Ivanhoe","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Grey_crowned_crane,_Balearica_regulorum.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Balearica_regulorum_1_Luc_Viatour.jpg/1280px-Balearica_regulorum_1_Luc_Viatour.jpg","credit":"Luc Viatour","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Balearica_regulorum_1_Luc_Viatour.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Balearica_regulorum_001.jpg/1280px-Balearica_regulorum_001.jpg","credit":"H. Zell","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Balearica_regulorum_001.jpg"}]}'::jsonb,'Balearica regulorum','["https://en.wikipedia.org/wiki/Grey_crowned_crane","https://www.gbif.org/species/search?q=Balearica%20regulorum"]'::jsonb)
