insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('robusta-coffee','UGA','Robusta Coffee',null,'flora',0.4,32.2,'The hardy coffee species native to Uganda’s forests, grown by over a million households.','Wild robusta still grows in forests such as Kibale; Uganda is one of Africa’s largest coffee exporters. The pin is a representative point.','Native to','Ugandan forests',false,true,9,'{"color":"#6F4E37","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Coffea_canephora_berries.JPG/1280px-Coffea_canephora_berries.JPG","credit":"Ksd5","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Coffea_canephora_berries.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Coffea_canephora_4.JPG/1280px-Coffea_canephora_4.JPG","credit":"Vinayaraj","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Coffea_canephora_4.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Coffea_canephora_6.JPG/1280px-Coffea_canephora_6.JPG","credit":"Vinayaraj","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Coffea_canephora_6.JPG"}]}'::jsonb,'Coffea canephora','["https://en.wikipedia.org/wiki/Coffea_canephora","https://www.gbif.org/species/search?q=Coffea%20canephora"]'::jsonb)
