insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mlilwane','SWZ','Mlilwane Wildlife Sanctuary',null,'savanna',-26.47,31.16,'Eswatini’s oldest protected area, in the Ezulwini valley below Nyonyane rock.','Founded in the 1960s by Ted Reilly on his family farm, it began the country’s conservation movement; zebra, antelope and hippos roam it.','Opened','1964',false,true,1,'{"color":"#2D6A4F","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Mlilwane_Wildlife_Sanctuary_in_Eswatini_01.jpg/1280px-Mlilwane_Wildlife_Sanctuary_in_Eswatini_01.jpg","credit":"Bernard Gagnon","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mlilwane_Wildlife_Sanctuary_in_Eswatini_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Zabras_in_Mlilwane_Wildlife_Sanctuary.jpg/1280px-Zabras_in_Mlilwane_Wildlife_Sanctuary.jpg","credit":"Vaiz Ha","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Zabras_in_Mlilwane_Wildlife_Sanctuary.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Mlilwane_Wildlife_Sanctuary_02.jpg/1280px-Mlilwane_Wildlife_Sanctuary_02.jpg","credit":"Bernard Gagnon","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Mlilwane_Wildlife_Sanctuary_02.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Mlilwane_Wildlife_Sanctuary"]'::jsonb)
