insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('hlane','SWZ','Hlane Royal National Park',null,'savanna',-26.25,31.88,'The kingdom’s largest protected area, former royal hunting grounds in the lowveld.','It holds white rhinos, elephants and lions, and the densest nesting of white-backed vultures in Africa.','Area','~220 km²',false,true,2,'{"color":"#FFD900","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Hlane_Royal_National_Park_banner_White_Rhinos_wallowing_and_resting_in_the_bushes.jpg/1280px-Hlane_Royal_National_Park_banner_White_Rhinos_wallowing_and_resting_in_the_bushes.jpg","credit":"Bernard Dupont","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Hlane_Royal_National_Park_banner_White_Rhinos_wallowing_and_resting_in_the_bushes.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Mr3_hlane.jpg/1280px-Mr3_hlane.jpg","credit":"Antonio Olmedo","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Mr3_hlane.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Hlane-Basic-Hide-At-Hippo-Pool.JPG/1280px-Hlane-Basic-Hide-At-Hippo-Pool.JPG","credit":"Bjørn Christian Tørrissen","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Hlane-Basic-Hide-At-Hippo-Pool.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Hlane_Royal_National_Park"]'::jsonb)
