insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sibebe-rock','SWZ','Sibebe Rock',null,'rock',-26.25,31.18,'A bare granite dome near Mbabane, one of the largest exposed granite monoliths in the world.','The rock rises about 350 m above the valley; hikers climb it with local Swazi guides.','Rise','~350 m',false,true,3,'{"color":"#C8784A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Granite_monolith.jpg/1280px-Granite_monolith.jpg","credit":"theswazigirl","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Granite_monolith.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Sibebe"]'::jsonb)
