insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('malolotja','SWZ','Malolotja Nature Reserve',null,'mountain',-26.1,31.1,'Highveld grassland and gorges in the north-west, with waterfalls and canopy-level zip lines.','It contains Ngwenya, one of the world’s oldest known mines, where people dug red haematite more than 40,000 years ago.','Ngwenya mine','~40,000+ years',false,true,4,'{"color":"#3E5EB9","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Malolotja_Scenery_(31722500693).jpg/1280px-Malolotja_Scenery_(31722500693).jpg","credit":"Bernard Dupont","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Malolotja_Scenery_(31722500693).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Malolotja.jpg/1280px-Malolotja.jpg","credit":"René C. Nielsen","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Malolotja.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Malolotja_Scenery_(32380407282).jpg/1280px-Malolotja_Scenery_(32380407282).jpg","credit":"Bernard Dupont","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Malolotja_Scenery_(32380407282).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Malolotja_Nature_Reserve","https://en.wikipedia.org/wiki/Ngwenya_Mine"]'::jsonb)
