insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('white-rhino-eswatini','SWZ','Southern White Rhinoceros',null,'fauna',-26.25,31.88,'The larger of Africa’s two rhinos, grazing the lowveld in small groups.','Hunted to fewer than about 100 animals around 1900, it recovered to many thousands through protection. Eswatini’s rhinos are closely guarded. The pin is in Hlane.','Around 1900','~100 left',false,true,5,'{"color":"#8C8C8C","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/1/15/S%C3%BCdliches_Breitmaulnashorn_(Ceratotherium_simum_simum),_Weibchen_s%C3%A4ugt_Jungtier_in_Uganda.webm/S%C3%BCdliches_Breitmaulnashorn_(Ceratotherium_simum_simum),_Weibchen_s%C3%A4ugt_Jungtier_in_Uganda.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/1/15/S%C3%BCdliches_Breitmaulnashorn_(Ceratotherium_simum_simum),_Weibchen_s%C3%A4ugt_Jungtier_in_Uganda.webm/S%C3%BCdliches_Breitmaulnashorn_(Ceratotherium_simum_simum),_Weibchen_s%C3%A4ugt_Jungtier_in_Uganda.webm.360p.mpeg4.mov","credit":"See source page","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:S%C3%BCdliches_Breitmaulnashorn_(Ceratotherium_simum_simum),_Weibchen_s%C3%A4ugt_Jungtier_in_Uganda.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Adult_White_Rhinoceros_(Ceratotherium_simum_simum)_(CWPG).jpg/1280px-Adult_White_Rhinoceros_(Ceratotherium_simum_simum)_(CWPG).jpg","credit":"Vauxford","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Adult_White_Rhinoceros_(Ceratotherium_simum_simum)_(CWPG).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Rhinoc%C3%A9ros_blanc_du_Sud_(Ceratotherium_simum_simum)_(1).jpg/1280px-Rhinoc%C3%A9ros_blanc_du_Sud_(Ceratotherium_simum_simum)_(1).jpg","credit":"Gzen92","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Rhinoc%C3%A9ros_blanc_du_Sud_(Ceratotherium_simum_simum)_(1).jpg"}]}'::jsonb,'Ceratotherium simum simum','["https://en.wikipedia.org/wiki/Southern_white_rhinoceros","https://www.gbif.org/species/search?q=Ceratotherium%20simum%20simum"]'::jsonb)
