insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kaapsehoop-cycad','SWZ','Kaapsehoop Cycad',null,'flora',-26.1,31.1,'A slow-growing cycad of rocky highveld slopes, part of a plant group older than the dinosaurs.','Cycads are among the most threatened plants because collectors dig them up; this one is Critically Endangered. The pin is near Malolotja.','IUCN status','Critically Endangered',false,true,6,'{"color":"#3A5A40","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Encephalartos_laevifolius,_habitus,_Pretoria_NBT,_a.jpg/1280px-Encephalartos_laevifolius,_habitus,_Pretoria_NBT,_a.jpg","credit":"JMK","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Encephalartos_laevifolius,_habitus,_Pretoria_NBT,_a.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Encephalartos_laevifolius-IMG_9693.JPG/1280px-Encephalartos_laevifolius-IMG_9693.JPG","credit":"C T Johansson","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Encephalartos_laevifolius-IMG_9693.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Encephalartos_laevifolius_furnas_2015.jpg/1280px-Encephalartos_laevifolius_furnas_2015.jpg","credit":"andy_king50","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Encephalartos_laevifolius_furnas_2015.jpg"}]}'::jsonb,'Encephalartos laevifolius','["https://en.wikipedia.org/wiki/Encephalartos_laevifolius","https://www.gbif.org/species/search?q=Encephalartos%20laevifolius"]'::jsonb)
