insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sehlabathebe','LSO','Sehlabathebe National Park',null,'mountain',-29.9,29.12,'High grassland, wetlands and sandstone arches in the Maloti Mountains.','Since 2013 it has formed part of the Maloti-Drakensberg World Heritage Site shared with South Africa, with San rock art in its shelters.','Joined WHS','2013',true,true,1,'{"color":"#5B6C8F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/WV_banner_Maloti_Drakensberg.jpg/1280px-WV_banner_Maloti_Drakensberg.jpg","credit":"Tom Adams","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:WV_banner_Maloti_Drakensberg.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/af/Early_Morning_view_from_Sehlabathebe_House_-_panoramio.jpg/1280px-Early_Morning_view_from_Sehlabathebe_House_-_panoramio.jpg","credit":"Graham Maclachlan","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Early_Morning_view_from_Sehlabathebe_House_-_panoramio.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/985/","https://en.wikipedia.org/wiki/Sehlabathebe_National_Park"]'::jsonb)
