insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('maletsunyane-falls','LSO','Maletsunyane Falls',null,'waterfall',-29.87,28.05,'A single drop of 192 m into a basalt gorge near Semonkong.','Semonkong means “place of smoke”, for the spray. The falls hold one of the world’s longest commercial abseils.','Drop','192 m',false,true,2,'{"color":"#48CAE4","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Maletsunyanefalls.JPG/1280px-Maletsunyanefalls.JPG","credit":"BagelBelt","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Maletsunyanefalls.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/Maletsunyane_Below_Falls.jpg/1280px-Maletsunyane_Below_Falls.jpg","credit":"Vanellus Foto","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Maletsunyane_Below_Falls.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/The_circle_River.jpg/1280px-The_circle_River.jpg","credit":"Letlhogonolo Ramasilo","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:The_circle_River.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Maletsunyane_Falls"]'::jsonb)
