insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('thaba-bosiu','LSO','Thaba Bosiu','“mountain at night”','heritage',-29.38,27.68,'A flat-topped sandstone mountain that served as King Moshoeshoe I’s fortress in the 1820s–1860s.','Never taken by force, it was the cradle of the Basotho nation; Moshoeshoe is buried on its summit.','Founder','Moshoeshoe I',false,true,3,'{"color":"#C1440E","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Thaba_Bosiu.jpg/1280px-Thaba_Bosiu.jpg","credit":"Vanellus Foto","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Thaba_Bosiu.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/Thaba_Bosiu_-_panoramio.jpg/1280px-Thaba_Bosiu_-_panoramio.jpg","credit":"Graham Maclachlan","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Thaba_Bosiu_-_panoramio.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/King_Moshoeshoe_Day_2023_at_Thaba_Bosiu.jpg/1280px-King_Moshoeshoe_Day_2023_at_Thaba_Bosiu.jpg","credit":"U.S. Embassy Maseru","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:King_Moshoeshoe_Day_2023_at_Thaba_Bosiu.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Thaba_Bosiu"]'::jsonb)
