insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('sani-pass','LSO','Sani Pass',null,'mountain',-29.59,29.29,'A dirt road of hairpin bends climbing the Drakensberg escarpment from South Africa into Lesotho at about 2,876 m.','Long passable only by 4×4, it is one of Africa’s most famous mountain roads; the border post sits at the top.','Summit','~2,876 m',false,true,4,'{"color":"#009543","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Sani_Pass_Lesotho.jpg/1280px-Sani_Pass_Lesotho.jpg","credit":"Martin Schärli","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Sani_Pass_Lesotho.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Sani_Pass_Lesotho_2.jpg/1280px-Sani_Pass_Lesotho_2.jpg","credit":"Amada44","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Sani_Pass_Lesotho_2.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/Sani_Pass_Lesotho_3.jpg/1280px-Sani_Pass_Lesotho_3.jpg","credit":"Amada44","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Sani_Pass_Lesotho_3.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Sani_Pass"]'::jsonb)
