insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('bearded-vulture','LSO','Bearded Vulture','ntsu (Sesotho)','fauna',-29.4,28.8,'A huge vulture that eats bone, dropping large bones onto rocks to crack them.','Southern Africa’s isolated population lives mostly in the Lesotho highlands and is Critically Endangered regionally. The pin is in the Maloti.','Diet','~70–90% bone',false,true,5,'{"color":"#E07A3F","intensity":0.85,"motion":"orbit"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/f6/Adult_bearded_vulture_(Gypaetus_barbatus).webm/Adult_bearded_vulture_(Gypaetus_barbatus).webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/f6/Adult_bearded_vulture_(Gypaetus_barbatus).webm/Adult_bearded_vulture_(Gypaetus_barbatus).webm.360p.mpeg4.mov","credit":"Luca Casale (photo), Nabin K. Sapkota (video)","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Adult_bearded_vulture_(Gypaetus_barbatus).webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Bartgeier_Gypaetus_barbatus_closeup1_Richard_Bartz.jpg/1280px-Bartgeier_Gypaetus_barbatus_closeup1_Richard_Bartz.jpg","credit":"Richard Bartz","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Bartgeier_Gypaetus_barbatus_closeup1_Richard_Bartz.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Bartgeier_Gypaetus_barbatus_closeup2_Richard_Bartz.jpg/1280px-Bartgeier_Gypaetus_barbatus_closeup2_Richard_Bartz.jpg","credit":"Richard Bartz","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Bartgeier_Gypaetus_barbatus_closeup2_Richard_Bartz.jpg"}]}'::jsonb,'Gypaetus barbatus','["https://en.wikipedia.org/wiki/Bearded_vulture","https://www.gbif.org/species/search?q=Gypaetus%20barbatus"]'::jsonb)
