insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('spiral-aloe','LSO','Spiral Aloe','kharetsa','flora',-29.6,28.2,'Lesotho’s national flower: an aloe whose leaves form a perfect spiral, found only in the Maloti.','It grows on steep basalt slopes, often in snow; illegal collection made it Endangered. The pin is in the Maloti.','IUCN status','Endangered',false,true,6,'{"color":"#2D6A4F","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Aloe-Polyphylla-Lesotho.jpg/1280px-Aloe-Polyphylla-Lesotho.jpg","credit":"Bjørn Christian Tørrissen","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Aloe-Polyphylla-Lesotho.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Aloe_polyphylla_1.jpg/1280px-Aloe_polyphylla_1.jpg","credit":"Stan Shebs","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Aloe_polyphylla_1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Aloe_polyphylla_3.jpg/1280px-Aloe_polyphylla_3.jpg","credit":"Stan Shebs","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Aloe_polyphylla_3.jpg"}]}'::jsonb,'Aloe polyphylla','["https://en.wikipedia.org/wiki/Aloe_polyphylla","https://www.gbif.org/species/search?q=Aloe%20polyphylla"]'::jsonb)
